        while changed:
            changed = False
            for const in constraints:
                unassigned = []
                ones = 0
                for r, c in const['cells']:
                    if grid[r][c] == 1:
                        ones += 1
                    elif grid[r][c] == -1:
                        unassigned.append((r, c))

                # Contradiction checks
