def solve(observation):
    # Extract grid and size
    grid = observation['data']
    N = len(grid)

    # Initialize domains: True if a star can be placed at (r, c)
    # Obstacles ('B') are initially False
    initial_domains = [[grid[r][c] != 'B' for c in range(N)] for r in range(N)]

    def solve_recursive(domains, unassigned_rows, assigned_cols):
        # Base case: all rows have been assigned a star
        if not unassigned_rows:
            return []

        # Forward checking: Ensure every unassigned row has at least one valid column
        for r in unassigned_rows:
            if not any(domains[r]):
                return None

        # Forward checking: Ensure every unassigned column has at least one valid row
        for c in range(N):
            if c not in assigned_cols:
                if not any(domains[r][c] for r in unassigned_rows):
                    return None

        # MRV (Minimum Remaining Values) heuristic: 
        # Pick the row with the fewest valid columns to drastically reduce branching factor
        best_r = min(unassigned_rows, key=lambda r: sum(domains[r]))
        unassigned_rows_next = [r for r in unassigned_rows if r != best_r]

        # Try placing a star in each valid column of the chosen row
        for c in range(N):
            if domains[best_r][c]:
                # Create a deep copy of domains for the new state
                new_domains = [[domains[i][j] for j in range(N)] for i in range(N)]

                # Apply constraints for the newly placed star at (best_r, c)
                for r in unassigned_rows_next:
                    # 1. Column constraint: no other star can be in the same column
                    new_domains[r][c] = False 

                    # 2. Touching constraint: no star can be adjacent (including diagonally)
                    if abs(r - best_r) <= 1:
                        if c > 0: 
                            new_domains[r][c - 1] = False
                        if c < N - 1: 
                            new_domains[r][c + 1] = False

                # Recurse with updated domains and assignments
                res = solve_recursive(new_domains, unassigned_rows_next, assigned_cols | {c})
                if res is not None:
                    return [(best_r, c)] + res

        return None

    # Start the recursive solver
    solution = solve_recursive(initial_domains, list(range(N)), set())

    # Format the output
    if solution:
        ans = [[None for _ in range(N)] for _ in range(N)]
        for r, c in solution:
            ans[r][c] = 'S'
        return ans
    return "No Solution"

