    def get_neighbors(r, c):
        neighbors = []
        if r > 0: neighbors.append((r - 1, c))
        if r < N - 1: neighbors.append((r + 1, c))
        if c > 0: neighbors.append((r, c - 1))
        if c < N - 1: neighbors.append((r, c + 1))
        return neighbors

    def revise(xi, xj):
        revised = False
        to_remove = set()

        is_same_row = xi[0] == xj[0]
        is_same_col = xi[1] == xj[1]
        is_adjacent = (is_same_row and abs(xi[1] - xj[1]) == 1) or \
                      (is_same_col and abs(xi[0] - xj[0]) == 1)

        pair = tuple(sorted([xi, xj]))
        has_dot = pair in dots

        for x in domains[xi]:
            satisfies = False
            for y in domains[xj]:
                valid = True

                # Sudoku constraints: unique in row and column
                if is_same_row or is_same_col:
