                            valid = False

                if valid:
                    satisfies = True
                    break

            if not satisfies:
                to_remove.add(x)
                revised = True

        if revised:
            domains[xi] -= to_remove

        return revised

    def ac3():
        queue = []
        # Initialize queue with all pairs of variables in the same row or column
        for r in range(N):
            for c in range(N):
                xi = (r, c)
                for c2 in range(N):
                    if c != c2:
                        queue.append((xi, (r, c2)))
                for r2 in range(N):
                    if r != r2:
