                        queue.append(((r2, c), xi))
        return True

    # Apply AC-3 to prune domains
    if not ac3():
        return "No Solution"

    def backtrack(assignment):
        if len(assignment) == N * N:
            return assignment

        # Select unassigned variable using Minimum Remaining Values (MRV) heuristic
        unassigned = [v for v in domains if v not in assignment]
        unassigned.sort(key=lambda v: len(domains[v]))
