                    nval = assignment[(nr, nc)]
                    pair = tuple(sorted([(r, c), (nr, nc)]))
                    has_dot = pair in dots
                    if has_dot and abs(val - nval) != 1:
                        consistent = False
                        break
                    if not has_dot and abs(val - nval) == 1:
                        consistent = False
                        break

            if consistent:
                assignment[var] = val
                result = backtrack(assignment)
                if result:
                    return result
                del assignment[var]

        return None

    # Start backtracking search
    solution = backtrack({})

    if solution:
        res = [[0] * N for _ in range(N)]
        for (r, c), val in solution.items():
            res[r][c] = val
        return res
    else:
        return "No Solution"

