from collections import deque

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    N = len(data)

    # Parse dots into a set of bidirectional adjacent pairs
    dots = set()
    for r, c in adjacent:
        if r % 1 == 0:
            # Horizontal dot
            r_int = int(r)
            c1 = int(c - 0.5)
            c2 = int(c + 0.5)
            dots.add( ((r_int, c1), (r_int, c2)) )
            dots.add( ((r_int, c2), (r_int, c1)) )
        else:
            # Vertical dot
            c_int = int(c)
            r1 = int(r - 0.5)
            r2 = int(r + 0.5)
            dots.add( ((r1, c_int), (r2, c_int)) )
            dots.add( ((r2, c_int), (r1, c_int)) )

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Precompute neighbors (cells in the same row or column)
    neighbors = {}
    for r in range(N):
        for c in range(N):
            nbrs = []
            for r2 in range(N):
                if r2 != r: nbrs.append((r2, c))
            for c2 in range(N):
                if c2 != c: nbrs.append((r, c2))
            neighbors[(r, c)] = nbrs

    def revise(doms, xi, xj):
        """
        Revise domain of xi based on constraints with xj.
        Returns True if domain was modified.
        """
        revised = False
        to_remove = set()

        # Check if xi and xj are orthogonally adjacent
        is_adj = abs(xi[0] - xj[0]) + abs(xi[1] - xj[1]) == 1
        has_dot = (xi, xj) in dots if is_adj else False

        for x in doms[xi]:
            valid_y_found = False
            for y in doms[xj]:
                # Constraint 1: Alldiff in row/col
                if x == y: 
                    continue

                # Constraint 2: Consecutive dots
                if is_adj:
                    if has_dot and abs(x - y) != 1: 
                        continue
                    if not has_dot and abs(x - y) == 1: 
                        continue

                valid_y_found = True
                break

            if not valid_y_found:
                to_remove.add(x)
                revised = True

        if revised:
            doms[xi] -= to_remove
        return revised

    def ac3(doms, queue=None):
        """
        AC-3 Constraint Propagation Algorithm.
        """
        if queue is None:
            queue = deque()
            for xi in neighbors:
                for xj in neighbors[xi]:
                    queue.append((xi, xj))
        else:
            queue = deque(queue)

        while queue:
            xi, xj = queue.popleft()
            if revise(doms, xi, xj):
                if not doms[xi]:
                    return False # Domain wiped out, invalid state
                for xm in neighbors[xi]:
                    if xm != xj:
                        queue.append( (xm, xi) )
        return True

    # Initial constraint propagation
    if not ac3(domains):
        return "No Solution"

    def solve_bt(doms):
        """
        Backtracking search with Minimum Remaining Values (MRV) heuristic.
        """
        unassigned = [pos for pos in doms if len(doms[pos]) > 1]
        if not unassigned:
            return doms # All variables assigned

        # MRV heuristic: pick the variable with the smallest domain
        unassigned.sort(key=lambda pos: len(doms[pos]))
        xi = unassigned[0]

        for val in sorted(list(doms[xi])):
            new_doms = {pos: set(d) for pos, d in doms.items()}
            new_doms[xi] = {val}

            # Propagate the new assignment
            queue = [ (xj, xi) for xj in neighbors[xi] ]
            if ac3(new_doms, queue):
                result = solve_bt(new_doms)
                if result:
                    return result
        return False

    result_doms = solve_bt(domains)
    if not result_doms:
        return "No Solution"

    # Format the final answer
    ans = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            ans[r][c] = list(result_doms[(r, c)])[0]

    return ans

if __name__ == "__main__":
    print(solve(OBSERVATION))
