from collections import deque

def propagate(domains, dots, N):
    queue = deque()
    in_queue = set()

    def add_to_queue(arc):
        if arc not in in_queue:
            queue.append(arc)
            in_queue.add(arc)

    # Initialize queue with all constraints
    for r in range(N):
        for c in range(N):
            # Row alldiff constraints
            for c2 in range(N):
                if c != c2:
                    add_to_queue(((r, c), (r, c2), 'alldiff'))
            # Column alldiff constraints
            for r2 in range(N):
                if r != r2:
                    add_to_queue(((r, c), (r2, c), 'alldiff'))
            # Orthogonal adjacency constraints (dot or nodot)
            for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                if 0 <= nr < N and 0 <= nc < N:
                    r_min, r_max = min(r, nr), max(r, nr)
                    c_min, c_max = min(c, nc), max(c, nc)
                    is_dot = ((r_min, c_min), (r_max, c_max)) in dots
                    add_to_queue(((r, c), (nr, nc), 'dot' if is_dot else 'nodot'))

    # AC-3 Algorithm
    while queue:
        arc = queue.popleft()
        in_queue.remove(arc)
        (r1, c1), (r2, c2), constraint_type = arc

        new_domain = set()
        for v1 in domains[r1][c1]:
            satisfies = False
            for v2 in domains[r2][c2]:
                if constraint_type == 'alldiff':
                    if v1 != v2:
                        satisfies = True
                        break
                elif constraint_type == 'dot':
                    if abs(v1 - v2) == 1:
                        satisfies = True
                        break
                elif constraint_type == 'nodot':
                    if abs(v1 - v2) != 1 and v1 != v2:
                        satisfies = True
                        break
            if satisfies:
                new_domain.add(v1)

        if len(new_domain) < len(domains[r1][c1]):
            domains[r1][c1] = new_domain
            if len(new_domain) == 0:
                return False # Contradiction found

            # Re-evaluate constraints pointing to the modified cell
            for c3 in range(N):
                if c3 != c1:
                    add_to_queue(((r1, c3), (r1, c1), 'alldiff'))
            for r3 in range(N):
                if r3 != r1:
                    add_to_queue(((r3, c1), (r1, c1), 'alldiff'))
            for nr, nc in [(r1-1, c1), (r1+1, c1), (r1, c1-1), (r1, c1+1)]:
                if 0 <= nr < N and 0 <= nc < N:
                    r_min, r_max = min(r1, nr), max(r1, nr)
                    c_min, c_max = min(c1, nc), max(c1, nc)
                    is_dot = ((r_min, c_min), (r_max, c_max)) in dots
                    add_to_queue(((nr, nc), (r1, c1), 'dot' if is_dot else 'nodot'))

    return True

def solve_recursive(domains, dots, N):
    # Find the unassigned cell with the Minimum Remaining Values (MRV heuristic)
    min_len = N + 1
    best_cell = None
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) > 1:
                if len(domains[r][c]) < min_len:
                    min_len = len(domains[r][c])
                    best_cell = (r, c)

    if best_cell is None:
        # All cells assigned successfully
        return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

    r, c = best_cell

    for v in domains[r][c]:
        # Create a deep copy of domains for the backtracking branch
        new_domains = [[set(domains[i][j]) for j in range(N)] for i in range(N)]
        new_domains[r][c] = {v}

        if propagate(new_domains, dots, N):
            result = solve_recursive(new_domains, dots, N)
            if result:
                return result

    return None

def solve(observation):
    data = observation['data']
    N = len(data)

    # Parse dots into a set of normalized coordinate pairs
    dots = set()
    for r, c in observation['adjacent']:
        if r == int(r): # Horizontal dot
            r = int(r)
            c1 = int(c - 0.5)
            c2 = int(c + 0.5)
            dots.add(((r, c1), (r, c2)))
        else: # Vertical dot
            r1 = int(r - 0.5)
            r2 = int(r + 0.5)
            c = int(c)
            dots.add(((r1, c), (r2, c)))

    # Initialize domains
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Initial constraint propagation
    if not propagate(domains, dots, N):
        return "No Solution"

    # Backtracking search
    result = solve_recursive(domains, dots, N)
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
