                    if g[r][c] is not None and g[r][c] == g[r+2][c] and g[r+1][c] is None:
                        g[r+1][c] = 'W' if g[r][c] == 'B' else 'B'
                        changed = True

            # Rule 3 for rows
            for r in range(N):
                b_count = g[r].count('B')
                w_count = g[r].count('W')
                if b_count == N // 2 and w_count < N // 2:
                    for c in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == N // 2 and b_count < N // 2:
                    for c in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # Rule 3 for cols
            for c in range(N):
                col_cells = [g[r][c] for r in range(N)]
                b_count = col_cells.count('B')
                w_count = col_cells.count('W')
                if b_count == N // 2 and w_count < N // 2:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == N // 2 and b_count < N // 2:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # Rule 5: Uniqueness (Rows)
            full_rows = [g[r] for r in range(N) if None not in g[r]]
            for r in range(N):
                if g[r].count(None) == 2:
                    indices = [c for c in range(N) if g[r][c] is None]
                    b_count = g[r].count('B')
                    w_count = g[r].count('W')
                    if b_count == N // 2 - 1 and w_count == N // 2 - 1:
                        test_row_1 = list(g[r])
                        test_row_1[indices[0]] = 'B'
                        test_row_1[indices[1]] = 'W'

                        test_row_2 = list(g[r])
                        test_row_2[indices[0]] = 'W'
                        test_row_2[indices[1]] = 'B'

                        if test_row_1 in full_rows:
                            g[r][indices[0]] = 'W'
                            g[r][indices[1]] = 'B'
                            changed = True
                        elif test_row_2 in full_rows:
                            g[r][indices[0]] = 'B'
                            g[r][indices[1]] = 'W'
                            changed = True

            # Rule 5: Uniqueness (Cols)
            full_cols = [[g[r][c] for r in range(N)] for c in range(N) if None not in [g[r][c] for r in range(N)]]
            for c in range(N):
                col_cells = [g[r][c] for r in range(N)]
                if col_cells.count(None) == 2:
                    indices = [r for r in range(N) if g[r][c] is None]
                    b_count = col_cells.count('B')
                    w_count = col_cells.count('W')
                    if b_count == N // 2 - 1 and w_count == N // 2 - 1:
                        test_col_1 = list(col_cells)
                        test_col_1[indices[0]] = 'B'
                        test_col_1[indices[1]] = 'W'

                        test_col_2 = list(col_cells)
                        test_col_2[indices[0]] = 'W'
                        test_col_2[indices[1]] = 'B'

                        if test_col_1 in full_cols:
                            g[indices[0]][c] = 'W'
                            g[indices[1]][c] = 'B'
                            changed = True
                        elif test_col_2 in full_cols:
                            g[indices[0]][c] = 'B'
                            g[indices[1]][c] = 'W'
                            changed = True

        return g

    def solve_recursive(g):
        if not is_valid(g):
            return None

        g_copy = copy.deepcopy(g)
        g_copy = propagate(g_copy)

        if not is_valid(g_copy):
            return None

        is_solved = True
        for r in range(len(g_copy)):
            if None in g_copy[r]:
                is_solved = False
                break

        if is_solved:
            return g_copy

        # Heuristic: pick the empty cell in the most constrained row/col
        best_r, best_c = -1, -1
        max_filled = -1
        N = len(g_copy)
        for r in range(N):
            for c in range(N):
                if g_copy[r][c] is None:
                    filled_r = N - g_copy[r].count(None)
                    filled_c = N - [g_copy[i][c] for i in range(N)].count(None)
                    if filled_r + filled_c > max_filled:
                        max_filled = filled_r + filled_c
                        best_r, best_c = r, c

        if best_r != -1:
            for guess in ['B', 'W']:
                g_copy[best_r][best_c] = guess
                result = solve_recursive(g_copy)
                if result is not None:
                    return result
                g_copy[best_r][best_c] = None # backtrack

        return None

    solution = solve_recursive(grid)
    if solution:
        return solution
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
