def solve(observation):
    grid = [row[:] for row in observation['data']]
    N = len(grid)

    def check_connectivity(g, color):
        """
        Checks if all cells of the given color can potentially form a single 
        connected component using the currently available (color or None) cells.
        """
        allowed = {color, None}
        start_cell = None
        total_color = 0
        for r in range(N):
            for c in range(N):
                if g[r][c] == color:
                    if start_cell is None:
                        start_cell = (r, c)
                    total_color += 1

        if total_color <= 1:
            return True

        visited = set([start_cell])
        q = [start_cell]
        reached_color = 1

        while q:
            curr_r, curr_c = q.pop(0)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if g[nr][nc] in allowed and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
                        if g[nr][nc] == color:
                            reached_color += 1

        return reached_color == total_color

    def deduce(g):
        """
        Applies strict logical deductions to reduce the search space.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. 2x2 Rule: No 2x2 area can be monochromatic.
            for r in range(N - 1):
                for c in range(N - 1):
                    cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                    colors = [g[nr][nc] for nr, nc in cells]
                    b_count = colors.count('B')
                    w_count = colors.count('W')

                    if b_count == 4 or w_count == 4:
                        return False # Contradiction: 2x2 monochromatic square

                    if b_count == 3 and w_count == 0:
                        for nr, nc in cells:
                            if g[nr][nc] is None:
                                g[nr][nc] = 'W'
                                changed = True

                    if w_count == 3 and b_count == 0:
                        for nr, nc in cells:
                            if g[nr][nc] is None:
                                g[nr][nc] = 'B'
                                changed = True

            # 2. Unreachable Component Rule: 
            # If a connected component of (Color U None) contains no actual Color cells,
            # then none of its cells can be Color (they would be isolated). Thus, they must be OppColor.
            for color, opp_color in [('B', 'W'), ('W', 'B')]:
                allowed = {color, None}
                visited = set()
                components = []

                for r in range(N):
                    for c in range(N):
                        if g[r][c] in allowed and (r, c) not in visited:
                            comp = []
                            q = [(r, c)]
                            visited.add((r, c))
                            has_color = False

                            while q:
                                curr_r, curr_c = q.pop(0)
                                comp.append((curr_r, curr_c))
                                if g[curr_r][curr_c] == color:
                                    has_color = True

                                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                    nr, nc = curr_r + dr, curr_c + dc
                                    if 0 <= nr < N and 0 <= nc < N:
                                        if g[nr][nc] in allowed and (nr, nc) not in visited:
                                            visited.add((nr, nc))
                                            q.append((nr, nc))

                            components.append((comp, has_color))

                color_comps = [comp for comp, has_color in components if has_color]
                if len(color_comps) > 1:
                    return False # Contradiction: Multiple disconnected components of the same color

                if len(color_comps) == 1:
                    for comp, has_color in components:
                        if not has_color:
                            for r, c in comp:
                                if g[r][c] is None:
                                    g[r][c] = opp_color
                                    changed = True

            # 3. Articulation Point Rule (Must-Connect):
            # If setting an empty cell to Color A disconnects Color B, it MUST be Color B.
            for r in range(N):
                for c in range(N):
                    if g[r][c] is None:
                        g[r][c] = 'W'
                        b_valid = check_connectivity(g, 'B')
                        g[r][c] = 'B'
                        w_valid = check_connectivity(g, 'W')
                        g[r][c] = None

                        if not b_valid and not w_valid:
                            return False # Contradiction: Cell cannot be B or W
                        elif not b_valid:
                            g[r][c] = 'B'
                            changed = True
                        elif not w_valid:
                            g[r][c] = 'W'
                            changed = True

        return True

    def solve_recursive(g):
        # Apply deductions first
        if not deduce(g):
            return None

        # Find the most constrained empty cell to branch on
        best_cell = None
        max_score = -1

        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    score = 0
                    # Orthogonal neighbors are more restrictive
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N and g[nr][nc] is not None:
                            score += 2
                    # Diagonal neighbors also provide constraints (especially for 2x2 rule)
                    for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N and g[nr][nc] is not None:
                            score += 1

                    if score > max_score:
                        max_score = score
                        best_cell = (r, c)

        # If no empty cells are left, the puzzle is solved
        if best_cell is None:
            return g

        r, c = best_cell

        # Simple heuristic: try the color that might prevent 2x2 blocks (opposite of majority neighbor)
        b_neighbors = sum(1 for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if 0 <= r+dr < N and 0 <= c+dc < N and g[r+dr][c+dc] == 'B')
        w_neighbors = sum(1 for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] if 0 <= r+dr < N and 0 <= c+dc < N and g[r+dr][c+dc] == 'W')

        colors_to_try = ['W', 'B'] if b_neighbors > w_neighbors else ['B', 'W']

        for color in colors_to_try:
            new_g = [row[:] for row in g]
            new_g[r][c] = color
            result = solve_recursive(new_g)
            if result is not None:
                return result

        return None

    solution = solve_recursive(grid)
    if solution:
        return solution
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
