def solve(observation):
    data = observation['data']
    N = len(data)
    dots = set(tuple(x) for x in observation['adjacent'])

    # Initialize domains for each cell
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def get_neighbors(r, c):
        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < N-1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < N-1: neighbors.append((r, c+1))
        return neighbors

    def has_dot(r1, c1, r2, c2):
        mid_r = (r1 + r2) / 2.0
        mid_c = (c1 + c2) / 2.0
        return (mid_r, mid_c) in dots

    def propagate(current_domains):
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if len(current_domains[r][c]) == 0:
                        return False

                    # Naked Singles: If a cell has only one possible value, remove it from its row and column
                    if len(current_domains[r][c]) == 1:
                        val = list(current_domains[r][c])[0]
                        for i in range(N):
                            if i != c and val in current_domains[r][i]:
                                current_domains[r][i].remove(val)
                                changed = True
                            if i != r and val in current_domains[i][c]:
                                current_domains[i][c].remove(val)
                                changed = True

                    # Dot Constraints
                    for nr, nc in get_neighbors(r, c):
                        if has_dot(r, c, nr, nc):
                            # Must be consecutive
                            new_domain = set()
                            for v in current_domains[r][c]:
                                if (v-1 in current_domains[nr][nc]) or (v+1 in current_domains[nr][nc]):
                                    new_domain.add(v)
                            if len(new_domain) < len(current_domains[r][c]):
                                current_domains[r][c] = new_domain
                                changed = True
                        else:
                            # Must NOT be consecutive
                            new_domain = set()
                            for v in current_domains[r][c]:
                                # Keep v if there is at least one value in the neighbor's domain that is NOT consecutive to v
                                if not current_domains[nr][nc].issubset({v-1, v+1}):
                                    new_domain.add(v)
                            if len(new_domain) < len(current_domains[r][c]):
                                current_domains[r][c] = new_domain
                                changed = True

            # Hidden Singles in Rows
            for r in range(N):
                for val in range(1, N + 1):
                    possible_cols = [c for c in range(N) if val in current_domains[r][c]]
                    if len(possible_cols) == 0:
                        return False
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(current_domains[r][c]) > 1:
                            current_domains[r][c] = {val}
                            changed = True

            # Hidden Singles in Columns
            for c in range(N):
                for val in range(1, N + 1):
                    possible_rows = [r for r in range(N) if val in current_domains[r][c]]
                    if len(possible_rows) == 0:
                        return False
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(current_domains[r][c]) > 1:
                            current_domains[r][c] = {val}
                            changed = True

        # Final check for empty domains after propagation
        for r in range(N):
            for c in range(N):
                if len(current_domains[r][c]) == 0:
                    return False
        return True

    def backtrack(current_domains):
        # Propagate constraints
        if not propagate(current_domains):
            return None

        # Find the unassigned cell with the minimum remaining values (MRV heuristic)
        min_len = float('inf')
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(current_domains[r][c]) > 1:
                    if len(current_domains[r][c]) < min_len:
                        min_len = len(current_domains[r][c])
                        best_cell = (r, c)

        # If all cells are assigned, we found a solution
        if best_cell is None:
            return [[list(current_domains[r][c])[0] for c in range(N)] for r in range(N)]

        r, c = best_cell
        # Try all possible values for the selected cell
        for val in list(current_domains[r][c]):
            # Create a deep copy of domains for the recursive call
            new_domains = [[set(d) for d in row] for row in current_domains]
            new_domains[r][c] = {val}
            result = backtrack(new_domains)
            if result:
                return result

        return None

    ans = backtrack(domains)
    return ans if ans else "No Solution"

