OBSERVATION = {'data': [[None, 2, None, 3, None, 1, None], [2, None, None, None, None, None, None], [None, None, None, None, 4, None, 4], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, 2, None, None], [3, None, None, 3, None, None, 3]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Parse islands
    islands = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                islands[(r, c)] = data[r][c]

    if not islands:
        return {}

    # Find all potential valid edges (orthogonal, not passing through islands)
    potential_edges = []

    # Horizontal edges
    for r in range(R):
        prev_c = -1
        for c in range(C):
            if (r, c) in islands:
                if prev_c != -1:
                    potential_edges.append(((r, prev_c), (r, c)))
                prev_c = c

    # Vertical edges
    for c in range(C):
        prev_r = -1
        for r in range(R):
            if (r, c) in islands:
                if prev_r != -1:
                    potential_edges.append(((prev_r, c), (r, c)))
                prev_r = r

    E = len(potential_edges)

    # Precompute crossings between potential edges
    crossings = {i: [] for i in range(E)}
    for i in range(E):
        u1, v1 = potential_edges[i]
        for j in range(i + 1, E):
            u2, v2 = potential_edges[j]
            is_h1 = u1[0] == v1[0]
            is_h2 = u2[0] == v2[0]

            # Only horizontal and vertical edges can cross
            if is_h1 != is_h2:
                if is_h1:
                    h_edge, v_edge = potential_edges[i], potential_edges[j]
                else:
                    h_edge, v_edge = potential_edges[j], potential_edges[i]

                r_h, c1_h, c2_h = h_edge[0][0], h_edge[0][1], h_edge[1][1]
                c_v, r1_v, r2_v = v_edge[0][1], v_edge[0][0], v_edge[1][0]

                # Check if they intersect
                if r1_v < r_h < r2_v and c1_h < c_v < c2_h:
                    crossings[i].append(j)
                    crossings[j].append(i)

    # Precompute incident edges for each island
    incident = {isl: [] for isl in islands}
    for i, (u, v) in enumerate(potential_edges):
        incident[u].append(i)
        incident[v].append(i)

    # Constraint propagation to reduce domains
    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1. Island capacity constraints
            for isl, req in islands.items():
                inc = incident[isl]

                for i in inc:
                    dom = domains[i]
                    new_dom = []
                    for val in dom:
                        # Calculate min and max possible bridges from OTHER incident edges
                        min_others = sum(domains[j][0] for j in inc if j != i)
                        max_others = sum(domains[j][-1] for j in inc if j != i)

                        # Check if assigning 'val' to edge 'i' leaves a valid remaining requirement
                        if min_others <= req - val <= max_others:
                            new_dom.append(val)

                    if len(new_dom) < len(dom):
                        domains[i] = new_dom
                        changed = True

                    if not domains[i]:
                        return False # Domain wiped out, invalid state

            # 2. Crossing constraints
            for i in range(E):
                if domains[i] == [0]:
                    continue
                # If edge i MUST have at least 1 bridge
                if domains[i][0] > 0:
                    for j in crossings[i]:
                        if domains[j] != [0]:
                            if 0 in domains[j]:
                                domains[j] = [0] # Crossing edge MUST have 0 bridges
                                changed = True
                            else:
                                return False # Contradiction
        return True

    # Backtracking search with Minimum Remaining Values (MRV) heuristic
    def solve_bt(domains):
        if not propagate(domains):
            return None

        # Find the most constrained unassigned edge
        best_i = -1
        min_len = 4
        for i in range(E):
            if len(domains[i]) > 1:
                if len(domains[i]) < min_len:
                    min_len = len(domains[i])
                    best_i = i

        # If all edges are assigned, check global connectivity
        if best_i == -1:
            adj = {isl: [] for isl in islands}
            for i, (u, v) in enumerate(potential_edges):
                if domains[i][0] > 0:
                    adj[u].append(v)
                    adj[v].append(u)

            start = list(islands.keys())[0]
            visited = set([start])
            q = [start]
            while q:
                curr = q.pop(0)
                for nxt in adj[curr]:
                    if nxt not in visited:
                        visited.add(nxt)
                        q.append(nxt)

            if len(visited) == len(islands):
                return domains
            return None

        # Branch on the chosen edge
        for val in domains[best_i]:
            new_domains = [list(d) for d in domains]
            new_domains[best_i] = [val]
            res = solve_bt(new_domains)
            if res is not None:
                return res

        return None

    # Initial domains: each edge can have 0, 1, or 2 bridges
    initial_domains = [[0, 1, 2] for _ in range(E)]

    result_domains = solve_bt(initial_domains)

    if result_domains is None:
        return "No Solution"

    # Format the answer
    ans = {}
    for i, (u, v) in enumerate(potential_edges):
        val = result_domains[i][0]
        if val > 0:
            ans[(u, v)] = val

    return ans

