def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Initialize state grid
    # -1: unknown, 0: safe, 1: mine
    initial_state = [[-1 for _ in range(C)] for _ in range(R)]

    # Numbered cells are inherently safe (not mines)
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
