    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighbors.append((nr, nc))
        return neighbors

    def propagate(state):
        """
        Applies human-like deductive rules to aggressively prune the search space.
        Returns True if the state is valid (so far), False if a contradiction is found.
        """
        changed = True
        while changed:
            changed = False

            # Rule 1 & 2: Basic constraint satisfaction for each numbered cell
            for r in range(R):
                for c in range(C):
                    if data[r][c] is not None:
                        k = data[r][c]
                        neighbors = get_neighbors(r, c)
                        unknowns = []
                        mines = 0
                        for nr, nc in neighbors:
                            if state[nr][nc] == 1:
                                mines += 1
                            elif state[nr][nc] == -1:
                                unknowns.append((nr, nc))

                        # Contradiction: too many mines
                        if mines > k:
                            return False

                        if len(unknowns) == 0:
                            # Contradiction: not enough mines and no unknowns left
                            if mines != k:
                                return False
                        else:
                            # Rule 1: If current mines equal the clue, all remaining unknowns are safe
                            if mines == k:
                                for nr, nc in unknowns:
                                    state[nr][nc] = 0
                                    changed = True
                            # Rule 2: If current mines + unknowns equal the clue, all unknowns must be mines
                            elif mines + len(unknowns) == k:
                                for nr, nc in unknowns:
                                    state[nr][nc] = 1
                                    changed = True
                            # Contradiction: even if all unknowns are mines, we can't reach the clue
                            elif mines + len(unknowns) < k:
                                return False

            if changed:
                continue

            # Rule 3: Subset rules (e.g., 1-2 pattern deduction)
            # Collect all active constraints
            constraints = []
            for r in range(R):
                for c in range(C):
                    if data[r][c] is not None:
                        k = data[r][c]
                        neighbors = get_neighbors(r, c)
                        unknowns = set()
                        mines = 0
                        for nr, nc in neighbors:
                            if state[nr][nc] == 1:
                                mines += 1
                            elif state[nr][nc] == -1:
                                unknowns.add((nr, nc))
                        if len(unknowns) > 0:
                            constraints.append((unknowns, k - mines))

            # Compare pairs of constraints to find subsets
            for i in range(len(constraints)):
                for j in range(len(constraints)):
                    if i == j:
                        continue
                    U_A, req_A = constraints[i]
                    U_B, req_B = constraints[j]

                    # If U_A is a proper subset of U_B
                    if U_A and U_B and U_A.issubset(U_B) and U_A != U_B:
                        diff = U_B - U_A
                        req_diff = req_B - req_A

                        # Contradiction in subset logic
                        if req_diff < 0 or req_diff > len(diff):
                            return False

                        # If the remaining required mines exactly match the remaining cells
                        if req_diff == len(diff):
                            for nr, nc in diff:
                                if state[nr][nc] == -1:
                                    state[nr][nc] = 1
                                    changed = True
                        # If no more mines are required from the remaining cells
                        elif req_diff == 0:
                            for nr, nc in diff:
                                if state[nr][nc] == -1:
                                    state[nr][nc] = 0
                                    changed = True

        return True

    def solve_backtrack(state):
        """
        Backtracking search with aggressive constraint propagation.
        """
        # Apply deductions; if contradiction, prune this branch
        if not propagate(state):
            return None

        # Find the most constrained unknown cell to branch on
        best_cell = None
        max_adj_numbers = -1
        for r in range(R):
            for c in range(C):
                if state[r][c] == -1:
                    # Heuristic: prioritize cells adjacent to the most numbered clues
                    adj_numbers = sum(1 for nr, nc in get_neighbors(r, c) if data[nr][nc] is not None)
                    if adj_numbers > max_adj_numbers:
                        max_adj_numbers = adj_numbers
                        best_cell = (r, c)

        # If no unknown cells remain, we found a solution
        if not best_cell:
            return state

        r, c = best_cell

        # Branch 1: Assume it's a mine
        state_copy = [row[:] for row in state]
        state_copy[r][c] = 1
        res = solve_backtrack(state_copy)
        if res is not None:
            return res

        # Branch 2: Assume it's safe
        state_copy = [row[:] for row in state]
        state_copy[r][c] = 0
        res = solve_backtrack(state_copy)
        if res is not None:
            return res

        return None

    final_state = solve_backtrack(initial_state)

    if final_state is None:
        return "No Solution"

    # Format the output grid
    ans = []
    for r in range(R):
        row = []
        for c in range(C):
            if final_state[r][c] == 1:
                row.append('F')
            else:
                row.append(None)
        ans.append(row)

    return ans

