            if assigned_var in c['scope']:
                new_scope = c['scope'] - {assigned_var}
                new_needed = c['needed'] - val
                if new_needed < 0 or new_needed > len(new_scope):
                    return None # Contradiction detected
                if len(new_scope) > 0:
                    new_constraints.append({'scope': new_scope, 'needed': new_needed})
            else:
                new_constraints.append(c)
        return new_constraints

    def simplify(current_constraints, current_assignment):
        """Applies human-like deduction rules (forcing and subset rules) to simplify constraints."""
        current_constraints = list(current_constraints)
        changed = True
        while changed:
            changed = False
            forced = {}

            # Rule 1: Basic forcing (all mines or no mines)
            for c in current_constraints:
                if c['needed'] == 0:
                    for v in c['scope']:
                        if v not in forced:
                            forced[v] = 0
                        elif forced[v] != 0:
                            return None, None
                elif c['needed'] == len(c['scope']):
                    for v in c['scope']:
                        if v not in forced:
                            forced[v] = 1
                        elif forced[v] != 1:
                            return None, None

            if forced:
                changed = True
                for v, val in forced.items():
                    current_assignment[v] = val
                    current_constraints = propagate(v, val, current_constraints)
                    if current_constraints is None:
                        return None, None
                continue

            # Clean up constraints to remove duplicates and detect contradictions
            cleaned_constraints = []
            scope_to_needed = {}
            for c in current_constraints:
                if len(c['scope']) > 0:
                    fs = frozenset(c['scope'])
                    if fs in scope_to_needed:
                        if scope_to_needed[fs] != c['needed']:
                            return None, None
                    else:
                        scope_to_needed[fs] = c['needed']
                        cleaned_constraints.append(c)
