    edges = []
    # Find all valid horizontal edges between adjacent islands
    for r in range(R):
        prev_c = -1
        for c in range(C):
            if (r, c) in islands:
                if prev_c != -1:
                    edges.append(((r, prev_c), (r, c)))
                prev_c = c

    # Find all valid vertical edges between adjacent islands
    for c in range(C):
        prev_r = -1
        for r in range(R):
            if (r, c) in islands:
                if prev_r != -1:
                    edges.append(((prev_r, c), (r, c)))
                prev_r = r

    # Identify all pairs of edges that cross each other
    crossings = []
    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            e1 = edges[i]
            e2 = edges[j]
            # e1 horizontal, e2 vertical
            if e1[0][0] == e1[1][0] and e2[0][1] == e2[1][1]:
                r1, c1 = e1[0]
                _, c2 = e1[1]
                r3, c3 = e2[0]
                r4, _ = e2[1]
                if r3 < r1 < r4 and c1 < c3 < c2:
                    crossings.append((e1, e2))
