    domains = {e: [0, 1, 2] for e in edges}
    for e in edges:
        req1 = islands[e[0]]
        req2 = islands[e[1]]
        domains[e] = [x for x in domains[e] if x <= req1 and x <= req2]

    def propagate(current_domains):
        """
        Aggressively prune domains based on island requirements and crossing constraints.
        """
        changed = True
        while changed:
            changed = False

            # Constraint 1: Island bridge requirements
            for u, req in islands.items():
                incident = [e for e in edges if u in e]
                for e in incident:
                    # Calculate min and max bridges that OTHER incident edges can provide
                    min_other = sum(min(current_domains[o]) for o in incident if o != e)
                    max_other = sum(max(current_domains[o]) for o in incident if o != e)

                    # The current edge must make up the difference to reach exactly 'req'
                    new_domain = [x for x in current_domains[e] if req - max_other <= x <= req - min_other]

                    if len(new_domain) < len(current_domains[e]):
                        current_domains[e] = new_domain
                        changed = True
                        if not current_domains[e]:
