        """
        adj = {u: [] for u in islands}
        for e in edges:
            if max(current_domains[e]) > 0:
                adj[e[0]].append(e[1])
                adj[e[1]].append(e[0])

        start_node = list(islands.keys())[0]
        visited = set()
        q = [start_node]
        visited.add(start_node)
        while q:
            curr = q.pop(0)
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)
        return len(visited) == len(islands)

    def is_connected(current_domains):
        """
        Check if the definitively assigned graph is fully connected.
        """
        adj = {u: [] for u in islands}
        for e in edges:
            if min(current_domains[e]) > 0:
                adj[e[0]].append(e[1])
                adj[e[1]].append(e[0])

        start_node = list(islands.keys())[0]
        visited = set()
