    def backtrack(current_domains):
        # Apply constraint propagation
        if not propagate(current_domains):
            return None

        # Prune if the graph is already disconnected beyond repair
        if not can_be_connected(current_domains):
            return None

        # Check if we have a complete assignment
        all_assigned = all(len(d) == 1 for d in current_domains.values())
        if all_assigned:
