                best_e = e

        # Try assigning values (larger values first often finds solutions faster in Hashi)
        for val in sorted(current_domains[best_e], reverse=True):
            new_domains = copy.deepcopy(current_domains)
            new_domains[best_e] = [val]
            res = backtrack(new_domains)
            if res:
                return res

        return None

    result_domains = backtrack(domains)
    if result_domains:
        ans = {}
        for e, d in result_domains.items():
            if d[0] > 0:
                ans[e] = d[0]
        return ans
    return "No Solution"

