class AkariSolver:
    def __init__(self, data):
        self.R = len(data)
        self.C = len(data[0])
        self.grid = data
        self.white_cells = []
        self.numbered_walls = {}

        # Parse grid
        for r in range(self.R):
            for c in range(self.C):
                if self.grid[r][c] is None:
                    self.white_cells.append((r, c))
                elif self.grid[r][c] >= 0:
                    self.numbered_walls[(r, c)] = self.grid[r][c]

        # Precompute visible cells for each white cell (line of sight)
        self.visible_from = {}
        for r, c in self.white_cells:
            vis = [(r, c)]
            # Up
            for i in range(r - 1, -1, -1):
                if self.grid[i][c] is not None: break
                vis.append((i, c))
            # Down
            for i in range(r + 1, self.R):
                if self.grid[i][c] is not None: break
                vis.append((i, c))
            # Left
            for j in range(c - 1, -1, -1):
                if self.grid[r][j] is not None: break
                vis.append((r, j))
            # Right
            for j in range(c + 1, self.C):
                if self.grid[r][j] is not None: break
                vis.append((r, j))
            self.visible_from[(r, c)] = vis

        # Precompute adjacent white cells for numbered walls
        self.wall_adj = {}
        for (r, c), n in self.numbered_walls.items():
            adj = []
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < self.R and 0 <= nc < self.C and self.grid[nr][nc] is None:
                    adj.append((nr, nc))
            self.wall_adj[(r, c)] = adj

    def solve(self):
        # Start backtracking with empty sets of bulbs and crossed-out cells
        return self.backtrack(set(), set())

    def backtrack(self, bulbs, crosses):
        # 1. Constraint Propagation (Human-like deduction)
        changed = True
        while changed:
            changed = False

            # Rule A: Numbered Wall Constraints
            for wall, n in self.numbered_walls.items():
                adj = self.wall_adj[wall]
                b_count = sum(1 for cell in adj if cell in bulbs)
                u_cells = [cell for cell in adj if cell not in bulbs and cell not in crosses]

                if b_count > n: 
                    return None # Too many bulbs
                if b_count + len(u_cells) < n: 
                    return None # Not enough space for required bulbs

                if b_count == n and u_cells:
                    # Wall satisfied, cross out remaining adjacent cells
                    for cell in u_cells:
                        crosses.add(cell)
                    changed = True
                    break
                elif b_count + len(u_cells) == n and u_cells:
                    # Must place bulbs in all remaining adjacent cells
                    for cell in u_cells:
                        if cell in crosses: return None # Contradiction
                        bulbs.add(cell)
                        # Placing a bulb crosses out all visible cells
                        for v_cell in self.visible_from[cell]:
                            if v_cell != cell:
                                if v_cell in bulbs: return None # Bulbs see each other
                                crosses.add(v_cell)
                    changed = True
                    break

            if changed: continue

            # Rule B: Illumination Constraints
            lit_cells = set()
            for b in bulbs:
                lit_cells.update(self.visible_from[b])

            for cell in self.white_cells:
                if cell not in lit_cells:
                    possible_bulbs = [v for v in self.visible_from[cell] if v not in crosses]
                    if len(possible_bulbs) == 0:
                        return None # Cell cannot be lit
                    if len(possible_bulbs) == 1:
                        # Only one valid spot to light this cell
                        pb = possible_bulbs[0]
                        if pb not in bulbs:
                            bulbs.add(pb)
                            for v_cell in self.visible_from[pb]:
                                if v_cell != pb:
                                    if v_cell in bulbs: return None
                                    crosses.add(v_cell)
                            changed = True
                            break

        # 2. Check if solved
        lit_cells = set()
        for b in bulbs:
            lit_cells.update(self.visible_from[b])

        if len(lit_cells) == len(self.white_cells):
            # Verify all wall constraints are strictly met
            for wall, n in self.numbered_walls.items():
                if sum(1 for cell in self.wall_adj[wall] if cell in bulbs) != n:
                    return None
            return bulbs

        # 3. Branching (Guessing with heuristic)
        # Pick an unlit cell with the fewest possible bulb locations
        best_cell = None
        min_options = float('inf')
        best_options = []

        for cell in self.white_cells:
            if cell not in lit_cells:
                possible_bulbs = [v for v in self.visible_from[cell] if v not in crosses]
                if len(possible_bulbs) < min_options:
                    min_options = len(possible_bulbs)
                    best_cell = cell
                    best_options = possible_bulbs

        if best_cell is None:
            return None

        # Try each possible bulb location for the chosen cell
        for option in best_options:
            new_bulbs = set(bulbs)
            new_crosses = set(crosses)

            new_bulbs.add(option)
            for v_cell in self.visible_from[option]:
                if v_cell != option:
                    new_crosses.add(v_cell)

            result = self.backtrack(new_bulbs, new_crosses)
            if result is not None:
                return result

        return None

def solve(observation):
    data = observation['data']
    solver = AkariSolver(data)
    result = solver.solve()

    if result is None:
        return "No Solution"

    # Format output as requested: N x N grid with 'B' for bulbs, None otherwise
    ans = [[None for _ in range(solver.C)] for _ in range(solver.R)]
    for r, c in result:
        ans[r][c] = 'B'

    return ans

