class AkariSolver:
    def __init__(self, data):
        self.N = len(data)
        self.data = data
        # State representation:
        # 0: EMPTY (can place bulb)
        # 1: BULB
        # 2: CROSS (illuminated or crossed out by numbered cell constraint)
        # 3: BLACK (wall)
        self.state = [[0 for _ in range(self.N)] for _ in range(self.N)]
        self.numbered = {}
        self.white_cells = []

        for r in range(self.N):
            for c in range(self.N):
                if data[r][c] is None:
                    self.white_cells.append((r, c))
                else:
                    self.state[r][c] = 3
                    if data[r][c] != -1:
                        self.numbered[(r, c)] = data[r][c]

        # Precompute visibility for each white cell to optimize propagation
        self.visibility = {}
        for r, c in self.white_cells:
            self.visibility[(r, c)] = self.compute_visibility(r, c)

    def compute_visibility(self, r, c):
        vis = [(r, c)]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            while 0 <= nr < self.N and 0 <= nc < self.N and self.data[nr][nc] is None:
                vis.append((nr, nc))
                nr += dr
                nc += dc
        return vis

    def place_bulb(self, r, c):
        # Cannot place a bulb on a non-empty cell
        if self.state[r][c] != 0:
            return False

        # Check if placing a bulb here would illuminate another bulb
        for vr, vc in self.visibility[(r, c)]:
            if self.state[vr][vc] == 1:
                return False

        # Place the bulb and cross out all visible cells
        self.state[r][c] = 1
        for vr, vc in self.visibility[(r, c)]:
            if (vr, vc) != (r, c):
                self.state[vr][vc] = 2
        return True

    def propagate(self):
        changed = True
        while changed:
            changed = False

            # Rule 1: Numbered cell constraints
            for (r, c), target in self.numbered.items():
                bulbs = 0
                empty = []
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < self.N and 0 <= nc < self.N:
                        if self.state[nr][nc] == 1:
                            bulbs += 1
                        elif self.state[nr][nc] == 0:
                            empty.append((nr, nc))

                # Too many bulbs around the numbered cell
                if bulbs > target:
                    return False
                # Not enough available spaces to satisfy the numbered cell
                if bulbs + len(empty) < target:
                    return False

                # If exactly satisfied, cross out remaining empty adjacent cells
                if bulbs == target and len(empty) > 0:
                    for nr, nc in empty:
                        self.state[nr][nc] = 2
                        changed = True
                # If all remaining empty cells must be bulbs to satisfy the target
                elif bulbs + len(empty) == target and len(empty) > 0:
                    for nr, nc in empty:
                        if not self.place_bulb(nr, nc):
                            return False
                        changed = True

            # Rule 2: Unilluminated cell constraints
            for r, c in self.white_cells:
                illuminated = False
                for vr, vc in self.visibility[(r, c)]:
                    if self.state[vr][vc] == 1:
                        illuminated = True
                        break

                if not illuminated:
                    possible_bulbs = []
                    for vr, vc in self.visibility[(r, c)]:
                        if self.state[vr][vc] == 0:
                            possible_bulbs.append((vr, vc))

                    # If an unilluminated cell cannot be illuminated by any available cell
                    if len(possible_bulbs) == 0:
                        return False
                    # If there is only one possible cell that can illuminate it, a bulb MUST be placed there
                    if len(possible_bulbs) == 1:
                        br, bc = possible_bulbs[0]
                        if not self.place_bulb(br, bc):
                            return False
                        changed = True
        return True

    def backtrack(self):
        unilluminated_cells = []
        for r, c in self.white_cells:
            illuminated = False
            for vr, vc in self.visibility[(r, c)]:
                if self.state[vr][vc] == 1:
                    illuminated = True
                    break
            if not illuminated:
                options = [ (vr, vc) for vr, vc in self.visibility[(r, c)] if self.state[vr][vc] == 0 ]
                unilluminated_cells.append( (len(options), (r, c), options) )

        if unilluminated_cells:
            # MRV (Minimum Remaining Values) heuristic: branch on the cell with the fewest options
            unilluminated_cells.sort()
            _, target_cell, options = unilluminated_cells[0]

            for opt_r, opt_c in options:
                saved_state = [row[:] for row in self.state]
                if self.place_bulb(opt_r, opt_c):
                    if self.propagate():
                        if self.backtrack():
                            return True
                self.state = [row[:] for row in saved_state]
            return False
        else:
            # All white cells are illuminated. Verify all numbered cells are exactly satisfied.
            for (r, c), target in self.numbered.items():
                bulbs = sum(1 for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                            if 0 <= r+dr < self.N and 0 <= c+dc < self.N and self.state[r+dr][c+dc] == 1)
                if bulbs != target:
                    return False
            return True

    def solve(self):
        # Initial constraint propagation
        if not self.propagate():
            return "No Solution"

        # Backtracking search for remaining ambiguities
        if not self.backtrack():
            return "No Solution"

        # Format the final answer
        ans = [[None for _ in range(self.N)] for _ in range(self.N)]
        for r in range(self.N):
            for c in range(self.N):
                if self.state[r][c] == 1:
                    ans[r][c] = 'B'
        return ans

def solve(observation):
    solver = AkariSolver(observation['data'])
    return solver.solve()

