        D.append(rows + [R])

    # State grid: 1 for water, 0 for empty, -1 for unknown
    state = [[-1]*C for _ in range(R)]

    def propagate(current_D, current_state):
        changed = True
        while changed:
            changed = False

            # 1. Update state from domains
            for r in range(num_regions):
                if not current_D[r]: return False
                min_l = min(current_D[r])
                max_l = max(current_D[r])
                for i, j in cells[r]:
                    if i >= max_l and current_state[i][j] != 1:
                        current_state[i][j] = 1
                        changed = True
                    if i < min_l and current_state[i][j] != 0:
                        current_state[i][j] = 0
                        changed = True

            # 2. Update domains from state
            for r in range(num_regions):
                new_D = []
                for l in current_D[r]:
                    consistent = True
                    for i, j in cells[r]:
                        if current_state[i][j] == 1 and i < l:
                            consistent = False
                            break
                        if current_state[i][j] == 0 and i >= l:
                            consistent = False
                            break
                    if consistent:
                        new_D.append(l)
                if len(new_D) < len(current_D[r]):
                    current_D[r] = new_D
                    changed = True
                if not current_D[r]: return False

            # 3. Row clues
            for i in range(R):
                water = sum(1 for j in range(C) if current_state[i][j] == 1)
                empty = sum(1 for j in range(C) if current_state[i][j] == 0)
                unknown = C - water - empty
                if water > row_clues[i]: return False
                if water + unknown < row_clues[i]: return False
                if water == row_clues[i] and unknown > 0:
                    for j in range(C):
                        if current_state[i][j] == -1:
                            current_state[i][j] = 0
                            changed = True
                if water + unknown == row_clues[i] and unknown > 0:
                    for j in range(C):
                        if current_state[i][j] == -1:
                            current_state[i][j] = 1
                            changed = True

            # 4. Col clues
            for j in range(C):
                water = sum(1 for i in range(R) if current_state[i][j] == 1)
                empty = sum(1 for i in range(R) if current_state[i][j] == 0)
                unknown = R - water - empty
                if water > col_clues[j]: return False
                if water + unknown < col_clues[j]: return False
                if water == col_clues[j] and unknown > 0:
                    for i in range(R):
                        if current_state[i][j] == -1:
                            current_state[i][j] = 0
                            changed = True
                if water + unknown == col_clues[j] and unknown > 0:
                    for i in range(R):
                        if current_state[i][j] == -1:
                            current_state[i][j] = 1
                            changed = True

            # 5. Lookahead for domains (prune levels that immediately violate clues)
            for r in range(num_regions):
                if len(current_D[r]) > 1:
                    new_D = []
                    for l in current_D[r]:
                        valid = True

                        # Check row clues
                        for i in range(R):
                            added_water = 0
                            added_empty = 0
                            for r_i, c_i in cells[r]:
                                if r_i == i:
                                    if r_i >= l and current_state[r_i][c_i] != 1:
                                        added_water += 1
                                    elif r_i < l and current_state[r_i][c_i] != 0:
                                        added_empty += 1
                            if added_water > 0:
                                current_water = sum(1 for j in range(C) if current_state[i][j] == 1)
                                if current_water + added_water > row_clues[i]:
                                    valid = False
                                    break
                            if added_empty > 0:
                                current_empty = sum(1 for j in range(C) if current_state[i][j] == 0)
                                if current_empty + added_empty > C - row_clues[i]:
                                    valid = False
                                    break
                        if not valid:
                            continue

                        # Check col clues
                        for j in range(C):
                            added_water = 0
                            added_empty = 0
                            for r_i, c_i in cells[r]:
                                if c_i == j:
                                    if r_i >= l and current_state[r_i][c_i] != 1:
                                        added_water += 1
                                    elif r_i < l and current_state[r_i][c_i] != 0:
                                        added_empty += 1
                            if added_water > 0:
                                current_water = sum(1 for i in range(R) if current_state[i][j] == 1)
                                if current_water + added_water > col_clues[j]:
                                    valid = False
                                    break
                            if added_empty > 0:
                                current_empty = sum(1 for i in range(R) if current_state[i][j] == 0)
                                if current_empty + added_empty > R - col_clues[j]:
                                    valid = False
                                    break
                        if valid:
                            new_D.append(l)

                    if len(new_D) < len(current_D[r]):
                        current_D[r] = new_D
                        changed = True

        return True

    def search(current_D, current_state):
        if not propagate(current_D, current_state):
            return None

        # Check if solved
        solved = True
        for r in range(R):
            for c in range(C):
                if current_state[r][c] == -1:
                    solved = False
                    break
            if not solved:
                break

        if solved:
            return current_state

        # Find the most constrained region to branch on
        best_r = -1
        min_len = float('inf')
        for r in range(num_regions):
            if len(current_D[r]) > 1 and len(current_D[r]) < min_len:
                min_len = len(current_D[r])
                best_r = r

        if best_r == -1:
            return None

        # Branching
        for l in current_D[best_r]:
            next_D = copy.deepcopy(current_D)
            next_state = copy.deepcopy(current_state)
            next_D[best_r] = [l]
            result = search(next_D, next_state)
            if result:
                return result

        return None

    solution_state = search(D, state)

    if solution_state:
        ans = []
        for r in range(R):
            row_str = []
            for c in range(C):
                if solution_state[r][c] == 1:
                    row_str.append('W')
                else:
                    row_str.append(None)
            ans.append(row_str)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
