def solve(observation):
    """
    Solves a Hashiwokakero (Bridges) puzzle using constraint propagation and backtracking.
    Mimics human deduction by iteratively applying local constraints (island bridge counts,
    no-crossing rules) to reduce the domain of possible bridges for each edge.
    """
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Parse islands
    islands = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                islands[(r, c)] = data[r][c]

    # Identify all potential edges (connections between adjacent islands in same row/col)
    edges = []
    island_list = list(islands.keys())
    for i in range(len(island_list)):
        r1, c1 = island_list[i]
        # Look right for the nearest island
        for c2 in range(c1 + 1, C):
            if data[r1][c2] is not None:
                edges.append(((r1, c1), (r1, c2)))
                break
        # Look down for the nearest island
        for r2 in range(r1 + 1, R):
            if data[r2][c1] is not None:
                edges.append(((r1, c1), (r2, c1)))
                break

    # Map each island to its incident edges
    island_edges = {i: [] for i in islands}
    for e in edges:
        island_edges[e[0]].append(e)
        island_edges[e[1]].append(e)

    # Precompute crossing edges to enforce the no-crossing rule efficiently
    crossings = {e: [] for e in edges}
    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            e1 = edges[i]
            e2 = edges[j]
            # Check if e1 is horizontal and e2 is vertical
            if e1[0][0] == e1[1][0] and e2[0][1] == e2[1][1]:
                r = e1[0][0]
                c1, c2 = min(e1[0][1], e1[1][1]), max(e1[0][1], e1[1][1])
                c = e2[0][1]
                r1, r2 = min(e2[0][0], e2[1][0]), max(e2[0][0], e2[1][0])
                if r1 < r < r2 and c1 < c < c2:
                    crossings[e1].append(e2)
                    crossings[e2].append(e1)
            # Check if e2 is horizontal and e1 is vertical
            elif e2[0][0] == e2[1][0] and e1[0][1] == e1[1][1]:
                r = e2[0][0]
                c1, c2 = min(e2[0][1], e2[1][1]), max(e2[0][1], e2[1][1])
                c = e1[0][1]
                r1, r2 = min(e1[0][0], e1[1][0]), max(e1[0][0], e1[1][0])
                if r1 < r < r2 and c1 < c < c2:
                    crossings[e1].append(e2)
                    crossings[e2].append(e1)

    # Initial domain for each edge is [0, 1, 2] bridges
    domains = {e: [0, 1, 2] for e in edges}

    def propagate(domains):
        """
        Applies local constraints to prune the domains of edges.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Island capacity constraints
            for island, req in islands.items():
                inc_edges = island_edges[island]
                min_sum = sum(min(domains[e]) for e in inc_edges)
                max_sum = sum(max(domains[e]) for e in inc_edges)

                # If the required bridges cannot be met, state is invalid
                if min_sum > req or max_sum < req:
                    return False

                for e in inc_edges:
                    # Deduce the maximum and minimum possible bridges for edge 'e'
                    max_e = req - (min_sum - min(domains[e]))
                    min_e = req - (max_sum - max(domains[e]))

                    new_domain = [v for v in domains[e] if min_e <= v <= max_e]
                    if not new_domain:
                        return False
                    if len(new_domain) < len(domains[e]):
                        domains[e] = new_domain
                        changed = True

            # 2. No-crossing constraints
            for e, cross_edges in crossings.items():
                if min(domains[e]) > 0: # If edge 'e' definitely has at least 1 bridge
                    for ce in cross_edges:
                        if domains[ce] != [0]:
                            if 0 not in domains[ce]:
                                return False # Contradiction: crossing edge must also exist
                            domains[ce] = [0]
                            changed = True
        return True

    def check_connectivity(domains):
        """
        Checks if the current domains allow for a single connected component.
        Prunes states where isolated components are formed that cannot connect to the rest.
        """
        adj = {i: [] for i in islands}
        for e in edges:
            if max(domains[e]) > 0: # Consider all possible edges
                adj[e[0]].append(e[1])
                adj[e[1]].append(e[0])

        visited = set()
        components = []
        for i in islands:
            if i not in visited:
                comp = set()
                q = [i]
                visited.add(i)
                while q:
                    curr = q.pop(0)
                    comp.add(curr)
                    for neighbor in adj[curr]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            q.append(neighbor)
                components.append(comp)

        # If multiple components exist, check if any are "closed" (cannot connect outside)
        if len(components) > 1:
            for comp in components:
                can_connect_outside = False
                for i in comp:
                    for e in island_edges[i]:
                        other = e[0] if e[1] == i else e[1]
                        if other not in comp and max(domains[e]) > 0:
                            can_connect_outside = True
                            break
                    if can_connect_outside:
                        break
                if not can_connect_outside:
                    return False # Found an isolated component that doesn't include all islands
        return True

    def backtrack(domains):
        """
        Recursive backtracking search with constraint propagation.
        """
        if not propagate(domains):
            return None
        if not check_connectivity(domains):
            return None

        # Find edges that are not yet fully determined
        unassigned = [e for e in edges if len(domains[e]) > 1]

        if not unassigned:
            # All edges determined, perform final strict connectivity check
            adj = {i: [] for i in islands}
            for e in edges:
                if domains[e][0] > 0:
                    adj[e[0]].append(e[1])
                    adj[e[1]].append(e[0])
            visited = set()
            start = list(islands.keys())[0]
            q = [start]
            visited.add(start)
            while q:
                curr = q.pop(0)
                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        q.append(neighbor)
            if len(visited) == len(islands):
                return domains
            else:
                return None

        # Heuristic: Minimum Remaining Values (MRV)
        e = min(unassigned, key=lambda x: len(domains[x]))

        for val in domains[e]:
            # Create a deep copy of domains for the recursive branch
            new_domains = {k: v[:] for k, v in domains.items()}
            new_domains[e] = [val]
            result = backtrack(new_domains)
            if result:
                return result
        return None

    result_domains = backtrack(domains)

    if result_domains:
        ans = {}
        for e, dom in result_domains.items():
            if dom[0] > 0:
                ans[e] = dom[0]
        return ans
    return "No Solution"

