                elif g[i][j] == 'B': rb += 1
                if g[j][i] == 'W': cw += 1
                elif g[j][i] == 'B': cb += 1
            if rw > n // 2 or rb > n // 2 or cw > n // 2 or cb > n // 2: return False

        # Check for uniqueness of fully filled rows and columns
        rows = set()
        for r in g:
            if None not in r:
                tr = tuple(r)
                if tr in rows: return False
                rows.add(tr)

