        for j in range(n):
            col = tuple(g[i][j] for i in range(n))
            if None not in col:
                if col in cols: return False
                cols.add(col)

        return True

    def fast_deduce(g):
        changed = True
        while changed:
            changed = False

            # 1. Consecutive rules
