            # 3. Uniqueness rules (for rows/cols missing exactly 2 cells)
            for i in range(n):
                empty_cols = [j for j in range(n) if g[i][j] is None]
                if len(empty_cols) == 2:
                    for val1, val2 in [('W', 'B'), ('B', 'W')]:
