                            g[i][empty_cols[1]] = val1
                            changed = True
                            break

            for j in range(n):
                empty_rows = [i for i in range(n) if g[i][j] is None]
                if len(empty_rows) == 2:
                    for val1, val2 in [('W', 'B'), ('B', 'W')]:
                        g[empty_rows[0]][j] = val1
                        g[empty_rows[1]][j] = val2

                        is_duplicate = False
                        tc = tuple(g[r][j] for r in range(n))
