                                col_k = tuple(g[r][k] for r in range(n))
                                if None not in col_k and col_k == tc:
                                    is_duplicate = True
                                    break

                        g[empty_rows[0]][j] = None
                        g[empty_rows[1]][j] = None

                        if is_duplicate:
                            g[empty_rows[0]][j] = val2
                            g[empty_rows[1]][j] = val1
                            changed = True
                            break

            if not is_valid(g):
                return False

        return True

    def strong_deduce(g):
        # Lookahead deduction: try placing 'W' and 'B' and see if it leads to a contradiction
        changed = True
        while changed:
            if not fast_deduce(g):
                return False
            changed = False
            for i in range(n):
                for j in range(n):
                    if g[i][j] is None:
                        g[i][j] = 'W'
                        valid_w = is_valid(g)
                        if valid_w:
                            temp_g = [row[:] for row in g]
                            valid_w = fast_deduce(temp_g)

                        g[i][j] = 'B'
                        valid_b = is_valid(g)
                        if valid_b:
                            temp_g = [row[:] for row in g]
                            valid_b = fast_deduce(temp_g)

                        g[i][j] = None

                        if valid_w and not valid_b:
                            g[i][j] = 'W'
                            changed = True
                            break
                        elif valid_b and not valid_w:
                            g[i][j] = 'B'
                            changed = True
                            break
                        elif not valid_w and not valid_b:
                            return False
                if changed:
                    break
        return True

    def solve_bt(g):
        if not strong_deduce(g):
            return None

        best_cell = None
        for i in range(n):
            for j in range(n):
                if g[i][j] is None:
                    best_cell = (i, j)
                    break
            if best_cell:
                break

        if not best_cell:
            return g if is_valid(g) else None

        i, j = best_cell
        for val in ['W', 'B']:
            g[i][j] = val
            if is_valid(g):
                new_g = [row[:] for row in g]
                res = solve_bt(new_g)
                if res: return res
            g[i][j] = None

        return None

    res = solve_bt([row[:] for row in grid])
    return res if res else "No Solution"

