                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            for c in range(N):
                b_count = sum(1 for r in range(N) if g[r][c] == 'B')
                w_count = sum(1 for r in range(N) if g[r][c] == 'W')
                if b_count > N // 2 or w_count > N // 2:
                    return False
                if b_count == N // 2 and w_count < N // 2:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'W'
                            changed = True
                elif w_count == N // 2 and b_count < N // 2:
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = 'B'
                            changed = True

            # 3. Uniqueness
            full_rows = [r for r in range(N) if all(g[r][c] is not None for c in range(N))]
            for r1 in range(N):
                if r1 in full_rows: continue
                empty_cols = [c for c in range(N) if g[r1][c] is None]
                if len(empty_cols) == 2:
                    c1, c2 = empty_cols
                    for r2 in full_rows:
                        match = True
                        for c in range(N):
                            if c != c1 and c != c2 and g[r1][c] != g[r2][c]:
                                match = False
                                break
                        if match:
                            if g[r2][c1] == 'B':
                                g[r1][c1] = 'W'
                                g[r1][c2] = 'B'
                            else:
                                g[r1][c1] = 'B'
                                g[r1][c2] = 'W'
                            changed = True
                            break

            full_cols = [c for c in range(N) if all(g[r][c] is not None for r in range(N))]
            for c1 in range(N):
                if c1 in full_cols: continue
                empty_rows = [r for r in range(N) if g[r][c1] is None]
                if len(empty_rows) == 2:
                    r1, r2 = empty_rows
                    for c2 in full_cols:
                        match = True
                        for r in range(N):
                            if r != r1 and r != r2 and g[r][c1] != g[r][c2]:
                                match = False
                                break
                        if match:
                            if g[r1][c2] == 'B':
                                g[r1][c1] = 'W'
                                g[r2][c1] = 'B'
                            else:
                                g[r1][c1] = 'B'
                                g[r2][c1] = 'W'
                            changed = True
                            break

            # Check for invalid state (3 consecutive)
            for r in range(N):
                for c in range(N - 2):
                    if g[r][c] is not None and g[r][c] == g[r][c+1] == g[r][c+2]:
                        return False
            for c in range(N):
                for r in range(N - 2):
                    if g[r][c] is not None and g[r][c] == g[r+1][c] == g[r+2][c]:
                        return False

            # Check for duplicate full rows/cols
            full_rows_data = [tuple(g[r]) for r in full_rows]
            if len(full_rows_data) != len(set(full_rows_data)):
                return False
            full_cols_data = [tuple(g[r][c] for r in range(N)) for c in full_cols]
            if len(full_cols_data) != len(set(full_cols_data)):
                return False

        return True

    def is_solved(g):
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    return False
        return True

    def backtrack(g):
        curr_grid = copy.deepcopy(g)
        if not deduce(curr_grid):
            return None

        if is_solved(curr_grid):
            return curr_grid

        best_r, best_c = -1, -1
        max_filled = -1
        for r in range(N):
            for c in range(N):
                if curr_grid[r][c] is None:
                    filled_r = sum(1 for x in curr_grid[r] if x is not None)
                    filled_c = sum(1 for x in range(N) if curr_grid[x][c] is not None)
                    if filled_r + filled_c > max_filled:
                        max_filled = filled_r + filled_c
                        best_r, best_c = r, c

        if best_r != -1:
            for color in ['B', 'W']:
                curr_grid[best_r][best_c] = color
                res = backtrack(curr_grid)
                if res:
                    return res
                curr_grid[best_r][best_c] = None

        return None

    solution = backtrack(grid)
    if solution:
        return solution
    return "No Solution"

