from collections import deque

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    N = len(data)

    # Parse dots into a set of normalized coordinate pairs
    dots = set()
    for r, c in adjacent:
        if r % 1 != 0: # Vertical dot
            r1, r2 = int(r - 0.5), int(r + 0.5)
            c1 = c2 = int(c)
        else: # Horizontal dot
            r1 = r2 = int(r)
            c1, c2 = int(c - 0.5), int(c + 0.5)

        # Normalize pair order to ensure consistent lookups
        if (r1, c1) > (r2, c2):
            r1, c1, r2, c2 = r2, c2, r1, c1
        dots.add(((r1, c1), (r2, c2)))

    def is_adj(u, v):
        return abs(u[0] - v[0]) + abs(u[1] - v[1]) == 1

    def has_dot(u, v):
        if u > v: u, v = v, u
        return (u, v) in dots

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    def is_valid(x, y, u, v):
        # Alldiff constraint for cells in the same row or column
        if x == y: 
            return False
        # Consecutive constraints for orthogonally adjacent cells
        if is_adj(u, v):
            dot = has_dot(u, v)
            if dot and abs(x - y) != 1: 
                return False
            if not dot and abs(x - y) == 1: 
                return False
        return True

    def revise(u, v):
        revised = False
        to_remove = set()
        for x in domains[u]:
            supported = False
            for y in domains[v]:
                if is_valid(x, y, u, v):
                    supported = True
                    break
            if not supported:
                to_remove.add(x)
                revised = True
        if revised:
            domains[u] -= to_remove
        return revised

    def ac3(queue):
        while queue:
            u, v = queue.popleft()
            if revise(u, v):
                if not domains[u]:
                    return False # Domain wiped out, contradiction
                r, c = u
                # Add all neighbors of u (cells in same row/col) back to queue
                for c_other in range(N):
                    if c_other != c:
                        w = (r, c_other)
                        if w != v: queue.append((w, u))
                for r_other in range(N):
                    if r_other != r:
                        w = (r_other, c)
                        if w != v: queue.append((w, u))
        return True

    # Initial AC-3 queue with all row and column constraints
    initial_queue = deque()
    for r in range(N):
        for c1 in range(N):
            for c2 in range(N):
                if c1 != c2:
                    initial_queue.append(((r, c1), (r, c2)))
    for c in range(N):
        for r1 in range(N):
            for r2 in range(N):
                if r1 != r2:
                    initial_queue.append(((r1, c), (r2, c)))

    if not ac3(initial_queue):
        return "No Solution"

    def select_unassigned_variable():
        min_len = N + 1
        best_var = None
        for r in range(N):
            for c in range(N):
                if len(domains[(r, c)]) > 1:
                    if len(domains[(r, c)]) < min_len:
                        min_len = len(domains[(r, c)])
                        best_var = (r, c)
        return best_var

    def backtrack():
        var = select_unassigned_variable()
        if var is None:
            return True # All variables assigned

        # Snapshot domains for backtracking
        original_domains = {k: set(v) for k, v in domains.items()}

        for val in sorted(list(domains[var])):
            domains[var] = {val}

            # Propagate the new assignment
            queue = deque()
            r, c = var
            for c_other in range(N):
                if c_other != c: queue.append(((r, c_other), var))
            for r_other in range(N):
                if r_other != r: queue.append(((r_other, c), var))

            if ac3(queue):
                if backtrack():
                    return True

            # Restore domains if assignment failed
            for k in domains:
                domains[k] = set(original_domains[k])

        return False

    if backtrack():
        res = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(list(domains[(r, c)])[0])
            res.append(row)
        return res
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
