def solve(observation):
    board = observation['data']
    R = len(board)
    C = len(board[0])

    # Precompute the set of cells that can illuminate each white cell
    illuminators = [[[] for _ in range(C)] for _ in range(R)]

    for r in range(R):
        for c in range(C):
            if board[r][c] is None:
                # Up
                tr = r
                while tr >= 0 and board[tr][c] is None:
                    illuminators[r][c].append((tr, c))
                    tr -= 1
                # Down
                tr = r + 1
                while tr < R and board[tr][c] is None:
                    illuminators[r][c].append((tr, c))
                    tr += 1
                # Left
                tc = c - 1
                while tc >= 0 and board[r][tc] is None:
                    illuminators[r][c].append((r, tc))
                    tc -= 1
                # Right
                tc = c + 1
                while tc < C and board[r][tc] is None:
                    illuminators[r][c].append((r, tc))
                    tc += 1

    def place_bulb(b, r, c):
        """Places a bulb at (r, c) and marks all visible cells as 'X' (cannot contain bulb)."""
        if b[r][c] == 'B': return True
        if b[r][c] == 'X': return False
        b[r][c] = 'B'
        for vr, vc in illuminators[r][c]:
            if (vr, vc) != (r, c):
                if b[vr][vc] == 'B': return False # Contradiction: bulbs see each other
                b[vr][vc] = 'X'
        return True

    def deduce(b):
        """Applies deterministic logical deductions to reduce the search space."""
        changed = True
        while changed:
            changed = False

            # 1. Numbered cell constraints
            for r in range(R):
                for c in range(C):
                    if isinstance(b[r][c], int) and b[r][c] >= 0:
                        req = b[r][c]
                        bulbs = 0
                        unknowns = []
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if b[nr][nc] == 'B':
                                    bulbs += 1
                                elif b[nr][nc] is None:
                                    unknowns.append((nr, nc))

                        if bulbs > req: return False
                        if bulbs + len(unknowns) < req: return False

                        if bulbs == req and unknowns:
                            for ur, uc in unknowns:
                                b[ur][uc] = 'X'
                                changed = True
                        elif bulbs + len(unknowns) == req and unknowns:
                            for ur, uc in unknowns:
                                if not place_bulb(b, ur, uc): return False
                                changed = True

            # 2. Unilluminated cell constraints
            for r in range(R):
                for c in range(C):
                    if illuminators[r][c] and b[r][c] in (None, 'X'):
                        is_lit = False
                        possible_bulbs = []
                        for pr, pc in illuminators[r][c]:
                            if b[pr][pc] == 'B':
                                is_lit = True
                                break
                            elif b[pr][pc] is None:
                                possible_bulbs.append((pr, pc))

                        if not is_lit:
                            if len(possible_bulbs) == 0:
                                return False # Contradiction: cell cannot be illuminated
                            elif len(possible_bulbs) == 1:
                                br, bc = possible_bulbs[0]
                                if not place_bulb(b, br, bc): return False
                                changed = True
        return True

    def is_solved(b):
        """Checks if the board is completely and correctly solved."""
        for r in range(R):
            for c in range(C):
                if illuminators[r][c]: # White cell
                    is_lit = False
                    for pr, pc in illuminators[r][c]:
                        if b[pr][pc] == 'B':
                            is_lit = True
                            break
                    if not is_lit: return False
                elif isinstance(b[r][c], int) and b[r][c] >= 0: # Numbered cell
                    req = b[r][c]
                    bulbs = 0
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C and b[nr][nc] == 'B':
                            bulbs += 1
                    if bulbs != req: return False
        return True

    def backtrack(b):
        """Backtracking search with constraint propagation."""
        if not deduce(b): return None
        if is_solved(b): return b

        # Heuristic: Find the unilluminated cell with the fewest possible bulb placements
        best_cell = None
        min_poss = float('inf')
        possible_for_best = []

        for r in range(R):
            for c in range(C):
                if illuminators[r][c] and b[r][c] in (None, 'X'):
                    is_lit = False
                    poss = []
                    for pr, pc in illuminators[r][c]:
                        if b[pr][pc] == 'B':
                            is_lit = True
                            break
                        elif b[pr][pc] is None:
                            poss.append((pr, pc))

                    if not is_lit:
                        if len(poss) < min_poss:
                            min_poss = len(poss)
                            best_cell = (r, c)
                            possible_for_best = poss

        if best_cell is None:
            return None

        # Branch on the possible bulb locations for the most constrained cell
        for br, bc in possible_for_best:
            b_copy = [row[:] for row in b]
            if place_bulb(b_copy, br, bc):
                res = backtrack(b_copy)
                if res: return res

        return None

    initial_board = [row[:] for row in board]
    solved_board = backtrack(initial_board)

    if solved_board:
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if solved_board[r][c] == 'B':
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    return "No Solution"

