# The solver uses constraint propagation (bounds consistency) and backtracking.
# It models the problem with variables for each possible edge, with domains {0, 1, 2}.
# Constraints:
# 1. Sum of edges incident to an island equals its number.
# 2. Crossing edges cannot both be > 0.
# 3. The graph of islands with > 0 bridges must be connected.

def solve(observation):
    data = observation['data']
    islands = {}
    for r in range(len(data)):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                islands[(r, c)] = data[r][c]

    edges = []
    # Generate all possible horizontal edges between adjacent islands
    for r in range(len(data)):
        prev_c = -1
        for c in range(len(data[r])):
            if (r, c) in islands:
                if prev_c != -1:
                    edges.append(((r, prev_c), (r, c)))
                prev_c = c

    # Generate all possible vertical edges between adjacent islands
    for c in range(len(data[0])):
        prev_r = -1
        for r in range(len(data)):
            if (r, c) in islands:
                if prev_r != -1:
                    edges.append(((prev_r, c), (r, c)))
                prev_r = r

    # Identify all pairs of crossing edges
    crossings = []
    for i, e1 in enumerate(edges):
        for j in range(i + 1, len(edges)):
            e2 = edges[j]
            if e1[0][0] == e1[1][0] and e2[0][1] == e2[1][1]:
                h_edge, v_edge = e1, e2
            elif e1[0][1] == e1[1][1] and e2[0][0] == e2[1][0]:
                h_edge, v_edge = e2, e1
            else:
                continue

            r = h_edge[0][0]
            c1, c2 = min(h_edge[0][1], h_edge[1][1]), max(h_edge[0][1], h_edge[1][1])

            c = v_edge[0][1]
            r1, r2 = min(v_edge[0][0], v_edge[1][0]), max(v_edge[0][0], v_edge[1][0])

            if c1 < c < c2 and r1 < r < r2:
                crossings.append((i, j))

    # Map each island to its incident edge indices
    incident = {i: [] for i in islands}
    for idx, e in enumerate(edges):
        incident[e[0]].append(idx)
        incident[e[1]].append(idx)

    # Initial domains for each edge: 0, 1, or 2 bridges
    domains = {i: {0, 1, 2} for i in range(len(edges))}

    def propagate(domains):
        """
        Applies bounds consistency to aggressively prune the search space.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Island capacity constraints
            for i, target in islands.items():
                min_sum = sum(min(domains[e]) for e in incident[i])
                max_sum = sum(max(domains[e]) for e in incident[i])

                if min_sum > target or max_sum < target:
                    return False

                for e in incident[i]:
                    min_e = min(domains[e])
                    max_e = max(domains[e])

                    # Deduce new bounds based on the remaining capacity
                    new_max = target - (min_sum - min_e)
                    new_min = target - (max_sum - max_e)

                    new_domain = {v for v in domains[e] if new_min <= v <= new_max}
                    if len(new_domain) < len(domains[e]):
                        domains[e] = new_domain
                        changed = True
                    if not domains[e]:
                        return False

            # 2. Crossing constraints
            for e1, e2 in crossings:
                if min(domains[e1]) > 0:
                    if 0 not in domains[e2]: return False
                    if domains[e2] != {0}:
                        domains[e2] = {0}
                        changed = True
                if min(domains[e2]) > 0:
                    if 0 not in domains[e1]: return False
                    if domains[e1] != {0}:
                        domains[e1] = {0}
                        changed = True
        return True

    def is_possibly_connected(domains):
        """
        Checks if the graph of all *possible* edges is connected.
        If not, no valid assignment can be connected, so we can prune early.
        """
        adj = {i: [] for i in islands}
        for e_idx, e in enumerate(edges):
            if max(domains[e_idx]) > 0:
                u, v = e
                adj[u].append(v)
                adj[v].append(u)

        if not islands: return True
        start_node = list(islands.keys())[0]
        visited = set()
        q = [start_node]
        while q:
            curr = q.pop()
            if curr not in visited:
                visited.add(curr)
                q.extend(adj[curr])

        return len(visited) == len(islands)

    def solve_recursive(domains):
        if not propagate(domains):
            return None
        if not is_possibly_connected(domains):
            return None

        unassigned = [e for e in range(len(edges)) if len(domains[e]) > 1]
        if not unassigned:
            return domains

        # MRV Heuristic: Pick an edge incident to an island with the fewest unassigned edges
        best_e = None
        min_unassigned_incident = float('inf')
        for i in islands:
            unassigned_inc = [e for e in incident[i] if len(domains[e]) > 1]
            if 0 < len(unassigned_inc) < min_unassigned_incident:
                min_unassigned_incident = len(unassigned_inc)
                best_e = unassigned_inc[0]

        if best_e is None:
            best_e = unassigned[0]

        # Try assigning values, preferring larger values to maintain connectivity
        for val in sorted(list(domains[best_e]), reverse=True):
            new_domains = {e: set(d) for e, d in domains.items()}
            new_domains[best_e] = {val}
            result = solve_recursive(new_domains)
            if result:
                return result

        return None

    final_domains = solve_recursive(domains)
    if not final_domains:
        return "No Solution"

    ans = {}
    for i, e in enumerate(edges):
        val = list(final_domains[i])[0]
        if val > 0:
            ans[e] = val

    return ans

