                else:
                    return "Contradiction"

        idx = len(constraints)
        constraints.append({
            'target': target,
            'unassigned': set(unassigned_set)
        })
        for var in unassigned_set:
            var_to_constraints[var].append(idx)
        return True

    def apply_advanced_rules(queue):
        added = False
        n = len(constraints)
        for i in range(n):
            ci = constraints[i]
            if not ci['unassigned']: continue

            # Only compare with constraints that share variables
            related_constraints = set()
            for var in ci['unassigned']:
                for c_idx in var_to_constraints[var]:
                    if c_idx != i:
                        related_constraints.add(c_idx)

            for j in related_constraints:
                cj = constraints[j]
                if not cj['unassigned']: continue

                # Subset rule: if ci is a subset of cj
                if ci['unassigned'] < cj['unassigned']:
                    new_unassigned = cj['unassigned'] - ci['unassigned']
                    new_target = cj['target'] - ci['target']

                    if new_target < 0 or new_target > len(new_unassigned):
                        return "Contradiction"

                    res_add = add_constraint(new_target, new_unassigned)
                    if res_add == "Contradiction":
                        return "Contradiction"
                    elif res_add:
                        added = True
                        if new_target == 0:
                            for u in new_unassigned:
                                if assignment[u] == -1: queue.append((u, 0))
                        elif new_target == len(new_unassigned):
                            for u in new_unassigned:
                                if assignment[u] == -1: queue.append((u, 1))

                # Intersection rule
                I = ci['unassigned'] & cj['unassigned']
                if I and not ci['unassigned'].issubset(cj['unassigned']) and not cj['unassigned'].issubset(ci['unassigned']):
                    A_prime = ci['unassigned'] - I
                    B_prime = cj['unassigned'] - I
                    diff = ci['target'] - cj['target']

                    # If difference in targets equals the size of A', all A' must be 1 and all B' must be 0
                    if diff == len(A_prime):
                        for u in A_prime:
                            if assignment[u] == -1: 
                                queue.append((u, 1))
                                added = True
                        for u in B_prime:
                            if assignment[u] == -1: 
                                queue.append((u, 0))
                                added = True
                    elif -diff == len(B_prime):
                        for u in B_prime:
                            if assignment[u] == -1: 
                                queue.append((u, 1))
                                added = True
                        for u in A_prime:
                            if assignment[u] == -1: 
                                queue.append((u, 0))
                                added = True
        return added

    def propagate(queue):
        while True:
            while queue:
                var, val = queue.pop(0)
                if assignment[var] != -1:
                    if assignment[var] != val:
                        return False
                    continue

                assignment[var] = val

                for c_idx in var_to_constraints[var]:
                    c = constraints[c_idx]
                    if var in c['unassigned']:
                        c['unassigned'].remove(var)
                        if val == 1:
                            c['target'] -= 1

                        if c['target'] < 0 or c['target'] > len(c['unassigned']):
                            return False

                        if c['target'] == 0:
                            for u in list(c['unassigned']):
                                if assignment[u] == -1: queue.append((u, 0))
                        elif c['target'] == len(c['unassigned']):
                            for u in list(c['unassigned']):
                                if assignment[u] == -1: queue.append((u, 1))

            res = apply_advanced_rules(queue)
            if res == "Contradiction":
                return False
            if not res and not queue:
                break

        return True

    # Initial propagation
    queue = []
    for c in constraints:
        if c['target'] == 0:
            for u in list(c['unassigned']):
                queue.append((u, 0))
        elif c['target'] == len(c['unassigned']):
            for u in list(c['unassigned']):
                queue.append((u, 1))

    if not propagate(queue):
        return "No Solution"

    def backtrack():
        best_var = -1
        best_score = float('inf')

        # MRV Heuristic
        for c in constraints:
            if len(c['unassigned']) > 0:
                score = len(c['unassigned'])
                if score < best_score:
                    best_score = score

        if best_score != float('inf'):
            candidates = set()
            for c in constraints:
                if len(c['unassigned']) == best_score:
                    candidates.update(c['unassigned'])

            # Degree Heuristic tie-breaker
            max_degree = -1
            for var in candidates:
                degree = len(var_to_constraints[var])
                if degree > max_degree:
                    max_degree = degree
                    best_var = var

        if best_var == -1:
            return True

        # Save state
        saved_assignment = list(assignment)
        saved_targets = [c['target'] for c in constraints]
        saved_unassigned = [set(c['unassigned']) for c in constraints]
        saved_constraints_len = len(constraints)
        saved_var_to_constraints = [list(vtc) for vtc in var_to_constraints]

        # Branch on 1 (Black)
        queue = [(best_var, 1)]
        if propagate(queue):
            if backtrack():
                return True

        # Restore state
        for i in range(R * C):
            assignment[i] = saved_assignment[i]
        while len(constraints) > saved_constraints_len:
            constraints.pop()
        for i in range(len(constraints)):
            constraints[i]['target'] = saved_targets[i]
            constraints[i]['unassigned'] = set(saved_unassigned[i])
        for i in range(R * C):
            var_to_constraints[i] = list(saved_var_to_constraints[i])

        # Branch on 0 (White)
        queue = [(best_var, 0)]
        if propagate(queue):
            if backtrack():
                return True

        # Restore state before returning False
        for i in range(R * C):
            assignment[i] = saved_assignment[i]
        while len(constraints) > saved_constraints_len:
            constraints.pop()
        for i in range(len(constraints)):
            constraints[i]['target'] = saved_targets[i]
            constraints[i]['unassigned'] = set(saved_unassigned[i])
        for i in range(R * C):
            var_to_constraints[i] = list(saved_var_to_constraints[i])

        return False

    if backtrack():
        res = []
        for r in range(R):
            row = []
            for c in range(C):
                val = assignment[r * C + c]
                if val == 1:
                    row.append('B')
                else:
                    row.append(None)
            res.append(row)
        return res
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
