OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [2, None, None, None, None, None, None], [None, None, 7, 2, None, None, None], [None, None, None, None, None, None, None]], 'adjacent': [[0.0, 1.5], [0.5, 2.0], [0.5, 5.0], [1.5, 3.0], [1.5, 5.0], [1.5, 6.0], [2.0, 2.5], [3.0, 0.5], [3.0, 3.5], [3.0, 4.5], [3.5, 1.0], [3.5, 3.0], [3.5, 4.0], [3.5, 6.0], [4.0, 1.5], [4.0, 2.5], [4.0, 3.5], [5.0, 0.5], [6.0, 1.5]]}

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    N = len(data)

    # Convert adjacent list to a set of tuples for O(1) lookups
    dots_set = set((float(r), float(c)) for r, c in adjacent)

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Build adjacency list for the constraint graph
    # Neighbors include all cells in the same row and same column
    neighbors = {}
    for r in range(N):
        for c in range(N):
            u = (r, c)
            neighbors[u] = set()
            for i in range(N):
                if i != c:
                    neighbors[u].add((r, i))
                if i != r:
                    neighbors[u].add((i, c))

    # Precompute valid assignments for each arc to drastically speed up AC-3
    valid_y_for_x = {}
    for u in neighbors:
        for v in neighbors[u]:
            valid_y_for_x[(u, v)] = {x: set() for x in range(1, N + 1)}
            is_ortho = abs(u[0] - v[0]) + abs(u[1] - v[1]) == 1
            has_dot = False
            if is_ortho:
                mid_r = (u[0] + v[0]) / 2.0
                mid_c = (u[1] + v[1]) / 2.0
                has_dot = (mid_r, mid_c) in dots_set

            for x in range(1, N + 1):
                for y in range(1, N + 1):
                    if x == y:
                        continue # Latin Square constraint: all diff in row/col
                    if is_ortho:
                        if has_dot and abs(x - y) != 1:
                            continue # Must be consecutive if dot exists
                        if not has_dot and abs(x - y) == 1:
                            continue # Must NOT be consecutive if no dot exists
                    valid_y_for_x[(u, v)][x].add(y)

    def revise(domains, u, v):
        """Revise domain of u based on domain of v."""
        revised = False
        to_remove = set()
        allowed_y = domains[v]
        vyfx = valid_y_for_x[(u, v)]
        for x in domains[u]:
            # If no valid y exists in domains[v] for this x, x is invalid
            if not vyfx[x].intersection(allowed_y):
                to_remove.add(x)
        if to_remove:
            domains[u] -= to_remove
            revised = True
        return revised

    def ac3(domains, queue=None):
        """Arc Consistency 3 algorithm."""
        if queue is None:
            queue = set((u, v) for u in domains for v in neighbors[u])
        else:
            queue = set(queue)

        while queue:
            u, v = queue.pop()
            if revise(domains, u, v):
                if not domains[u]:
                    return False # Domain wiped out, constraint violation
                for w in neighbors[u]:
                    if w != v:
                        queue.add((w, u))
        return True

    # Initial constraint propagation
    if not ac3(domains):
        return "No Solution"

    def backtrack(domains):
        """Backtracking search with Minimum Remaining Values (MRV) heuristic."""
        min_len = N + 1
        best_u = None

        # Find the unassigned variable with the smallest domain
        for u, dom in domains.items():
            l = len(dom)
            if l > 1 and l < min_len:
                min_len = l
                best_u = u
                if min_len == 2: # Optimization: break early if domain size is 2
                    break

        if best_u is None:
            return domains # All variables assigned successfully

        u = best_u

        for val in domains[u]:
            # Create a deep copy of domains for the new branch
            new_domains = {k: set(v) for k, v in domains.items()}
            new_domains[u] = {val}

            # Only add arcs affected by this assignment to the AC-3 queue
            queue = set((w, u) for w in neighbors[u])
            if ac3(new_domains, queue):
                result = backtrack(new_domains)
                if result:
                    return result
        return None

    result_domains = backtrack(domains)

    if result_domains:
        ans = [[0] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                ans[r][c] = list(result_domains[(r, c)])[0]
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
