OBSERVATION = {'data': [[1, None, None, None, None, 1, 1, None, None, -1], [None, 2, None, None, None, None, None, None, -1, None], [None, None, None, None, None, None, 0, None, None, None], [0, None, 1, None, None, None, None, None, None, None], [1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, 1], [None, None, None, None, None, None, None, 1, None, 2], [None, None, None, 1, None, None, None, None, None, None], [None, -1, None, None, None, None, None, None, 2, None], [-1, None, None, -1, -1, None, None, None, None, -1]]}

def solve(observation):
    data = observation['data']
    n = len(data)

    # Precompute line of sight for each white cell
    los = [[[] for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is None:
                vis = [(r, c)]
                # up
                for i in range(r - 1, -1, -1):
                    if data[i][c] is not None: break
                    vis.append((i, c))
                # down
                for i in range(r + 1, n):
                    if data[i][c] is not None: break
                    vis.append((i, c))
                # left
                for j in range(c - 1, -1, -1):
                    if data[r][j] is not None: break
                    vis.append((r, j))
                # right
                for j in range(c + 1, n):
                    if data[r][j] is not None: break
                    vis.append((r, j))
                los[r][c] = vis

    class State:
        def __init__(self):
            self.status = [[0 for _ in range(n)] for _ in range(n)]
            # 0: unassigned, 1: bulb, -1: empty, 2: black
            for r in range(n):
                for c in range(n):
                    if data[r][c] is not None:
                        self.status[r][c] = 2

        def copy(self):
            new_state = State()
            new_state.status = [row[:] for row in self.status]
            return new_state

    def place_bulb(state, r, c):
        if state.status[r][c] == -1: return False
        if state.status[r][c] == 1: return True
        state.status[r][c] = 1
        for vr, vc in los[r][c]:
            if (vr, vc) != (r, c):
                if state.status[vr][vc] == 1: return False
                state.status[vr][vc] = -1
        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # 1. Enforce numbered black cell constraints
            for r in range(n):
                for c in range(n):
                    if isinstance(data[r][c], int) and data[r][c] >= 0:
                        k = data[r][c]
                        adj = []
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < n and data[nr][nc] is None:
                                adj.append((nr, nc))

                        bulbs = sum(1 for nr, nc in adj if state.status[nr][nc] == 1)
                        unassigned = [(nr, nc) for nr, nc in adj if state.status[nr][nc] == 0]

                        if bulbs > k: return False
                        if bulbs + len(unassigned) < k: return False

                        if bulbs == k and unassigned:
                            for nr, nc in unassigned:
                                state.status[nr][nc] = -1
                                changed = True
                        elif bulbs + len(unassigned) == k and unassigned:
                            for nr, nc in unassigned:
                                if not place_bulb(state, nr, nc): return False
                                changed = True

            # 2. Enforce illumination constraints
            illuminated = set()
            for r in range(n):
                for c in range(n):
                    if state.status[r][c] == 1:
                        for vr, vc in los[r][c]:
                            illuminated.add((vr, vc))

            for r in range(n):
                for c in range(n):
                    if data[r][c] is None and (r, c) not in illuminated:
                        possible = [(vr, vc) for vr, vc in los[r][c] if state.status[vr][vc] == 0]
                        if not possible:
                            return False
                        if len(possible) == 1:
                            pr, pc = possible[0]
                            if not place_bulb(state, pr, pc): return False
                            changed = True
                            break
                if changed: break

        return True

    def solve_recursive(state):
        if not propagate(state):
            return None

        illuminated = set()
        for r in range(n):
            for c in range(n):
                if state.status[r][c] == 1:
                    for vr, vc in los[r][c]:
                        illuminated.add((vr, vc))

        # Branch on the most constrained unilluminated cell
        best_cell = None
        min_possible = float('inf')
        for r in range(n):
            for c in range(n):
                if data[r][c] is None and (r, c) not in illuminated:
                    possible = [(vr, vc) for vr, vc in los[r][c] if state.status[vr][vc] == 0]
                    if len(possible) < min_possible:
                        min_possible = len(possible)
                        best_cell = (r, c)

        if best_cell is not None:
            r, c = best_cell
            possible = [(vr, vc) for vr, vc in los[r][c] if state.status[vr][vc] == 0]
            for pr, pc in possible:
                new_state = state.copy()
                if place_bulb(new_state, pr, pc):
                    res = solve_recursive(new_state)
                    if res is not None: return res
            return None

        # Branch on unsatisfied numbered cells if any remain
        for r in range(n):
            for c in range(n):
                if isinstance(data[r][c], int) and data[r][c] >= 0:
                    k = data[r][c]
                    adj = []
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and data[nr][nc] is None:
                            adj.append((nr, nc))
                    bulbs = sum(1 for nr, nc in adj if state.status[nr][nc] == 1)
                    if bulbs < k:
                        unassigned = [(nr, nc) for nr, nc in adj if state.status[nr][nc] == 0]
                        if not unassigned:
                            return None
                        nr, nc = unassigned[0]

                        # Try placing a bulb
                        new_state = state.copy()
                        if place_bulb(new_state, nr, nc):
                            res = solve_recursive(new_state)
                            if res is not None: return res

                        # Try leaving it empty
                        new_state = state.copy()
                        new_state.status[nr][nc] = -1
                        res = solve_recursive(new_state)
                        if res is not None: return res

                        return None

        # All constraints satisfied, mark remaining unassigned as empty
        for r in range(n):
            for c in range(n):
                if state.status[r][c] == 0:
                    state.status[r][c] = -1

        return state

    initial_state = State()
    final_state = solve_recursive(initial_state)

    if final_state is None:
        return "No Solution"

    ans = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if final_state.status[r][c] == 1:
                ans[r][c] = 'B'

    return ans

