OBSERVATION = {'region': [[0, 1, 1, 1, 2, 2, 2], [0, 1, 1, 3, 2, 2, 4], [0, 1, 1, 3, 3, 3, 4], [5, 5, 1, 3, 6, 6, 4], [7, 5, 1, 3, 6, 8, 8], [7, 5, 5, 5, 6, 8, 8], [7, 9, 9, 9, 9, 8, 8]], 'row_stitch_counts': [1, 3, 2, 4, 5, 4, 3], 'col_stitch_counts': [2, 3, 3, 3, 4, 4, 3]}

def solve(observation):
    region = observation['region']
    row_clues = observation['row_stitch_counts']
    col_clues = observation['col_stitch_counts']
    N = len(region)

    # 1. Identify all possible edges (stitches must cross region boundaries)
    edges = []
    for r in range(N):
        for c in range(N):
            # Check right neighbor
            if c + 1 < N and region[r][c] != region[r][c+1]:
                edges.append( ((r, c), (r, c+1)) )
            # Check bottom neighbor
            if r + 1 < N and region[r][c] != region[r+1][c]:
                edges.append( ((r, c), (r+1, c)) )

    num_edges = len(edges)

    # Precompute incidence list for fast lookups
    cell_to_edges = [[[] for _ in range(N)] for _ in range(N)]
    for idx, (u, v) in enumerate(edges):
        cell_to_edges[u[0]][u[1]].append(idx)
        cell_to_edges[v[0]][v[1]].append(idx)

    # State variables for backtracking
    edge_state = [-1] * num_edges # -1: unknown, 0: off, 1: on
    cell_used = [[0] * N for _ in range(N)] # 0: unused, 1: used
    row_used = [0] * N
    col_used = [0] * N

    best_solution = None

    def solve_backtrack(edge_idx):
        nonlocal best_solution

        # Aggressive Pruning: Check if current state violates clues or cannot reach them
        for r in range(N):
            if row_used[r] > row_clues[r]: return False
            possible = 0
            for c in range(N):
                if cell_used[r][c] == 0:
                    # Cell is available, check if it has any valid incident edges left
                    for e in cell_to_edges[r][c]:
                        if edge_state[e] == -1:
                            possible += 1
                            break
            if row_used[r] + possible < row_clues[r]: return False

        for c in range(N):
            if col_used[c] > col_clues[c]: return False
            possible = 0
            for r in range(N):
                if cell_used[r][c] == 0:
                    for e in cell_to_edges[r][c]:
                        if edge_state[e] == -1:
                            possible += 1
                            break
            if col_used[c] + possible < col_clues[c]: return False

        # Base case: all edges decided
        if edge_idx == num_edges:
            ans = []
            for i, state in enumerate(edge_state):
                if state == 1:
                    ans.append(list(edges[i]))
            best_solution = ans
            return True

        # Skip if this edge was already determined by constraint propagation
        if edge_state[edge_idx] != -1:
            return solve_backtrack(edge_idx + 1)

        u, v = edges[edge_idx]

        # Check if we can place a stitch here (both holes must be empty)
        can_place = (cell_used[u[0]][u[1]] == 0 and cell_used[v[0]][v[1]] == 0)

        if can_place:
            # --- Branch 1: Place the stitch ---
            edge_state[edge_idx] = 1
            cell_used[u[0]][u[1]] = 1
            cell_used[v[0]][v[1]] = 1
            row_used[u[0]] += 1
            row_used[v[0]] += 1
            col_used[u[1]] += 1
            col_used[v[1]] += 1

            # Forward Checking / Propagation: 
            # Two stitches cannot share a hole, so disable all other edges incident to u and v
            propagated_edges = []
            for e in cell_to_edges[u[0]][u[1]]:
                if e != edge_idx and edge_state[e] == -1:
                    edge_state[e] = 0
                    propagated_edges.append(e)
            for e in cell_to_edges[v[0]][v[1]]:
                if e != edge_idx and edge_state[e] == -1:
                    edge_state[e] = 0
                    propagated_edges.append(e)

            if solve_backtrack(edge_idx + 1):
                return True

            # Backtrack Branch 1
            for e in propagated_edges:
                edge_state[e] = -1
            edge_state[edge_idx] = -1
            cell_used[u[0]][u[1]] = 0
            cell_used[v[0]][v[1]] = 0
            row_used[u[0]] -= 1
            row_used[v[0]] -= 1
            col_used[u[1]] -= 1
            col_used[v[1]] -= 1

        # --- Branch 2: Do NOT place the stitch ---
        edge_state[edge_idx] = 0
        if solve_backtrack(edge_idx + 1):
            return True
        edge_state[edge_idx] = -1

        return False

    solve_backtrack(0)

    if best_solution is None:
        return "No Solution"

    return str(best_solution)

if __name__ == "__main__":
    print(solve(OBSERVATION))
