def revise(domains, u, v, dots):
    """
    Revises the domain of variable u based on the constraints with variable v.
    Returns True if the domain of u was modified.
    """
    revised = False
    r1, c1 = u
    r2, c2 = v
    is_adj = (abs(r1 - r2) + abs(c1 - c2) == 1)
    is_dot = is_adj and ((u, v) in dots)

    to_remove = set()
    for x in domains[u]:
        satisfies = False
        if is_adj:
            if is_dot:
                # Must be consecutive
                if (x - 1 in domains[v]) or (x + 1 in domains[v]):
                    satisfies = True
            else:
                # Must NOT be consecutive, and must be different (same row/col)
                for y in domains[v]:
                    if y != x and abs(x - y) != 1:
                        satisfies = True
                        break
        else:
            # Not adjacent, but in same row/col, so must be different
            for y in domains[v]:
                if y != x:
                    satisfies = True
                    break

        if not satisfies:
            to_remove.add(x)
            revised = True

    if revised:
        domains[u] -= to_remove
    return revised

def ac3_queue(domains, queue_list, dots, N):
    """
    Runs the AC-3 algorithm to enforce arc consistency using a given initial queue.
    """
    queue = set(queue_list)
    while queue:
        u, v = queue.pop()
        if revise(domains, u, v, dots):
            if not domains[u]:
                return False # Domain wiped out, constraint violation
            r1, c1 = u
            # Add all neighbors of u (except v) back to the queue
            for r2 in range(N):
                for c2 in range(N):
                    w = (r2, c2)
                    if w != u and w != v and (r1 == r2 or c1 == c2):
                        queue.add((w, u))
    return True

def solve_csp(domains, dots, N):
    """
    Backtracking search with Minimum Remaining Values (MRV) heuristic and 
    Maintaining Arc Consistency (MAC).
    """
    # Find unassigned variable with minimum remaining values (MRV)
    min_len = N + 1
    best_u = None
    for r in range(N):
        for c in range(N):
            if len(domains[(r, c)]) > 1:
                if len(domains[(r, c)]) < min_len:
                    min_len = len(domains[(r, c)])
                    best_u = (r, c)

    if best_u is None:
        return domains # All variables assigned, puzzle solved

    # Try assigning each possible value to the chosen variable
    for val in sorted(list(domains[best_u])):
        new_domains = {k: set(v) for k, v in domains.items()}
        new_domains[best_u] = {val}

        # Propagate constraints from this new assignment
        queue = []
        r1, c1 = best_u
        for r2 in range(N):
            for c2 in range(N):
                v = (r2, c2)
                if best_u != v and (r1 == r2 or c1 == c2):
                    queue.append((v, best_u))

        if ac3_queue(new_domains, queue, dots, N):
            result = solve_csp(new_domains, dots, N)
            if result:
                return result

    return False

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    N = len(data)

    # Parse dots into a set of bidirectional edges
    dots = set()
    for r, c in adjacent:
        if int(r) == r: # Horizontal dot
            r = int(r)
            c1 = int(c - 0.5)
            c2 = int(c + 0.5)
            dots.add( ((r, c1), (r, c2)) )
            dots.add( ((r, c2), (r, c1)) )
        else: # Vertical dot
            r1 = int(r - 0.5)
            r2 = int(r + 0.5)
            c = int(c)
            dots.add( ((r1, c), (r2, c)) )
            dots.add( ((r2, c), (r1, c)) )

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Initial constraint propagation (AC-3)
    queue = []
    for r1 in range(N):
        for c1 in range(N):
            u = (r1, c1)
            for r2 in range(N):
                for c2 in range(N):
                    v = (r2, c2)
                    if u != v and (r1 == r2 or c1 == c2):
                        queue.append((u, v))

    if not ac3_queue(domains, queue, dots, N):
        return "No Solution"

    # Start backtracking search
