def solve_grid(grid):
    """
    Backtracking solver with constraint propagation.
    """
    if not deduce(grid):
        return None

    N = len(grid)

    # Find the most constrained empty cell (MRV heuristic)
    best_cell = None
    min_options = 3

    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                options = []
                for color in ['B', 'W']:
                    grid[r][c] = color
                    valid = True

                    # Quick check 3 consecutive
                    if c >= 2 and grid[r][c-2] == grid[r][c-1] == color: valid = False
                    if c >= 1 and c + 1 < N and grid[r][c-1] == color == grid[r][c+1]: valid = False
                    if c + 2 < N and color == grid[r][c+1] == grid[r][c+2]: valid = False
                    if r >= 2 and grid[r-2][c] == grid[r-1][c] == color: valid = False
                    if r >= 1 and r + 1 < N and grid[r-1][c] == color == grid[r+1][c]: valid = False
                    if r + 2 < N and color == grid[r+1][c] == grid[r+2][c]: valid = False

                    # Quick check counts
                    if grid[r].count(color) > N // 2: valid = False
                    col = [grid[i][c] for i in range(N)]
                    if col.count(color) > N // 2: valid = False

                    if valid:
                        options.append(color)

                grid[r][c] = None

                if len(options) == 0:
                    return None
                if len(options) < min_options:
                    min_options = len(options)
                    best_cell = (r, c, options)
                    if min_options == 1:
                        break
        if min_options == 1:
            break

    if best_cell is None:
        return grid

    r, c, options = best_cell
    for color in options:
        new_grid = [row[:] for row in grid]
        new_grid[r][c] = color
        result = solve_grid(new_grid)
        if result is not None:
            return result

    return None

