        """Verifies if a fully assigned state is a valid solution."""
        for node, req_deg in node_req.items():
            if sum(domains[e][0] for e in incident_edges[node]) != req_deg:
                return False
        adj = {n: [] for n in nodes}
        for i, e in enumerate(edges):
            if domains[i][0] > 0:
                u, v = e
                adj[u].append(v)
                adj[v].append(u)
        if not nodes: return True
        start = nodes[0]
        visited = set([start])
        q = [start]
        while q:
            curr = q.pop(0)
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)
        return len(visited) == len(nodes)

    # Initial domains: each edge can have 0, 1, or 2 bridges
    domains = {i: [0, 1, 2] for i in range(len(edges))}

    if not propagate(domains):
        return "No Solution"

    def backtrack(domains):
        unassigned = [i for i in range(len(edges)) if len(domains[i]) > 1]
        if not unassigned:
            if check_solution(domains):
                return domains
            return None

        # Minimum Remaining Values (MRV) heuristic
        unassigned.sort(key=lambda i: len(domains[i]))
        e_idx = unassigned[0]

        # Try values in descending order (often finds connections faster)
        for val in sorted(domains[e_idx], reverse=True):
            new_domains = {k: v[:] for k, v in domains.items()}
            new_domains[e_idx] = [val]
            if propagate(new_domains):
                res = backtrack(new_domains)
                if res:
                    return res
        return None

    res = backtrack(domains)
    if res:
        ans = {}
        for i, e in enumerate(edges):
            val = res[i][0]
            if val > 0:
                ans[e] = val
        return ans
    return "No Solution"

