    state = ['E'] * N
    lit_count = [0] * N
    req = [-1] * N
    white_cells = []
    numbered_walls = []

    # Parse grid
    for r in range(R):
        for c in range(C):
            i = r * C + c
            val = grid[r][c]
            if val is not None:
                state[i] = 'W'
                req[i] = val
                if val != -1:
                    numbered_walls.append(i)
            else:
                white_cells.append(i)

