    V = [[] for _ in range(N)]
    for i in white_cells:
        r, c = i // C, i % C
        V[i].append(i)
        # Up
        tr = r - 1
        while tr >= 0 and grid[tr][c] is None:
            V[i].append(tr * C + c)
            tr -= 1
        # Down
        tr = r + 1
        while tr < R and grid[tr][c] is None:
            V[i].append(tr * C + c)
            tr += 1
        # Left
        tc = c - 1
        while tc >= 0 and grid[r][tc] is None:
            V[i].append(r * C + tc)
            tc -= 1
        # Right
        tc = c + 1
        while tc < C and grid[r][tc] is None:
            V[i].append(r * C + tc)
            tc += 1

    # Precompute adjacent white cells for numbered walls
    adj = [[] for _ in range(N)]
    for i in numbered_walls:
        r, c = i // C, i % C
        if r > 0 and grid[r-1][c] is None: adj[i].append((r-1)*C + c)
        if r < R-1 and grid[r+1][c] is None: adj[i].append((r+1)*C + c)
        if c > 0 and grid[r][c-1] is None: adj[i].append(r*C + c - 1)
        if c < C-1 and grid[r][c+1] is None: adj[i].append(r*C + c + 1)

    def place_bulb(i, current_state, current_lit_count):
        """Places a bulb at index i, updates lit counts, and marks illuminated cells."""
        if current_state[i] != 'E': 
            return False
        current_state[i] = 'B'
        for v in V[i]:
            current_lit_count[v] += 1
            if v != i:
                if current_state[v] == 'B': 
                    return False # Contradiction: Bulb illuminates another bulb
                if current_state[v] == 'E':
                    current_state[v] = 'M'
        return True

    def deduce(current_state, current_lit_count):
        """Applies human-like logical deductions to aggressively prune the search space."""
        changed = True
        while changed:
            changed = False

            # Rule 1: Numbered walls satisfaction
            for w in numbered_walls:
                r = req[w]
                adjs = adj[w]
                bulbs = 0
                empties = []
                for a in adjs:
                    if current_state[a] == 'B': bulbs += 1
                    elif current_state[a] == 'E': empties.append(a)

                if bulbs > r: return False # Too many bulbs
                if bulbs + len(empties) < r: return False # Not enough spots

                if bulbs == r and empties:
                    # Wall satisfied, mark remaining adjacent cells
                    for e in empties:
                        current_state[e] = 'M'
                        changed = True
                elif bulbs + len(empties) == r and empties:
                    # All remaining empty spots must be bulbs
                    for e in empties:
                        if not place_bulb(e, current_state, current_lit_count): return False
                        changed = True

            # Rule 2: Unlit cells must be illuminated
            for w in white_cells:
                if current_lit_count[w] == 0:
                    opts = [v for v in V[w] if current_state[v] == 'E']
                    if not opts: return False # Unlit cell cannot be illuminated
                    if len(opts) == 1:
                        # Only one valid spot to illuminate this cell
                        if not place_bulb(opts[0], current_state, current_lit_count): return False
                        changed = True

        return True

    def solve_recursive(current_state, current_lit_count):
        """Backtracking search with constraint propagation."""
        if not deduce(current_state, current_lit_count):
            return False

        min_opts = 999
        best_opts = []

        # Find the most constrained unlit cell
        for w in white_cells:
            if current_lit_count[w] == 0:
                opts = [v for v in V[w] if current_state[v] == 'E']
                if len(opts) < min_opts:
                    min_opts = len(opts)
                    best_opts = opts

        # Find the most constrained unsatisfied numbered wall
        for w in numbered_walls:
            bulbs = sum(1 for a in adj[w] if current_state[a] == 'B')
            if bulbs < req[w]:
                opts = [a for a in adj[w] if current_state[a] == 'E']
                if len(opts) < min_opts:
                    min_opts = len(opts)
                    best_opts = opts

        # If no unlit cells and no unsatisfied walls, puzzle is solved
        if min_opts == 999:
            return True

        # Branch on the first option of the most constrained element
        branch_cell = best_opts[0]

        # Branch 1: Try placing a Bulb
        new_state = list(current_state)
        new_lit_count = list(current_lit_count)
        if place_bulb(branch_cell, new_state, new_lit_count):
            if solve_recursive(new_state, new_lit_count):
                for i in range(N): current_state[i] = new_state[i]
                return True

        # Branch 2: Try Marking the cell (no bulb)
        new_state = list(current_state)
        new_lit_count = list(current_lit_count)
        new_state[branch_cell] = 'M'
        if solve_recursive(new_state, new_lit_count):
            for i in range(N): current_state[i] = new_state[i]
            return True

        return False

    if solve_recursive(state, lit_count):
        ans = [[None]*C for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if state[r*C + c] == 'B':
                    ans[r][c] = 'B'
        return ans
    else:
        return "No Solution"

