            for j in range(i + 1, len(active_constraints)):
                u_b, r_b = active_constraints[j]

                I = u_a.intersection(u_b)
                if not I: continue

                u_a_diff = u_a - I
                u_b_diff = u_b - I

                # Bounds for number of black cells in the intersection I
                max_I = min(r_a, r_b, len(I))
                min_I = max(0, r_a - len(u_a_diff), r_b - len(u_b_diff))

