            for r in range(R):
                for c in range(C):
                    if state[r][c] == -1:
                        state[r][c] = 0
            return True

        r, c = best_cell

        for val in [1, 0]:
            success, assigned = full_propagate([(r, c, val)])
            if success:
                if backtrack():
                    return True
            # Undo assignments
            for ar, ac in assigned:
                state[ar][ac] = -1

        return False

    # Seed the initial propagation queue with obvious 0s and maxes
    initial_queue = []
    for cr, cc, target in constraints:
        neighbors = constraint_neighbors[(cr, cc)]
        num_unassigned = len(neighbors)
        if target == 0:
            for nr, nc in neighbors:
                initial_queue.append((nr, nc, 0))
        elif target == num_unassigned:
            for nr, nc in neighbors:
                initial_queue.append((nr, nc, 1))

    success, assigned = full_propagate(initial_queue)
    if not success:
        return "No Solution"

    if backtrack():
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if state[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

