    # Parse the unit string to determine subgrid dimensions and overall grid size
    if 'x' in unit_str:
        sub_r, sub_c = map(int, unit_str.split('x'))
    else:
        sub_r = sub_c = int(unit_str)

    N = sub_r * sub_c

    # Precompute peers and units for each cell to optimize constraint propagation
    peers = {}
    units = {}
    for r in range(N):
        for c in range(N):
            row_unit = [(r, i) for i in range(N)]
            col_unit = [(i, c) for i in range(N)]
            sr, sc = (r // sub_r) * sub_r, (c // sub_c) * sub_c
            sub_unit = [(i, j) for i in range(sr, sr + sub_r) for j in range(sc, sc + sub_c)]

            units[(r, c)] = [row_unit, col_unit, sub_unit]

            peer_set = set(row_unit + col_unit + sub_unit)
            peer_set.remove((r, c))
            peers[(r, c)] = peer_set

    def assign(possibilities, r, c, v):
        """
        Assign value v to cell (r, c) by eliminating all other values from its possibilities.
        Returns False if a contradiction is found, True otherwise.
        """
        other_values = possibilities[(r, c)].copy()
        other_values.discard(v)
        for v2 in other_values:
            if not eliminate(possibilities, r, c, v2):
                return False
        return True

    def eliminate(possibilities, r, c, v):
        """
        Eliminate value v from the possibilities of cell (r, c).
        Propagates constraints (Naked Singles and Hidden Singles).
        Returns False if a contradiction is found, True otherwise.
        """
        if v not in possibilities[(r, c)]:
            return True
        possibilities[(r, c)].remove(v)

        # Contradiction: no possible values left for this cell
        if len(possibilities[(r, c)]) == 0:
            return False

        # Naked Single: if only one value is left, eliminate it from all peers
        elif len(possibilities[(r, c)]) == 1:
            v2 = next(iter(possibilities[(r, c)]))
            for pr, pc in peers[(r, c)]:
                if not eliminate(possibilities, pr, pc, v2):
                    return False

        # Hidden Single: check if v can only be placed in one cell within any of its units
        for unit in units[(r, c)]:
            places = [(ur, uc) for ur, uc in unit if v in possibilities[(ur, uc)]]
            if len(places) == 0:
                return False # Contradiction: nowhere to place v in this unit
            elif len(places) == 1:
                pr, pc = places[0]
                if len(possibilities[(pr, pc)]) > 1:
                    if not assign(possibilities, pr, pc, v):
                        return False
        return True

    # Initialize possibilities for all cells
    possibilities = {(r, c): set(range(1, N + 1)) for r in range(N) for c in range(N)}

    # Apply initial given values
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                if not assign(possibilities, r, c, data[r][c]):
                    return "No Solution"

    def search(possibilities):
        """
        Backtracking search with Minimum Remaining Values (MRV) heuristic.
        """
        if possibilities is False:
            return False

        # Find the cell with the fewest possibilities > 1
        unsolved = [(len(possibilities[(r, c)]), (r, c)) 
                    for r in range(N) for c in range(N) 
                    if len(possibilities[(r, c)]) > 1]

        if not unsolved:
            return possibilities # Puzzle solved

        min_len, (r, c) = min(unsolved)

        # Try assigning each possible value to the chosen cell
        for v in possibilities[(r, c)]:
            possibilities_copy = {k: val.copy() for k, val in possibilities.items()}
            if assign(possibilities_copy, r, c, v):
                result = search(possibilities_copy)
                if result:
                    return result
        return False

    # Execute search
    result = search(possibilities)

    # Format the output grid
    if result:
        solution = [[next(iter(result[(r, c)])) for c in range(N)] for r in range(N)]
        return solution
    else:
        return "No Solution"

