        if r == int(r): # Horizontal dot
            r = int(r)
            c1 = int(c - 0.5)
            c2 = int(c + 0.5)
            dots.add(((r, c1), (r, c2)))
            dots.add(((r, c2), (r, c1)))
        else: # Vertical dot
            c = int(c)
            r1 = int(r - 0.5)
            r2 = int(r + 0.5)
            dots.add(((r1, c), (r2, c)))
            dots.add(((r2, c), (r1, c)))

    # Precompute neighbors (same row and same column)
    neighbors_dict = {}
    for r in range(N):
        for c in range(N):
            neighbors = set()
            for i in range(N):
                if i != c: neighbors.add((r, i))
                if i != r: neighbors.add((i, c))
            neighbors_dict[(r, c)] = neighbors

    # Precompute adjacency and dot presence for fast lookup
    adj_info = {}
    for r in range(N):
        for c in range(N):
            for nr, nc in neighbors_dict[(r, c)]:
                is_adj = (abs(r - nr) + abs(c - nc) == 1)
                has_dot = ((r, c), (nr, nc)) in dots
                adj_info[((r, c), (nr, nc))] = (is_adj, has_dot)

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None and val != 0:
                domains[(r, c)] = {val}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    def revise(c1, c2, current_domains):
        revised = False
        is_adj, has_dot = adj_info[(c1, c2)]
        d1 = current_domains[c1]
        d2 = current_domains[c2]
        to_remove = set()

        if is_adj:
            if has_dot:
                # If there is a dot, v1 must have at least one adjacent value in d2
                for v1 in d1:
                    if (v1 - 1 not in d2) and (v1 + 1 not in d2):
                        to_remove.add(v1)
            else:
                # If no dot, v1 cannot be adjacent to ALL possible values in d2
                # Also v1 != v2 is enforced. So d2 cannot be a subset of {v1-1, v1, v1+1}
                for v1 in d1:
