        if initial_queue is None:
            queue = deque()
            for r in range(N):
                for c in range(N):
                    for nr, nc in neighbors_dict[(r, c)]:
                        queue.append(((r, c), (nr, nc)))
        else:
            queue = deque(initial_queue)

        while queue:
            c1, c2 = queue.popleft()
            if revise(c1, c2, current_domains):
                if not current_domains[c1]:
                    return False
                for nr, nc in neighbors_dict[c1]:
                    if (nr, nc) != c2:
                        queue.append(((nr, nc), c1))
