            if min_len == 2:
                break

        if best_cell is None:
            return current_domains # All domains have size 1, solved

        r, c = best_cell
        for val in list(current_domains[(r, c)]):
            new_domains = {k: v.copy() for k, v in current_domains.items()}
            new_domains[(r, c)] = {val}

            # Add arcs to queue for the newly assigned cell
            queue = []
            for nr, nc in neighbors_dict[(r, c)]:
                queue.append(((nr, nc), (r, c)))

            if ac3(new_domains, queue):
                result = backtrack(new_domains)
                if result:
                    return result

        return False

    # Initial constraint propagation
    if not ac3(domains):
        return "No Solution"

    # Backtracking search
    final_domains = backtrack(domains)

    if final_domains:
        res = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append(list(final_domains[(r, c)])[0])
            res.append(row)
        return res
    else:
        return "No Solution"

