import collections

# The solve function implements a backtracking algorithm with aggressive constraint propagation.
# It uses two main rules of Yin-Yang:
# 1. No 2x2 block can be monochromatic.
# 2. All cells of the same color must be orthogonally connected.
# The deduce function applies these rules to find forced moves, drastically reducing the search space.

def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    def is_valid(current_grid):
        # Check 2x2 rule: no 2x2 block can be all 'B' or all 'W'
        for r in range(R - 1):
            for c in range(C - 1):
                val = current_grid[r][c]
                if val is not None:
                    if val == current_grid[r+1][c] == current_grid[r][c+1] == current_grid[r+1][c+1]:
                        return False

