                    if current_grid[r][c] == color:
                        if first_cell is None:
                            first_cell = (r, c)
                        color_count += 1

            if color_count == 0:
                continue

            visited_color_count = 0
            visited = {first_cell}
            q = collections.deque([first_cell])

            while q:
                curr_r, curr_c = q.popleft()
                if current_grid[curr_r][curr_c] == color:
                    visited_color_count += 1

                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < R and 0 <= nc < C:
                        if (nr, nc) not in visited:
                            val = current_grid[nr][nc]
                            # We can traverse through cells of the same color or empty cells
                            if val == color or val is None:
                                visited.add((nr, nc))
                                q.append((nr, nc))

            # If we couldn't reach all cells of this color, the grid is invalid
            if visited_color_count < color_count:
