    def deduce(current_grid):
        changed = True
        while changed:
            changed = False

            # 1. 2x2 deductions: if 3 cells in a 2x2 are the same color, the 4th must be opposite
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                    colors = [current_grid[nr][nc] for nr, nc in cells]
                    b_count = colors.count('B')
                    w_count = colors.count('W')
                    e_count = colors.count(None)

                    if b_count == 3 and e_count == 1:
                        idx = colors.index(None)
                        nr, nc = cells[idx]
                        current_grid[nr][nc] = 'W'
                        changed = True
                    elif w_count == 3 and e_count == 1:
                        idx = colors.index(None)
                        nr, nc = cells[idx]
                        current_grid[nr][nc] = 'B'
                        changed = True

            # 2. Connectivity deductions: test each empty cell
            for r in range(R):
                for c in range(C):
                    if current_grid[r][c] is None:
                        # Try setting to 'B'
                        current_grid[r][c] = 'B'
                        valid_b = is_valid(current_grid)

                        # Try setting to 'W'
                        current_grid[r][c] = 'W'
                        valid_w = is_valid(current_grid)

                        # Revert
                        current_grid[r][c] = None

                        if valid_b and not valid_w:
                            current_grid[r][c] = 'B'
                            changed = True
                        elif valid_w and not valid_b:
                            current_grid[r][c] = 'W'
                            changed = True
                        elif not valid_b and not valid_w:
                            # Contradiction found, this branch is invalid
                            return False

        return True

    def cell_score(r, c, grid_copy):
        # Heuristic: prioritize cells with many filled neighbors
        score = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid_copy[nr][nc] is not None:
                    if dr == 0 or dc == 0:
                        score += 2 # Orthogonal neighbor
                    else:
                        score += 1 # Diagonal neighbor
        return score

    def backtrack(current_grid):
        # Apply deductions to find forced moves
        if not deduce(current_grid):
            return None

        empty_cells = [(r, c) for r in range(R) for c in range(C) if current_grid[r][c] is None]

        # If no empty cells left, we found a solution
        if not empty_cells:
            if is_valid(current_grid):
                return current_grid
            return None

        # Pick the most constrained empty cell
        empty_cells.sort(key=lambda x: cell_score(x[0], x[1], current_grid), reverse=True)
        r, c = empty_cells[0]

        # Try both colors
        for color in ['B', 'W']:
            current_grid[r][c] = color
            if is_valid(current_grid):
                next_grid = [row[:] for row in current_grid]
                result = backtrack(next_grid)
                if result:
                    return result
            current_grid[r][c] = None

        return None

    # Initial validity check
    if not is_valid(grid):
        return "No Solution"

    # Start backtracking search
    solution = backtrack([row[:] for row in grid])
    if solution:
        return solution
    else:
        return "No Solution"

