    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                target = data[r][c]
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            neighbors.append((nr, nc))
                constraint = {'target': target, 'unassigned': set(neighbors), 'assigned_mines': 0}
                constraints.append(constraint)
                for nr, nc in neighbors:
                    var_to_constraints[(nr, nc)].append(constraint)

