                if (r, c) in constraint['unassigned']:
                    constraint['unassigned'].remove((r, c))
                    if val == 1:
                        constraint['assigned_mines'] += 1

                    mines_left = constraint['target'] - constraint['assigned_mines']

                    # Check for immediate failure
                    if mines_left < 0 or mines_left > len(constraint['unassigned']):
                        return False

                    # If constraint is fully determined, queue the remaining variables
                    if mines_left == 0:
                        for nr, nc in list(constraint['unassigned']):
                            queue.append((nr, nc, 0))
                    elif mines_left == len(constraint['unassigned']):
                        for nr, nc in list(constraint['unassigned']):
                            queue.append((nr, nc, 1))
        return True

    def apply_subset_reduction(queue):
        """
        Mimic human deduction: if unassigned variables of constraint A are a strict subset 
        of constraint B, we can deduce the number of mines in the remaining variables of B.
        """
        active_constraints = [c for c in constraints if len(c['unassigned']) > 0]
        n = len(active_constraints)
        made_changes = False

        for i in range(n):
            for j in range(n):
                if i == j: continue
                c1 = active_constraints[i]
                c2 = active_constraints[j]

                if not c1['unassigned'] or not c2['unassigned']:
                    continue

                if c1['unassigned'] < c2['unassigned']:
                    mines1 = c1['target'] - c1['assigned_mines']
                    mines2 = c2['target'] - c2['assigned_mines']

                    remaining_mines = mines2 - mines1
                    remaining_vars = c2['unassigned'] - c1['unassigned']

                    if remaining_mines < 0 or remaining_mines > len(remaining_vars):
                        return "CONTRADICTION"

                    if remaining_mines == 0:
                        for r, c in remaining_vars:
                            if (r, c) not in assignment:
                                queue.append((r, c, 0))
                                made_changes = True
                    elif remaining_mines == len(remaining_vars):
                        for r, c in remaining_vars:
                            if (r, c) not in assignment:
                                queue.append((r, c, 1))
                                made_changes = True

        return made_changes

    def full_propagate(queue):
        """Alternate between basic propagation and subset reduction until stable."""
        while True:
            if not propagate(queue):
                return False
            res = apply_subset_reduction(queue)
            if res == "CONTRADICTION":
                return False
            if not res:
                break
        return True

    # Initial population of the propagation queue
    queue = []
    for constraint in constraints:
        mines_left = constraint['target'] - constraint['assigned_mines']
        if mines_left == 0:
            for nr, nc in list(constraint['unassigned']):
                queue.append((nr, nc, 0))
        elif mines_left == len(constraint['unassigned']):
            for nr, nc in list(constraint['unassigned']):
                queue.append((nr, nc, 1))

    if not full_propagate(queue):
        return "No Solution"

    def backtrack():
        """Backtracking search with Minimum Remaining Values (MRV) and Degree heuristics."""
        unassigned_vars = [(r, c) for r in range(R) for c in range(C) if (r, c) not in assignment]
        if not unassigned_vars:
            return True

        best_var = None
        min_slack = float('inf')
        max_degree = -1

        # Heuristic: Pick the variable involved in the tightest constraints
        for r, c in unassigned_vars:
            degree = len(var_to_constraints[(r, c)])
            slack = min([len(constraint['unassigned']) for constraint in var_to_constraints[(r, c)]] + [float('inf')])

            if slack < min_slack:
                min_slack = slack
                max_degree = degree
                best_var = (r, c)
            elif slack == min_slack and degree > max_degree:
                max_degree = degree
                best_var = (r, c)

        if best_var is None:
            best_var = unassigned_vars[0]

        # Try assigning 1 (Black) then 0 (White)
        for val in [1, 0]:
            # Save state
            saved_assignment = assignment.copy()
            saved_constraints = [{'unassigned': set(c['unassigned']), 'assigned_mines': c['assigned_mines']} for c in constraints]

            queue = [(best_var[0], best_var[1], val)]
            if full_propagate(queue):
                if backtrack():
                    return True

            # Restore state
            assignment.clear()
            assignment.update(saved_assignment)
            for i, c in enumerate(constraints):
                c['unassigned'] = set(saved_constraints[i]['unassigned'])
                c['assigned_mines'] = saved_constraints[i]['assigned_mines']

        return False

    if backtrack():
        result = []
        for r in range(R):
            row = []
            for c in range(C):
                if assignment.get((r, c), 0) == 1:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    else:
        return "No Solution"

