            for i in range(N):
                if i != c:
                    n_list.append((r, i))
                if i != r:
                    n_list.append((i, c))
            neighbors[(r, c)] = n_list

    # Precompute adjacency and dot presence to speed up the revise function
    is_adj_cache = {}
    has_dot_cache = {}
    for r1 in range(N):
        for c1 in range(N):
            for r2 in range(N):
                for c2 in range(N):
                    if (r1, c1) == (r2, c2): continue
                    is_adj = abs(r1 - r2) + abs(c1 - c2) == 1
                    is_adj_cache[((r1, c1), (r2, c2))] = is_adj
                    if is_adj:
                        mid_r = (r1 + r2) / 2.0
                        mid_c = (c1 + c2) / 2.0
                        has_dot_cache[((r1, c1), (r2, c2))] = (mid_r, mid_c) in adj_set
                    else:
                        has_dot_cache[((r1, c1), (r2, c2))] = False

    def revise(domains, c1, c2):
        revised = False
        is_adj = is_adj_cache[(c1, c2)]
        has_dot = has_dot_cache[(c1, c2)]

        to_remove = set()
        for v in domains[c1]:
            supported = False
            for w in domains[c2]:
                if v == w:
                    continue
                if is_adj:
                    if has_dot and abs(v - w) != 1:
                        continue
                    if not has_dot and abs(v - w) == 1:
                        continue
                supported = True
                break
            if not supported:
                to_remove.add(v)

        if to_remove:
            domains[c1] -= to_remove
            revised = True

        return revised

    def propagate(domains, queue):
        import collections
        q = collections.deque(queue)
        while q:
            c1, c2 = q.popleft()
            if revise(domains, c1, c2):
                if not domains[c1]:
                    return False
                for neighbor in neighbors[c1]:
                    if neighbor != c2:
                        q.append((neighbor, c1))
        return True

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Initial constraint propagation queue
    queue = []
    for r in range(N):
        for c in range(N):
            for neighbor in neighbors[(r, c)]:
                queue.append(((r, c), neighbor))

    if not propagate(domains, queue):
        return "No Solution"

    # Backtracking search with Minimum Remaining Values (MRV) heuristic
    def backtrack(domains):
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                l = len(domains[(r, c)])
                if l > 1 and l < min_len:
                    min_len = l
                    best_cell = (r, c)

        if best_cell is None:
            return domains

        for val in domains[best_cell]:
            new_domains = {k: v.copy() for k, v in domains.items()}
            new_domains[best_cell] = {val}

            queue = []
            for neighbor in neighbors[best_cell]:
                queue.append((neighbor, best_cell))

            if propagate(new_domains, queue):
                result = backtrack(new_domains)
                if result:
                    return result

        return False

    result = backtrack(domains)
    if result:
        ans = [[0]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                ans[r][c] = list(result[(r, c)])[0]
        return ans
    else:
        return "No Solution"

