OBSERVATION = {'row_black_runs': [[4, 2, 1], [1, 3], [1, 4], [4], [5], [1], [3, 1], [4, 2], [7], [7]], 'col_black_runs': [[1], [2, 1], [1, 1, 3], [1, 4], [4], [5, 4], [5, 2], [4, 2], [3, 2], [1, 4]]}

def solve_line(clues, state):
    """
    Solves a single line (row or column) given the clues and current state.
    state: list of 0 (unknown), 1 (black), -1 (white)
    Returns a new state with deduced cells, or None if no valid placement exists.
    """
    memo = {}
    def can_place(c_idx, s_idx):
        if (c_idx, s_idx) in memo:
            return memo[(c_idx, s_idx)]

        # If all clues are placed, remaining cells must be able to be white
        if c_idx == len(clues):
            for i in range(s_idx, len(state)):
                if state[i] == 1:
                    memo[(c_idx, s_idx)] = False
                    return False
            memo[(c_idx, s_idx)] = True
            return True

        # If we run out of cells but still have clues to place
        if s_idx >= len(state):
            memo[(c_idx, s_idx)] = False
            return False

        res = False

        # Option 1: Leave current cell white (if it's not forced black)
        if state[s_idx] != 1:
            if can_place(c_idx, s_idx + 1):
                res = True

        # Option 2: Place the next block starting at current cell
        L = clues[c_idx]
        if s_idx + L <= len(state):
            can_place_block = True
            # Check if the block can be placed (no forced white cells in the way)
            for i in range(s_idx, s_idx + L):
                if state[i] == -1:
                    can_place_block = False
                    break

            if can_place_block:
                # If block reaches the end of the line
                if s_idx + L == len(state):
                    if can_place(c_idx + 1, s_idx + L):
                        res = True
                else:
                    # Block must be followed by at least one white cell
                    if state[s_idx + L] != 1:
                        if can_place(c_idx + 1, s_idx + L + 1):
                            res = True

        memo[(c_idx, s_idx)] = res
        return res

    # Check if the current state is valid at all
    if not can_place(0, 0):
        return None

    new_state = list(state)
    # Try forcing each unknown cell to black and white to see if it's constrained
    for i in range(len(state)):
        if state[i] == 0:
            # Try black
            state[i] = 1
            memo.clear()
            can_be_black = can_place(0, 0)

            # Try white
            state[i] = -1
            memo.clear()
            can_be_white = can_place(0, 0)

            # Backtrack
            state[i] = 0

            if can_be_black and not can_be_white:
                new_state[i] = 1
            elif can_be_white and not can_be_black:
                new_state[i] = -1
            elif not can_be_black and not can_be_white:
                return None # Contradiction found

    return new_state

def format_grid(grid):
    """Converts the internal grid representation to the required output format."""
    res = []
    for row in grid:
        res.append(['B' if cell == 1 else None for cell in row])
    return res

def backtrack(grid, row_clues, col_clues):
    """Recursively guesses cells when logical deduction gets stuck."""
    R = len(grid)
    C = len(grid[0])

    # Find the first unknown cell
    best_r, best_c = -1, -1
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0:
                best_r, best_c = r, c
                break
        if best_r != -1:
            break

    # If no unknown cells, the puzzle is solved
    if best_r == -1:
        return format_grid(grid)

    # Guess Black
    grid_copy = [row[:] for row in grid]
    grid_copy[best_r][best_c] = 1
    res = propagate_and_backtrack(grid_copy, row_clues, col_clues)
    if res != "No Solution":
        return res

    # Guess White
    grid_copy = [row[:] for row in grid]
    grid_copy[best_r][best_c] = -1
    res = propagate_and_backtrack(grid_copy, row_clues, col_clues)
    return res

def propagate_and_backtrack(grid, row_clues, col_clues):
    """Applies logical deduction until no more changes occur, then falls back to backtracking."""
    R = len(grid)
    C = len(grid[0])

    changed = True
    while changed:
        changed = False

        # Process all rows
        for r in range(R):
            state = grid[r]
            new_state = solve_line(row_clues[r], state)
            if new_state is None:
                return "No Solution"
            if new_state != state:
                grid[r] = new_state
                changed = True

        # Process all columns
        for c in range(C):
            state = [grid[r][c] for r in range(R)]
            new_state = solve_line(col_clues[c], state)
            if new_state is None:
                return "No Solution"
            if new_state != state:
                for r in range(R):
                    grid[r][c] = new_state[r]
                changed = True

    return backtrack(grid, row_clues, col_clues)

def solve(observation):
    """Main solver function."""
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']

    R = len(row_clues)
    C = len(col_clues)

    # Initialize grid with 0 (unknown)
    grid = [[0] * C for _ in range(R)]

    return propagate_and_backtrack(grid, row_clues, col_clues)

