                    comp = []
                    q = [i]
                    visited_certain.add(i)
                    while q:
                        curr = q.pop(0)
                        comp.append(curr)
                        for nxt in adj_certain[curr]:
                            if nxt not in visited_certain:
                                visited_certain.add(nxt)
                                q.append(nxt)
                    components.append(comp)

            for comp in components:
                if len(comp) < len(islands):
                    can_leave = False
                    for u in comp:
                        for e in island_edges[u]:
                            v = e[0] if e[1] == u else e[1]
                            if v not in comp and max(domains[e]) > 0:
                                can_leave = True
                                break
                        if can_leave:
                            break
                    if not can_leave:
                        return False
        return True

    def solve_csp(domains):
        if not propagate(domains):
            return None

        unassigned = [e for e in edges if len(domains[e]) > 1]
        if not unassigned:
            return domains

        # Heuristic: pick the most constrained edge (smallest domain)
        unassigned.sort(key=lambda e: len(domains[e]))
        e = unassigned[0]

        # Try larger values first to find a solution faster
        for val in sorted(list(domains[e]), reverse=True):
            new_domains = {k: set(v) for k, v in domains.items()}
            new_domains[e] = {val}
            result = solve_csp(new_domains)
            if result:
                return result
        return None

    final_domains = solve_csp(domains)
    if not final_domains:
        return "No Solution"

    ans = {}
    for e, dom in final_domains.items():
        val = list(dom)[0]
        if val > 0:
            ans[e] = val

    return ans

