OBSERVATION = {'row_black_runs': [[1], [3], [3], [4], [2]], 'col_black_runs': [[2, 1], [1, 2], [4], [2], [1]]}

def solve_line(clues, line):
    """
    Solves a single line (row or column) using Dynamic Programming.
    Returns a new line with updated deduced cells, or None if the line is invalid.
    """
    length = len(line)
    num_clues = len(clues)

    def can_match(line_idx, clue_idx, current_line, memo):
        state = (line_idx, clue_idx)
        if state in memo:
            return memo[state]

        # If all clues are placed, the rest of the line must be empty (0 or -1)
        if clue_idx == num_clues:
            res = all(x in (0, -1) for x in current_line[line_idx:])
            memo[state] = res
            return res

        # If we run out of line space but still have clues
        if line_idx >= length:
            memo[state] = False
            return False

        clue = clues[clue_idx]
        res = False

        # Option 1: Leave the current cell empty (0)
        if current_line[line_idx] in (0, -1):
            if can_match(line_idx + 1, clue_idx, current_line, memo):
                res = True

        # Option 2: Place the current clue block starting at line_idx
        if not res and line_idx + clue <= length:
            # Check if the block can be placed (no 0s in the way)
            if all(x in (1, -1) for x in current_line[line_idx : line_idx+clue]):
                if clue_idx == num_clues - 1:
                    # If it's the last clue, check the rest of the line
                    if can_match(line_idx + clue, clue_idx + 1, current_line, memo):
                        res = True
                else:
                    # If not the last clue, it MUST be followed by at least one empty cell (0)
                    if line_idx + clue < length and current_line[line_idx + clue] in (0, -1):
                        if can_match(line_idx + clue + 1, clue_idx + 1, current_line, memo):
                            res = True

        memo[state] = res
        return res

    # Initial check to see if the line is valid at all
    memo = {}
    if not can_match(0, 0, line, memo):
        return None

    new_line = list(line)
    # Test each unknown cell to see if it MUST be 0 or 1
    for i in range(length):
        if line[i] == -1:
            # Test setting to 0
            line[i] = 0
            can_0 = can_match(0, 0, line, {})

            # Test setting to 1
            line[i] = 1
            can_1 = can_match(0, 0, line, {})

            # Restore to unknown
            line[i] = -1

            # Deduce based on possibilities
            if can_0 and not can_1:
                new_line[i] = 0
            elif can_1 and not can_0:
                new_line[i] = 1
            elif not can_0 and not can_1:
                return None # Contradiction found

    return new_line

def propagate(grid, row_clues, col_clues):
    """
    Repeatedly applies line solving to rows and columns until no more changes can be made.
    """
    R = len(row_clues)
    C = len(col_clues)

    changed = True
    while changed:
        changed = False

        # Process all rows
        for r in range(R):
            line = grid[r]
            new_line = solve_line(row_clues[r], line)
            if new_line is None:
                return None
            if new_line != line:
                grid[r] = new_line
                changed = True

        # Process all columns
        for c in range(C):
            line = [grid[r][c] for r in range(R)]
            new_line = solve_line(col_clues[c], line)
            if new_line is None:
                return None
            if new_line != line:
                for r in range(R):
                    grid[r][c] = new_line[r]
                changed = True

    return grid

def backtrack(grid, row_clues, col_clues):
    """
    Backtracking search for when logical deduction is not enough.
    Guesses the most constrained unknown cell.
    """
    R = len(row_clues)
    C = len(col_clues)

    best_r, best_c = -1, -1
    min_unknowns = float('inf')

    # Find the best cell to guess (most constrained)
    for r in range(R):
        for c in range(C):
            if grid[r][c] == -1:
                unknowns = sum(1 for x in grid[r] if x == -1) + sum(1 for r2 in range(R) if grid[r2][c] == -1)
                if unknowns < min_unknowns:
                    min_unknowns = unknowns
                    best_r, best_c = r, c

    if best_r == -1:
        return grid # Fully solved

    # Guess 1 (black) first, then 0 (white)
    for guess in (1, 0):
        new_grid = [list(row) for row in grid]
        new_grid[best_r][best_c] = guess

        result = propagate(new_grid, row_clues, col_clues)
        if result is not None:
            if all(result[r][c] != -1 for r in range(R) for c in range(C)):
                return result
            final_result = backtrack(result, row_clues, col_clues)
            if final_result is not None:
                return final_result

    return None

def format_grid(grid):
    """
    Formats the internal grid representation to the requested output format.
    """
    return [[ 'B' if cell == 1 else None for cell in row ] for row in grid]

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']

    R = len(row_clues)
    C = len(col_clues)

    # Initialize grid with -1 (unknown)
    grid = [[-1] * C for _ in range(R)]

    # Initial logical deduction
    grid = propagate(grid, row_clues, col_clues)
    if grid is None:
        return "No Solution"

    # Check if solved by pure deduction
    if all(grid[r][c] != -1 for r in range(R) for c in range(C)):
        return format_grid(grid)

    # Fallback to backtracking if needed
    final_grid = backtrack(grid, row_clues, col_clues)
    if final_grid is not None:
        return format_grid(final_grid)

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
