from collections import deque

class Solver:
    def __init__(self, observation):
        self.data = observation['data']
        self.n = len(self.data)
        self.adjacent = observation['adjacent']

        # Initialize domains for each cell
        self.domains = {}
        for r in range(self.n):
            for c in range(self.n):
                if self.data[r][c] is not None:
                    self.domains[(r, c)] = {self.data[r][c]}
                else:
                    self.domains[(r, c)] = set(range(1, self.n + 1))

        # Parse dots into a set of adjacent cell pairs
        self.dots = set()
        for r, c in self.adjacent:
            if r == int(r): # Horizontal dot
                r_int, c_int = int(r), int(c - 0.5)
                self.dots.add(((r_int, c_int), (r_int, c_int + 1)))
                self.dots.add(((r_int, c_int + 1), (r_int, c_int)))
            else: # Vertical dot
                r_int, c_int = int(r - 0.5), int(c)
                self.dots.add(((r_int, c_int), (r_int + 1, c_int)))
                self.dots.add(((r_int + 1, c_int), (r_int, c_int)))

    def get_neighbors(self, r, c):
        # Returns all cells in the same row and column
        neighbors = []
        for i in range(self.n):
            if i != c:
                neighbors.append((r, i))
            if i != r:
                neighbors.append((i, c))
        return neighbors

    def revise(self, r1, c1, r2, c2):
        revised = False
        is_adjacent = abs(r1 - r2) + abs(c1 - c2) == 1
        has_dot = ((r1, c1), (r2, c2)) in self.dots

        domain2 = self.domains[(r2, c2)]
        to_remove = set()

        for x in self.domains[(r1, c1)]:
            valid_y_found = False
            for y in domain2:
                if x == y:
                    continue # Alldiff constraint for row/col
                if is_adjacent:
                    diff = abs(x - y)
                    if has_dot and diff != 1:
                        continue # Must be consecutive if dot exists
                    if not has_dot and diff == 1:
                        continue # Must NOT be consecutive if no dot exists
                valid_y_found = True
                break

            if not valid_y_found:
                to_remove.add(x)
                revised = True

        if revised:
            self.domains[(r1, c1)] -= to_remove

        return revised

    def ac3(self):
        queue = deque()
        for r1 in range(self.n):
            for c1 in range(self.n):
                for r2, c2 in self.get_neighbors(r1, c1):
                    queue.append((r1, c1, r2, c2))

        while queue:
            r1, c1, r2, c2 = queue.popleft()
            if self.revise(r1, c1, r2, c2):
                if len(self.domains[(r1, c1)]) == 0:
                    return False
                for r3, c3 in self.get_neighbors(r1, c1):
                    if (r3, c3) != (r2, c2):
                        queue.append((r3, c3, r1, c1))
        return True

    def backtrack(self):
        # Minimum Remaining Values (MRV) heuristic
        min_len = self.n + 1
        best_cell = None
        for r in range(self.n):
            for c in range(self.n):
                if len(self.domains[(r, c)]) > 1:
                    if len(self.domains[(r, c)]) < min_len:
                        min_len = len(self.domains[(r, c)])
                        best_cell = (r, c)

        if best_cell is None:
            # All cells have exactly 1 value, puzzle solved
            return [[list(self.domains[(r, c)])[0] for c in range(self.n)] for r in range(self.n)]

        r, c = best_cell
        for val in list(self.domains[(r, c)]):
            # Save state before assignment
            saved_domains = {k: v.copy() for k, v in self.domains.items()}
            self.domains[(r, c)] = {val}

            # Propagate constraints from the new assignment
            queue = deque()
            for r2, c2 in self.get_neighbors(r, c):
                queue.append((r2, c2, r, c))

            possible = True
            while queue:
                r1, c1, r2, c2 = queue.popleft()
                if self.revise(r1, c1, r2, c2):
                    if len(self.domains[(r1, c1)]) == 0:
                        possible = False
                        break
                    for r3, c3 in self.get_neighbors(r1, c1):
                        if (r3, c3) != (r2, c2):
                            queue.append((r3, c3, r1, c1))

            if possible:
                result = self.backtrack()
                if result:
                    return result

            # Restore state if assignment failed
            self.domains = saved_domains

        return None

    def solve(self):
        if not self.ac3():
            return "No Solution"
        result = self.backtrack()
        if result:
            return result
        return "No Solution"

def solve(observation):
    solver = Solver(observation)
    return solver.solve()

if __name__ == "__main__":
    print(solve(OBSERVATION))
