def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    R = len(row_targets)
    C = len(col_targets)

    # Weights are implicitly 1 to N based on the visual puzzle structure
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Step 1: Find all valid configurations for each row independently
    valid_row_configs = []
    for r in range(R):
        target = row_targets[r]
        configs = []

        def find_configs(c, current_sum, current_config):
            if c == C:
                if current_sum == target:
                    configs.append(tuple(current_config))
                return

            # Option 1: Cell is not black (0)
            current_config.append(0)
            find_configs(c + 1, current_sum, current_config)
            current_config.pop()

            # Option 2: Cell is black (1)
            if current_sum + col_weights[c] <= target:
                current_config.append(1)
                find_configs(c + 1, current_sum + col_weights[c], current_config)
                current_config.pop()

        find_configs(0, 0, [])
        if not configs:
            return "No Solution" # Impossible row target
        valid_row_configs.append(configs)

    # Step 2: Constraint Propagation (Human-like deduction)
    # Iteratively narrow down possible configurations by checking column bounds
    locked_configs = [None] * R

    while True:
        changed = False

        # Lock rows that have only one valid configuration left
        for r in range(R):
            if locked_configs[r] is None and len(valid_row_configs[r]) == 1:
                locked_configs[r] = valid_row_configs[r][0]
                changed = True

        # Calculate the absolute minimum and maximum possible sums for each column
        min_col_sums = [0] * C
        max_col_sums = [0] * C
        for r in range(R):
            if locked_configs[r] is not None:
                for c in range(C):
                    if locked_configs[r][c] == 1:
                        min_col_sums[c] += row_weights[r]
                        max_col_sums[c] += row_weights[r]
            else:
                for c in range(C):
                    can_be_one = any(config[c] == 1 for config in valid_row_configs[r])
                    must_be_one = all(config[c] == 1 for config in valid_row_configs[r])
                    if can_be_one:
                        max_col_sums[c] += row_weights[r]
                    if must_be_one:
                        min_col_sums[c] += row_weights[r]

        # Global impossibility check
        for c in range(C):
            if min_col_sums[c] > col_targets[c] or max_col_sums[c] < col_targets[c]:
                return "No Solution"

        # Filter configurations of unlocked rows based on column bounds
        for r in range(R):
            if locked_configs[r] is not None:
                continue

            new_configs = []
            for config in valid_row_configs[r]:
                possible = True
                for c in range(C):
                    # Calculate what the min/max would be if we chose THIS specific config
                    current_min_contrib = row_weights[r] if all(cfg[c] == 1 for cfg in valid_row_configs[r]) else 0
                    current_max_contrib = row_weights[r] if any(cfg[c] == 1 for cfg in valid_row_configs[r]) else 0

                    specific_contrib = row_weights[r] if config[c] == 1 else 0

                    new_min = min_col_sums[c] - current_min_contrib + specific_contrib
                    new_max = max_col_sums[c] - current_max_contrib + specific_contrib

                    if new_min > col_targets[c] or new_max < col_targets[c]:
                        possible = False
                        break
                if possible:
                    new_configs.append(config)

            if len(new_configs) == 0:
                return "No Solution"

            if len(new_configs) < len(valid_row_configs[r]):
                valid_row_configs[r] = new_configs
                changed = True

        if not changed:
            break

    # Step 3: DFS with aggressive pruning on the reduced search space
    # Precalculate remaining bounds for fast DFS pruning
    max_remaining_col_sums = []
    min_remaining_col_sums = []
    for r in range(R):
        max_sums = [0] * C
        min_sums = [0] * C
        for next_r in range(r, R):
            for c in range(C):
                can_be_one = any(config[c] == 1 for config in valid_row_configs[next_r])
                must_be_one = all(config[c] == 1 for config in valid_row_configs[next_r])
                if can_be_one:
                    max_sums[c] += row_weights[next_r]
                if must_be_one:
                    min_sums[c] += row_weights[next_r]
        max_remaining_col_sums.append(max_sums)
        min_remaining_col_sums.append(min_sums)
    max_remaining_col_sums.append([0] * C)
    min_remaining_col_sums.append([0] * C)

    def dfs(r, current_col_sums):
        if r == R:
            return current_col_sums == col_targets

        for config in valid_row_configs[r]:
            next_col_sums = list(current_col_sums)
            possible = True
            for c in range(C):
                if config[c] == 1:
                    next_col_sums[c] += row_weights[r]

                # Prune if current sum exceeds target or if target is unreachable
                if next_col_sums[c] > col_targets[c]:
                    possible = False
                    break
                if next_col_sums[c] + max_remaining_col_sums[r+1][c] < col_targets[c]:
                    possible = False
                    break
                if next_col_sums[c] + min_remaining_col_sums[r+1][c] > col_targets[c]:
                    possible = False
                    break

            if possible:
                solution.append(config)
                if dfs(r + 1, next_col_sums):
                    return True
                solution.pop()

        return False

    solution = []
    if dfs(0, [0] * C):
        grid = []
        for r in range(R):
            row = []
            for c in range(C):
                if solution[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            grid.append(row)
        return grid
    else:
        return "No Solution"

