def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    # Identify all unknown cells (cells without numbers)
    unknowns = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] is None:
                unknowns.append((r, c))

    # Precompute numbered cells and their unknown neighbors for fast propagation
    numbered_cells = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] is not None:
                neighbors = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] is None:
                            neighbors.append((nr, nc))
                numbered_cells.append((r, c, grid[r][c], neighbors))

    # Sort unknowns by the number of adjacent numbered cells to optimize backtracking
    adj_count = {u: 0 for u in unknowns}
    for r, c, n, neighbors in numbered_cells:
        for nr, nc in neighbors:
            adj_count[(nr, nc)] += 1

    unknowns.sort(key=lambda x: adj_count[x], reverse=True)

    def propagate(assignment):
        """
        Applies constraint propagation to deduce safe cells and mines.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False
            for r, c, n, neighbors in numbered_cells:
                u_neighbors = []
                m_count = 0
                for nr, nc in neighbors:
                    if (nr, nc) in assignment:
                        if assignment[(nr, nc)] == 1:
                            m_count += 1
                    else:
                        u_neighbors.append((nr, nc))

                # Contradiction: too many mines
                if m_count > n:
                    return False
                # Contradiction: not enough potential mines
                if m_count + len(u_neighbors) < n:
                    return False

                # Deduction: all remaining neighbors must be safe
                if m_count == n and len(u_neighbors) > 0:
                    for nr, nc in u_neighbors:
                        assignment[(nr, nc)] = 0
                    changed = True
                # Deduction: all remaining neighbors must be mines
                elif m_count + len(u_neighbors) == n and len(u_neighbors) > 0:
                    for nr, nc in u_neighbors:
                        assignment[(nr, nc)] = 1
                    changed = True
        return True

    # Initial propagation before any guessing
    initial_assignment = {}
    if not propagate(initial_assignment):
        return "No Solution"

    def backtrack(idx, current_assignment):
        """
        Backtracking search to find a valid assignment for all unknown cells.
        """
        if idx == len(unknowns):
            return current_assignment

        r, c = unknowns[idx]
        # Skip if already deduced by propagation
        if (r, c) in current_assignment:
            return backtrack(idx + 1, current_assignment)

        # Try assigning Safe (0) then Mine (1)
        for val in [0, 1]:
            new_assignment = current_assignment.copy()
            new_assignment[(r, c)] = val

            if propagate(new_assignment):
                res = backtrack(idx + 1, new_assignment)
                if res is not None:
                    return res

        return None

    final_assignment = backtrack(0, initial_assignment)

    if final_assignment is not None:
        res = []
        for r in range(R):
            row = []
            for c in range(C):
                if grid[r][c] is not None:
                    row.append(None)
                else:
                    row.append('F' if final_assignment.get((r, c), 0) == 1 else None)
            res.append(row)
        return res
    else:
        return "No Solution"

