def get_peers_and_units(N, r_unit, c_unit):
    peers = {}
    units = {}
    unit_list = []

    # Row units
    for r in range(N):
        unit_list.append([(r, c) for c in range(N)])
    # Column units
    for c in range(N):
        unit_list.append([(r, c) for r in range(N)])
    # Subgrid units
    for sr in range(0, N, r_unit):
        for sc in range(0, N, c_unit):
            unit_list.append([(r, c) for r in range(sr, sr + r_unit) for c in range(sc, sc + c_unit)])

    # Map each cell to its units and peers
    for r in range(N):
        for c in range(N):
            units[(r, c)] = []
            peers[(r, c)] = set()
            for u in unit_list:
                if (r, c) in u:
                    units[(r, c)].append(u)
                    for cell in u:
                        if cell != (r, c):
                            peers[(r, c)].add(cell)

    return peers, units, unit_list

def eliminate(values, s, d, peers, units):
    """Eliminate value d from the possible values of cell s."""
    if d not in values[s]:
        return True # Already eliminated

    values[s].remove(d)

    # Rule 1: If a cell is reduced to one possible value, eliminate that value from its peers.
    if len(values[s]) == 0:
        return False # Contradiction: no possible values left
    elif len(values[s]) == 1:
        d2 = values[s][0]
        for peer in peers[s]:
            if not eliminate(values, peer, d2, peers, units):
                return False

    # Rule 2: If a unit has only one possible cell for a value d, assign d to that cell.
    for u in units[s]:
        dplaces = [s2 for s2 in u if d in values[s2]]
        if len(dplaces) == 0:
            return False # Contradiction: no place for this value in the unit
        elif len(dplaces) == 1:
            # If the cell doesn't already have this as its only value, assign it
            if len(values[dplaces[0]]) > 1:
                if not assign(values, dplaces[0], d, peers, units):
                    return False
    return True

def assign(values, s, d, peers, units):
    """Assign value d to cell s by eliminating all other possible values."""
    other_values = [v for v in values[s] if v != d]
    for d2 in other_values:
        if not eliminate(values, s, d2, peers, units):
            return False
    return True

def search(values, peers, units, N):
    """Using depth-first search and constraint propagation, try all possible values."""
    if values is False:
        return False
    if all(len(values[s]) == 1 for s in values):
        return values # Solved

    # Minimum Remaining Values (MRV) heuristic: choose the cell with the fewest possibilities
    n, s = min((len(values[s]), s) for s in values if len(values[s]) > 1)

    for d in list(values[s]):
        # Create a deep copy of the values dictionary
        values_copy = {k: list(v) for k, v in values.items()}
        if assign(values_copy, s, d, peers, units):
            result = search(values_copy, peers, units, N)
            if result:
                return result
    return False

def solve(observation):
    data = observation['data']
    unit_str = observation['unit']

    # Parse unit dimensions
    if 'x' in unit_str:
        r_unit, c_unit = map(int, unit_str.split('x'))
    else:
        r_unit = c_unit = int(unit_str)

    N = r_unit * c_unit

    peers, units, unit_list = get_peers_and_units(N, r_unit, c_unit)

    # Initialize all cells with all possible values (1 to N)
    values = { (r, c): list(range(1, N + 1)) for r in range(N) for c in range(N) }

    # Apply initial constraints from the given grid
    for r in range(N):
        for c in range(N):
            val = data[r][c]
            if val is not None:
                if not assign(values, (r, c), val, peers, units):
                    return "No Solution"

    # Search for a solution
    result = search(values, peers, units, N)

    if result:
        # Format the result into a 2D list
        ans = [[result[(r, c)][0] for c in range(N)] for r in range(N)]
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
