import itertools

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])

    regions = {}
    for r in range(R):
        for c in range(C):
            reg = grid_data[r][c]
            if reg not in regions:
                regions[reg] = []
            regions[reg].append((r, c))

    region_ids = list(regions.keys())
    num_regions = len(region_ids)

    TETROMINOES = {
        'I': [
            [(0,0), (0,1), (0,2), (0,3)],
            [(0,0), (1,0), (2,0), (3,0)]
        ],
        'T': [
            [(0,0), (0,1), (0,2), (1,1)],
            [(1,0), (1,1), (1,2), (0,1)],
            [(0,0), (1,0), (2,0), (1,1)],
            [(0,1), (1,1), (2,1), (1,0)]
        ],
        'S': [
            [(1,0), (1,1), (0,1), (0,2)],
            [(0,0), (0,1), (1,1), (1,2)],
            [(0,0), (1,0), (1,1), (2,1)],
            [(1,0), (2,0), (0,1), (1,1)]
        ],
        'L': [
            [(0,0), (1,0), (2,0), (0,1)],
            [(0,0), (1,0), (2,0), (2,1)],
            [(0,1), (1,1), (2,1), (0,0)],
            [(0,1), (1,1), (2,1), (2,0)],
            [(0,0), (0,1), (0,2), (1,0)],
            [(0,0), (0,1), (0,2), (1,2)],
            [(1,0), (1,1), (1,2), (0,0)],
            [(1,0), (1,1), (1,2), (0,2)]
        ]
    }

    def normalize(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    NORMALIZED_TETROMINOES = {}
    for t_type, shapes in TETROMINOES.items():
        for shape in shapes:
            NORMALIZED_TETROMINOES[normalize(shape)] = t_type

    def get_type(cells):
        norm = normalize(cells)
        return NORMALIZED_TETROMINOES.get(norm)

    def is_connected(cells):
        if not cells: return True
        cells_set = set(cells)
        start = cells[0]
        visited = {start}
        q = [start]
        while q:
            r, c = q.pop(0)
            for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells_set and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(cells)

    def has_2x2(shaded_cells):
        for r, c in shaded_cells:
            if (r+1, c) in shaded_cells and (r, c+1) in shaded_cells and (r+1, c+1) in shaded_cells:
                return True
        return False

    def can_be_connected(current_shaded, unassigned_cells):
        if not current_shaded: return True
        all_available = current_shaded | unassigned_cells
        start = next(iter(current_shaded))
        visited = {start}
        q = [start]
        while q:
            r, c = q.pop(0)
            for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in all_available and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return current_shaded.issubset(visited)

    adjacencies = {reg: set() for reg in region_ids}
    for r in range(R):
        for c in range(C):
            reg = grid_data[r][c]
            for dr, dc in [(0,1), (1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    nreg = grid_data[nr][nc]
                    if reg != nreg:
                        adjacencies[reg].add(nreg)
                        adjacencies[nreg].add(reg)

    placements = {}
    for reg in region_ids:
        placements[reg] = []
        cells = regions[reg]
        for combo in itertools.combinations(cells, 4):
            if is_connected(list(combo)):
                t_type = get_type(list(combo))
                if t_type:
                    placements[reg].append((t_type, list(combo)))

    # Sort regions by MRV (Minimum Remaining Values) heuristic
    region_ids.sort(key=lambda r: len(placements[r]))

    def solve_recursive(idx, current_shaded, current_types):
        if idx == num_regions:
            if is_connected(list(current_shaded)):
                return current_shaded, current_types
            return None

        unassigned_cells = set()
        for i in range(idx, num_regions):
            unassigned_cells.update(regions[region_ids[i]])

        if not can_be_connected(current_shaded, unassigned_cells):
            return None

        reg = region_ids[idx]
        for t_type, cells in placements[reg]:
            valid = True
            for adj in adjacencies[reg]:
                if adj in current_types and current_types[adj] == t_type:
                    valid = False
                    break
            if not valid: continue

            new_shaded = current_shaded | set(cells)
            if has_2x2(new_shaded): continue

            current_types[reg] = t_type
            res = solve_recursive(idx + 1, new_shaded, current_types)
            if res: return res
            del current_types[reg]

        return None

    result = solve_recursive(0, set(), {})

    if result:
        shaded_cells, types = result
        ans_grid = [[None for _ in range(C)] for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if (r, c) in shaded_cells:
                    reg = grid_data[r][c]
                    ans_grid[r][c] = types[reg]
        return ans_grid
    else:
        return "No Solution"

