OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1], [0, 0, 1, 1, 2, 2], [0, 1, 1, 1, 2, 2], [3, 3, 1, 1, 2, 2], [3, 3, 4, 4, 4, 4], [3, 3, 4, 4, 4, 4]]}

def get_tetrominoes():
    """Generates all unique orientations of L, I, T, S tetrominoes."""
    shapes = {
        'I': [[(0,0), (0,1), (0,2), (0,3)]],
        'L': [[(0,0), (1,0), (2,0), (2,1)]],
        'T': [[(0,0), (0,1), (0,2), (1,1)]],
        'S': [[(0,1), (0,2), (1,0), (1,1)]]
    }
    all_shapes = []
    for t_type, base_shapes in shapes.items():
        type_shapes = set()
        for base_shape in base_shapes:
            for rot in range(4):
                # Rotate 90 degrees
                rotated = [(c, -r) for r, c in base_shape]
                min_r = min(r for r, c in rotated)
                min_c = min(c for r, c in rotated)
                norm = tuple(sorted((r - min_r, c - min_c) for r, c in rotated))
                type_shapes.add(norm)

                # Reflect
                reflected = [(r, -c) for r, c in rotated]
                min_r = min(r for r, c in reflected)
                min_c = min(c for r, c in reflected)
                norm_ref = tuple(sorted((r - min_r, c - min_c) for r, c in reflected))
                type_shapes.add(norm_ref)
        for shape in type_shapes:
            all_shapes.append((shape, t_type))
    return all_shapes

def get_valid_placements(region_cells, all_tetrominoes):
    """Finds all valid placements of any tetromino within a specific region."""
    placements = []
    region_set = set(region_cells)
    if not region_cells:
        return placements

    min_r_reg = min(r for r, c in region_cells)
    max_r_reg = max(r for r, c in region_cells)
    min_c_reg = min(c for r, c in region_cells)
    max_c_reg = max(c for r, c in region_cells)

    for shape, t_type in all_tetrominoes:
        shape_w = max(c for r, c in shape) + 1
        shape_h = max(r for r, c in shape) + 1

        # Slide the bounding box of the shape across the bounding box of the region
        for r_offset in range(min_r_reg, max_r_reg - shape_h + 2):
            for c_offset in range(min_c_reg, max_c_reg - shape_w + 2):
                placed_cells = tuple(sorted((r + r_offset, c + c_offset) for r, c in shape))
                if all(cell in region_set for cell in placed_cells):
                    placements.append((placed_cells, t_type))
    return placements

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])

    # Parse regions
    regions = {}
    for r in range(R):
        for c in range(C):
            reg_id = grid_data[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))

    # Determine region adjacencies
    adj = {reg_id: set() for reg_id in regions}
    for r in range(R):
        for c in range(C):
            reg_id = grid_data[r][c]
            for dr, dc in [(0,1), (1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    n_reg_id = grid_data[nr][nc]
                    if reg_id != n_reg_id:
                        adj[reg_id].add(n_reg_id)
                        adj[n_reg_id].add(reg_id)

    all_tetrominoes = get_tetrominoes()

    # Precompute domains for each region
    region_domains = {}
    for reg_id, cells in regions.items():
        domain = get_valid_placements(cells, all_tetrominoes)
        if not domain:
            return "No Solution"
        region_domains[reg_id] = domain

    # Sort regions by domain size (Minimum Remaining Values heuristic)
    sorted_regions = sorted(regions.keys(), key=lambda k: len(region_domains[k]))

    def is_potentially_connected(assigned_cells, unassigned_regions):
        """
        Checks if the currently shaded cells plus all cells in unassigned regions
        form a single connected component. If not, the final solution cannot be connected.
        """
        if not assigned_cells and not unassigned_regions:
            return True

        potential_area = set(assigned_cells)
        for reg_id in unassigned_regions:
            potential_area.update(regions[reg_id])

        if not potential_area:
            return True

        start_node = next(iter(potential_area))
        visited = set([start_node])
        queue = [start_node]

        while queue:
            curr_r, curr_c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if (nr, nc) in potential_area and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

        return len(visited) == len(potential_area)

    def has_2x2(cells_set):
        """Checks if there is any fully shaded 2x2 block."""
        for r, c in cells_set:
            if (r+1, c) in cells_set and (r, c+1) in cells_set and (r+1, c+1) in cells_set:
                return True
        return False

    def solve_backtrack(idx, current_assignment, current_cells_set):
        if idx == len(sorted_regions):
            # Final strict connectivity check
            if is_potentially_connected(current_cells_set, []):
                return current_assignment
            return None

        reg_id = sorted_regions[idx]
        unassigned = sorted_regions[idx+1:]

        for cells, t_type in region_domains[reg_id]:
            # Constraint: Adjacent regions cannot have the same tetromino type
            valid_type = True
            for neighbor in adj[reg_id]:
                if neighbor in current_assignment:
                    if current_assignment[neighbor][1] == t_type:
                        valid_type = False
                        break
            if not valid_type:
                continue

            new_cells_set = current_cells_set.union(cells)

            # Constraint: No 2x2 block can be fully shaded
            if has_2x2(new_cells_set):
                continue

            # Constraint: Global connectivity pruning
            if not is_potentially_connected(new_cells_set, unassigned):
                continue

            # Recurse
            current_assignment[reg_id] = (cells, t_type)
            res = solve_backtrack(idx + 1, current_assignment, new_cells_set)
            if res:
                return res
            del current_assignment[reg_id]

        return None

    solution = solve_backtrack(0, {}, set())

    if solution:
        ans_grid = [[None for _ in range(C)] for _ in range(R)]
        for reg_id, (cells, t_type) in solution.items():
            for r, c in cells:
                ans_grid[r][c] = t_type
        return ans_grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
