OBSERVATION = {'row_sum': [6, 4, 9, 7, 11], 'col_sum': [4, 9, 3, 7, 13]}

def solve(observation):
    row_sums = observation['row_sum']
    col_sums = observation['col_sum']
    R = len(row_sums)
    C = len(col_sums)

    # Weights are based on 1-indexed positions (1 to N)
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Helper to find all valid subsets of indices that sum to the target
    def get_subsets(target, weights):
        subsets = []
        n = len(weights)
        def dfs(idx, current_sum, current_subset):
            if current_sum == target:
                subsets.append(list(current_subset))
                return
            if idx == n or current_sum > target:
                return
            # Option 1: Include the current weight
            current_subset.append(idx)
            dfs(idx + 1, current_sum + weights[idx], current_subset)
            current_subset.pop()
            # Option 2: Exclude the current weight
            dfs(idx + 1, current_sum, current_subset)
        dfs(0, 0, [])
        return subsets

    # Initialize domains (all possible valid configurations for each row and column)
    row_domains = [get_subsets(row_sums[r], col_weights) for r in range(R)]
    col_domains = [get_subsets(col_sums[c], row_weights) for c in range(C)]

    # If any row or column has no valid subsets initially, the puzzle is unsolvable
    if any(not d for d in row_domains) or any(not d for d in col_domains):
        return "No Solution"

    # Grid state: -1 for unknown, 0 for empty, 1 for black
    grid = [[-1] * C for _ in range(R)]

    # Constraint propagation to aggressively reduce the search space
    def propagate(grid, row_domains, col_domains):
        changed = True
        while changed:
            changed = False

            # 1. Deduce cell values from row domains
            for r in range(R):
                if not row_domains[r]: return False
                for c in range(C):
                    if grid[r][c] == -1:
                        can_be_0 = any(c not in subset for subset in row_domains[r])
                        can_be_1 = any(c in subset for subset in row_domains[r])
                        if can_be_0 and not can_be_1:
                            grid[r][c] = 0
                            changed = True
                        elif can_be_1 and not can_be_0:
                            grid[r][c] = 1
                            changed = True

            # 2. Deduce cell values from column domains
            for c in range(C):
                if not col_domains[c]: return False
                for r in range(R):
                    if grid[r][c] == -1:
                        can_be_0 = any(r not in subset for subset in col_domains[c])
                        can_be_1 = any(r in subset for subset in col_domains[c])
                        if can_be_0 and not can_be_1:
                            grid[r][c] = 0
                            changed = True
                        elif can_be_1 and not can_be_0:
                            grid[r][c] = 1
                            changed = True

            # 3. Filter row domains based on newly determined cell values
            for r in range(R):
                new_domain = []
                for subset in row_domains[r]:
                    valid = True
                    for c in range(C):
                        if grid[r][c] == 1 and c not in subset:
                            valid = False; break
                        if grid[r][c] == 0 and c in subset:
                            valid = False; break
                    if valid:
                        new_domain.append(subset)
                if len(new_domain) < len(row_domains[r]):
                    row_domains[r] = new_domain
                    changed = True

            # 4. Filter column domains based on newly determined cell values
            for c in range(C):
                new_domain = []
                for subset in col_domains[c]:
                    valid = True
                    for r in range(R):
                        if grid[r][c] == 1 and r not in subset:
                            valid = False; break
                        if grid[r][c] == 0 and r in subset:
                            valid = False; break
                    if valid:
                        new_domain.append(subset)
                if len(new_domain) < len(col_domains[c]):
                    col_domains[c] = new_domain
                    changed = True

        return True

    # Backtracking search with constraint propagation
    def backtrack(grid, row_domains, col_domains):
        if not propagate(grid, row_domains, col_domains):
            return False

        # Find the most constrained unassigned cell
        min_options = float('inf')
        best_cell = None

        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    # Heuristic: sum of remaining valid subsets in its row and column
                    options = len(row_domains[r]) + len(col_domains[c])
                    if options < min_options:
                        min_options = options
                        best_cell = (r, c)

        if not best_cell:
            return True # All cells successfully assigned

        r, c = best_cell

        # Save state before branching
        grid_copy = [row[:] for row in grid]
        row_domains_copy = [domain[:] for domain in row_domains]
        col_domains_copy = [domain[:] for domain in col_domains]

        # Branch 1: Try setting the cell to black (1)
        grid[r][c] = 1
        if backtrack(grid, row_domains, col_domains):
            return True

        # Restore state
        for i in range(R): grid[i] = grid_copy[i][:]
        for i in range(R): row_domains[i] = row_domains_copy[i][:]
        for i in range(C): col_domains[i] = col_domains_copy[i][:]

        # Branch 2: Try setting the cell to empty (0)
        grid[r][c] = 0
        if backtrack(grid, row_domains, col_domains):
            return True

        # Restore state and backtrack
        for i in range(R): grid[i] = grid_copy[i][:]
        for i in range(R): row_domains[i] = row_domains_copy[i][:]
        for i in range(C): col_domains[i] = col_domains_copy[i][:]
        return False

    if backtrack(grid, row_domains, col_domains):
        # Format the output as requested
        res = []
        for r in range(R):
            row_res = []
            for c in range(C):
                if grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            res.append(row_res)
        return res
    else:
        return "No Solution"

if __name__ == "__main__":
