class SlitherlinkSolver:
    def __init__(self, clues):
        self.R = len(clues)
        self.C = len(clues[0])
        self.clues = clues
        self.edges = {}
        self.unknown_edges = set()

        # Initialize all possible edges
        for r in range(self.R + 1):
            for c in range(self.C):
                self.unknown_edges.add(('H', r, c))
        for r in range(self.R):
            for c in range(self.C + 1):
                self.unknown_edges.add(('V', r, c))

        # Adjacency list for dots to edges
        self.adj = {}
        for r in range(self.R + 1):
            for c in range(self.C + 1):
                self.adj[(r, c)] = []
                if r > 0: self.adj[(r, c)].append(('V', r-1, c))
                if r < self.R: self.adj[(r, c)].append(('V', r, c))
                if c > 0: self.adj[(r, c)].append(('H', r, c-1))
                if c < self.C: self.adj[(r, c)].append(('H', r, c))

        # Edges for each cell
        self.cell_edges = {}
        for r in range(self.R):
            for c in range(self.C):
                self.cell_edges[(r, c)] = [
                    ('H', r, c), ('H', r+1, c),
                    ('V', r, c), ('V', r, c+1)
                ]

    def get_endpoints(self, edge):
        type, r, c = edge
        if type == 'H':
            return ((r, c), (r, c+1))
        else:
            return ((r, c), (r+1, c))

    def propagate(self):
        changed = True
        while changed:
            changed = False

            # 1. Cell clues constraints
            for r in range(self.R):
                for c in range(self.C):
                    clue = self.clues[r][c]
                    if clue is None: continue

                    edges = self.cell_edges[(r, c)]
                    ones = sum(1 for e in edges if self.edges.get(e) == 1)
                    unknowns = [e for e in edges if e in self.unknown_edges]

                    if ones > clue: return False
                    if ones + len(unknowns) < clue: return False

                    if ones == clue and unknowns:
                        for e in unknowns:
                            self.edges[e] = 0
                            self.unknown_edges.remove(e)
                            changed = True
                    elif ones + len(unknowns) == clue and unknowns:
                        for e in unknowns:
                            self.edges[e] = 1
                            self.unknown_edges.remove(e)
                            changed = True

            # 2. Dot degree constraints
            for r in range(self.R + 1):
                for c in range(self.C + 1):
                    edges = self.adj[(r, c)]
                    ones = sum(1 for e in edges if self.edges.get(e) == 1)
                    unknowns = [e for e in edges if e in self.unknown_edges]

                    if ones > 2: return False
                    if ones == 1 and len(unknowns) == 0: return False

                    if ones == 2 and unknowns:
                        for e in unknowns:
                            self.edges[e] = 0
                            self.unknown_edges.remove(e)
                            changed = True
                    elif ones == 1 and len(unknowns) == 1:
                        e = unknowns[0]
                        self.edges[e] = 1
                        self.unknown_edges.remove(e)
                        changed = True
                    elif ones == 0 and len(unknowns) == 1:
                        e = unknowns[0]
                        self.edges[e] = 0
                        self.unknown_edges.remove(e)
                        changed = True

            # 3. Loop constraints
            adj_1 = {}
            for e, val in self.edges.items():
                if val == 1:
                    u, v = self.get_endpoints(e)
                    adj_1.setdefault(u, []).append(v)
                    adj_1.setdefault(v, []).append(u)

            visited = set()
            components = []
            has_loop = False
            loop_comp = None

            for node in adj_1:
                if node not in visited:
                    comp = set()
                    q = [node]
                    visited.add(node)
                    parent = {node: None}
                    node_has_loop = False

                    while q:
                        curr = q.pop(0)
                        comp.add(curr)
                        for nxt in adj_1[curr]:
                            if nxt not in visited:
                                visited.add(nxt)
                                parent[nxt] = curr
                                q.append(nxt)
                            elif parent[curr] != nxt:
                                node_has_loop = True

                    components.append(comp)
                    if node_has_loop:
                        has_loop = True
                        loop_comp = comp

            if has_loop:
                # If a loop exists, it must contain all 1s
                if len(loop_comp) < len(adj_1):
                    return False
                # And no other edges can be 1
                if self.unknown_edges:
                    for e in list(self.unknown_edges):
                        self.edges[e] = 0
                        self.unknown_edges.remove(e)
                        changed = True
            else:
                # Prevent premature loops
                comp_of = {}
                for i, comp in enumerate(components):
                    for node in comp:
                        comp_of[node] = i

                for e in list(self.unknown_edges):
                    u, v = self.get_endpoints(e)
                    if u in comp_of and v in comp_of and comp_of[u] == comp_of[v]:
                        if len(components) > 1:
                            # Closing this would leave other 1s disconnected
                            self.edges[e] = 0
                            self.unknown_edges.remove(e)
                            changed = True
                        else:
                            # Check if closing this loop would violate any clues
                            can_close = True
                            for r in range(self.R):
                                for c in range(self.C):
                                    clue = self.clues[r][c]
                                    if clue is not None:
                                        edges = self.cell_edges[(r, c)]
                                        ones = sum(1 for ce in edges if self.edges.get(ce) == 1 or ce == e)
                                        if ones != clue:
                                            can_close = False
                                            break
                                if not can_close: break
                            if not can_close:
                                self.edges[e] = 0
                                self.unknown_edges.remove(e)
                                changed = True
        return True

    def get_best_unknown_edge(self):
        best_e = None
        min_unknowns = 10

        # Prioritize edges around constrained cells
        for r in range(self.R):
            for c in range(self.C):
                if self.clues[r][c] is not None:
                    edges = self.cell_edges[(r, c)]
                    unknowns = [e for e in edges if e in self.unknown_edges]
                    if 0 < len(unknowns) < min_unknowns:
                        min_unknowns = len(unknowns)
                        best_e = unknowns[0]

        # Prioritize edges extending existing paths
        for r in range(self.R + 1):
            for c in range(self.C + 1):
                edges = self.adj[(r, c)]
                ones = sum(1 for e in edges if self.edges.get(e) == 1)
                if ones > 0:
                    unknowns = [e for e in edges if e in self.unknown_edges]
                    if 0 < len(unknowns) < min_unknowns:
                        min_unknowns = len(unknowns)
                        best_e = unknowns[0]

        if best_e is None:
            best_e = next(iter(self.unknown_edges))

        return best_e

    def backtrack(self):
        if not self.unknown_edges:
            return self.check_solution()

        e = self.get_best_unknown_edge()

        for val in [1, 0]:
            saved_edges = self.edges.copy()
            saved_unknowns = self.unknown_edges.copy()

            self.edges[e] = val
            self.unknown_edges.remove(e)

            if self.propagate():
                res = self.backtrack()
                if res: return res

            self.edges = saved_edges
            self.unknown_edges = saved_unknowns

        return None

    def check_solution(self):
        # Verify all clues
        for r in range(self.R):
            for c in range(self.C):
                clue = self.clues[r][c]
                if clue is not None:
                    edges = self.cell_edges[(r, c)]
                    ones = sum(1 for e in edges if self.edges.get(e) == 1)
                    if ones != clue: return None

        # Verify dot degrees
        for r in range(self.R + 1):
            for c in range(self.C + 1):
                edges = self.adj[(r, c)]
                ones = sum(1 for e in edges if self.edges.get(e) == 1)
                if ones != 0 and ones != 2: return None

        # Verify single closed loop
        adj_1 = {}
        for e, val in self.edges.items():
            if val == 1:
                u, v = self.get_endpoints(e)
                adj_1.setdefault(u, []).append(v)
                adj_1.setdefault(v, []).append(u)

        if not adj_1: return None

        visited = set()
        start_node = next(iter(adj_1))
        q = [start_node]
        visited.add(start_node)

        while q:
            curr = q.pop(0)
            for nxt in adj_1[curr]:
                if nxt not in visited:
                    visited.add(nxt)
                    q.append(nxt)

        if len(visited) != len(adj_1): return None

        # Extract ordered path
        path = [start_node]
        curr = start_node
        prev = None
        while True:
            neighbors = adj_1[curr]
            nxt = neighbors[0] if neighbors[0] != prev else neighbors[1]
            path.append(nxt)
            if nxt == start_node:
                break
            prev = curr
            curr = nxt

        return path

    def solve(self):
        if not self.propagate():
            return None
        return self.backtrack()

def solve(observation):
    clues = observation['data']
    solver = SlitherlinkSolver(clues)
    path = solver.solve()
    if path:
        return path
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
