def solve(observation):
    """
    Solves the Sudoku puzzle using human-like deduction (Naked Singles, Hidden Singles)
    and efficient backtracking with the Minimum Remaining Values (MRV) heuristic.
    """
    data = observation['data']
    unit_str = observation['unit']

    # Parse grid dimensions
    if 'x' in unit_str:
        r_str, c_str = unit_str.split('x')
        R, C = int(r_str), int(c_str)
    else:
        R = C = int(unit_str)
    N = R * C

    # Initialize candidates for each cell
    candidates = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                candidates[(r, c)] = {data[r][c]}
            else:
                candidates[(r, c)] = set(range(1, N + 1))

    # Precompute peers for each cell to optimize constraint propagation
    peers_dict = {}
    for r in range(N):
        for c in range(N):
            peers = set()
            # Row and Column peers
            for i in range(N):
                if i != c: peers.add((r, i))
                if i != r: peers.add((i, c))
            # Subgrid peers
            br, bc = r // R * R, c // C * C
            for i in range(R):
                for j in range(C):
                    if (br + i, bc + j) != (r, c):
                        peers.add((br + i, bc + j))
            peers_dict[(r, c)] = peers

    # Precompute groups (rows, columns, subgrids) for Hidden Singles deduction
    groups = []
    for i in range(N):
        groups.append([(i, j) for j in range(N)]) # Rows
        groups.append([(j, i) for j in range(N)]) # Columns
    for br in range(0, N, R):
        for bc in range(0, N, C):
            groups.append([(br + i, bc + j) for i in range(R) for j in range(C)]) # Subgrids

    def propagate(current_candidates):
        """
        Applies constraint propagation to reduce the search space.
        Implements Naked Singles and Hidden Singles techniques.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles: If a cell has only one candidate, remove it from its peers
            for cell, cands in current_candidates.items():
                if len(cands) == 1:
                    val = next(iter(cands))
                    for peer in peers_dict[cell]:
                        if val in current_candidates[peer]:
                            current_candidates[peer].remove(val)
                            changed = True
                            if len(current_candidates[peer]) == 0:
                                return False # Contradiction: peer has no valid candidates

            # 2. Hidden Singles: If a value can only be placed in one cell within a group, place it
            for group in groups:
                for val in range(1, N + 1):
                    possible_cells = [cell for cell in group if val in current_candidates[cell]]
                    if len(possible_cells) == 0:
                        return False # Contradiction: value cannot be placed anywhere in the group
                    if len(possible_cells) == 1:
                        cell = possible_cells[0]
                        if len(current_candidates[cell]) > 1:
                            current_candidates[cell] = {val}
                            changed = True
        return True

    def search(current_candidates):
        """
        Recursive backtracking search with MRV heuristic.
        """
        # Propagate constraints first
        if not propagate(current_candidates):
            return False

        # Check if the puzzle is completely solved
        if all(len(cands) == 1 for cands in current_candidates.values()):
            return current_candidates

        # MRV Heuristic: Choose the empty cell with the fewest remaining candidates
        min_len = N + 1
        best_cell = None
        for cell, cands in current_candidates.items():
            if 1 < len(cands) < min_len:
                min_len = len(cands)
                best_cell = cell

        # Try all possible values for the chosen cell
        for val in current_candidates[best_cell]:
            # Create a deep copy of candidates for the new branch
            new_candidates = {k: v.copy() for k, v in current_candidates.items()}
            new_candidates[best_cell] = {val}

            result = search(new_candidates)
            if result:
                return result

        return False

    # Start the solving process
    solution = search(candidates)

    # Format the output
    if solution:
        res = [[0] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                res[r][c] = next(iter(solution[(r, c)]))
        return res
    else:
        return "No Solution"

