# The puzzle requires us to fill a grid with Black ('B') and White (None) cells.
# Each row has a target sum, which is the sum of the column-weights of its Black cells.
# Each column has a target sum, which is the sum of the row-weights of its Black cells.
# Row weights are 1 to R (top to bottom). Column weights are 1 to C (left to right).
# We solve this using Constraint Satisfaction (CSP) techniques:
# 1. Precompute all valid combinations of Black/White cells for each row and column that satisfy their respective target sums.
# 2. Use constraint propagation to iteratively reduce the domains of valid combinations. If all valid combinations for a row/col agree on a cell's state, we fix that cell and filter the combinations of the intersecting col/row.
# 3. If propagation doesn't fully solve the grid, use backtracking search with the reduced domains.

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    R = len(row_targets)
    C = len(col_targets)

    # Weights are implicitly 1 to N based on position
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Precompute valid combinations for each row
    row_combos = []
    for i in range(R):
        target = row_targets[i]
        combos = []
        for mask in range(1 << C):
            s = sum(col_weights[j] for j in range(C) if (mask & (1 << j)))
            if s == target:
                combos.append(tuple(1 if (mask & (1 << j)) else 0 for j in range(C)))
        row_combos.append(combos)

    # Precompute valid combinations for each column
    col_combos = []
    for j in range(C):
        target = col_targets[j]
        combos = []
        for mask in range(1 << R):
            s = sum(row_weights[i] for i in range(R) if (mask & (1 << i)))
            if s == target:
                combos.append(tuple(1 if (mask & (1 << i)) else 0 for i in range(R)))
        col_combos.append(combos)

    # Grid to store the current state: -1 for unassigned, 0 for White, 1 for Black
    grid = [[-1] * C for _ in range(R)]

    def propagate():
        """
        Iteratively enforces consistency between row and column combinations.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # Check rows and update grid/cols
            for i in range(R):
                if not row_combos[i]: 
                    return False
                for j in range(C):
                    if grid[i][j] == -1:
                        first_val = row_combos[i][0][j]
                        # If all valid combos for this row have the same value at column j
                        if all(combo[j] == first_val for combo in row_combos[i]):
                            grid[i][j] = first_val
                            changed = True
                            # Filter the column combinations to match this new assignment
                            col_combos[j] = [c for c in col_combos[j] if c[i] == first_val]
                            if not col_combos[j]: 
                                return False

            # Check cols and update grid/rows
            for j in range(C):
                if not col_combos[j]: 
                    return False
                for i in range(R):
                    if grid[i][j] == -1:
                        first_val = col_combos[j][0][i]
                        # If all valid combos for this column have the same value at row i
                        if all(combo[i] == first_val for combo in col_combos[j]):
                            grid[i][j] = first_val
                            changed = True
                            # Filter the row combinations to match this new assignment
                            row_combos[i] = [c for c in row_combos[i] if c[j] == first_val]
                            if not row_combos[i]: 
                                return False
        return True

    # Initial propagation to reduce search space
    if not propagate():
        return "No Solution"

    def solve_bt():
        """
        Backtracking search to find a valid assignment if propagation is not enough.
        """
        # Find the row with the fewest remaining combinations (> 1) to branch on
        min_combos = float('inf')
        best_row = -1
        for i in range(R):
            if len(row_combos[i]) > 1:
                if len(row_combos[i]) < min_combos:
                    min_combos = len(row_combos[i])
                    best_row = i

        if best_row == -1:
            # All rows have exactly 1 combination left. Verify and construct final grid.
            for i in range(R):
                if len(row_combos[i]) != 1: 
                    return False
                for j in range(C):
                    grid[i][j] = row_combos[i][0][j]
            return True

        # Save state before branching
        original_row_combos = [list(c) for c in row_combos]
        original_col_combos = [list(c) for c in col_combos]
        original_grid = [list(row) for row in grid]

        # Try each valid combination for the chosen row
        for combo in original_row_combos[best_row]:
            row_combos[best_row] = [combo]
            valid = True

            # Apply the combination to the grid and filter column domains
            for j in range(C):
                if grid[best_row][j] == -1:
                    grid[best_row][j] = combo[j]
                    col_combos[j] = [c for c in col_combos[j] if c[best_row] == combo[j]]
                    if not col_combos[j]:
                        valid = False
                        break
                elif grid[best_row][j] != combo[j]:
                    valid = False
                    break

            # If valid so far, propagate and recurse
            if valid and propagate():
                if solve_bt():
                    return True

            # Backtrack: restore state
            for i in range(R): row_combos[i] = list(original_row_combos[i])
            for j in range(C): col_combos[j] = list(original_col_combos[j])
            for i in range(R):
                for j in range(C):
                    grid[i][j] = original_grid[i][j]

        return False

    if solve_bt():
        # Format the output as requested: 'B' for black, None for non-black
        res = []
        for r in range(R):
            row_res = []
            for c in range(C):
                row_res.append('B' if grid[r][c] == 1 else None)
            res.append(row_res)
        return res

    return "No Solution"

