    valid_row_configs = []
    for r in range(R):
        configs = []
        # Iterate through all possible 2^C combinations for a row
        for i in range(1 << C):
            config = [(i >> c) & 1 for c in range(C)]
            # Check if the combination satisfies the row target sum
            if sum(config[c] * col_weights[c] for c in range(C)) == row_targets[r]:
                configs.append(config)
        valid_row_configs.append(configs)

    grid = []

    def backtrack(r):
        # If all rows are filled, verify column constraints exactly
        if r == R:
            for c in range(C):
                if sum(grid[i][c] * row_weights[i] for i in range(R)) != col_targets[c]:
                    return False
            return True

        # Try each valid configuration for the current row
        for config in valid_row_configs[r]:
            grid.append(config)

            # Aggressive constraint propagation (pruning)
            possible = True
            for c in range(C):
                current_sum = sum(grid[i][c] * row_weights[i] for i in range(r + 1))

                # Prune if current column sum exceeds target
                if current_sum > col_targets[c]:
                    possible = False
                    break

                # Prune if it's impossible to reach the target even if all remaining cells are black
                max_rem = sum(row_weights[i] for i in range(r + 1, R))
                if current_sum + max_rem < col_targets[c]:
                    possible = False
                    break

            # If still possible, proceed to the next row
            if possible:
                if backtrack(r + 1):
                    return True

            # Backtrack
            grid.pop()

        return False

    if backtrack(0):
        # Format the output grid as requested
        res = []
        for r in range(R):
            row_res = []
            for c in range(C):
                if grid[r][c] == 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            res.append(row_res)
        return res
    else:
        return "No Solution"

