        if r < N-1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < N-1: res.append((r, c+1))
        return res

    def propagate(current_state):
        """
        Applies deductive rules to aggressively prune the search space.
        Returns False if a contradiction is found, True otherwise.
        """
