            for reg_id, cells in regions.items():
                ones = [cell for cell in cells if current_state[cell[0]][cell[1]] == 1]
                nones = [cell for cell in cells if current_state[cell[0]][cell[1]] == -1]

                if len(ones) > 2:
                    return False # Contradiction: too many shaded cells
                if len(ones) + len(nones) < 2:
