                        neighbors = get_neighbors(r, c)
                        ones = [(nr, nc) for nr, nc in neighbors if current_state[nr][nc] == 1]
                        nones = [(nr, nc) for nr, nc in neighbors if current_state[nr][nc] == -1]

                        if len(ones) > 1:
                            return False # Contradiction: dominoes touching orthogonally
                        if len(ones) == 0 and len(nones) == 0:
                            return False # Contradiction: isolated shaded cell

                        if len(ones) == 1 and len(nones) > 0:
                            # Domino is complete, block all other neighbors
                            for nr, nc in nones:
                                current_state[nr][nc] = 0
                                changed = True
                        elif len(ones) == 0 and len(nones) == 1:
                            # Forced to form a domino with the only available neighbor
                            nr, nc = nones[0]
                            current_state[nr][nc] = 1
                            changed = True

                    elif current_state[r][c] == -1:
                        neighbors = get_neighbors(r, c)
                        ones = [(nr, nc) for nr, nc in neighbors if current_state[nr][nc] == 1]
                        nones = [(nr, nc) for nr, nc in neighbors if current_state[nr][nc] == -1]

                        # If shading this cell would touch two existing shaded cells, it's invalid
                        if len(ones) > 1:
                            current_state[r][c] = 0
                            changed = True
                        # If this cell cannot possibly form a domino, it must be unshaded
                        elif len(ones) == 0 and len(nones) == 0:
                            current_state[r][c] = 0
                            changed = True

        return True

    def is_solved(current_state):
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == -1:
                    return False
        for reg_id, cells in regions.items():
            if sum(current_state[r][c] for r, c in cells) != 2:
                return False
        for r in range(N):
            for c in range(N):
                if current_state[r][c] == 1:
                    ones = sum(1 for nr, nc in get_neighbors(r, c) if current_state[nr][nc] == 1)
                    if ones != 1:
                        return False
        return True

    def backtrack(current_state):
        if not propagate(current_state):
            return None

        if is_solved(current_state):
            return current_state

        # Heuristic: Pick an unassigned cell in the region closest to being resolved
        best_cell = None
        min_nones = float('inf')
        best_reg = None

        for reg_id, cells in regions.items():
            nones = sum(1 for r, c in cells if current_state[r][c] == -1)
            if 0 < nones < min_nones:
                min_nones = nones
                best_reg = reg_id

        if best_reg is not None:
            for r, c in regions[best_reg]:
                if current_state[r][c] == -1:
                    best_cell = (r, c)
                    break
        else:
            # Fallback
            for r in range(N):
                for c in range(N):
                    if current_state[r][c] == -1:
                        best_cell = (r, c)
                        break

        if not best_cell:
            return None

        r, c = best_cell

        # Try shading the cell
        state_copy = [row[:] for row in current_state]
        state_copy[r][c] = 1
        res = backtrack(state_copy)
        if res: return res

        # Try leaving the cell unshaded
        state_copy = [row[:] for row in current_state]
        state_copy[r][c] = 0
        res = backtrack(state_copy)
        if res: return res

        return None

    solution = backtrack(state)

    if solution:
        ans = []
        for r in range(N):
            row_ans = []
            for c in range(N):
                if solution[r][c] == 1:
                    row_ans.append('S')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
