                on = 0
                off = 0
                unk = []
                for e in edges:
                    if state[e] == 1: on += 1
                    elif state[e] == 0: off += 1
                    else: unk.append(e)

                if on > clue or off > 4 - clue:
                    return False

                if on == clue and unk:
                    for e in unk: state[e] = 0
                    changed = True
                elif off == 4 - clue and unk:
                    for e in unk: state[e] = 1
                    changed = True

            # 2. Vertex degree constraints
            for v in range(len(adj)):
                edges = adj[v]
                on = 0
                off = 0
                unk = []
                for e in edges:
                    if state[e] == 1: on += 1
                    elif state[e] == 0: off += 1
                    else: unk.append(e)

                if on > 2: return False
                if on == 1 and len(edges) - off == 1: return False

                if on == 2 and unk:
                    for e in unk: state[e] = 0
                    changed = True
                elif on == 1 and len(edges) - off == 2 and unk:
                    for e in unk: state[e] = 1
                    changed = True
                elif on == 0 and len(edges) - off == 1 and unk:
                    for e in unk: state[e] = 0
                    changed = True

            # 3. Loop and cycle constraints
            parent = {}
            def find(i):
                if parent.setdefault(i, i) == i: return i
                parent[i] = find(parent[i])
                return parent[i]
            def union(i, j):
                root_i = find(i)
                root_j = find(j)
                if root_i != root_j:
                    parent[root_i] = root_j
                    return True
                return False

