                # If a cycle is formed, no other 1s can exist outside it
                for e in range(num_edges):
                    if state[e] == 1:
                        u, v = edge_endpoints[e]
                        if find(u) != cycle_root:
                            return False

                # Force all remaining unknowns to 0
                unk = [e for e in range(num_edges) if state[e] == -1]
                if unk:
                    for e in unk: state[e] = 0
                    changed = True

            # 4. Premature cycle prevention
            for e in range(num_edges):
