                    if find(u) == find(v):
                        has_outside_1s = False
                        for other_e in range(num_edges):
                            if state[other_e] == 1:
                                ou, ov = edge_endpoints[other_e]
                                if find(ou) != find(u):
                                    has_outside_1s = True
