                                changed = True
        return True

    def full_propagate(state):
        # Combines basic propagation with 1-step lookahead for powerful deduction
        while True:
            if not propagate(state):
                return False

            changed = False
            unk = [e for e in range(num_edges) if state[e] == -1]
            for e in unk:
                state_0 = list(state)
                state_0[e] = 0
                res_0 = propagate(state_0)

                state_1 = list(state)
                state_1[e] = 1
                res_1 = propagate(state_1)

                if not res_0 and not res_1:
                    return False
                elif not res_0:
                    state[e] = 1
                    changed = True
                    break
                elif not res_1:
                    state[e] = 0
                    changed = True
                    break

            if not changed:
