        for r, c, clue in clue_cells:
            if sum(1 for e in cell_edges[r][c] if state[e] == 1) != clue:
                return False
        for v in range(len(adj)):
            on = sum(1 for e in adj[v] if state[e] == 1)
            if on != 0 and on != 2:
                return False

        parent = {}
        def find(i):
            if parent.setdefault(i, i) == i: return i
            parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
