                roots.add(find(u))
        if len(roots) != 1: return False

        return True

    def solve_recursive(state):
        if not full_propagate(state):
            return None
        if is_solved(state):
            return state

        # Heuristic branching: prefer extending an existing path
        best_e = -1
        for v in range(len(adj)):
            on = sum(1 for e in adj[v] if state[e] == 1)
            if on == 1:
                for e in adj[v]:
                    if state[e] == -1:
                        best_e = e
                        break
            if best_e != -1: break

        # Fallback: most constrained cell
        if best_e == -1:
            best_score = -1
            for r, c, clue in clue_cells:
                unk = [e for e in cell_edges[r][c] if state[e] == -1]
