            for e in range(num_edges):
                if state[e] == -1:
                    best_e = e
                    break

        if best_e == -1:
            return None

        for val in (1, 0):
            new_state = list(state)
            new_state[best_e] = val
            res = solve_recursive(new_state)
            if res: return res

        return None

    initial_state = [-1] * num_edges
    for r, c, clue in clue_cells:
        if clue == 0:
            for e in cell_edges[r][c]:
                initial_state[e] = 0

    final_state = solve_recursive(initial_state)

    if not final_state:
        return "No Solution"

    # Extract the loop coordinates
    start_v = -1
    for v in range(len(adj)):
        if sum(1 for e in adj[v] if final_state[e] == 1) > 0:
            start_v = v
            break

    if start_v == -1: return "No Solution"

    loop = []
    curr_v = start_v
    prev_e = -1

    while True:
        loop.append((curr_v // (N + 1), curr_v % (N + 1)))
        next_v = -1
        for e in adj[curr_v]:
            if final_state[e] == 1 and e != prev_e:
                u, v = edge_endpoints[e]
                next_v = v if u == curr_v else u
                prev_e = e
                break
        if next_v == start_v:
            loop.append((next_v // (N + 1), next_v % (N + 1)))
            break
        if next_v == -1:
            break
        curr_v = next_v

    return loop

