def get_symmetries(shape):
    symmetries = []
    for flip in [False, True]:
        for rot in range(4):
            curr = shape
            if flip:
                curr = [(r, -c) for r, c in curr]
            for _ in range(rot):
                curr = [(c, -r) for r, c in curr]
            min_r = min(r for r, c in curr)
            min_c = min(c for r, c in curr)
            norm = tuple(sorted((r - min_r, c - min_c) for r, c in curr))
            symmetries.append(norm)
    return list(set(symmetries))

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])

    # 1. Parse regions
    region_cells = {}
    for r in range(R):
        for c in range(C):
            r_id = grid_data[r][c]
            if r_id not in region_cells:
                region_cells[r_id] = set()
            region_cells[r_id].add((r, c))

    regions = list(region_cells.keys())

    # 2. Build adjacency graph
    adj_graph = {r_id: set() for r_id in regions}
    for r in range(R):
        for c in range(C):
            r_id = grid_data[r][c]
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    n_id = grid_data[nr][nc]
                    if r_id != n_id:
                        adj_graph[r_id].add(n_id)

    # 3. Generate shape map
    base_shapes = {
        'I': [(0,0), (0,1), (0,2), (0,3)],
        'L': [(0,0), (0,1), (0,2), (1,0)],
        'T': [(0,0), (0,1), (0,2), (1,1)],
        'S': [(0,1), (0,2), (1,0), (1,1)],
        'O': [(0,0), (0,1), (1,0), (1,1)]
    }
    shape_map = {}
    for name, shape in base_shapes.items():
        for sym in get_symmetries(shape):
            shape_map[sym] = name

    # 4. Precalculate valid placements for each region
    valid_placements = {r_id: [] for r_id in regions}
    import itertools
    for r_id, cells in region_cells.items():
        for subset in itertools.combinations(cells, 4):
            # Check if the 4 cells are connected
            start = subset[0]
            q = [start]
            visited = {start}
            while q:
                curr = q.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nxt = (curr[0]+dr, curr[1]+dc)
                    if nxt in subset and nxt not in visited:
                        visited.add(nxt)
                        q.append(nxt)

            if len(visited) == 4:
                # Normalize and identify shape
                min_r = min(r for r, c in subset)
                min_c = min(c for r, c in subset)
                norm = tuple(sorted((r - min_r, c - min_c) for r, c in subset))
                shape_type = shape_map.get(norm)
                # O shape is forbidden
                if shape_type and shape_type != 'O':
                    valid_placements[r_id].append((shape_type, set(subset)))

    # Order regions by Minimum Remaining Values (MRV) heuristic
    region_order = sorted(regions, key=lambda r: len(valid_placements[r]))

    def creates_2x2(new_cells, existing_cells):
        combined = existing_cells | new_cells
        for r, c in new_cells:
            for dr, dc in [(0,0), (-1,0), (0,-1), (-1,-1)]:
                tr, tc = r + dr, c + dc
                if {(tr, tc), (tr+1, tc), (tr, tc+1), (tr+1, tc+1)}.issubset(combined):
                    return True
        return False

    def connectivity_possible(shaded_cells, unassigned_regions):
        if not shaded_cells: return True
        usable = set(shaded_cells)
        for r_id in unassigned_regions:
            usable.update(region_cells[r_id])

        start = next(iter(shaded_cells))
        q = [start]
        visited = {start}

        while q:
            r, c = q.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in usable and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        # All currently shaded cells must be in the same component
        if not shaded_cells.issubset(visited): 
            return False

        # Every unassigned region must be able to connect to the main component
        for r_id in unassigned_regions:
            if not any(cell in visited for cell in region_cells[r_id]):
                return False
        return True

    def is_fully_connected(shaded_cells):
        if not shaded_cells: return True
        start = next(iter(shaded_cells))
        q = [start]
        visited = {start}
        while q:
            r, c = q.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in shaded_cells and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(shaded_cells)

    # 5. Backtracking search
    def backtrack(idx, current_shaded, assigned_shapes):
        if idx == len(region_order):
            if is_fully_connected(current_shaded):
                return current_shaded, assigned_shapes
            return None

        r_id = region_order[idx]
        unassigned = region_order[idx+1:]

        for shape_type, cells in valid_placements[r_id]:
            # Constraint: Adjacent regions cannot have the same shape
            conflict = False
            for adj in adj_graph[r_id]:
                if adj in assigned_shapes and assigned_shapes[adj] == shape_type:
                    conflict = True
                    break
            if conflict: continue

            # Constraint: No 2x2 block can be fully shaded
            if creates_2x2(cells, current_shaded):
                continue

            new_shaded = current_shaded | cells

            # Pruning: Check if global connectivity is still possible
            if not connectivity_possible(new_shaded, unassigned):
                continue

            assigned_shapes[r_id] = shape_type
            res = backtrack(idx + 1, new_shaded, assigned_shapes)
            if res: return res
            del assigned_shapes[r_id]

        return None

    result = backtrack(0, set(), {})

    if result:
        shaded_cells, assigned_shapes = result
        ans_grid = [[None for _ in range(C)] for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if (r, c) in shaded_cells:
                    r_id = grid_data[r][c]
                    ans_grid[r][c] = assigned_shapes[r_id]
        return ans_grid

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
