                    q.append((nr, nc))
                    if val == color:
                        visited_target_count += 1

        # If we couldn't reach all target cells, the current state is invalid
        if visited_target_count < target_count:
            return False

    return True

def deduce(grid):
    R = len(grid)
    C = len(grid[0])
    changed = True
    # Aggressively propagate constraints by tentatively placing colors
    while changed:
        changed = False
        for r in range(R):
            for c in range(C):
                if grid[r][c] is None:
                    # Try placing 'B'
                    grid[r][c] = 'B'
                    valid_B = is_valid(grid)

                    # Try placing 'W'
                    grid[r][c] = 'W'
                    valid_W = is_valid(grid)

                    # Reset
                    grid[r][c] = None

                    # Deduce based on validity
                    if valid_B and not valid_W:
                        grid[r][c] = 'B'
                        changed = True
                    elif valid_W and not valid_B:
                        grid[r][c] = 'W'
                        changed = True
                    elif not valid_B and not valid_W:
                        return False # Contradiction found, branch is dead
    return True

def solve_recursive(grid):
    # Work on a copy to allow backtracking
    grid_copy = [row[:] for row in grid]

    # Apply human-like logical deductions
    if not deduce(grid_copy):
        return None

    # Find the best empty cell to branch on (Most Constrained Variable heuristic)
    best_cell = None
    max_filled = -1
    for r in range(len(grid_copy)):
        for c in range(len(grid_copy[0])):
            if grid_copy[r][c] is None:
                filled = 0
                # Count filled neighbors (including diagonals) to find tight spots
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < len(grid_copy) and 0 <= nc < len(grid_copy[0]) and grid_copy[nr][nc] is not None:
                            filled += 1
                if filled > max_filled:
                    max_filled = filled
                    best_cell = (r, c)

    # If no empty cells are left, the puzzle is solved
    if best_cell is None:
        return grid_copy

    r, c = best_cell

    # Branch: Try 'B'
    grid_copy[r][c] = 'B'
    res = solve_recursive(grid_copy)
    if res: return res

    # Branch: Try 'W'
    grid_copy[r][c] = 'W'
    res = solve_recursive(grid_copy)
    if res: return res

    return None

def solve(observation):
    grid = observation['data']
    result = solve_recursive(grid)
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
