                ((r, c), (r, c+1)),
                ((r+1, c), (r+1, c+1)),
                ((r, c), (r+1, c)),
                ((r, c+1), (r+1, c+1))
            ]

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # 1. Cell clues constraints
            for r in range(R):
                for c in range(C):
                    clue = clues[r][c]
                    if clue is None: continue

                    cell_e = cell_edges[(r, c)]
                    in_c = sum(1 for e in cell_e if state[e] == 1)
                    unk_c = sum(1 for e in cell_e if state[e] == -1)

                    if in_c > clue: return False
                    if in_c + unk_c < clue: return False

                    if in_c == clue and unk_c > 0:
                        for e in cell_e:
                            if state[e] == -1:
                                state[e] = 0
                                changed = True
                    elif in_c + unk_c == clue and unk_c > 0:
                        for e in cell_e:
                            if state[e] == -1:
                                state[e] = 1
                                changed = True

            # 2. Dot degree constraints
            for dot, incident in adj.items():
                in_c = sum(1 for e in incident if state[e] == 1)
                unk_c = sum(1 for e in incident if state[e] == -1)

                if in_c > 2: return False
                if in_c == 1 and unk_c == 0: return False

                if in_c == 2 and unk_c > 0:
                    for e in incident:
                        if state[e] == -1:
                            state[e] = 0
                            changed = True
                elif in_c == 1 and unk_c == 1:
                    for e in incident:
                        if state[e] == -1:
                            state[e] = 1
                            changed = True
                elif in_c == 0 and unk_c == 1:
                    for e in incident:
                        if state[e] == -1:
                            state[e] = 0
                            changed = True

            # 3. Loop constraints (prevent premature loops)
            in_adj = {}
            for e, s in state.items():
                if s == 1:
                    u, v = e
                    if u not in in_adj: in_adj[u] = []
                    if v not in in_adj: in_adj[v] = []
                    in_adj[u].append(v)
                    in_adj[v].append(u)

            visited = set()
            components = []
            loops = []
            for node in in_adj:
                if node not in visited:
                    comp = set()
                    q = [node]
                    visited.add(node)
                    while q:
                        curr = q.pop(0)
                        comp.add(curr)
                        for neighbor in in_adj[curr]:
                            if neighbor not in visited:
                                visited.add(neighbor)
                                q.append(neighbor)

                    if all(len(in_adj[n]) == 2 for n in comp):
                        loops.append(comp)
                    components.append(comp)

            if len(loops) > 1: return False
            if len(loops) == 1:
                loop_comp = loops[0]
                for e, s in state.items():
                    if s == 1:
                        u, v = e
                        if u not in loop_comp or v not in loop_comp:
                            return False
                for e, s in state.items():
