                        if u in in_adj and v in in_adj:
                            u_comp = None
                            for comp in components:
                                if u in comp:
                                    u_comp = comp
                                    break
                            if u_comp and v in u_comp:
                                if len(u_comp) < len(in_adj):
                                    state[e] = 0
                                    changed = True

        return True

    def solve_recursive(state):
        if not propagate(state):
            return None

        unknowns = [e for e, s in state.items() if s == -1]
        if not unknowns:
            in_edges = [e for e, s in state.items() if s == 1]
            if not in_edges: return None

            in_adj = {}
            for u, v in in_edges:
                if u not in in_adj: in_adj[u] = []
                if v not in in_adj: in_adj[v] = []
                in_adj[u].append(v)
                in_adj[v].append(u)

            if any(len(neighbors) != 2 for neighbors in in_adj.values()):
                return None

            start_node = next(iter(in_adj))
            visited = set()
            q = [start_node]
            visited.add(start_node)
            while q:
                curr = q.pop(0)
                for neighbor in in_adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        q.append(neighbor)

            if len(visited) != len(in_adj):
                return None

            return state

        branch_edge = None
        # Heuristic 1: Extend an existing path
        for dot, incident in adj.items():
            in_c = sum(1 for e in incident if state[e] == 1)
            if in_c == 1:
                for e in incident:
                    if state[e] == -1:
                        branch_edge = e
                        break
            if branch_edge: break

        # Heuristic 2: Pick an edge in a cell with the most known edges
        if not branch_edge:
            best_score = -1
            for r in range(R):
                for c in range(C):
                    clue = clues[r][c]
                    if clue is not None:
                        cell_e = cell_edges[(r, c)]
                        unk_e = [e for e in cell_e if state[e] == -1]
                        if unk_e:
                            score = 4 - len(unk_e)
                            if score > best_score:
                                best_score = score
                                branch_edge = unk_e[0]

        # Fallback
        if not branch_edge:
            branch_edge = unknowns[0]

        state_copy = state.copy()
        state_copy[branch_edge] = 1
        res = solve_recursive(state_copy)
        if res: return res

        state_copy = state.copy()
        state_copy[branch_edge] = 0
        return solve_recursive(state_copy)

    res_state = solve_recursive(edges)
    if not res_state:
        return "No Solution"

    in_edges = [e for e, s in res_state.items() if s == 1]
    loop_adj = {}
    for u, v in in_edges:
        if u not in loop_adj: loop_adj[u] = []
        if v not in loop_adj: loop_adj[v] = []
        loop_adj[u].append(v)
        loop_adj[v].append(u)

    start_node = in_edges[0][0]
    loop = [start_node]
    curr = start_node
    prev = None

    while True:
        neighbors = loop_adj[curr]
        next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
        loop.append(next_node)
        if next_node == start_node:
            break
        prev = curr
        curr = next_node

    return loop

