import itertools

def generate_tetrominoes():
    shapes = {
        'I': [[(0,0), (0,1), (0,2), (0,3)]],
        'O': [[(0,0), (0,1), (1,0), (1,1)]],
        'T': [[(0,0), (0,1), (0,2), (1,1)]],
        'S': [[(0,1), (0,2), (1,0), (1,1)]],
        'L': [[(0,0), (1,0), (2,0), (2,1)]]
    }

    all_shapes = {}
    for name, base_shapes in shapes.items():
        all_shapes[name] = set()
        for shape in base_shapes:
            for flip in [False, True]:
                for rot in range(4):
                    current = shape
                    if flip:
                        current = [(r, -c) for r, c in current]
                    for _ in range(rot):
                        current = [(c, -r) for r, c in current]

                    min_r = min(r for r, c in current)
                    min_c = min(c for r, c in current)
                    norm = tuple(sorted((r - min_r, c - min_c) for r, c in current))
                    all_shapes[name].add(norm)
    return all_shapes

TETROMINOES = generate_tetrominoes()

def get_tetromino_type(cells):
    if len(cells) != 4: return None
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    norm = tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    for name, shapes in TETROMINOES.items():
        if norm in shapes:
            return name
    return None

def is_connected(cells):
    if not cells: return True
    start = cells[0]
    visited = {start}
    q = [start]
    while q:
        r, c = q.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if (nr, nc) in cells and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append((nr, nc))
    return len(visited) == len(cells)

def get_placements(region_cells):
    placements = []
    cells = list(region_cells)
    for combo in itertools.combinations(cells, 4):
        if is_connected(combo):
            t_type = get_tetromino_type(combo)
            if t_type and t_type != 'O':
                placements.append((combo, t_type))
    return placements

def get_adjacencies(grid):
    R = len(grid)
    C = len(grid[0])
    adj = {}
    for r in range(R):
        for c in range(C):
            reg = grid[r][c]
            if reg not in adj:
                adj[reg] = set()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < R and 0 <= nc < C:
                    nreg = grid[nr][nc]
                    if reg != nreg:
                        adj[reg].add(nreg)
    return adj

def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    regions = {}
    for r in range(R):
        for c in range(C):
            reg = grid[r][c]
            if reg not in regions:
                regions[reg] = []
            regions[reg].append((r, c))

    adjacencies = get_adjacencies(grid)

    region_placements = {}
    for reg, cells in regions.items():
        region_placements[reg] = get_placements(cells)
        if not region_placements[reg]:
            return "No Solution"

    ordered_regions = sorted(regions.keys(), key=lambda r: len(region_placements[r]))

    def can_connect(shaded, unassigned_regs):
        if not shaded: return True
        potential = set(shaded)
        for reg in unassigned_regs:
            potential.update(regions[reg])

        shaded_list = list(shaded)
        visited_shaded = set()
        components = []
        for cell in shaded_list:
            if cell not in visited_shaded:
                comp = set()
                q = [cell]
                visited_shaded.add(cell)
                while q:
                    curr = q.pop(0)
                    comp.add(curr)
                    r, c = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if (nr, nc) in shaded and (nr, nc) not in visited_shaded:
                            visited_shaded.add((nr, nc))
                            q.append((nr, nc))
                components.append(comp)

        if len(components) <= 1:
            return True

        start_comp = components[0]
        visited = set(start_comp)
        q = list(start_comp)

        while q:
            r, c = q.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in potential and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        return all(cell in visited for cell in shaded)

    def is_fully_connected(shaded):
        if not shaded: return True
        start = next(iter(shaded))
        visited = {start}
        q = [start]
        while q:
            r, c = q.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) in shaded and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(shaded)

    assigned_types = {}

    def backtrack(idx, current_shaded):
        if idx == len(ordered_regions):
            if is_fully_connected(current_shaded):
                return current_shaded
            return None

        reg = ordered_regions[idx]
        unassigned = ordered_regions[idx+1:]

        for combo, t_type in region_placements[reg]:
            valid_adj = True
            for nreg in adjacencies[reg]:
                if nreg in assigned_types and assigned_types[nreg] == t_type:
                    valid_adj = False
                    break
            if not valid_adj: continue

            new_shaded = current_shaded | set(combo)

            valid_2x2 = True
            for r, c in combo:
                for dr, dc in [(0,0), (-1,0), (0,-1), (-1,-1)]:
                    r0, c0 = r+dr, c+dc
                    if (r0, c0) in new_shaded and \
                       (r0+1, c0) in new_shaded and \
                       (r0, c0+1) in new_shaded and \
                       (r0+1, c0+1) in new_shaded:
                        valid_2x2 = False
                        break
                if not valid_2x2: break
            if not valid_2x2: continue

            if not can_connect(new_shaded, unassigned): continue

            assigned_types[reg] = t_type
            res = backtrack(idx + 1, new_shaded)
            if res: return res
            del assigned_types[reg]

        return None

    solution_shaded = backtrack(0, set())

    if solution_shaded:
        ans = []
        for r in range(R):
            row_ans = []
            for c in range(C):
                if (r, c) in solution_shaded:
                    reg = grid[r][c]
                    reg_cells = [cell for cell in solution_shaded if grid[cell[0]][cell[1]] == reg]
                    t_type = get_tetromino_type(reg_cells)
                    row_ans.append(t_type)
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
