def get_incident_edges(r, c, N):
    """Returns all valid grid edges incident to dot (r, c)."""
    edges = []
    if r > 0: edges.append(tuple(sorted(((r-1, c), (r, c)))))
    if r < N: edges.append(tuple(sorted(((r, c), (r+1, c)))))
    if c > 0: edges.append(tuple(sorted(((r, c-1), (r, c)))))
    if c < N: edges.append(tuple(sorted(((r, c), (r, c+1)))))
    return edges

def get_components(edges):
    """Finds connected components of True edges."""
    true_edges = [e for e, v in edges.items() if v == True]
    adj = {}
    for u, v in true_edges:
        adj.setdefault(u, []).append(v)
        adj.setdefault(v, []).append(u)

    visited_edges = set()
    components = []
    for e in true_edges:
        if e not in visited_edges:
            comp = set()
            q = [e]
            while q:
                curr_e = q.pop(0)
                if curr_e in comp: continue
                comp.add(curr_e)
                visited_edges.add(curr_e)
                u, v = curr_e
                for nxt_v in adj.get(u, []):
                    nxt_e = tuple(sorted((u, nxt_v)))
                    if nxt_e not in comp: q.append(nxt_e)
                for nxt_v in adj.get(v, []):
                    nxt_e = tuple(sorted((v, nxt_v)))
                    if nxt_e not in comp: q.append(nxt_e)
            components.append(comp)
    return components

def is_closed_loop(comp):
    """Checks if a component forms a closed loop (all nodes degree 2)."""
    adj = {}
    for u, v in comp:
        adj[u] = adj.get(u, 0) + 1
        adj[v] = adj.get(v, 0) + 1
    return all(deg == 2 for deg in adj.values())

def is_valid_solution(edges, clues, N):
    """Validates if the current edge assignment is a complete valid solution."""
    comps = get_components(edges)
    if len(comps) != 1: return False
    comp = comps[0]
    if not is_closed_loop(comp): return False

    visited_dots = set()
    for u, v in comp:
        visited_dots.add(u)
        visited_dots.add(v)

    for clue_pos in clues:
        if clue_pos not in visited_dots:
            return False

    return True

def get_configs(r, c, clue_type, k, N):
    """Generates all valid local edge configurations for a given clue."""
    configs = []
    if clue_type == 'W':
        # Horizontal segment passing through (r, c)
        for L1 in range(1, k):
            L2 = k - L1
            if c - L1 >= 0 and c + L2 <= N:
                config = {}
                for i in range(1, L1 + 1):
                    config[tuple(sorted(((r, c-i), (r, c-i+1))))] = True
                for j in range(1, L2 + 1):
                    config[tuple(sorted(((r, c+j-1), (r, c+j))))] = True
                # Must turn at ends
                if c - L1 - 1 >= 0:
                    config[tuple(sorted(((r, c-L1-1), (r, c-L1))))] = False
                if c + L2 + 1 <= N:
                    config[tuple(sorted(((r, c+L2), (r, c+L2+1))))] = False
                # Must go straight through the circle
                if r - 1 >= 0: config[tuple(sorted(((r-1, c), (r, c))))] = False
                if r + 1 <= N: config[tuple(sorted(((r, c), (r+1, c))))] = False
                configs.append(config)
        # Vertical segment passing through (r, c)
        for L1 in range(1, k):
            L2 = k - L1
            if r - L1 >= 0 and r + L2 <= N:
                config = {}
                for i in range(1, L1 + 1):
                    config[tuple(sorted(((r-i, c), (r-i+1, c))))] = True
                for j in range(1, L2 + 1):
                    config[tuple(sorted(((r+j-1, c), (r+j, c))))] = True
                # Must turn at ends
                if r - L1 - 1 >= 0:
                    config[tuple(sorted(((r-L1-1, c), (r-L1, c))))] = False
                if r + L2 + 1 <= N:
                    config[tuple(sorted(((r+L2, c), (r+L2+1, c))))] = False
                # Must go straight through the circle
                if c - 1 >= 0: config[tuple(sorted(((r, c-1), (r, c))))] = False
                if c + 1 <= N: config[tuple(sorted(((r, c), (r, c+1))))] = False
                configs.append(config)

    elif clue_type == 'B':
        orientations = [
            ((-1, 0), (0, 1)),  # North, East
            ((-1, 0), (0, -1)), # North, West
            ((1, 0), (0, 1)),   # South, East
            ((1, 0), (0, -1))   # South, West
        ]
        for dir1, dir2 in orientations:
            for L1 in range(1, k):
                L2 = k - L1
                end1_r, end1_c = r + dir1[0]*L1, c + dir1[1]*L1
                end2_r, end2_c = r + dir2[0]*L2, c + dir2[1]*L2
                if 0 <= end1_r <= N and 0 <= end1_c <= N and 0 <= end2_r <= N and 0 <= end2_c <= N:
                    config = {}
                    # True edges for the two segments
                    for i in range(1, L1 + 1):
                        r_a, c_a = r + dir1[0]*(i-1), c + dir1[1]*(i-1)
                        r_b, c_b = r + dir1[0]*i, c + dir1[1]*i
                        config[tuple(sorted(((r_a, c_a), (r_b, c_b))))] = True
                    for j in range(1, L2 + 1):
                        r_a, c_a = r + dir2[0]*(j-1), c + dir2[1]*(j-1)
                        r_b, c_b = r + dir2[0]*j, c + dir2[1]*j
                        config[tuple(sorted(((r_a, c_a), (r_b, c_b))))] = True

                    # Must turn at ends
                    next1_r, next1_c = r + dir1[0]*(L1+1), c + dir1[1]*(L1+1)
                    if 0 <= next1_r <= N and 0 <= next1_c <= N:
                        config[tuple(sorted(((end1_r, end1_c), (next1_r, next1_c))))] = False
                    next2_r, next2_c = r + dir2[0]*(L2+1), c + dir2[1]*(L2+1)
                    if 0 <= next2_r <= N and 0 <= next2_c <= N:
                        config[tuple(sorted(((end2_r, end2_c), (next2_r, next2_c))))] = False

                    # Must turn at the circle itself
                    for d_r, d_c in [(-1,0), (1,0), (0,-1), (0,1)]:
                        if (d_r, d_c) != dir1 and (d_r, d_c) != dir2:
                            adj_r, adj_c = r + d_r, c + d_c
                            if 0 <= adj_r <= N and 0 <= adj_c <= N:
                                config[tuple(sorted(((r, c), (adj_r, adj_c))))] = False

                    configs.append(config)
    return configs

def deduce(edges, N, clues):
    """Applies logical deductions to force edge assignments."""
    changed = True
    while changed:
        changed = False
        for r in range(N + 1):
            for c in range(N + 1):
                incident = get_incident_edges(r, c, N)
                true_count = sum(1 for e in incident if edges[e] == True)
                unassigned = [e for e in incident if edges[e] is None]

                if true_count > 2: return False
                if true_count == 2 and unassigned:
                    for e in unassigned:
                        edges[e] = False
                        changed = True
                elif true_count == 1:
                    if len(unassigned) == 0: return False
                    if len(unassigned) == 1:
                        edges[unassigned[0]] = True
                        changed = True
                elif true_count == 0:
                    if len(unassigned) == 1:
                        edges[unassigned[0]] = False
                        changed = True

        # Check for premature closed loops
        comps = get_components(edges)
        true_edges_count = sum(1 for v in edges.values() if v == True)
        for comp in comps:
            if is_closed_loop(comp):
                if len(comp) < true_edges_count:
                    return False
                visited_dots = set()
                for e in comp:
                    visited_dots.add(e[0])
                    visited_dots.add(e[1])
                all_clues_visited = all(clue_pos in visited_dots for clue_pos in clues)
                if not all_clues_visited:
                    return False

                # If it's a closed loop containing all clues, force remaining edges to False
                for e in edges:
                    if edges[e] is None:
                        edges[e] = False
                        changed = True

    if all(v is not None for v in edges.values()):
        if is_valid_solution(edges, clues, N):
            return True
        return False
    return None

def backtrack(edges, N, clues):
    """Backtracking search to resolve remaining unassigned edges."""
    res = deduce(edges, N, clues)
    if res == False: return False
    if res == True: return edges

    unassigned = [e for e, v in edges.items() if v is None]
    if not unassigned:
        if is_valid_solution(edges, clues, N): return edges
        return False

    # Heuristic: pick an edge adjacent to a degree-1 dot to extend the path
    best_edge = None
    for e in unassigned:
        u, v = e
        deg_u = sum(1 for adj in get_incident_edges(*u, N) if edges[adj] == True)
        deg_v = sum(1 for adj in get_incident_edges(*v, N) if edges[adj] == True)
        if deg_u == 1 or deg_v == 1:
            best_edge = e
            break
    if not best_edge:
        best_edge = unassigned[0]

    edges_copy = edges.copy()
    edges_copy[best_edge] = True
    res_true = backtrack(edges_copy, N, clues)
    if res_true: return res_true

    edges_copy = edges.copy()
    edges_copy[best_edge] = False
    return backtrack(edges_copy, N, clues)

def extract_path(edges):
    """Converts the set of True edges into an ordered list of coordinates."""
    true_edges = [e for e, v in edges.items() if v == True]
    if not true_edges: return []

    adj = {}
    for u, v in true_edges:
        adj.setdefault(u, []).append(v)
        adj.setdefault(v, []).append(u)

    start_node = true_edges[0][0]
    path = [start_node]
    curr = start_node
    prev = None

    while True:
        neighbors = adj[curr]
        if len(neighbors) != 2: return []
        nxt = neighbors[0] if neighbors[0] != prev else neighbors[1]
        if nxt == start_node:
            break
        path.append(nxt)
        prev = curr
        curr = nxt

    path.append(start_node)
    return path

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    clues = {}
    for r in range(N + 1):
        for c in range(N + 1):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]

    clue_configs = {}
    for pos, clue_str in clues.items():
        clue_type = clue_str[0]
        k = int(clue_str[1:])
        configs = get_configs(pos[0], pos[1], clue_type, k, N)
        if not configs: return "No Solution"
        clue_configs[pos] = configs

    clue_positions = list(clues.keys())

    def search_configs(idx, current_assigned):
        """Iterates through combinations of valid clue configurations."""
        if idx == len(clue_positions):
            edges = {}
            for r in range(N + 1):
                for c in range(N + 1):
                    if c < N: edges[tuple(sorted(((r, c), (r, c+1))))] = None
                    if r < N: edges[tuple(sorted(((r, c), (r+1, c))))] = None

            for e, v in current_assigned.items():
                edges[e] = v

            res = backtrack(edges, N, clues)
            if res: return res
            return False

        pos = clue_positions[idx]
        for config in clue_configs[pos]:
            compatible = True
            for e, v in config.items():
                if e in current_assigned and current_assigned[e] != v:
                    compatible = False
                    break
            if compatible:
                new_assigned = current_assigned.copy()
                new_assigned.update(config)

                # Quick prune: check if any dot exceeds degree 2
                deg_ok = True
                deg_counts = {}
                for e, v in new_assigned.items():
                    if v:
                        deg_counts[e[0]] = deg_counts.get(e[0], 0) + 1
                        deg_counts[e[1]] = deg_counts.get(e[1], 0) + 1
                if any(d > 2 for d in deg_counts.values()):
                    deg_ok = False

                if deg_ok:
                    res = search_configs(idx + 1, new_assigned)
                    if res: return res
        return False

    final_edges = search_configs(0, {})
    if not final_edges: return "No Solution"
    return extract_path(final_edges)

