def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    R = len(row_targets)
    C = len(col_targets)

    # Weights are inferred to be 1 to N based on standard puzzle rules and the image
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # 1. Generate all valid configurations for each row independently
    valid_rows = []
    for i in range(R):
        target = row_targets[i]
        valid = []
        def get_row_combinations(idx, current_sum, current_cfg):
            if idx == C:
                if current_sum == target:
                    valid.append(tuple(current_cfg))
                return
            # Prune if remaining weights cannot possibly reach the target
            rem_weights = sum(col_weights[k] for k in range(idx, C))
            if current_sum + rem_weights < target:
                return

            # Option 1: Cell is non-black (0)
            get_row_combinations(idx + 1, current_sum, current_cfg + [0])
            # Option 2: Cell is black (1)
            if current_sum + col_weights[idx] <= target:
                get_row_combinations(idx + 1, current_sum + col_weights[idx], current_cfg + [1])

        get_row_combinations(0, 0, [])
        valid_rows.append(valid)

    # 2. Generate all valid configurations for each column independently
    valid_cols = []
    for j in range(C):
        target = col_targets[j]
        valid = []
        def get_col_combinations(idx, current_sum, current_cfg):
            if idx == R:
                if current_sum == target:
                    valid.append(tuple(current_cfg))
                return
            # Prune if remaining weights cannot possibly reach the target
            rem_weights = sum(row_weights[k] for k in range(idx, R))
            if current_sum + rem_weights < target:
                return

            # Option 1: Cell is non-black (0)
            get_col_combinations(idx + 1, current_sum, current_cfg + [0])
            # Option 2: Cell is black (1)
            if current_sum + row_weights[idx] <= target:
                get_col_combinations(idx + 1, current_sum + row_weights[idx], current_cfg + [1])

        get_col_combinations(0, 0, [])
        valid_cols.append(valid)

    # 3. Constraint Propagation (AC-3 style) to drastically reduce search space
    # We iteratively filter valid_rows and valid_cols by ensuring they agree on possible cell values
    changed = True
    while changed:
        changed = False
        for i in range(R):
            for j in range(C):
                if not valid_rows[i] or not valid_cols[j]:
                    return "No Solution"

                # Find allowed values for cell (i, j) from the perspective of its row and column
                allowed_from_rows = set(cfg[j] for cfg in valid_rows[i])
                allowed_from_cols = set(cfg[i] for cfg in valid_cols[j])

                # The cell must satisfy both row and column constraints simultaneously
                allowed = allowed_from_rows.intersection(allowed_from_cols)
                if not allowed:
                    return "No Solution"

                # Filter out row configurations that require an impossible cell value
                new_valid_rows = [cfg for cfg in valid_rows[i] if cfg[j] in allowed]
                if len(new_valid_rows) < len(valid_rows[i]):
                    valid_rows[i] = new_valid_rows
                    changed = True

                # Filter out column configurations that require an impossible cell value
                new_valid_cols = [cfg for cfg in valid_cols[j] if cfg[i] in allowed]
                if len(new_valid_cols) < len(valid_cols[j]):
                    valid_cols[j] = new_valid_cols
                    changed = True

    # Precompute which cells can potentially be black for aggressive backtracking pruning
    can_be_one = [[False] * C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            if any(cfg[j] == 1 for cfg in valid_rows[i]):
                can_be_one[i][j] = True

    # 4. Backtracking Search with Minimum Remaining Values (MRV) heuristic
    grid = [None] * R

    def backtrack(assigned_count, current_col_sums):
        if assigned_count == R:
            return current_col_sums == col_targets

        # MRV: Pick the unassigned row with the fewest valid configurations left
        min_len = float('inf')
        best_row = -1
        for i in range(R):
            if grid[i] is None:
                if len(valid_rows[i]) < min_len:
                    min_len = len(valid_rows[i])
                    best_row = i

        for row_cfg in valid_rows[best_row]:
            possible = True
            next_col_sums = list(current_col_sums)

            # Apply the chosen row configuration and check immediate column sum violations
            for j in range(C):
                if row_cfg[j]:
                    next_col_sums[j] += row_weights[best_row]
                if next_col_sums[j] > col_targets[j]:
                    possible = False
                    break

            if possible:
                # Look-ahead Pruning: Check if the remaining unassigned rows can provide enough weight
                # to reach the column targets, considering only cells that are still allowed to be black.
                for j in range(C):
                    rem_sum_j = 0
                    for i in range(R):
                        if grid[i] is None and i != best_row and can_be_one[i][j]:
                            rem_sum_j += row_weights[i]
                    if next_col_sums[j] + rem_sum_j < col_targets[j]:
                        possible = False
                        break

            if possible:
                grid[best_row] = row_cfg
                if backtrack(assigned_count + 1, next_col_sums):
                    return True
                grid[best_row] = None

        return False

    if backtrack(0, [0] * C):
        # Format the output grid
        res = []
        for row in grid:
            res.append(['B' if cell else None for cell in row])
        return res
    else:
        return "No Solution"

