OBSERVATION = {'row_sum': [17, 24, 21, 19, 23, 24, 8], 'col_sum': [20, 24, 21, 12, 16, 27, 14]}

def solve(observation):
    row_sums = observation['row_sum']
    col_sums = observation['col_sum']
    R = len(row_sums)
    C = len(col_sums)

    # Weights are 1-based indices as per the puzzle rules
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Precompute all valid cell configurations (bitmasks) for each row
    # that satisfy the row's target sum.
    valid_row_configs = []
    for i in range(R):
        target = row_sums[i]
        configs = []
        for mask in range(1 << C):
            current_sum = 0
            for j in range(C):
                if (mask >> j) & 1:
                    current_sum += col_weights[j]
            if current_sum == target:
                configs.append(mask)
        valid_row_configs.append(configs)

    # Precompute exact possible sums that can be formed by any subset of the remaining rows.
    # possible_suffix_sums[i] contains all possible sums using a subset of row_weights[i:]
    # This allows for aggressive, exact pruning (mimicking human deduction: "Can I still reach the target?").
    possible_suffix_sums = []
    for i in range(R + 1):
        sums = {0}
        for w in row_weights[i:]:
            new_sums = set(sums)
            for s in sums:
                new_sums.add(s + w)
            sums = new_sums
        possible_suffix_sums.append(sums)

    def backtrack(row_idx, current_col_sums):
        # Base case: all rows processed successfully
        if row_idx == R:
            return True, []

        for mask in valid_row_configs[row_idx]:
            possible = True
            next_col_sums = list(current_col_sums)

            for j in range(C):
                if (mask >> j) & 1:
                    next_col_sums[j] += row_weights[row_idx]

                # Aggressive Pruning: Check if the required remaining sum for column j
                # can actually be formed by some combination of the remaining row weights.
                # If next_col_sums[j] > col_sums[j], the difference is negative and won't be in the set.
                if col_sums[j] - next_col_sums[j] not in possible_suffix_sums[row_idx + 1]:
                    possible = False
                    break

            if possible:
                success, grid = backtrack(row_idx + 1, next_col_sums)
                if success:
                    return True, [mask] + grid

        return False, []

    success, grid_masks = backtrack(0, [0] * C)

    if success:
        res = []
        for mask in grid_masks:
            row_res = []
            for j in range(C):
                if (mask >> j) & 1:
                    row_res.append('B')
                else:
                    row_res.append(None)
            res.append(row_res)
        return res
    else:
        return "No Solution"

