        visited = set()
        curr = start_node
        prev = None
        while True:
            visited.add(curr)
            neighbors = adj[curr]
            if len(neighbors) != 2: return False
            nxt = neighbors[0] if neighbors[0] != prev else neighbors[1]
            prev = curr
            curr = nxt
            if curr == start_node:
                break

        if len(visited) != sum(1 for v in adj.values() if len(v) > 0):
            return False

        if len([c for c in circles if c in visited]) != len(circles):
            return False

        return True

    def get_path(state):
        adj = { (r, c): [] for r in range(N) for c in range(N) }
        for e, val in state.items():
            if val == 1:
                u, v = e
                adj[u].append(v)
                adj[v].append(u)
        start_node = next(iter(circles))
        curr = start_node
        prev = None
        path = []
        while True:
            path.append(curr)
            neighbors = adj[curr]
            nxt = neighbors[0] if neighbors[0] != prev else neighbors[1]
            prev = curr
            curr = nxt
            if curr == start_node:
                path.append(curr)
                break
        return path

    def solve_recursive(state):
        if not propagate(state):
            return None
        if is_solved(state):
            return state

        best_e = None
        best_score = -1

        deg = { (r, c): 0 for r in range(N) for c in range(N) }
        for e, val in state.items():
            if val == 1:
                deg[e[0]] += 1
                deg[e[1]] += 1

        for e, val in state.items():
            if val == -1:
                score = deg[e[0]] + deg[e[1]]
                if score > best_score:
                    best_score = score
                    best_e = e

        if not best_e: return None

        state_copy = state.copy()
        state_copy[best_e] = 1
        res = solve_recursive(state_copy)
        if res: return res

        state_copy = state.copy()
        state_copy[best_e] = 0
        return solve_recursive(state_copy)

    final_state = solve_recursive(edges)
    if final_state:
        return get_path(final_state)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
