def solve(observation):
    tree_grid = observation['tree']
    row_clues = observation['row_tent_counts']
    col_clues = observation['col_tent_counts']

    R = len(row_clues)
    C = len(col_clues)

    trees = []
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))

    # Pre-calculate valid domains for each tree to mimic human deduction
    # A valid tent location must be orthogonally adjacent to exactly one tree (Rule 1 strict interpretation)
    # It must also not violate any 0-clue rows/cols initially.
    tree_domains = []
    for r, c in trees:
        domain = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if tree_grid[nr][nc] != 'T':
                    if row_clues[nr] > 0 and col_clues[nc] > 0:
                        # Enforce strict rule: exactly one adjacent tree
                        adj_trees = 0
                        for ddr, ddc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nnr, nnc = nr + ddr, nc + ddc
                            if 0 <= nnr < R and 0 <= nnc < C and tree_grid[nnr][nnc] == 'T':
                                adj_trees += 1
                        if adj_trees == 1:
                            domain.append((nr, nc))
        tree_domains.append(domain)

    # Pair trees with their domains and sort by domain size (Minimum Remaining Values heuristic)
    # This drastically reduces the search space by forcing highly constrained trees first.
    trees_with_domains = list(zip(trees, tree_domains))
    trees_with_domains.sort(key=lambda x: len(x[1]))

    tents = []
    row_counts = [0] * R
    col_counts = [0] * C

    def is_valid(r, c):
        # Check row and column capacity
        if row_counts[r] >= row_clues[r]: return False
        if col_counts[c] >= col_clues[c]: return False

        # Check 8-way adjacency with existing tents
        for tr, tc in tents:
            if abs(tr - r) <= 1 and abs(tc - c) <= 1:
                return False
        return True

    def backtrack(idx):
        # If all trees have been assigned a tent, verify final counts
        if idx == len(trees_with_domains):
            return row_counts == row_clues and col_counts == col_clues

        tree, domain = trees_with_domains[idx]
        for r, c in domain:
            if is_valid(r, c):
                # Place tent
                tents.append((r, c))
                row_counts[r] += 1
                col_counts[c] += 1

                # Recurse
                if backtrack(idx + 1):
                    return True

                # Backtrack
                tents.pop()
                row_counts[r] -= 1
                col_counts[c] -= 1

        return False

    if backtrack(0):
        # Construct the final answer grid
        ans = [[None for _ in range(C)] for _ in range(R)]
        for r, c in tents:
            ans[r][c] = 't'
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
