    edges = []
    edge_idx = {}
    for r in range(N + 1):
        for c in range(N + 1):
            if c < N:
                e = ((r, c), (r, c+1))
                edge_idx[e] = len(edges)
                edges.append(e)
            if r < N:
                e = ((r, c), (r+1, c))
                edge_idx[e] = len(edges)
                edges.append(e)

    adj = { (r, c): [] for r in range(N + 1) for c in range(N + 1) }
    for i, ((r1, c1), (r2, c2)) in enumerate(edges):
        adj[(r1, c1)].append(i)
        adj[(r2, c2)].append(i)

    def get_edge(r1, c1, r2, c2):
        if r1 > r2 or (r1 == r2 and c1 > c2):
            r1, c1, r2, c2 = r2, c2, r1, c1
        return edge_idx.get(((r1, c1), (r2, c2)))

    assignment = [-1] * len(edges)

