                e_dn = get_edge(r, c, r+1, c)
                e_lf = get_edge(r, c, r, c-1)
                e_rt = get_edge(r, c, r, c+1)

                vs = [e for e in [e_up, e_dn] if e is not None]
                hs = [e for e in [e_lf, e_rt] if e is not None]

                if typ == 'W':
