                    h_in = sum(1 for e in hs if assignment[e] == 1)
                    v_out = sum(1 for e in vs if assignment[e] == 0)
                    h_out = sum(1 for e in hs if assignment[e] == 0)

                    if v_in > 0 or h_out > 0 or len(hs) < 2:
                        for e in vs:
