                            if not set_edge(p2, 0): return False
                        if p2 is not None and assignment[p2] == 1 and p1 is not None:
                            if not set_edge(p1, 0): return False

                    v_out = sum(1 for e in vs if assignment[e] == 0)
                    if v_out == 1 and len(vs) == 2:
                        for e in vs:
                            if assignment[e] == -1:
                                if not set_edge(e, 1): return False
                    elif len(vs) == 1 and vs[0] is not None and assignment[vs[0]] == -1:
                        if not set_edge(vs[0], 1): return False

                    h_out = sum(1 for e in hs if assignment[e] == 0)
                    if h_out == 1 and len(hs) == 2:
                        for e in hs:
                            if assignment[e] == -1:
                                if not set_edge(e, 1): return False
                    elif len(hs) == 1 and hs[0] is not None and assignment[hs[0]] == -1:
