                    u1, v1 = edges[ins[0]]
                    u2, v2 = edges[ins[1]]
                    d1 = (u1[0]-r if u1[0]!=r else v1[0]-r, u1[1]-c if u1[1]!=c else v1[1]-c)
                    d2 = (u2[0]-r if u2[0]!=r else v2[0]-r, u2[1]-c if u2[1]!=c else v2[1]-c)
                    d1 = (d1[0]//abs(d1[0]) if d1[0]!=0 else 0, d1[1]//abs(d1[1]) if d1[1]!=0 else 0)
                    d2 = (d2[0]//abs(d2[0]) if d2[0]!=0 else 0, d2[1]//abs(d2[1]) if d2[1]!=0 else 0)

                    def get_len_info(dr, dc):
                        l = 0
                        curr_r, curr_c = r, c
                        while True:
                            nr, nc = curr_r + dr, curr_c + dc
                            e = get_edge(curr_r, curr_c, nr, nc)
                            if e is None or assignment[e] == 0:
                                return l, True, None
                            if assignment[e] == 1:
                                l += 1
                                curr_r, curr_c = nr, nc
                            else:
                                return l, False, e

                    def get_max_len(dr, dc):
                        l = 0
                        curr_r, curr_c = r, c
