        if not check_degrees(): return False
        if not check_clues(): return False
        if not check_connectivity(): return False

        best_e = -1
        for r in range(N + 1):
            for c in range(N + 1):
                inc = adj[(r, c)]
                in_c = sum(1 for e in inc if assignment[e] == 1)
                if in_c == 1:
                    for e in inc:
                        if assignment[e] == -1:
                            best_e = e
                            break
                if best_e != -1: break
            if best_e != -1: break

        if best_e == -1:
            for i in range(len(edges)):
                if assignment[i] == -1:
                    best_e = i
                    break

