            in_edges = [i for i, a in enumerate(assignment) if a == 1]
            if not in_edges: return False
            adj_in = {}
            for e in in_edges:
                u, v = edges[e]
                adj_in.setdefault(u, []).append(v)
                adj_in.setdefault(v, []).append(u)
            for clue_pos in clues:
                if clue_pos not in adj_in or len(adj_in[clue_pos]) != 2:
                    return False
            start = edges[in_edges[0]][0]
            visited = set()
            q = [start]
            visited.add(start)
            while q:
                curr = q.pop(0)
                for nxt in adj_in.get(curr, []):
                    if nxt not in visited:
                        visited.add(nxt)
                        q.append(nxt)
            if len(visited) != len(adj_in): return False
            return True

        saved_assignment = list(assignment)

        assignment[best_e] = 1
        if solve_bt(): return True

        for i in range(len(edges)): assignment[i] = saved_assignment[i]

        assignment[best_e] = 0
        if solve_bt(): return True

        for i in range(len(edges)): assignment[i] = saved_assignment[i]
        return False

    if solve_bt():
        in_edges = [i for i, a in enumerate(assignment) if a == 1]
        adj_in = {}
        for e in in_edges:
            u, v = edges[e]
            adj_in.setdefault(u, []).append(v)
            adj_in.setdefault(v, []).append(u)

        start = edges[in_edges[0]][0]
        path = [start]
        curr = start
        prev = None
        while True:
            nxts = adj_in[curr]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append(nxt)
            prev = curr
            curr = nxt
            if curr == start:
                break
        return path
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
