OBSERVATION = {'data': [[None, None, 'W3', None, None, None, None, None], [None, None, 'B3', None, None, None, None, None], [None, None, None, None, 'B2', None, 'W3', None], [None, 'W4', None, None, None, None, None, None], [None, None, None, None, 'W2', 'B3', None, 'W6'], [None, None, None, None, 'B5', None, 'W2', None], ['B7', None, 'B2', None, None, None, None, None], [None, None, None, None, None, None, None, None]]}

class MasyuSolver:
    def __init__(self, observation):
        self.obs = observation['data']
        self.N = len(self.obs) - 1
        self.circles = {}
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                if self.obs[r][c] is not None:
                    self.circles[(r, c)] = self.obs[r][c]

        self.edges = {}
        for r in range(self.N + 1):
            for c in range(self.N):
                self.edges[('H', r, c)] = -1
        for c in range(self.N + 1):
            for r in range(self.N):
                self.edges[('V', r, c)] = -1

        self.valid_H, self.valid_V = self.get_valid_segments()
        self.options = self.get_circle_options()

    def get_incident(self, r, c):
        inc = []
        if c > 0: inc.append(('H', r, c - 1))
        if c < self.N: inc.append(('H', r, c))
        if r > 0: inc.append(('V', r - 1, c))
        if r < self.N: inc.append(('V', r, c))
        return inc

    def get_valid_segments(self):
        valid_H = []
        valid_V = []

        def is_valid_seg(is_h, rc, p1, p2):
            length = p2 - p1
            # Check internal nodes
            for p in range(p1 + 1, p2):
                r, c = (rc, p) if is_h else (p, rc)
                if (r, c) in self.circles:
                    clue = self.circles[(r, c)]
                    if clue.startswith('B'):
                        return False # Cannot pass through Black circle
                    if clue.startswith('W'):
                        k = int(clue[1:])
                        if length != k:
                            return False # If passing through White, length must match
            # Check endpoints
            for p in (p1, p2):
                r, c = (rc, p) if is_h else (p, rc)
                if (r, c) in self.circles:
                    clue = self.circles[(r, c)]
                    if clue.startswith('W'):
                        return False # Cannot end at White circle
                    if clue.startswith('B'):
                        k = int(clue[1:])
                        if length >= k:
                            return False # If ending at Black, length must be strictly less than k
            return True

        for r in range(self.N + 1):
            for c1 in range(self.N + 1):
                for c2 in range(c1 + 1, self.N + 1):
                    if is_valid_seg(True, r, c1, c2):
                        valid_H.append((True, r, c1, c2))

        for c in range(self.N + 1):
            for r1 in range(self.N + 1):
                for r2 in range(r1 + 1, self.N + 1):
                    if is_valid_seg(False, c, r1, r2):
                        valid_V.append((False, c, r1, r2))

        return valid_H, valid_V

    def get_circle_options(self):
        options = {}
        for (r, c), clue in self.circles.items():
            k = int(clue[1:])
            if clue.startswith('W'):
                opts = []
                for seg in self.valid_H:
                    if seg[1] == r and seg[2] < c < seg[3] and seg[3] - seg[2] == k:
                        opts.append(seg)
                for seg in self.valid_V:
                    if seg[1] == c and seg[2] < r < seg[3] and seg[3] - seg[2] == k:
                        opts.append(seg)
                options[(r, c)] = opts
            else: # 'B'
                opts = []
                h_segs = [seg for seg in self.valid_H if seg[1] == r and (seg[2] == c or seg[3] == c)]
                v_segs = [seg for seg in self.valid_V if seg[1] == c and (seg[2] == r or seg[3] == r)]

                for h in h_segs:
                    lh = h[3] - h[2]
                    for v in v_segs:
                        lv = v[3] - v[2]
                        if lh + lv == k:
                            opts.append((h, v))
                options[(r, c)] = opts
        return options

    def get_reqs(self, opt, is_W):
        reqs = []
        if is_W:
            is_h, rc, p1, p2 = opt
            if is_h:
                for i in range(p1, p2): reqs.append((('H', rc, i), 1))
                if p1 > 0: reqs.append((('H', rc, p1 - 1), 0))
                if p2 < self.N: reqs.append((('H', rc, p2), 0))
            else:
                for i in range(p1, p2): reqs.append((('V', i, rc), 1))
                if p1 > 0: reqs.append((('V', p1 - 1, rc), 0))
                if p2 < self.N: reqs.append((('V', p2, rc), 0))
        else:
            h_seg, v_seg = opt
            _, r, c1, c2 = h_seg
            for i in range(c1, c2): reqs.append((('H', r, i), 1))
            if c1 > 0: reqs.append((('H', r, c1 - 1), 0))
            if c2 < self.N: reqs.append((('H', r, c2), 0))

            _, c, r1, r2 = v_seg
            for i in range(r1, r2): reqs.append((('V', i, c), 1))
            if r1 > 0: reqs.append((('V', r1 - 1, c), 0))
            if r2 < self.N: reqs.append((('V', r2, c), 0))
        return reqs

    def propagate_degrees(self):
        changed = False
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                inc = self.get_incident(r, c)
                in_count = sum(1 for e in inc if self.edges[e] == 1)
                out_count = sum(1 for e in inc if self.edges[e] == 0)
                unk_edges = [e for e in inc if self.edges[e] == -1]

                if in_count > 2: return 'CONFLICT'

                if in_count == 2:
                    for e in unk_edges:
                        self.edges[e] = 0
                        changed = True
                elif in_count == 1:
                    if len(unk_edges) == 0: return 'CONFLICT'
                    if len(unk_edges) == 1:
                        self.edges[unk_edges[0]] = 1
                        changed = True
                elif in_count == 0:
                    if (r, c) in self.circles:
                        if len(unk_edges) < 2: return 'CONFLICT'
                        if len(unk_edges) == 2:
                            for e in unk_edges:
                                self.edges[e] = 1
                                changed = True
                    else:
                        if len(unk_edges) == 1:
                            self.edges[unk_edges[0]] = 0
                            changed = True
        return changed

    def check_partial_loops(self):
        adj = { (r,c): [] for r in range(self.N+1) for c in range(self.N+1) }
        for e, val in self.edges.items():
            if val == 1:
                r1, c1 = e[1], e[2]
                r2, c2 = (r1, c1+1) if e[0] == 'H' else (r1+1, c1)
                adj[(r1, c1)].append((r2, c2))
                adj[(r2, c2)].append((r1, c1))

        visited = set()
        loops = []
        for node in adj:
            if node not in visited and len(adj[node]) > 0:
                comp = set()
                q = [node]
                while q:
                    curr = q.pop(0)
                    if curr in comp: continue
                    comp.add(curr)
                    for neighbor in adj[curr]:
                        if neighbor not in comp:
                            q.append(neighbor)

                if all(len(adj[n]) == 2 for n in comp):
                    loops.append(comp)
                visited.update(comp)

        if len(loops) > 1: return 'CONFLICT'
        if len(loops) == 1:
            loop = loops[0]
            for c in self.circles:
                if c not in loop: return 'CONFLICT'
            changed = False
            for e, val in self.edges.items():
                if val == -1:
                    self.edges[e] = 0
                    changed = True
            return changed
        return False

    def propagate(self):
        changed = True
        while changed:
            changed = False

            res = self.propagate_degrees()
            if res == 'CONFLICT': return False
            if res: changed = True

            res = self.check_partial_loops()
            if res == 'CONFLICT': return False
            if res: changed = True

            for pos, clue in self.circles.items():
                is_W = clue.startswith('W')
                valid_opts = []
                for opt in self.options[pos]:
                    reqs = self.get_reqs(opt, is_W)
                    compatible = True
                    for e, val in reqs:
                        if self.edges[e] == 1 - val:
                            compatible = False
                            break
                    if compatible:
                        valid_opts.append(opt)

                if len(valid_opts) == 0:
                    return False

                if len(valid_opts) < len(self.options[pos]):
                    self.options[pos] = valid_opts
                    changed = True

                if len(valid_opts) > 0:
                    common = set(self.get_reqs(valid_opts[0], is_W))
                    for opt in valid_opts[1:]:
                        common.intersection_update(self.get_reqs(opt, is_W))

                    for e, val in common:
                        if self.edges[e] == -1:
                            self.edges[e] = val
                            changed = True
                        elif self.edges[e] != val:
                            return False
        return True

    def check_single_loop(self):
        start = None
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                if sum(1 for e in self.get_incident(r, c) if self.edges[e] == 1) > 0:
                    start = (r, c)
                    break
            if start: break

        if not start: return False

        visited_nodes = set()
        curr = start
        prev = None

        while True:
            visited_nodes.add(curr)
            inc = self.get_incident(curr[0], curr[1])
            next_node = None
            for e in inc:
                if self.edges[e] == 1:
                    r1, c1 = e[1], e[2]
                    r2, c2 = (r1, c1+1) if e[0] == 'H' else (r1+1, c1)
                    other = (r2, c2) if curr == (r1, c1) else (r1, c1)
                    if other != prev:
                        next_node = other
                        break

            if not next_node: return False
            if next_node == start: break
            prev = curr
            curr = next_node

        for pos in self.circles:
            if pos not in visited_nodes:
                return False

        for e, val in self.edges.items():
            if val == 1:
                r1, c1 = e[1], e[2]
                r2, c2 = (r1, c1+1) if e[0] == 'H' else (r1+1, c1)
                if (r1, c1) not in visited_nodes or (r2, c2) not in visited_nodes:
                    return False

        return True

    def get_path(self):
        start = None
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                if sum(1 for e in self.get_incident(r, c) if self.edges[e] == 1) > 0:
                    start = (r, c)
                    break
            if start: break

        path = [start]
        curr = start
        prev = None

        while True:
            inc = self.get_incident(curr[0], curr[1])
            next_node = None
            for e in inc:
                if self.edges[e] == 1:
                    r1, c1 = e[1], e[2]
                    r2, c2 = (r1, c1+1) if e[0] == 'H' else (r1+1, c1)
                    other = (r2, c2) if curr == (r1, c1) else (r1, c1)
                    if other != prev:
                        next_node = other
                        break

            if next_node == start:
                path.append(start)
                break
            path.append(next_node)
            prev = curr
            curr = next_node

        return path

    def solve(self):
        if not self.propagate():
            return None

        if all(v != -1 for v in self.edges.values()):
            if self.check_single_loop():
                return self.get_path()
            return None

        best_e = None
        min_opts = float('inf')
        for pos in self.circles:
            if len(self.options[pos]) > 1 and len(self.options[pos]) < min_opts:
                is_W = self.circles[pos].startswith('W')
                for opt in self.options[pos]:
                    for e, val in self.get_reqs(opt, is_W):
                        if self.edges[e] == -1:
                            best_e = e
                            min_opts = len(self.options[pos])
                            break
                    if best_e: break
            if best_e: break

        if not best_e:
            for e, val in self.edges.items():
                if val == -1:
                    best_e = e
                    break

        if not best_e: return None

        for val in [1, 0]:
            saved_edges = self.edges.copy()
            saved_options = {k: v[:] for k, v in self.options.items()}

            self.edges[best_e] = val
            res = self.solve()
            if res: return res

            self.edges = saved_edges
            self.options = saved_options

        return None

def solve(observation):
    solver = MasyuSolver(observation)
    path = solver.solve()
    if path:
        return path
    return "No Solution"

