OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], ['W', None, None, 'W', None, None, 'B', 'W'], ['W', None, None, 'W', None, None, 'W', 'W'], [None, None, None, 'W', 'B', 'W', None, None], [None, None, 'W', None, 'W', None, 'W', None], [None, None, 'W', None, None, None, None, None], [None, None, 'W', None, 'W', None, 'W', None], ['B', 'W', None, None, None, 'W', None, None]]}

class MasyuSolver:
    def __init__(self, observation):
        self.grid = observation['data']
        self.N = len(self.grid)
        self.edges = {}
        # Initialize all valid grid edges as UNKNOWN (None)
        for r in range(self.N):
            for c in range(self.N):
                if r + 1 < self.N:
                    self.edges[((r, c), (r + 1, c))] = None
                if c + 1 < self.N:
                    self.edges[((r, c), (r, c + 1))] = None

        self.circles = {}
        for r in range(self.N):
            for c in range(self.N):
                if self.grid[r][c] in ['W', 'B']:
                    self.circles[(r, c)] = self.grid[r][c]

    def get_edge(self, u, v):
        """Returns 1 if IN, 0 if OUT or invalid/out-of-bounds, None if UNKNOWN."""
        if u > v:
            u, v = v, u
        return self.edges.get((u, v), 0)

    def set_edge(self, u, v, val):
        """Sets edge state. Returns False if it causes a conflict."""
        if u > v:
            u, v = v, u
        if (u, v) not in self.edges:
            return val == 0 # Conflict if trying to set an out-of-bounds edge to IN
        if self.edges[(u, v)] is not None:
            return self.edges[(u, v)] == val
        self.edges[(u, v)] = val
        self.changed = True
        return True

    def neighbors(self, r, c):
        res = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if 0 <= r + dr < self.N and 0 <= c + dc < self.N:
                res.append((r + dr, c + dc))
        return res

    def propagate(self):
        """Applies human-like deductive rules to reduce the search space."""
        self.changed = True
        while self.changed:
            self.changed = False

            # 1. Degree constraints for all vertices
            for r in range(self.N):
                for c in range(self.N):
                    v = (r, c)
                    in_edges = []
                    unk_edges = []
                    for u in self.neighbors(r, c):
                        state = self.get_edge(v, u)
                        if state == 1: in_edges.append(u)
                        elif state is None: unk_edges.append(u)

                    if v in self.circles:
                        if len(in_edges) > 2: return False
                        if len(in_edges) == 2:
                            for u in unk_edges:
                                if not self.set_edge(v, u, 0): return False
                        if len(in_edges) + len(unk_edges) < 2: return False
                        if len(in_edges) + len(unk_edges) == 2:
                            for u in unk_edges:
                                if not self.set_edge(v, u, 1): return False
                    else:
                        if len(in_edges) > 2: return False
                        if len(in_edges) == 2:
                            for u in unk_edges:
                                if not self.set_edge(v, u, 0): return False
                        if len(in_edges) == 1:
                            if len(unk_edges) == 0: return False
                            if len(unk_edges) == 1:
                                if not self.set_edge(v, unk_edges[0], 1): return False
                        if len(in_edges) == 0:
                            if len(unk_edges) == 1:
                                if not self.set_edge(v, unk_edges[0], 0): return False

            # 2. Circle specific constraints
            for (r, c), c_type in self.circles.items():
                v = (r, c)
                if c_type == 'W':
                    # Must go straight through the circle
                    for dr, dc in [(0, 1), (1, 0)]:
                        u1 = (r - dr, c - dc)
                        u2 = (r + dr, c + dc)
                        e1 = self.get_edge(v, u1)
                        e2 = self.get_edge(v, u2)
                        if e1 == 1:
                            if not self.set_edge(v, u2, 1): return False
                        if e2 == 1:
                            if not self.set_edge(v, u1, 1): return False
                        if e1 == 0:
                            if not self.set_edge(v, u2, 0): return False
                        if e2 == 0:
                            if not self.set_edge(v, u1, 0): return False

                    # Must turn at least once in the adjacent vertices
                    if self.get_edge(v, (r, c-1)) == 1 and self.get_edge(v, (r, c+1)) == 1:
                        ls = self.get_edge((r, c-1), (r, c-2))
                        rs = self.get_edge((r, c+1), (r, c+2))
                        if ls == 1:
                            if not self.set_edge((r, c+1), (r, c+2), 0): return False
                        if rs == 1:
                            if not self.set_edge((r, c-1), (r, c-2), 0): return False

                    if self.get_edge(v, (r-1, c)) == 1 and self.get_edge(v, (r+1, c)) == 1:
                        us = self.get_edge((r-1, c), (r-2, c))
                        ds = self.get_edge((r+1, c), (r+2, c))
                        if us == 1:
                            if not self.set_edge((r+1, c), (r+2, c), 0): return False
                        if ds == 1:
                            if not self.set_edge((r-1, c), (r-2, c), 0): return False

                elif c_type == 'B':
                    # Must turn at the circle
                    for dr, dc in [(0, 1), (1, 0)]:
                        u1 = (r - dr, c - dc)
                        u2 = (r + dr, c + dc)
                        if self.get_edge(v, u1) == 1:
                            if not self.set_edge(v, u2, 0): return False
                        if self.get_edge(v, u2) == 1:
                            if not self.set_edge(v, u1, 0): return False

                    # Must go straight in both adjacent vertices
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        u = (r + dr, c + dc)
                        w = (r + 2*dr, c + 2*dc)
                        if self.get_edge(v, u) == 1:
                            if not self.set_edge(u, w, 1): return False
                        if self.get_edge(u, w) == 0:
                            if not self.set_edge(v, u, 0): return False

            # 3. Prevent premature small loops
            if not self.check_loops():
                return False

        return True

    def check_loops(self):
        """Ensures no closed loops are formed unless they contain all circles."""
        adj = { (r, c): [] for r in range(self.N) for c in range(self.N) }
        for (u, v), state in self.edges.items():
            if state == 1:
                adj[u].append(v)
                adj[v].append(u)

        visited = set()
        components = []
        for v in adj:
            if v not in visited and len(adj[v]) > 0:
                comp = []
                q = [v]
                visited.add(v)
                while q:
                    curr = q.pop(0)
                    comp.append(curr)
                    for nxt in adj[curr]:
                        if nxt not in visited:
                            visited.add(nxt)
                            q.append(nxt)

                is_cycle = all(len(adj[node]) == 2 for node in comp)
                components.append((comp, is_cycle))

        all_circles = set(self.circles.keys())

        for comp, is_cycle in components:
            comp_set = set(comp)
            if is_cycle:
                if not all_circles.issubset(comp_set):
                    return False
                if len(components) > 1:
                    return False
            else:
                endpoints = [node for node in comp if len(adj[node]) == 1]
                if len(endpoints) == 2:
                    u, v = endpoints
                    if not all_circles.issubset(comp_set):
                        if self.get_edge(u, v) is None:
                            if not self.set_edge(u, v, 0): return False

        return True

    def is_solved(self):
        """Checks if the current state is a valid complete solution."""
        adj = { (r, c): [] for r in range(self.N) for c in range(self.N) }
        for (u, v), state in self.edges.items():
            if state == 1:
                adj[u].append(v)
                adj[v].append(u)

        for v in adj:
            if len(adj[v]) not in [0, 2]:
                return False

        for c in self.circles:
            if len(adj[c]) != 2:
                return False

        start = None
        for v in adj:
            if len(adj[v]) == 2:
                start = v
                break
        if not start: return False

        visited = set()
        q = [start]
        visited.add(start)
        while q:
            curr = q.pop(0)
            for nxt in adj[curr]:
                if nxt not in visited:
                    visited.add(nxt)
                    q.append(nxt)

        for v in adj:
            if len(adj[v]) > 0 and v not in visited:
                return False

        return True

    def get_loop_path(self):
        """Extracts the ordered sequence of coordinates forming the loop."""
        adj = { (r, c): [] for r in range(self.N) for c in range(self.N) }
        for (u, v), state in self.edges.items():
            if state == 1:
                adj[u].append(v)
                adj[v].append(u)

        start = None
        for v in adj:
            if len(adj[v]) == 2:
                start = v
                break

        path = [start]
        curr = start
        prev = None
        while True:
            nxts = adj[curr]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append(nxt)
            prev = curr
            curr = nxt
            if curr == start:
                break
        return path

    def solve(self):
        """Main backtracking search with constraint propagation."""
        if not self.propagate():
            return None

        if self.is_solved():
            return self.get_loop_path()

        unk_edges = [e for e, state in self.edges.items() if state is None]
        if not unk_edges:
            return None

        # Heuristic: prioritize edges connected to paths or circles
        def edge_score(e):
            u, v = e
            score = 0
            for node in (u, v):
                in_deg = sum(1 for n in self.neighbors(*node) if self.get_edge(node, n) == 1)
                if in_deg == 1: score += 10
                if node in self.circles: score += 5
            if u in self.circles and v in self.circles:
                score += 20
            return score

        unk_edges.sort(key=edge_score, reverse=True)
        e = unk_edges[0]

        saved_edges = self.edges.copy()

        # Branch: Try IN
        self.edges[e] = 1
        res = self.solve()
        if res: return res

        # Branch: Try OUT
        self.edges = saved_edges.copy()
        self.edges[e] = 0
        res = self.solve()
        if res: return res

        # Backtrack
        self.edges = saved_edges
        return None

def solve(observation):
    solver = MasyuSolver(observation)
    path = solver.solve()
    if path:
        return str(path)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
