class State:
    def __init__(self, N, num_edges):
        self.N = N
        self.num_edges = num_edges
        self.edges = [-1] * num_edges
        self.path_end = {}
        self.path_size = {}
        self.total_ones = 0

    def clone(self):
        new_state = State(self.N, self.num_edges)
        new_state.edges = list(self.edges)
        new_state.path_end = dict(self.path_end)
        new_state.path_size = dict(self.path_size)
        new_state.total_ones = self.total_ones
        return new_state

def set_edge(state, e, val, queue):
    if state.edges[e] != -1:
        return state.edges[e] == val
    state.edges[e] = val

    for cell in edge_to_cells[e]: queue.add(cell)
    for dot in edge_to_dots[e]: queue.add(dot)

    if val == 1:
        state.total_ones += 1
        u, v = edge_to_dots[e]
        eu = state.path_end.get(u, u)
        ev = state.path_end.get(v, v)

        if eu == v:
            for i in range(state.num_edges):
                if state.edges[i] == -1:
                    state.edges[i] = 0
                    for cell in edge_to_cells[i]: queue.add(cell)
                    for dot in edge_to_dots[i]: queue.add(dot)
        else:
            new_size = state.path_size.get(eu, 0) + state.path_size.get(ev, 0) + 1
            state.path_end[eu] = ev
            state.path_end[ev] = eu
            state.path_size[eu] = new_size
            state.path_size[ev] = new_size

            if u != eu and u in state.path_end: 
                del state.path_end[u]
                if u in state.path_size: del state.path_size[u]
            if v != ev and v in state.path_end: 
                del state.path_end[v]
                if v in state.path_size: del state.path_size[v]

    return True

def propagate(state, initial_queue=None):
