                            if state.edges[e] == -1:
                                if not set_edge(state, e, 0, queue): return False
                    elif c1 == 1 and cu == 1:
                        for e in dot_e:
                            if state.edges[e] == -1:
                                if not set_edge(state, e, 1, queue): return False
                    elif c1 == 0 and cu == 1:
                        for e in dot_e:
                            if state.edges[e] == -1:
                                if not set_edge(state, e, 0, queue): return False

        added = False
        for e in range(state.num_edges):
            if state.edges[e] == -1:
                u, v = edge_to_dots[e]
                eu = state.path_end.get(u, u)
                if eu == v:
                    if state.total_ones > state.path_size.get(u, 0):
                        if not set_edge(state, e, 0, queue): return False
                        added = True
        if not added:
            break

    return True

def solve_backtrack(state):
    if not propagate(state):
        return None

    if all(e != -1 for e in state.edges):
        for r in range(N):
            for c in range(N):
                if clues[r][c] is not None:
                    c1 = sum(1 for e in cell_edges[r][c] if state.edges[e] == 1)
                    if c1 != clues[r][c]: return None
        for r in range(N + 1):
            for c in range(N + 1):
                c1 = sum(1 for e in dot_edges[r][c] if state.edges[e] == 1)
                if c1 != 0 and c1 != 2: return None
        if state.total_ones == 0: return None

        start_e = state.edges.index(1)
        u, v = edge_to_dots[start_e]
        curr = v
        prev = u
        count = 1
        while curr != u:
            next_dot = None
            for e in dot_edges[curr[1]][curr[2]]:
                if state.edges[e] == 1:
                    d1, d2 = edge_to_dots[e]
                    other = d2 if d1 == curr else d1
                    if other != prev:
                        next_dot = other
                        break
            if next_dot is None: return None
            prev = curr
            curr = next_dot
            count += 1
        if count == state.total_ones:
            return state
        return None

    best_edge = -1
    best_score = -1

    for e in range(state.num_edges):
        if state.edges[e] == -1:
            score = 0
            u, v = edge_to_dots[e]
            u_e = dot_edges[u[1]][u[2]]
            v_e = dot_edges[v[1]][v[2]]
            if any(state.edges[x] == 1 for x in u_e): score += 10
            if any(state.edges[x] == 1 for x in v_e): score += 10

            for cell in edge_to_cells[e]:
                r, c = cell[1], cell[2]
                if clues[r][c] is not None:
                    k = clues[r][c]
                    cell_e = cell_edges[r][c]
                    c1 = sum(1 for x in cell_e if state.edges[x] == 1)
                    cu = sum(1 for x in cell_e if state.edges[x] == -1)
                    if cu > 0:
                        score += 5 - (cu - (k - c1))
                        if k == 3: score += 2
                        if k == 0: score += 2

            if score > best_score:
                best_score = score
                best_edge = e

    if best_edge == -1: return None

    for val in [1, 0]:
        new_state = state.clone()
        queue = set()
        if set_edge(new_state, best_edge, val, queue):
            res = solve_backtrack(new_state)
            if res is not None: return res

    return None

def extract_loop(state):
    start_e = -1
    for e in range(state.num_edges):
        if state.edges[e] == 1:
            start_e = e
            break

    if start_e == -1: return []

    u, v = edge_to_dots[start_e]
    loop = [u]
    curr = v
    prev = u

    while curr != u:
        loop.append(curr)
        next_dot = None
        for e in dot_edges[curr[1]][curr[2]]:
            if state.edges[e] == 1:
                d1, d2 = edge_to_dots[e]
                other = d2 if d1 == curr else d1
                if other != prev:
                    next_dot = other
                    break
        prev = curr
        curr = next_dot

    loop.append(u)
    return [(r, c) for _, r, c in loop]

def solve(observation):
    global N, clues, num_edges, cell_edges, dot_edges, edge_to_cells, edge_to_dots
    clues = observation['data']
    N = len(clues)
    num_edges = 2 * N * (N + 1)

    cell_edges = []
    for r in range(N):
        row_edges = []
        for c in range(N):
            e1 = r * N + c
            e2 = (r + 1) * N + c
            e3 = N * (N + 1) + r * (N + 1) + c
            e4 = N * (N + 1) + r * (N + 1) + c + 1
            row_edges.append((e1, e2, e3, e4))
        cell_edges.append(row_edges)

    dot_edges = []
    for r in range(N + 1):
        row_dots = []
        for c in range(N + 1):
            adj = []
            if c > 0: adj.append(r * N + c - 1)
            if c < N: adj.append(r * N + c)
            if r > 0: adj.append(N * (N + 1) + (r - 1) * (N + 1) + c)
            if r < N: adj.append(N * (N + 1) + r * (N + 1) + c)
            row_dots.append(adj)
        dot_edges.append(row_dots)

    edge_to_cells = [[] for _ in range(num_edges)]
    edge_to_dots = [[] for _ in range(num_edges)]

    for r in range(N):
        for c in range(N):
            for e in cell_edges[r][c]:
                edge_to_cells[e].append(('C', r, c))

    for r in range(N + 1):
        for c in range(N + 1):
            for e in dot_edges[r][c]:
                dot = ('D', r, c)
                if dot not in edge_to_dots[e]:
                    edge_to_dots[e].append(dot)

    initial_state = State(N, num_edges)
    solved_state = solve_backtrack(initial_state)

    if solved_state:
        return extract_loop(solved_state)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
