OBSERVATION = {'data': [[None, None, None, None, None, None, None, None, 3, None], [3, None, 2, 2, None, None, None, None, 1, None], [None, None, 2, 3, 2, 0, None, None, 3, 2], [None, None, 1, None, None, 1, None, None, 2, 3], [1, None, None, 3, 3, 3, None, 3, 2, None], [None, 3, None, 2, None, None, None, 2, 2, None], [None, 1, None, 2, None, None, None, 1, 1, 2], [3, None, 2, None, None, None, None, 2, None, None], [None, None, 2, 3, None, None, 2, 1, None, None], [3, None, 2, 3, None, 1, 2, None, 3, None]]}

import sys
sys.setrecursionlimit(2000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    num_vertices = (R + 1) * (C + 1)
    num_cells = R * C
    num_edges = (R + 1) * C + R * (C + 1)

    clues = []
    for r in range(R):
        for c in range(C):
            clues.append(data[r][c])

    val = [-1] * num_edges
    deg = [0] * num_vertices
    unk = [0] * num_vertices
    cell_sum = [0] * num_cells
    cell_unk = [4] * num_cells

    edge_endpoints = [None] * num_edges
    edge_cells = [[] for _ in range(num_edges)]
    vertex_edges = [[] for _ in range(num_vertices)]
    cell_edges_list = [[] for _ in range(num_cells)]

    def get_h_edge(r, c): return r * C + c
    def get_v_edge(r, c): return (R + 1) * C + r * (C + 1) + c

    for r in range(R + 1):
        for c in range(C):
            e = get_h_edge(r, c)
            u = r * (C + 1) + c
            v = r * (C + 1) + c + 1
            edge_endpoints[e] = (u, v)
            vertex_edges[u].append(e)
            vertex_edges[v].append(e)
            unk[u] += 1
            unk[v] += 1
            if r > 0:
                cell = (r - 1) * C + c
                edge_cells[e].append(cell)
                cell_edges_list[cell].append(e)
            if r < R:
                cell = r * C + c
                edge_cells[e].append(cell)
                cell_edges_list[cell].append(e)

    for r in range(R):
        for c in range(C + 1):
            e = get_v_edge(r, c)
            u = r * (C + 1) + c
            v = (r + 1) * (C + 1) + c
            edge_endpoints[e] = (u, v)
            vertex_edges[u].append(e)
            vertex_edges[v].append(e)
            unk[u] += 1
            unk[v] += 1
            if c > 0:
                cell = r * C + c - 1
                edge_cells[e].append(cell)
                cell_edges_list[cell].append(e)
            if c < C:
                cell = r * C + c
                edge_cells[e].append(cell)
                cell_edges_list[cell].append(e)

    def set_edge(e, value):
        if val[e] != -1:
            return val[e] == value
        val[e] = value
        u, v = edge_endpoints[e]
        if value == 1:
            deg[u] += 1
            deg[v] += 1
            for c in edge_cells[e]:
                cell_sum[c] += 1
        unk[u] -= 1
        unk[v] -= 1
        for c in edge_cells[e]:
            cell_unk[c] -= 1
        return True

    def propagate():
        while True:
            changed = False

            inner_changed = True
            while inner_changed:
                inner_changed = False
                for v in range(num_vertices):
                    d = deg[v]
                    u = unk[v]
                    if d > 2: return False
                    if d == 2 and u > 0:
                        for e in vertex_edges[v]:
                            if val[e] == -1:
                                set_edge(e, 0)
                                inner_changed = True
                    if d == 1 and u == 0: return False
                    if d == 1 and u == 1:
                        for e in vertex_edges[v]:
                            if val[e] == -1:
                                set_edge(e, 1)
                                inner_changed = True
                    if d == 0 and u == 1:
                        for e in vertex_edges[v]:
                            if val[e] == -1:
                                set_edge(e, 0)
                                inner_changed = True

                for c in range(num_cells):
                    if clues[c] is None: continue
                    s = cell_sum[c]
                    u = cell_unk[c]
                    target = clues[c]
                    if s > target: return False
                    if s + u < target: return False
                    if s == target and u > 0:
                        for e in cell_edges_list[c]:
                            if val[e] == -1:
                                set_edge(e, 0)
                                inner_changed = True
                    if s + u == target and u > 0:
                        for e in cell_edges_list[c]:
                            if val[e] == -1:
                                set_edge(e, 1)
                                inner_changed = True
                if inner_changed:
                    changed = True

            parent = list(range(num_vertices))
            def find(i):
                if parent[i] == i: return i
                parent[i] = find(parent[i])
                return parent[i]
            def union(i, j):
                root_i = find(i)
                root_j = find(j)
                if root_i != root_j:
                    parent[root_i] = root_j

            total_ones = 0
            for e in range(num_edges):
                if val[e] == 1:
                    total_ones += 1
                    u, v = edge_endpoints[e]
                    union(u, v)

            comp_ones = [0] * num_vertices
            comp_vertices = [0] * num_vertices

            for v in range(num_vertices):
                if deg[v] > 0:
                    root = find(v)
                    comp_vertices[root] += 1

            for e in range(num_edges):
                if val[e] == 1:
                    u, v = edge_endpoints[e]
                    comp_ones[find(u)] += 1

            cycle_found = False
            for v in range(num_vertices):
                if parent[v] == v and comp_vertices[v] > 0:
                    is_cycle = True
                    for u in range(num_vertices):
                        if find(u) == v and deg[u] != 2:
                            is_cycle = False
                            break
                    if is_cycle:
                        cycle_found = True
                        if comp_ones[v] < total_ones:
                            return False
                        for e in range(num_edges):
                            if val[e] == -1:
                                set_edge(e, 0)
                                changed = True
                        break

            if cycle_found:
                if changed: continue
                else: break

            for e in range(num_edges):
                if val[e] == -1:
                    u, v = edge_endpoints[e]
                    root_u = find(u)
                    root_v = find(v)
                    if root_u == root_v and deg[u] > 0:
                        if comp_ones[root_u] < total_ones:
                            set_edge(e, 0)
                            changed = True
                        else:
                            possible = True
                            for c in range(num_cells):
                                if clues[c] is not None:
                                    s = cell_sum[c]
                                    if e in cell_edges_list[c]:
                                        s += 1
                                    if s != clues[c]:
                                        possible = False
                                        break
                            if not possible:
                                set_edge(e, 0)
                                changed = True

            if not changed:
                break

        return True

    def check_single_loop():
        for d in deg:
            if d != 0 and d != 2: return False
        for c in range(num_cells):
            if clues[c] is not None and cell_sum[c] != clues[c]:
                return False

        parent = list(range(num_vertices))
        def find(i):
            if parent[i] == i: return i
            parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        first_v = -1
        for e in range(num_edges):
            if val[e] == 1:
                u, v = edge_endpoints[e]
                union(u, v)
                if first_v == -1: first_v = u

        if first_v == -1: return False

        root = find(first_v)
        for e in range(num_edges):
            if val[e] == 1:
                u, v = edge_endpoints[e]
                if find(u) != root: return False

        return True

    def solve_bt():
        if not propagate():
            return False

        if all(v != -1 for v in val):
            return check_single_loop()

        best_e = -1
        best_score = -1
        for e in range(num_edges):
            if val[e] == -1:
                score = 0
                u, v = edge_endpoints[e]
                if deg[u] == 1: score += 10
                if deg[v] == 1: score += 10
                for c in edge_cells[e]:
                    if clues[c] is not None:
                        if clues[c] == 3: score += 3
                        elif clues[c] == 2: score += 2
                        elif clues[c] == 1: score += 1
                if score > best_score:
                    best_score = score
                    best_e = e

        if best_e == -1:
            return False

        saved_val = list(val)
        saved_deg = list(deg)
        saved_unk = list(unk)
        saved_cell_sum = list(cell_sum)
        saved_cell_unk = list(cell_unk)

        if set_edge(best_e, 1):
            if solve_bt(): return True

        val[:] = saved_val
        deg[:] = saved_deg
        unk[:] = saved_unk
        cell_sum[:] = saved_cell_sum
        cell_unk[:] = saved_cell_unk

        if set_edge(best_e, 0):
            if solve_bt(): return True

        val[:] = saved_val
        deg[:] = saved_deg
        unk[:] = saved_unk
        cell_sum[:] = saved_cell_sum
        cell_unk[:] = saved_cell_unk

        return False

    def extract_loop():
        start_v = -1
        for v in range(num_vertices):
            if deg[v] == 2:
                start_v = v
                break
        if start_v == -1: return []

        loop = [start_v]
        curr = start_v
        prev = -1

        while True:
            next_v = -1
            for e in vertex_edges[curr]:
                if val[e] == 1:
                    u, v = edge_endpoints[e]
                    other = v if u == curr else u
                    if other != prev:
                        next_v = other
                        break
            if next_v == -1:
                break
            if next_v == start_v:
                loop.append(start_v)
                break
            loop.append(next_v)
            prev = curr
            curr = next_v

        res = []
        for v in loop:
            r = v // (C + 1)
            c = v % (C + 1)
            res.append((r, c))
        return res

    def preprocess():
        for r in range(R):
            for c in range(C):
                if clues[r * C + c] == 3:
                    if c + 1 < C and clues[r * C + c + 1] == 3:
                        set_edge(get_v_edge(r, c + 1), 1)
                        set_edge(get_h_edge(r, c), 1)
                        set_edge(get_h_edge(r + 1, c), 1)
                        set_edge(get_h_edge(r, c + 1), 1)
                        set_edge(get_h_edge(r + 1, c + 1), 1)
                    if r + 1 < R and clues[(r + 1) * C + c] == 3:
                        set_edge(get_h_edge(r + 1, c), 1)
                        set_edge(get_v_edge(r, c), 1)
                        set_edge(get_v_edge(r, c + 1), 1)
                        set_edge(get_v_edge(r + 1, c), 1)
                        set_edge(get_v_edge(r + 1, c + 1), 1)
                    if r == 0 and c == 0:
                        set_edge(get_h_edge(0, 0), 1)
                        set_edge(get_v_edge(0, 0), 1)
                    if r == 0 and c == C - 1:
                        set_edge(get_h_edge(0, C - 1), 1)
                        set_edge(get_v_edge(0, C), 1)
                    if r == R - 1 and c == 0:
                        set_edge(get_h_edge(R, 0), 1)
                        set_edge(get_v_edge(R - 1, 0), 1)
                    if r == R - 1 and c == C - 1:
                        set_edge(get_h_edge(R, C - 1), 1)
                        set_edge(get_v_edge(R - 1, C), 1)
                    if r + 1 < R and c + 1 < C and clues[(r + 1) * C + c + 1] == 3:
                        set_edge(get_h_edge(r, c), 1)
                        set_edge(get_v_edge(r, c), 1)
                        set_edge(get_h_edge(r + 2, c + 1), 1)
                        set_edge(get_v_edge(r + 1, c + 2), 1)
                    if r + 1 < R and c - 1 >= 0 and clues[(r + 1) * C + c - 1] == 3:
                        set_edge(get_h_edge(r, c), 1)
                        set_edge(get_v_edge(r, c + 1), 1)
                        set_edge(get_h_edge(r + 2, c - 1), 1)
                        set_edge(get_v_edge(r + 1, c - 1), 1)

    preprocess()
    if not solve_bt():
        return "No Solution"

    return extract_loop()

if __name__ == "__main__":
    print(solve(OBSERVATION))
