class SlitherlinkSolver:
    def __init__(self, clues):
        self.R = len(clues)
        self.C = len(clues[0])
        self.clues = clues

        self.edges = []
        self.edge_idx = {}

        # Horizontal edges
        for r in range(self.R + 1):
            for c in range(self.C):
                u = (r, c)
                v = (r, c + 1)
                self.edge_idx[(u, v)] = len(self.edges)
                self.edges.append((u, v))

        # Vertical edges
        for r in range(self.R):
            for c in range(self.C + 1):
                u = (r, c)
                v = (r + 1, c)
                self.edge_idx[(u, v)] = len(self.edges)
                self.edges.append((u, v))

        self.E = len(self.edges)
        self.state = [-1] * self.E

        self.adj = [[] for _ in range((self.R + 1) * (self.C + 1))]
        for i, (u, v) in enumerate(self.edges):
            uidx = u[0] * (self.C + 1) + u[1]
            vidx = v[0] * (self.C + 1) + v[1]
            self.adj[uidx].append(i)
            self.adj[vidx].append(i)

        self.cell_edges = []
        for r in range(self.R):
            row_edges = []
            for c in range(self.C):
                if clues[r][c] is not None:
                    e1 = self.edge_idx[((r, c), (r, c + 1))]
                    e2 = self.edge_idx[((r + 1, c), (r + 1, c + 1))]
                    e3 = self.edge_idx[((r, c), (r + 1, c))]
                    e4 = self.edge_idx[((r, c + 1), (r + 1, c + 1))]
                    row_edges.append((clues[r][c], [e1, e2, e3, e4]))
                else:
                    row_edges.append(None)
            self.cell_edges.append(row_edges)

    def apply_patterns(self):
        # Corners
        corners = [
            (0, 0, [self.edge_idx[((0,0), (0,1))], self.edge_idx[((0,0), (1,0))]]),
            (0, self.C-1, [self.edge_idx[((0,self.C-1), (0,self.C))], self.edge_idx[((0,self.C), (1,self.C))]]),
            (self.R-1, 0, [self.edge_idx[((self.R,0), (self.R,1))], self.edge_idx[((self.R-1,0), (self.R,0))]]),
            (self.R-1, self.C-1, [self.edge_idx[((self.R,self.C-1), (self.R,self.C))], self.edge_idx[((self.R-1,self.C), (self.R,self.C))]])
        ]
        for r, c, edges in corners:
            if self.clues[r][c] == 3:
                for e in edges: self.state[e] = 1
            elif self.clues[r][c] == 1:
                for e in edges: self.state[e] = 0

        # Adjacent 3s
        for r in range(self.R):
            for c in range(self.C - 1):
                if self.clues[r][c] == 3 and self.clues[r][c+1] == 3:
                    self.state[self.edge_idx[((r, c+1), (r+1, c+1))]] = 1
                    self.state[self.edge_idx[((r, c), (r+1, c))]] = 1
                    self.state[self.edge_idx[((r, c+2), (r+1, c+2))]] = 1

        for r in range(self.R - 1):
            for c in range(self.C):
                if self.clues[r][c] == 3 and self.clues[r+1][c] == 3:
                    self.state[self.edge_idx[((r+1, c), (r+1, c+1))]] = 1
                    self.state[self.edge_idx[((r, c), (r, c+1))]] = 1
                    self.state[self.edge_idx[((r+2, c), (r+2, c+1))]] = 1

        # Diagonal 3s
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                if self.clues[r][c] == 3 and self.clues[r+1][c+1] == 3:
                    self.state[self.edge_idx[((r, c), (r, c+1))]] = 1
                    self.state[self.edge_idx[((r, c), (r+1, c))]] = 1
                    self.state[self.edge_idx[((r+2, c+1), (r+2, c+2))]] = 1
                    self.state[self.edge_idx[((r+1, c+2), (r+2, c+2))]] = 1
                if self.clues[r][c+1] == 3 and self.clues[r+1][c] == 3:
                    self.state[self.edge_idx[((r, c+1), (r, c+2))]] = 1
                    self.state[self.edge_idx[((r, c+2), (r+1, c+2))]] = 1
                    self.state[self.edge_idx[((r+2, c), (r+2, c+1))]] = 1
                    self.state[self.edge_idx[((r+1, c), (r+2, c))]] = 1

        # 3 diagonal to 0
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                if self.clues[r][c] == 3 and self.clues[r+1][c+1] == 0:
                    self.state[self.edge_idx[((r+1, c), (r+1, c+1))]] = 1
                    self.state[self.edge_idx[((r, c+1), (r+1, c+1))]] = 1
                if self.clues[r+1][c+1] == 3 and self.clues[r][c] == 0:
                    self.state[self.edge_idx[((r+1, c+1), (r+1, c+2))]] = 1
                    self.state[self.edge_idx[((r+1, c+1), (r+2, c+1))]] = 1
                if self.clues[r][c+1] == 3 and self.clues[r+1][c] == 0:
                    self.state[self.edge_idx[((r+1, c+1), (r+1, c+2))]] = 1
                    self.state[self.edge_idx[((r, c+1), (r+1, c+1))]] = 1
                if self.clues[r+1][c] == 3 and self.clues[r][c+1] == 0:
                    self.state[self.edge_idx[((r+1, c), (r+1, c+1))]] = 1
                    self.state[self.edge_idx[((r+1, c+1), (r+2, c+1))]] = 1

    def check_subloops(self):
        changed = False
        adj1 = [[] for _ in range(len(self.adj))]
        for e, st in enumerate(self.state):
            if st == 1:
                u, v = self.edges[e]
                uidx = u[0] * (self.C + 1) + u[1]
                vidx = v[0] * (self.C + 1) + v[1]
                adj1[uidx].append(vidx)
                adj1[vidx].append(uidx)

        visited = [False] * len(self.adj)
        components = []
        comp_id = [-1] * len(self.adj)

        for i in range(len(self.adj)):
            if not visited[i] and len(adj1[i]) > 0:
                comp_nodes = []
                q = [i]
                visited[i] = True
                c_idx = len(components)
                while q:
                    curr = q.pop(0)
                    comp_nodes.append(curr)
                    comp_id[curr] = c_idx
                    for nxt in adj1[curr]:
                        if not visited[nxt]:
                            visited[nxt] = True
                            q.append(nxt)
                components.append(comp_nodes)

        total_ones = sum(1 for st in self.state if st == 1)

        for comp in components:
            if all(len(adj1[n]) == 2 for n in comp):
                if total_ones == len(comp):
                    valid = True
                    for r in range(self.R):
                        for c in range(self.C):
                            cell = self.cell_edges[r][c]
                            if cell is None: continue
                            clue, edges = cell
                            on = sum(1 for ce in edges if self.state[ce] == 1)
                            if on != clue:
                                valid = False
                                break
                        if not valid: break
                    if valid:
                        for e in range(self.E):
                            if self.state[e] == -1:
                                self.state[e] = 0
                                changed = True
                        return changed, True
                return False, False

        for e, st in enumerate(self.state):
            if st == -1:
                u, v = self.edges[e]
                uidx = u[0] * (self.C + 1) + u[1]
                vidx = v[0] * (self.C + 1) + v[1]

                if comp_id[uidx] != -1 and comp_id[uidx] == comp_id[vidx]:
                    comp_nodes = components[comp_id[uidx]]
                    if total_ones != len(comp_nodes) - 1:
                        self.state[e] = 0
                        changed = True
                        continue

                    valid = True
                    for r in range(self.R):
                        for c in range(self.C):
                            cell = self.cell_edges[r][c]
                            if cell is None: continue
                            clue, edges = cell
                            on = 0
                            for ce in edges:
                                if ce == e or self.state[ce] == 1:
                                    on += 1
                            if on != clue:
                                valid = False
                                break
                        if not valid: break

                    if not valid:
                        self.state[e] = 0
                        changed = True

        return changed, None

    def propagate(self):
        changed = True
        while changed:
            changed = False

            for r in range(self.R):
                for c in range(self.C):
                    cell = self.cell_edges[r][c]
                    if cell is None: continue
                    clue, edges = cell
                    on = sum(1 for e in edges if self.state[e] == 1)
                    unk = sum(1 for e in edges if self.state[e] == -1)

                    if on > clue or on + unk < clue:
                        return False

                    if unk > 0:
                        if on == clue:
                            for e in edges:
                                if self.state[e] == -1:
                                    self.state[e] = 0
                                    changed = True
                        elif on + unk == clue:
                            for e in edges:
                                if self.state[e] == -1:
                                    self.state[e] = 1
                                    changed = True

            for i in range(len(self.adj)):
                edges = self.adj[i]
                on = sum(1 for e in edges if self.state[e] == 1)
                unk = sum(1 for e in edges if self.state[e] == -1)

                if on > 2:
                    return False

                if unk > 0:
                    if on == 2:
                        for e in edges:
                            if self.state[e] == -1:
                                self.state[e] = 0
                                changed = True
                    elif on == 1 and unk == 1:
                        for e in edges:
                            if self.state[e] == -1:
                                self.state[e] = 1
                                changed = True
                    elif on == 0 and unk == 1:
                        for e in edges:
                            if self.state[e] == -1:
                                self.state[e] = 0
                                changed = True
                elif unk == 0:
                    if on == 1:
                        return False

            sub_changed, is_sol = self.check_subloops()
            if is_sol is False:
                return False
            if sub_changed:
                changed = True

        return True

    def is_solved(self):
        if any(st == -1 for st in self.state):
            return False
        for r in range(self.R):
            for c in range(self.C):
                cell = self.cell_edges[r][c]
                if cell is None: continue
                clue, edges = cell
                on = sum(1 for e in edges if self.state[e] == 1)
                if on != clue:
                    return False
        for i in range(len(self.adj)):
            edges = self.adj[i]
            on = sum(1 for e in edges if self.state[e] == 1)
            if on != 0 and on != 2:
                return False

        adj1 = [[] for _ in range(len(self.adj))]
        for e, st in enumerate(self.state):
            if st == 1:
                u, v = self.edges[e]
                uidx = u[0] * (self.C + 1) + u[1]
                vidx = v[0] * (self.C + 1) + v[1]
                adj1[uidx].append(vidx)
                adj1[vidx].append(uidx)

        start_node = -1
        for i in range(len(self.adj)):
            if len(adj1[i]) > 0:
                start_node = i
                break
        if start_node == -1:
            return False

        visited = [False] * len(self.adj)
        q = [start_node]
        visited[start_node] = True
        comp_size = 0
        while q:
            curr = q.pop(0)
            comp_size += 1
            for nxt in adj1[curr]:
                if not visited[nxt]:
                    visited[nxt] = True
                    q.append(nxt)

        total_nodes_with_edges = sum(1 for i in range(len(self.adj)) if len(adj1[i]) > 0)
        if comp_size != total_nodes_with_edges:
            return False

        return True

    def backtrack(self):
        if not self.propagate():
            return False

        if self.is_solved():
            return True

        best_e = -1
        min_unk = 5

        for r in range(self.R):
            for c in range(self.C):
                cell = self.cell_edges[r][c]
                if cell is None: continue
                clue, edges = cell
                unk_edges = [e for e in edges if self.state[e] == -1]
                if 0 < len(unk_edges) < min_unk:
                    min_unk = len(unk_edges)
                    best_e = unk_edges[0]

        if best_e == -1:
            for e in range(self.E):
                if self.state[e] == -1:
                    best_e = e
                    break

        if best_e == -1:
            return False

        saved_state = list(self.state)

        self.state[best_e] = 1
        if self.backtrack():
            return True

        self.state = list(saved_state)
        self.state[best_e] = 0
        if self.backtrack():
            return True

        self.state = list(saved_state)
        return False

    def get_loop(self):
        adj1 = {}
        for e, st in enumerate(self.state):
            if st == 1:
                u, v = self.edges[e]
                adj1.setdefault(u, []).append(v)
                adj1.setdefault(v, []).append(u)

        if not adj1: return []

        start_node = next(iter(adj1.keys()))
        loop = [start_node]
        curr = start_node
        prev = None

        while True:
            nxts = adj1[curr]
            nxt = nxts[0] if nxts[0] != prev else (nxts[1] if len(nxts) > 1 else None)
            if not nxt: break
            loop.append(nxt)
            if nxt == start_node:
                break
            prev = curr
            curr = nxt

        return loop

def solve(observation):
    clues = observation['data']
    solver = SlitherlinkSolver(clues)
    solver.apply_patterns()
    if solver.backtrack():
        return solver.get_loop()
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
