def solve(observation):
    regions = observation['data']
    R = len(regions)
    C = len(regions[0])

    # grid: -1 for unknown, 0 for unshaded, 1 for shaded
    grid = [[-1]*C for _ in range(R)]

    num_regions = max(max(row) for row in regions) + 1
    region_counts = [0] * num_regions
    region_unknowns = [0] * num_regions
    for r in range(R):
        for c in range(C):
            region_unknowns[regions[r][c]] += 1

    def is_valid():
        """
        Checks partial grid for violations of domino rules:
        - No shaded cell can have more than 1 shaded orthogonal neighbor.
        - No shaded cell can be isolated (0 shaded neighbors AND 0 unknown neighbors).
        """
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 1:
                    sn = 0
                    un = 0
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if grid[nr][nc] == 1:
                                sn += 1
                            elif grid[nr][nc] == -1:
                                un += 1
                    if sn > 1:
                        return False
                    if sn == 0 and un == 0:
                        return False
        return True

    ans = None

    def backtrack(idx):
        nonlocal ans
        if idx == R * C:
            # Final verification
            for count in region_counts:
                if count != 2:
                    return False
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        sn = sum(1 for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)] 
                                 if 0 <= r + dr < R and 0 <= c + dc < C and grid[r + dr][c + dc] == 1)
                        if sn != 1:
                            return False

            ans = [[('S' if grid[r][c] == 1 else None) for c in range(C)] for r in range(R)]
            return True

        r, c = idx // C, idx % C
        reg = regions[r][c]

        # Branch 1: Try leaving the cell unshaded (0)
        grid[r][c] = 0
        region_unknowns[reg] -= 1
        # Prune if we can no longer reach exactly 2 shaded cells in this region
        if region_counts[reg] + region_unknowns[reg] >= 2:
            if is_valid():
                if backtrack(idx + 1):
                    return True
        region_unknowns[reg] += 1

        # Branch 2: Try shading the cell (1)
        # Prune if the region already has 2 shaded cells
        if region_counts[reg] < 2:
            grid[r][c] = 1
            region_counts[reg] += 1
            region_unknowns[reg] -= 1
            if is_valid():
                if backtrack(idx + 1):
                    return True
            region_counts[reg] -= 1
            region_unknowns[reg] += 1

        # Backtrack
        grid[r][c] = -1
        return False

    if backtrack(0):
        return ans
    return "No Solution"

