def solve(observation):
    grid_size = len(observation['tree'])
    trees = []
    for r in range(grid_size):
        for c in range(grid_size):
            if observation['tree'][r][c] == 'T':
                trees.append((r, c))

    row_counts = list(observation['row_tent_counts'])
    col_counts = list(observation['col_tent_counts'])

    # Initialize domains for each tree
    # A domain is a list of valid (row, col) coordinates for the tree's tent
    domains = []
    for tr, tc in trees:
        domain = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = tr + dr, tc + dc
            if 0 <= nr < grid_size and 0 <= nc < grid_size:
                if observation['tree'][nr][nc] != 'T':
                    if row_counts[nr] > 0 and col_counts[nc] > 0:
                        domain.append((nr, nc))
        domains.append(domain)

    def propagate(current_tents, current_domains, row_rem, col_rem, trees):
        """
        Applies human-like deductive rules to aggressively prune the search space.
        Returns (success, new_tents, new_domains, new_row_rem, new_col_rem).
        """
        tents = list(current_tents)
        doms = [list(d) for d in current_domains]
        r_rem = list(row_rem)
        c_rem = list(col_rem)

        changed = True
        while changed:
            changed = False

            # Rule 1: Contradiction check - if an unassigned tree has no valid options, fail.
            for i in range(len(trees)):
                if tents[i] is None and len(doms[i]) == 0:
                    return False, None, None, None, None

            # Rule 2: Forced assignment - if a tree has exactly 1 option, it must be placed there.
            for i in range(len(trees)):
                if tents[i] is None and len(doms[i]) == 1:
                    r, c = doms[i][0]
                    tents[i] = (r, c)
                    r_rem[r] -= 1
                    c_rem[c] -= 1

                    # Check if row/col counts are violated
                    if r_rem[r] < 0 or c_rem[c] < 0:
                        return False, None, None, None, None
                    changed = True

                    # Propagate constraints to other trees' domains
                    for j in range(len(trees)):
                        if tents[j] is None:
                            new_dom = []
                            for dr, dc in doms[j]:
                                # Cannot share the same cell
                                if dr == r and dc == c:
                                    continue
                                # Tents cannot touch each other (orthogonally or diagonally)
                                if abs(dr - r) <= 1 and abs(dc - c) <= 1:
                                    continue
                                new_dom.append((dr, dc))
                            doms[j] = new_dom

            # Rule 3: Row/Col capacity - remove cells from domains if their row/col is full.
            for i in range(len(trees)):
                if tents[i] is None:
                    new_dom = []
                    for r, c in doms[i]:
                        if r_rem[r] > 0 and c_rem[c] > 0:
                            new_dom.append((r, c))
                    if len(new_dom) < len(doms[i]):
                        doms[i] = new_dom
                        changed = True

        return True, tents, doms, r_rem, c_rem

    def backtrack(tents, doms, r_rem, c_rem):
        """
        Recursive backtracking search with Minimum Remaining Values (MRV) heuristic.
        """
        # Find the unassigned tree with the smallest domain (MRV)
        best_i = -1
        min_len = float('inf')
        for i in range(len(trees)):
            if tents[i] is None:
                if len(doms[i]) < min_len:
                    min_len = len(doms[i])
                    best_i = i

        # Base case: all trees have been assigned a tent
        if best_i == -1:
            # Verify that all row and column counts are exactly satisfied
            if all(x == 0 for x in r_rem) and all(x == 0 for x in c_rem):
                return tents
            return None

        # Try assigning each valid cell in the chosen tree's domain
        for r, c in doms[best_i]:
            next_tents = list(tents)
            next_tents[best_i] = (r, c)
            next_doms = [list(d) for d in doms]
            next_r_rem = list(r_rem)
            next_c_rem = list(c_rem)

            next_r_rem[r] -= 1
            next_c_rem[c] -= 1

            # Prune if assignment violates row/col counts
            if next_r_rem[r] < 0 or next_c_rem[c] < 0:
                continue

            # Apply immediate constraints (no sharing, no touching)
            valid = True
            for j in range(len(trees)):
                if next_tents[j] is None:
                    new_dom = []
                    for dr, dc in next_doms[j]:
                        if dr == r and dc == c:
                            continue
                        if abs(dr - r) <= 1 and abs(dc - c) <= 1:
                            continue
                        new_dom.append((dr, dc))
                    next_doms[j] = new_dom
                    # Early failure if a domain becomes empty
                    if len(new_dom) == 0:
                        valid = False
                        break

            if not valid:
                continue

            # Apply aggressive constraint propagation
            success, p_tents, p_doms, p_r_rem, p_c_rem = propagate(next_tents, next_doms, next_r_rem, next_c_rem, trees)
            if success:
                # Recurse
                result = backtrack(p_tents, p_doms, p_r_rem, p_c_rem)
                if result:
                    return result

        return None

    # Initial propagation before starting search
    initial_tents = [None] * len(trees)
    success, p_tents, p_doms, p_r_rem, p_c_rem = propagate(initial_tents, domains, row_counts, col_counts, trees)

    if not success:
        return "No Solution"

    # Start backtracking search
    solution_tents = backtrack(p_tents, p_doms, p_r_rem, p_c_rem)

    if not solution_tents:
        return "No Solution"

    # Format the final answer grid
    ans = []
    for r in range(grid_size):
        row = []
        for c in range(grid_size):
            if (r, c) in solution_tents:
                row.append('t')
            else:
                row.append(None)
        ans.append(row)

    return ans

