class MasyuSolver:
    def __init__(self, observation):
        self.grid = observation['data']
        self.N = len(self.grid)
        # Edges: 0 for empty, 1 for line, -1 for unknown
        # H[r][c] is edge between (r,c) and (r,c+1)
        self.H = [[-1] * (self.N - 1) for _ in range(self.N)]
        # V[r][c] is edge between (r,c) and (r+1,c)
        self.V = [[-1] * self.N for _ in range(self.N - 1)]
        self.total_clues = sum(1 for r in range(self.N) for c in range(self.N) if self.grid[r][c] in ('W', 'B'))
        self.is_valid = True
        self.has_changed = False

    def get_edge(self, type, r, c):
        if type == 'H':
            if 0 <= r < self.N and 0 <= c < self.N - 1:
                return self.H[r][c]
            return 0
        else:
            if 0 <= r < self.N - 1 and 0 <= c < self.N:
                return self.V[r][c]
            return 0

    def set_edge(self, type, r, c, val):
        if type == 'H':
            if 0 <= r < self.N and 0 <= c < self.N - 1:
                if self.H[r][c] == -1:
                    self.H[r][c] = val
                    return True, True
                return self.H[r][c] == val, False
            return val == 0, False
        else:
            if 0 <= r < self.N - 1 and 0 <= c < self.N:
                if self.V[r][c] == -1:
                    self.V[r][c] = val
                    return True, True
                return self.V[r][c] == val, False
            return val == 0, False

    def try_set(self, type, r, c, val):
        success, changed = self.set_edge(type, r, c, val)
        if not success:
            self.is_valid = False
        elif changed:
            self.has_changed = True

    def propagate(self):
        self.is_valid = True
        self.has_changed = True
        while self.has_changed and self.is_valid:
            self.has_changed = False

            for r in range(self.N):
                for c in range(self.N):
                    edges = [
                        ('V', r-1, c),
                        ('V', r, c),
                        ('H', r, c-1),
                        ('H', r, c)
                    ]
                    vals = [self.get_edge(*e) for e in edges]
                    ones = vals.count(1)
                    minus_ones = vals.count(-1)

                    clue = self.grid[r][c]

                    # Node degree constraints
                    if clue in ('W', 'B'):
                        if ones + minus_ones < 2: self.is_valid = False; break
                        if ones > 2: self.is_valid = False; break
                        if ones == 2 and minus_ones > 0:
                            for i in range(4):
                                if vals[i] == -1: self.try_set(*edges[i], 0)
                        if ones + minus_ones == 2 and minus_ones > 0:
                            for i in range(4):
                                if vals[i] == -1: self.try_set(*edges[i], 1)
                    else:
                        if ones > 2: self.is_valid = False; break
                        if ones == 2 and minus_ones > 0:
                            for i in range(4):
                                if vals[i] == -1: self.try_set(*edges[i], 0)
                        if ones == 1 and minus_ones == 0: self.is_valid = False; break
                        if ones == 1 and minus_ones == 1:
                            for i in range(4):
                                if vals[i] == -1: self.try_set(*edges[i], 1)
                        if ones == 0 and minus_ones == 1:
                            for i in range(4):
                                if vals[i] == -1: self.try_set(*edges[i], 0)

                    if not self.is_valid: break

                    # Clue specific constraints
                    if clue == 'B':
                        if self.get_edge('H', r, c-1) == 1:
                            self.try_set('H', r, c, 0)
                            self.try_set('H', r, c-2, 1)
                        if self.get_edge('H', r, c) == 1:
                            self.try_set('H', r, c-1, 0)
                            self.try_set('H', r, c+1, 1)
                        if self.get_edge('V', r-1, c) == 1:
                            self.try_set('V', r, c, 0)
                            self.try_set('V', r-2, c, 1)
                        if self.get_edge('V', r, c) == 1:
                            self.try_set('V', r-1, c, 0)
                            self.try_set('V', r+1, c, 1)

                        if self.get_edge('H', r, c-2) == 0: self.try_set('H', r, c-1, 0)
                        if self.get_edge('H', r, c+1) == 0: self.try_set('H', r, c, 0)
                        if self.get_edge('V', r-2, c) == 0: self.try_set('V', r-1, c, 0)
                        if self.get_edge('V', r+1, c) == 0: self.try_set('V', r, c, 0)

                    if clue == 'W':
                        if self.get_edge('H', r, c-1) == 1 or self.get_edge('H', r, c) == 1:
                            self.try_set('V', r-1, c, 0)
                            self.try_set('V', r, c, 0)
                            self.try_set('H', r, c-1, 1)
                            self.try_set('H', r, c, 1)
                        if self.get_edge('V', r-1, c) == 1 or self.get_edge('V', r, c) == 1:
                            self.try_set('H', r, c-1, 0)
                            self.try_set('H', r, c, 0)
                            self.try_set('V', r-1, c, 1)
                            self.try_set('V', r, c, 1)

                        if self.get_edge('H', r, c) == 1:
                            if self.get_edge('H', r, c-2) == 1: self.try_set('H', r, c+1, 0)
                            if self.get_edge('H', r, c+1) == 1: self.try_set('H', r, c-2, 0)
                        if self.get_edge('V', r, c) == 1:
                            if self.get_edge('V', r-2, c) == 1: self.try_set('V', r+1, c, 0)
                            if self.get_edge('V', r+1, c) == 1: self.try_set('V', r-2, c, 0)

                        can_V = self.get_edge('V', r-1, c) != 0 and self.get_edge('V', r, c) != 0
                        can_H = self.get_edge('H', r, c-1) != 0 and self.get_edge('H', r, c) != 0
                        if not can_V and not can_H: self.is_valid = False; break
                        if not can_V:
                            self.try_set('H', r, c-1, 1)
                            self.try_set('H', r, c, 1)
                        if not can_H:
                            self.try_set('V', r-1, c, 1)
                            self.try_set('V', r, c, 1)

                if not self.is_valid: break

            if self.is_valid:
                self.check_cycles()

        return self.is_valid

    def check_cycles(self):
        adj = { (r, c): [] for r in range(self.N) for c in range(self.N) }
        for r in range(self.N):
            for c in range(self.N - 1):
                if self.H[r][c] == 1:
                    adj[(r, c)].append((r, c+1))
                    adj[(r, c+1)].append((r, c))
        for r in range(self.N - 1):
            for c in range(self.N):
                if self.V[r][c] == 1:
                    adj[(r, c)].append((r+1, c))
                    adj[(r+1, c)].append((r, c))

        visited = set()
        components = []
        for node in adj:
            if node not in visited and len(adj[node]) > 0:
                comp = []
                q = [node]
                visited.add(node)
                while q:
                    curr = q.pop(0)
                    comp.append(curr)
                    for neighbor in adj[curr]:
                        if neighbor not in visited:
                            visited.add(neighbor)
                            q.append(neighbor)
                components.append(comp)

        total_active_nodes = sum(1 for r in range(self.N) for c in range(self.N) if len(adj[(r, c)]) > 0)

        for comp in components:
            edges_in_comp = sum(len(adj[n]) for n in comp) // 2
            is_cycle = (edges_in_comp == len(comp))
            clues_in_comp = sum(1 for r, c in comp if self.grid[r][c] in ('W', 'B'))

            if is_cycle:
                if clues_in_comp < self.total_clues or len(comp) < total_active_nodes:
                    self.is_valid = False
                    return
                # Valid full cycle found, force all other edges to 0
                for r in range(self.N):
                    for c in range(self.N - 1):
                        if self.H[r][c] == -1: self.try_set('H', r, c, 0)
                for r in range(self.N - 1):
                    for c in range(self.N):
                        if self.V[r][c] == -1: self.try_set('V', r, c, 0)
            else:
                endpoints = [n for n in comp if len(adj[n]) == 1]
                if len(endpoints) == 2 and edges_in_comp >= 3:
                    u, v = endpoints
                    if clues_in_comp < self.total_clues or len(comp) < total_active_nodes:
                        r1, c1 = u
                        r2, c2 = v
                        if r1 == r2 and abs(c1 - c2) == 1:
                            self.try_set('H', r1, min(c1, c2), 0)
                        elif c1 == c2 and abs(r1 - r2) == 1:
                            self.try_set('V', min(r1, r2), c1, 0)

    def is_solved(self):
        adj = { (r, c): [] for r in range(self.N) for c in range(self.N) }
        for r in range(self.N):
            for c in range(self.N - 1):
                if self.H[r][c] == 1:
                    adj[(r, c)].append((r, c+1))
                    adj[(r, c+1)].append((r, c))
        for r in range(self.N - 1):
            for c in range(self.N):
                if self.V[r][c] == 1:
                    adj[(r, c)].append((r+1, c))
                    adj[(r+1, c)].append((r, c))

        for r in range(self.N):
            for c in range(self.N):
                if len(adj[(r, c)]) not in (0, 2): return False
                if self.grid[r][c] in ('W', 'B') and len(adj[(r, c)]) != 2: return False

        start_node = None
        for r in range(self.N):
            for c in range(self.N):
                if len(adj[(r, c)]) > 0:
                    start_node = (r, c)
                    break
            if start_node: break

        if not start_node: return False

        visited = set()
        q = [start_node]
        visited.add(start_node)
        while q:
            curr = q.pop(0)
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)

        for r in range(self.N):
            for c in range(self.N):
                if len(adj[(r, c)]) > 0 and (r, c) not in visited: return False

        return True

    def solve(self):
        if not self.propagate():
            return False

        if self.is_solved():
            return True

        best_edge = None
        for r in range(self.N):
            for c in range(self.N):
                edges = [('V', r-1, c), ('V', r, c), ('H', r, c-1), ('H', r, c)]
                vals = [self.get_edge(*e) for e in edges]
                if vals.count(1) == 1 and vals.count(-1) > 0:
                    for i in range(4):
                        if vals[i] == -1:
                            best_edge = edges[i]
                            break
                if best_edge: break
            if best_edge: break

        if not best_edge:
            for r in range(self.N):
                for c in range(self.N - 1):
                    if self.H[r][c] == -1:
                        best_edge = ('H', r, c)
                        break
                if best_edge: break
            if not best_edge:
                for r in range(self.N - 1):
                    for c in range(self.N):
                        if self.V[r][c] == -1:
                            best_edge = ('V', r, c)
                            break
                    if best_edge: break

        if not best_edge:
            return False

        saved_H = [row[:] for row in self.H]
        saved_V = [row[:] for row in self.V]

        self.try_set(*best_edge, 1)
        if self.solve():
            return True

        self.H = [row[:] for row in saved_H]
        self.V = [row[:] for row in saved_V]
        self.is_valid = True
        self.try_set(*best_edge, 0)
        if self.solve():
            return True

        self.H = saved_H
        self.V = saved_V
        return False

    def get_path(self):
        adj = { (r, c): [] for r in range(self.N) for c in range(self.N) }
        for r in range(self.N):
            for c in range(self.N - 1):
                if self.H[r][c] == 1:
                    adj[(r, c)].append((r, c+1))
                    adj[(r, c+1)].append((r, c))
        for r in range(self.N - 1):
            for c in range(self.N):
                if self.V[r][c] == 1:
                    adj[(r, c)].append((r+1, c))
                    adj[(r+1, c)].append((r, c))

        start_node = None
        for r in range(self.N):
            for c in range(self.N):
                if len(adj[(r, c)]) > 0:
                    start_node = (r, c)
                    break
            if start_node: break

        path = [start_node]
        curr = start_node
        prev = None

        while True:
            neighbors = adj[curr]
            next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
            path.append(next_node)
            prev = curr
            curr = next_node
            if curr == start_node:
                break

        return path

def solve(observation):
    solver = MasyuSolver(observation)
    if solver.solve():
        return str(solver.get_path())
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
