            regions[reg].append((r, c))

    # Find adjacencies between regions
    adjacencies = {reg: set() for reg in regions}
    for r in range(R):
        for c in range(C):
            reg1 = grid[r][c]
            if r + 1 < R:
                reg2 = grid[r+1][c]
                if reg1 != reg2:
                    adjacencies[reg1].add(reg2)
                    adjacencies[reg2].add(reg1)
            if c + 1 < C:
                reg2 = grid[r][c+1]
                if reg1 != reg2:
                    adjacencies[reg1].add(reg2)
                    adjacencies[reg2].add(reg1)

    # Helper to identify tetromino shape
    def get_shape(cells):
        r_counts = {}
        c_counts = {}
        for r, c in cells:
            r_counts[r] = r_counts.get(r, 0) + 1
            c_counts[c] = c_counts.get(c, 0) + 1

        if 4 in r_counts.values() or 4 in c_counts.values():
            return 'I'

        if len(r_counts) == 2 and len(c_counts) == 2:
            if sorted(list(r_counts.values())) == [2, 2] and sorted(list(c_counts.values())) == [2, 2]:
                return 'O'

        has_3 = False
        for count in r_counts.values():
            if count == 3: has_3 = True
        for count in c_counts.values():
            if count == 3: has_3 = True

        if has_3:
            degrees = {cell: 0 for cell in cells}
            for r1, c1 in cells:
                for r2, c2 in cells:
                    if abs(r1-r2) + abs(c1-c2) == 1:
                        degrees[(r1, c1)] += 1
            if 3 in degrees.values():
                return 'T'
            else:
                return 'L'
        else:
            return 'S'

    # Precompute all valid tetromino placements for each region
    placements = {reg: [] for reg in regions}
    for reg, cells in regions.items():
        subgraphs = set()
        cells_set = set(cells)

        def dfs(current_path):
            if len(current_path) == 4:
                subgraphs.add(frozenset(current_path))
                return
            neighbors = set()
            for r, c in current_path:
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in cells_set and (nr, nc) not in current_path:
                        neighbors.add((nr, nc))
            for n in neighbors:
                dfs(current_path + [n])

        for cell in cells:
            dfs([cell])

        for sg in subgraphs:
            shape = get_shape(sg)
            if shape != 'O': # O is forbidden by 2x2 rule
                placements[reg].append((shape, sg))

    # Sort regions by number of possible placements to fail fast
    ordered_regions = sorted(regions.keys(), key=lambda r: len(placements[r]))

    # Check constraints for a new placement
    def is_valid(assignment, new_reg, new_cells):
        new_shape = assignment[new_reg][0]
        # Adjacency rule: no two adjacent regions can have the same shape
        for adj_reg in adjacencies[new_reg]:
            if adj_reg in assignment:
                if assignment[adj_reg][0] == new_shape:
                    return False

        # 2x2 rule: no 2x2 area can be fully shaded
        shaded = set()
        for reg, (shape, cells) in assignment.items():
            shaded.update(cells)

        for r, c in new_cells:
            for dr, dc in [(0,0), (-1,0), (0,-1), (-1,-1)]:
                r0, c0 = r + dr, c + dc
                if (r0, c0) in shaded and (r0+1, c0) in shaded and \
                   (r0, c0+1) in shaded and (r0+1, c0+1) in shaded:
                    return False
        return True

    # Check if the current shaded cells can potentially form a single connected component
    def check_partial_connectivity(assignment):
        if not assignment: return True
        shaded = set()
        for reg, (shape, cells) in assignment.items():
            shaded.update(cells)

        components = []
        unvisited = set(shaded)
        while unvisited:
            start = unvisited.pop()
            comp = {start}
            queue = [start]
            while queue:
                r, c = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in unvisited:
                        unvisited.remove((nr, nc))
                        comp.add((nr, nc))
                        queue.append((nr, nc))
            components.append(comp)

        if len(components) <= 1:
            return True

        unassigned_regions = set(regions.keys()) - set(assignment.keys())
        unassigned_cells = set()
        for reg in unassigned_regions:
            unassigned_cells.update(regions[reg])

        for comp in components:
            can_connect = False
            for r, c in comp:
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in unassigned_cells:
                        can_connect = True
                        break
                if can_connect: break
            if not can_connect:
                return False
        return True

    best_solution = None

    # Backtracking search
    def backtrack(idx, assignment):
        nonlocal best_solution
        if idx == len(ordered_regions):
            if check_partial_connectivity(assignment):
                best_solution = assignment
                return True
            return False

        reg = ordered_regions[idx]
        for shape, cells in placements[reg]:
            assignment[reg] = (shape, cells)
            if is_valid(assignment, reg, cells):
                if check_partial_connectivity(assignment):
                    if backtrack(idx + 1, assignment):
                        return True
            del assignment[reg]
        return False

    backtrack(0, {})

    if best_solution:
        ans = [[None for _ in range(C)] for _ in range(R)]
        for reg, (shape, cells) in best_solution.items():
            for r, c in cells:
                ans[r][c] = shape
        return ans
    return "No Solution"

