OBSERVATION = {'data': [[0, 0, 0, 0, 0, 0, 1, 1], [0, 2, 2, 2, 2, 4, 1, 1], [0, 3, 3, 3, 4, 4, 1, 1], [0, 3, 3, 3, 4, 4, 1, 1], [0, 3, 3, 3, 4, 4, 5, 5], [8, 7, 7, 7, 6, 6, 5, 5], [8, 8, 8, 7, 6, 6, 5, 5], [8, 8, 8, 8, 6, 6, 5, 5]]}

def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    # Group cells by region ID
    region_cells = {}
    for r in range(R):
        for c in range(C):
            reg = grid[r][c]
            if reg not in region_cells:
                region_cells[reg] = []
            region_cells[reg].append((r, c))

    # Build region adjacency graph
    adj = {reg: set() for reg in region_cells}
    for r in range(R):
        for c in range(C):
            reg = grid[r][c]
            if r > 0 and grid[r-1][c] != reg:
                adj[reg].add(grid[r-1][c])
                adj[grid[r-1][c]].add(reg)
            if c > 0 and grid[r][c-1] != reg:
                adj[reg].add(grid[r][c-1])
                adj[grid[r][c-1]].add(reg)

    def normalize(cells):
        min_r = min(r for r, c in cells)
        min_c = min(c for r, c in cells)
        return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    def generate_shapes():
        # Base shapes for L, I, T, S (O is forbidden by 2x2 rule)
        base_shapes = {
            'I': [[(0,0), (0,1), (0,2), (0,3)]],
            'T': [[(0,0), (0,1), (0,2), (1,1)]],
            'S': [[(0,1), (0,2), (1,0), (1,1)]],
            'L': [[(0,0), (0,1), (0,2), (1,0)]]
        }
        shapes = {}
        for name, bases in base_shapes.items():
            shapes[name] = set()
            for base in bases:
                # Generate all rotations and reflections
                for flip in [False, True]:
                    for rot in range(4):
                        current = base
                        if flip:
                            current = [(r, -c) for r, c in current]
                        for _ in range(rot):
                            current = [(c, -r) for r, c in current]
                        shapes[name].add(normalize(current))
        return shapes

    SHAPES = generate_shapes()

    # Precompute all valid tetromino placements for each region
    valid_placements = {}
    for reg, cells in region_cells.items():
        valid_placements[reg] = []
        cells_set = set(cells)
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                for name, norms in SHAPES.items():
                    for norm in norms:
                        placement = tuple(sorted((r + dr, c + dc) for dr, dc in norm))
                        if all(p in cells_set for p in placement):
                            valid_placements[reg].append((name, placement))
        # Remove duplicates
        valid_placements[reg] = list(set(valid_placements[reg]))

    # Sort regions by number of valid placements to fail fast (Most Constrained Variable)
    region_ids = sorted(valid_placements.keys(), key=lambda k: len(valid_placements[k]))

    # Precompute unassigned cells for connectivity pruning
    unassigned_cells_by_idx = []
    current_unassigned = set()
    for rid in reversed(region_ids):
        current_unassigned.update(region_cells[rid])
        unassigned_cells_by_idx.append(set(current_unassigned))
    unassigned_cells_by_idx.reverse()

    def has_2x2(shaded_cells):
        for r, c in shaded_cells:
            if ((r+1, c) in shaded_cells and 
                (r, c+1) in shaded_cells and 
                (r+1, c+1) in shaded_cells):
                return True
        return False

    def can_connect_all(shaded_cells, unassigned_cells, last_added_cells):
        if not shaded_cells: return True
        allowed = shaded_cells | unassigned_cells
        start = next(iter(last_added_cells)) if last_added_cells else next(iter(shaded_cells))
        q = [start]
        visited = {start}
        while q:
            r, c = q.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in allowed and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return shaded_cells.issubset(visited)

    def backtrack(idx, current_shaded, current_types):
        if idx == len(region_ids):
            # Final strict connectivity check
            start = next(iter(current_shaded))
            q = [start]
            visited = {start}
            while q:
                r, c = q.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in current_shaded and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if len(visited) == len(current_shaded):
                return current_shaded, current_types
            return None

        rid = region_ids[idx]
        unassigned_cells = unassigned_cells_by_idx[idx+1] if idx + 1 < len(region_ids) else set()

        for t, cells in valid_placements[rid]:
            # Check adjacency constraint: no two adjacent regions can have the same tetromino type
            conflict = False
            for neighbor in adj[rid]:
                if neighbor in current_types and current_types[neighbor] == t:
                    conflict = True
                    break
            if conflict: continue

            new_shaded = current_shaded | set(cells)

            # Prune if a 2x2 block is fully shaded
            if has_2x2(new_shaded): continue

            # Prune if the current shaded cells cannot possibly be connected by remaining regions
            if not can_connect_all(new_shaded, unassigned_cells, set(cells)): continue

            current_types[rid] = t
            res = backtrack(idx + 1, new_shaded, current_types)
            if res: return res
            del current_types[rid]

        return None

    res = backtrack(0, set(), {})
    if not res:
        return "No Solution"

    final_shaded, final_types = res

    # Format output
    ans = []
    for r in range(R):
        row = []
        for c in range(C):
            if (r, c) in final_shaded:
                reg = grid[r][c]
                row.append(final_types[reg])
            else:
                row.append(None)
        ans.append(row)

    return str(ans)

