                    edge_c = curr_c if dx == 1 else curr_c - 1
                    pat[('H', r, edge_c)] = True
                    if i > 0:
                        if r < N: pat[('V', r, curr_c)] = False
                        if r > 0: pat[('V', r-1, curr_c)] = False

                step_r = 1 if dy == 1 else -1
                for i in range(y):
                    curr_r = r + i * step_r
                    edge_r = curr_r if dy == 1 else curr_r - 1
                    pat[('V', edge_r, c)] = True
                    if i > 0:
                        if c < N: pat[('H', curr_r, c)] = False
                        if c > 0: pat[('H', curr_r, c-1)] = False

                if dx == 1 and c > 0: pat[('H', r, c-1)] = False
                if dx == -1 and c < N: pat[('H', r, c)] = False
                if dy == 1 and r > 0: pat[('V', r-1, c)] = False
                if dy == -1 and r < N: pat[('V', r, c)] = False

                if dx == 1 and end_c < N: pat[('H', r, end_c)] = False
                if dx == -1 and end_c > 0: pat[('H', r, end_c-1)] = False
                if dy == 1 and end_r < N: pat[('V', end_r, c)] = False
                if dy == -1 and end_r > 0: pat[('V', end_r-1, c)] = False

                patterns.append(pat)
        return patterns

    def get_white_patterns(r, c, k, N):
        patterns = []
        for x in range(1, k):
            y = k - x
            start_c = c - x
            end_c = c + y
            if 0 <= start_c and end_c <= N:
                pat = {}
                for i in range(start_c, end_c):
                    pat[('H', r, i)] = True
                if start_c > 0: pat[('H', r, start_c-1)] = False
                if end_c < N: pat[('H', r, end_c)] = False
                for i in range(start_c + 1, end_c):
                    if r < N: pat[('V', r, i)] = False
                    if r > 0: pat[('V', r-1, i)] = False
                patterns.append(pat)

        for x in range(1, k):
            y = k - x
            start_r = r - x
            end_r = r + y
            if 0 <= start_r and end_r <= N:
                pat = {}
                for i in range(start_r, end_r):
                    pat[('V', i, c)] = True
                if start_r > 0: pat[('V', start_r-1, c)] = False
                if end_r < N: pat[('V', end_r, c)] = False
                for i in range(start_r + 1, end_r):
                    if c < N: pat[('H', i, c)] = False
                    if c > 0: pat[('H', i, c-1)] = False
                patterns.append(pat)
        return patterns

    edges = {}
    for r in range(N + 1):
        for c in range(N):
            edges[('H', r, c)] = None
    for r in range(N):
        for c in range(N + 1):
            edges[('V', r, c)] = None

    clue_patterns = {}
    for (r, c), clue in clues.items():
        color = clue[0]
        k = int(clue[1:])
        if color == 'B':
            clue_patterns[(r, c)] = get_black_patterns(r, c, k, N)
        else:
            clue_patterns[(r, c)] = get_white_patterns(r, c, k, N)

    def backtrack(edge_state, clue_pats):
        changed = True
        while changed:
            changed = False

            for pos, pats in list(clue_pats.items()):
                valid_pats = []
                for pat in pats:
                    compatible = True
                    for e, val in pat.items():
                        if edge_state[e] is not None and edge_state[e] != val:
                            compatible = False
                            break
                    if compatible:
                        valid_pats.append(pat)

                if len(valid_pats) == 0:
                    return None

                if len(valid_pats) < len(pats):
                    clue_pats[pos] = valid_pats
                    changed = True

                if len(valid_pats) == 1:
                    for e, val in valid_pats[0].items():
                        if edge_state[e] is None:
                            edge_state[e] = val
                            changed = True

            for r in range(N + 1):
                for c in range(N + 1):
                    adj_edges = []
                    if c < N: adj_edges.append(('H', r, c))
                    if c > 0: adj_edges.append(('H', r, c-1))
                    if r < N: adj_edges.append(('V', r, c))
                    if r > 0: adj_edges.append(('V', r-1, c))

                    T = sum(1 for e in adj_edges if edge_state[e] == True)
                    U = sum(1 for e in adj_edges if edge_state[e] == None)

                    if T > 2: return None
                    if T == 2 and U > 0:
                        for e in adj_edges:
                            if edge_state[e] is None:
                                edge_state[e] = False
                                changed = True
                    if T == 1 and U == 0: return None
                    if T == 1 and U == 1:
                        for e in adj_edges:
                            if edge_state[e] is None:
                                edge_state[e] = True
                                changed = True
                    if T == 0 and U == 1:
                        for e in adj_edges:
                            if edge_state[e] is None:
                                edge_state[e] = False
                                changed = True

            adj = {}
            for e, val in edge_state.items():
                if val == True:
                    if e[0] == 'H':
                        u = (e[1], e[2])
                        v = (e[1], e[2] + 1)
                    else:
                        u = (e[1], e[2])
                        v = (e[1] + 1, e[2])
                    adj.setdefault(u, []).append(v)
                    adj.setdefault(v, []).append(u)

            visited = set()
            for node in adj:
                if node not in visited:
                    comp = set()
                    q = [node]
                    while q:
                        curr = q.pop(0)
                        if curr not in comp:
                            comp.add(curr)
                            for neighbor in adj[curr]:
                                if neighbor not in comp:
                                    q.append(neighbor)

                    is_cycle = True
                    for n in comp:
                        if len(adj[n]) != 2:
                            is_cycle = False
                            break

                    if is_cycle:
                        if len(comp) == len(adj) and all(c in comp for c in clues):
                            for e in edge_state:
                                if edge_state[e] is None:
                                    edge_state[e] = False
                            return edge_state
                        else:
                            return None

                    visited.update(comp)

        if all(v is not None for v in edge_state.values()):
            return edge_state

        min_pats = 999
        best_clue = None
        for pos, pats in clue_pats.items():
            if len(pats) > 1 and len(pats) < min_pats:
                min_pats = len(pats)
                best_clue = pos

        if best_clue is not None:
            for pat in clue_pats[best_clue]:
                new_edge_state = edge_state.copy()
                new_clue_pats = {k: v.copy() for k, v in clue_pats.items()}
                new_clue_pats[best_clue] = [pat]
                res = backtrack(new_edge_state, new_clue_pats)
                if res is not None:
                    return res
            return None

        best_edge = None
        for e, val in edge_state.items():
            if val is None:
                adj_true = False
                if e[0] == 'H':
                    r, c = e[1], e[2]
                    if c > 0 and edge_state[('H', r, c-1)] == True: adj_true = True
                    if r > 0 and edge_state[('V', r-1, c)] == True: adj_true = True
                    if r < N and edge_state[('V', r, c)] == True: adj_true = True
                    if c+1 < N and edge_state[('H', r, c+1)] == True: adj_true = True
                    if r > 0 and edge_state[('V', r-1, c+1)] == True: adj_true = True
                    if r < N and edge_state[('V', r, c+1)] == True: adj_true = True
                else:
                    r, c = e[1], e[2]
                    if r > 0 and edge_state[('V', r-1, c)] == True: adj_true = True
                    if c > 0 and edge_state[('H', r, c-1)] == True: adj_true = True
                    if c < N and edge_state[('H', r, c)] == True: adj_true = True
                    if r+1 < N and edge_state[('V', r+1, c)] == True: adj_true = True
                    if c > 0 and edge_state[('H', r+1, c-1)] == True: adj_true = True
                    if c < N and edge_state[('H', r+1, c)] == True: adj_true = True

                if adj_true:
                    best_edge = e
                    break

        if best_edge is None:
            for e, val in edge_state.items():
                if val is None:
                    best_edge = e
                    break

        if best_edge is not None:
            for guess in [True, False]:
                new_edge_state = edge_state.copy()
                new_edge_state[best_edge] = guess
                new_clue_pats = {k: v.copy() for k, v in clue_pats.items()}
                res = backtrack(new_edge_state, new_clue_pats)
                if res is not None:
                    return res
            return None

        return None

    res_state = backtrack(edges, clue_patterns)
    if res_state is None:
        return "No Solution"

    adj = {}
    for e, val in res_state.items():
        if val == True:
            if e[0] == 'H':
                u = (e[1], e[2])
                v = (e[1], e[2] + 1)
            else:
                u = (e[1], e[2])
                v = (e[1] + 1, e[2])
            adj.setdefault(u, []).append(v)
            adj.setdefault(v, []).append(u)

    if not adj:
        return []

    start_node = next(iter(adj.keys()))
    path = [start_node]
    curr = start_node
    prev = None

    while True:
        neighbors = adj[curr]
        next_nodes = [n for n in neighbors if n != prev]
        if not next_nodes:
            break
        next_node = next_nodes[0]
        path.append(next_node)
        if next_node == start_node:
            break
        prev = curr
        curr = next_node

    return path

