OBSERVATION = {'tree': [[None, 'T', None, None, None, None, None, 'T'], [None, None, None, None, 'T', None, None, None], ['T', None, None, None, None, None, None, None], [None, None, None, 'T', None, None, None, None], [None, None, None, None, None, None, None, 'T'], [None, None, 'T', None, None, None, 'T', None], [None, 'T', 'T', None, None, None, 'T', None], [None, None, None, None, 'T', None, None, None]], 'row_tent_counts': [2, 1, 1, 2, 0, 2, 2, 2], 'col_tent_counts': [2, 0, 3, 1, 1, 2, 1, 2]}

def solve(observation):
    R = len(observation['tree'])
    C = len(observation['tree'][0])
    trees = []
    for r in range(R):
        for c in range(C):
            if observation['tree'][r][c] == 'T':
                trees.append((r, c))

    row_counts = list(observation['row_tent_counts'])
    col_counts = list(observation['col_tent_counts'])

    # Basic validation: total trees must equal total required tents
    if len(trees) != sum(row_counts) or len(trees) != sum(col_counts):
        return "No Solution"

    # Grid representation: 0 = empty, 1 = tree, 2 = tent
    grid = [[0] * C for _ in range(R)]
    for tr, tc in trees:
        grid[tr][tc] = 1

    # Pre-calculate valid potential tent locations for each tree
    # This applies static constraints: grid bounds, empty cell, row/col counts > 0,
    # and the strict rule: "Each tent must be orthogonally adjacent to its paired tree."
    tree_neighbors = []
    for tr, tc in trees:
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = tr + dr, tc + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 0:
                if row_counts[nr] > 0 and col_counts[nc] > 0:
                    # Enforce strict rule: exactly one adjacent tree
                    adj_trees = 0
                    for ddr, ddc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nnr, nnc = nr + ddr, nc + ddc
                        if 0 <= nnr < R and 0 <= nnc < C and grid[nnr][nnc] == 1:
                            adj_trees += 1
                    if adj_trees == 1:
                        neighbors.append((nr, nc))
        tree_neighbors.append(neighbors)

    def can_place_tent(r, c, row_counts, col_counts, grid):
        # Check dynamic constraints
        if row_counts[r] == 0 or col_counts[c] == 0:
            return False
        if grid[r][c] != 0:
            return False

        # Tents cannot touch each other, even diagonally
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    if grid[nr][nc] == 2:
                        return False
        return True

    def solve_bt(unassigned_trees, row_counts, col_counts, grid):
        if not unassigned_trees:
            # All trees assigned, verify counts are exactly met
            if any(x != 0 for x in row_counts) or any(x != 0 for x in col_counts):
                return False
            return True

        # Minimum Remaining Values (MRV) heuristic:
        # Pick the tree with the fewest valid tent placement options.
        # This aggressively prunes the search space by forcing necessary moves early.
        best_tree = -1
        min_options = float('inf')
        best_options = []

        for i in unassigned_trees:
            options = []
            for r, c in tree_neighbors[i]:
                if can_place_tent(r, c, row_counts, col_counts, grid):
                    options.append((r, c))

            if len(options) < min_options:
                min_options = len(options)
                best_tree = i
                best_options = options

                if min_options == 0:
                    return False # Dead end, backtrack
                if min_options == 1:
                    break # Optimization: forced move found, stop searching for a better tree

        unassigned_trees.remove(best_tree)

        for r, c in best_options:
            # Place tent
            grid[r][c] = 2
            row_counts[r] -= 1
            col_counts[c] -= 1

            if solve_bt(unassigned_trees, row_counts, col_counts, grid):
                return True

            # Backtrack
            grid[r][c] = 0
            row_counts[r] += 1
            col_counts[c] += 1

        unassigned_trees.add(best_tree)
        return False

    unassigned = set(range(len(trees)))
    if solve_bt(unassigned, row_counts, col_counts, grid):
        # Format the output grid
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if grid[r][c] == 2:
                    row.append('t')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
