OBSERVATION = {'data': [[None, 'B6', None, None, None, None, None, None], [None, None, None, None, 'B5', None, None, 'B8'], [None, None, None, None, None, None, None, None], ['W5', None, None, 'B3', None, 'W3', 'W5', None], [None, None, None, None, 'B4', None, None, None], [None, None, None, None, None, None, None, None], [None, 'B6', None, None, None, None, None, None], [None, None, None, None, None, None, None, None]]}

def parse_observation(obs):
    data = obs['data']
    N = len(data) - 1
    clues = []
    for r in range(N + 1):
        for c in range(N + 1):
            val = data[r][c]
            if val is not None:
                clues.append((val[0], int(val[1:]), r, c))
    return clues, N

def get_configs(clue_type, k, r, c, N):
    configs = []
    if clue_type == 'W':
        # Horizontal: must go straight through (r, c), so c1 < c < c2
        for c1 in range(max(0, c - k + 1), min(c, N - k + 1)):
            c2 = c1 + k
            req = [f"H_{r}_{i}" for i in range(c1, c2)]
            forb = []
            if r > 0: forb.append(f"V_{r-1}_{c}")
            if r < N: forb.append(f"V_{r}_{c}")
            if c1 > 0: forb.append(f"H_{r}_{c1-1}")
            if c2 < N: forb.append(f"H_{r}_{c2}")
            configs.append((req, forb))

        # Vertical: must go straight through (r, c), so r1 < r < r2
        for r1 in range(max(0, r - k + 1), min(r, N - k + 1)):
            r2 = r1 + k
            req = [f"V_{i}_{c}" for i in range(r1, r2)]
            forb = []
            if c > 0: forb.append(f"H_{r}_{c-1}")
            if c < N: forb.append(f"H_{r}_{c}")
            if r1 > 0: forb.append(f"V_{r1-1}_{c}")
            if r2 < N: forb.append(f"V_{r2}_{c}")
            configs.append((req, forb))

    elif clue_type == 'B':
        # UR: Up length u, Right length right_len
        for u in range(1, k):
            right_len = k - u
            if r - u >= 0 and c + right_len <= N:
                req = [f"V_{i}_{c}" for i in range(r - u, r)] + [f"H_{r}_{i}" for i in range(c, c + right_len)]
                forb = []
                if r < N: forb.append(f"V_{r}_{c}")
                if c > 0: forb.append(f"H_{r}_{c-1}")
                if r - u > 0: forb.append(f"V_{r-u-1}_{c}")
                if c + right_len < N: forb.append(f"H_{r}_{c+right_len}")
                configs.append((req, forb))

        # UL: Up length u, Left length l
        for u in range(1, k):
            l = k - u
            if r - u >= 0 and c - l >= 0:
                req = [f"V_{i}_{c}" for i in range(r - u, r)] + [f"H_{r}_{i}" for i in range(c - l, c)]
                forb = []
                if r < N: forb.append(f"V_{r}_{c}")
                if c < N: forb.append(f"H_{r}_{c}")
                if r - u > 0: forb.append(f"V_{r-u-1}_{c}")
                if c - l > 0: forb.append(f"H_{r}_{c-l-1}")
                configs.append((req, forb))

        # DR: Down length d, Right length right_len
        for d in range(1, k):
            right_len = k - d
            if r + d <= N and c + right_len <= N:
                req = [f"V_{i}_{c}" for i in range(r, r + d)] + [f"H_{r}_{i}" for i in range(c, c + right_len)]
                forb = []
                if r > 0: forb.append(f"V_{r-1}_{c}")
                if c > 0: forb.append(f"H_{r}_{c-1}")
                if r + d < N: forb.append(f"V_{r+d}_{c}")
                if c + right_len < N: forb.append(f"H_{r}_{c+right_len}")
                configs.append((req, forb))

        # DL: Down length d, Left length l
        for d in range(1, k):
            l = k - d
            if r + d <= N and c - l >= 0:
                req = [f"V_{i}_{c}" for i in range(r, r + d)] + [f"H_{r}_{i}" for i in range(c - l, c)]
                forb = []
                if r > 0: forb.append(f"V_{r-1}_{c}")
                if c < N: forb.append(f"H_{r}_{c}")
                if r + d < N: forb.append(f"V_{r+d}_{c}")
                if c - l > 0: forb.append(f"H_{r}_{c-l-1}")
                configs.append((req, forb))

    return configs

class GridSolver:
    def __init__(self, N, req, forb):
        self.N = N
        self.edges = {}
        for r in range(N + 1):
            for c in range(N): self.edges[f"H_{r}_{c}"] = None
        for r in range(N):
            for c in range(N + 1): self.edges[f"V_{r}_{c}"] = None

        for e in req: self.edges[e] = 1
        for e in forb: self.edges[e] = 0

    def propagate(self):
        changed = True
        while changed:
            changed = False
            for r in range(self.N + 1):
                for c in range(self.N + 1):
                    incident = []
                    if c > 0: incident.append(f"H_{r}_{c-1}")
                    if c < self.N: incident.append(f"H_{r}_{c}")
                    if r > 0: incident.append(f"V_{r-1}_{c}")
                    if r < self.N: incident.append(f"V_{r}_{c}")

                    vals = [self.edges[e] for e in incident]
                    ones = vals.count(1)
                    zeros = vals.count(0)
                    nones = vals.count(None)

                    if ones > 2: return False
                    if ones == 1 and nones == 0: return False

                    if ones == 2 and nones > 0:
                        for e in incident:
                            if self.edges[e] is None:
                                self.edges[e] = 0
                                changed = True
                    elif ones == 1 and nones == 1 and zeros == len(incident) - 2:
                        for e in incident:
                            if self.edges[e] is None:
                                self.edges[e] = 1
                                changed = True
                    elif ones == 0 and nones == 1 and zeros == len(incident) - 1:
                        for e in incident:
                            if self.edges[e] is None:
                                self.edges[e] = 0
                                changed = True
        return True

    def is_single_loop(self):
        adj = {}
        for e, val in self.edges.items():
            if val == 1:
                parts = e.split('_')
                if parts[0] == 'H':
                    r, c = int(parts[1]), int(parts[2])
                    u, v = (r, c), (r, c+1)
                else:
                    r, c = int(parts[1]), int(parts[2])
                    u, v = (r, c), (r+1, c)
                adj.setdefault(u, []).append(v)
                adj.setdefault(v, []).append(u)

        if not adj: return False

        for node, neighbors in adj.items():
            if len(neighbors) != 2: return False

        start_node = next(iter(adj))
        visited = set()
        curr = start_node
        prev = None
        while True:
            visited.add(curr)
            neighbors = adj[curr]
            next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
            prev = curr
            curr = next_node
            if curr == start_node: break

        return len(visited) == len(adj)

    def get_path(self):
        adj = {}
        for e, val in self.edges.items():
            if val == 1:
                parts = e.split('_')
                if parts[0] == 'H':
                    r, c = int(parts[1]), int(parts[2])
                    u, v = (r, c), (r, c+1)
                else:
                    r, c = int(parts[1]), int(parts[2])
                    u, v = (r, c), (r+1, c)
                adj.setdefault(u, []).append(v)
                adj.setdefault(v, []).append(u)

        start_node = next(iter(adj))
        path = [start_node]
        curr = start_node
        prev = None
        while True:
            neighbors = adj[curr]
            next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
            path.append(next_node)
            prev = curr
            curr = next_node
            if curr == start_node: break

        return path

    def solve(self):
        if not self.propagate(): return None

        best_e = None
        for e, val in self.edges.items():
            if val is None:
                best_e = e
                break

        if best_e is None:
            if self.is_single_loop(): return self.get_path()
            return None

        backup = self.edges.copy()
        self.edges[best_e] = 1
        res = self.solve()
        if res: return res

        self.edges = backup
        self.edges[best_e] = 0
        return self.solve()

def solve(observation):
    clues, N = parse_observation(observation)
    all_configs = [get_configs(*clue, N) for clue in clues]

    sorted_indices = list(range(len(clues)))
    sorted_indices.sort(key=lambda i: len(all_configs[i]))

    def backtrack_clues(idx, current_req, current_forb):
        if idx == len(clues):
            solver = GridSolver(N, current_req, current_forb)
            res = solver.solve()
            if res: return res
            return None

        clue_idx = sorted_indices[idx]
        for req, forb in all_configs[clue_idx]:
            conflict = False
            for e in req:
                if e in current_forb: conflict = True; break
            if conflict: continue
            for e in forb:
                if e in current_req: conflict = True; break
            if conflict: continue

            new_req = current_req.union(req)
            new_forb = current_forb.union(forb)
            res = backtrack_clues(idx + 1, new_req, new_forb)
            if res: return res

        return None

    path = backtrack_clues(0, set(), set())
    if path:
        return str(path)
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
