    # 4. Global count check
    total_req = sum(islands.values())
    current_white = sum(1 for r in range(R) for c in range(C) if grid[r][c] == 2)
    current_unknown = sum(1 for r in range(R) for c in range(C) if grid[r][c] == 0)
    if current_white + current_unknown < total_req:
        return False

    # 5. Fully solved strict checks
    is_full = (current_unknown == 0)
    if is_full:
        for i, comp in enumerate(white_comps):
            if len(wcomp_to_nums[i]) != 1:
