def deduce(grid, islands, R, C):
    # Hypothetical deduction: try setting each unknown cell to black/white and check validity
    changed = True
    while changed:
        changed = False
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0:
                    grid[r][c] = 1
                    valid_if_black = is_valid(grid, islands, R, C)

                    grid[r][c] = 2
                    valid_if_white = is_valid(grid, islands, R, C)

                    grid[r][c] = 0 # Reset

                    if valid_if_black and not valid_if_white:
                        grid[r][c] = 1
                        changed = True
                    elif valid_if_white and not valid_if_black:
                        grid[r][c] = 2
                        changed = True
                    elif not valid_if_black and not valid_if_white:
                        return False # Contradiction found
    return True

def solve_recursive(grid, islands, R, C):
    work_grid = [row[:] for row in grid]

    if not deduce(work_grid, islands, R, C):
        return None

    is_full = True
    for r in range(R):
        for c in range(C):
            if work_grid[r][c] == 0:
                is_full = False
                break
        if not is_full:
            break

    if is_full:
        if is_valid(work_grid, islands, R, C):
            return work_grid
        else:
            return None

    # Find an unknown cell to branch on
    guess_r, guess_c = -1, -1
    for r in range(R):
        for c in range(C):
            if work_grid[r][c] == 0:
                guess_r, guess_c = r, c
                break
        if guess_r != -1:
            break

    # Branch: Try Black
    work_grid[guess_r][guess_c] = 1
    if is_valid(work_grid, islands, R, C):
        res = solve_recursive(work_grid, islands, R, C)
        if res: return res

    # Branch: Try White
    work_grid[guess_r][guess_c] = 2
    if is_valid(work_grid, islands, R, C):
        res = solve_recursive(work_grid, islands, R, C)
        if res: return res

    return None

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    grid = [[0 for _ in range(C)] for _ in range(R)]
    islands = {}

    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                islands[(r, c)] = data[r][c]
                grid[r][c] = 2 # Numbered cells are initially white

    if not is_valid(grid, islands, R, C):
        return "No Solution"

    res_grid = solve_recursive(grid, islands, R, C)

    if res_grid:
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if res_grid[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
