def solve(observation):
    data = observation['data']
    N = len(data)

    # Extract regions
    regions = {}
    for r in range(N):
        for c in range(N):
            reg = data[r][c]
            if reg not in regions:
                regions[reg] = []
            regions[reg].append((r, c))

    # State tracking for backtracking
    col_has_star = [False] * N
    region_has_star = {reg: False for reg in regions}
    stars = [] # List of (row, col) tuples

    def can_place(r, c):
        # Check column constraint
        if col_has_star[c]: 
            return False

        # Check region constraint
        reg = data[r][c]
        if region_has_star[reg]: 
            return False

        # Check adjacency constraint (no touching stars, including diagonally)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: 
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    if (nr, nc) in stars:
                        return False
        return True

    def backtrack(r):
        # If we have successfully placed a star in every row, we found a solution
        if r == N:
            return True

        # Try placing a star in each column of the current row
        for c in range(N):
            if can_place(r, c):
                # Place the star and update constraints
                stars.append((r, c))
                col_has_star[c] = True
                region_has_star[data[r][c]] = True

                # Recurse to the next row
                if backtrack(r + 1):
                    return True

                # Backtrack: remove the star and restore constraints
                stars.pop()
                col_has_star[c] = False
                region_has_star[data[r][c]] = False

        return False

    # Start backtracking from row 0
    if backtrack(0):
        # Format the output grid
        ans = [[None for _ in range(N)] for _ in range(N)]
        for r, c in stars:
            ans[r][c] = 'S'
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
