def solve(observation):
    grid_size = len(observation['tree'])
    trees = []
    for r in range(grid_size):
        for c in range(grid_size):
            if observation['tree'][r][c] == 'T':
                trees.append((r, c))

    row_clues = observation['row_tent_counts']
    col_clues = observation['col_tent_counts']

    def get_neighbors(r, c):
        return [(r+dr, c+dc) for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] 
                if 0 <= r+dr < grid_size and 0 <= c+dc < grid_size]

    def get_8_neighbors(r, c):
        return [(r+dr, c+dc) for dr in [-1, 0, 1] for dc in [-1, 0, 1]
                if (dr != 0 or dc != 0) and 0 <= r+dr < grid_size and 0 <= c+dc < grid_size]

    def propagate(grid, row_rem, col_rem, unassigned_trees):
        changed = True
        while changed:
            changed = False

            # Check row constraints and propagate 0s
            for r in range(grid_size):
                if row_rem[r] < 0: return False
                avail_count = sum(1 for c in range(grid_size) if grid[r][c] == '?')
                if row_rem[r] > avail_count: return False
                if row_rem[r] == 0 and avail_count > 0:
                    for c in range(grid_size):
                        if grid[r][c] == '?':
                            grid[r][c] = '.'
                            changed = True

            # Check col constraints and propagate 0s
            for c in range(grid_size):
                if col_rem[c] < 0: return False
                avail_count = sum(1 for r in range(grid_size) if grid[r][c] == '?')
                if col_rem[c] > avail_count: return False
                if col_rem[c] == 0 and avail_count > 0:
                    for r in range(grid_size):
                        if grid[r][c] == '?':
                            grid[r][c] = '.'
                            changed = True

            # Ensure all unassigned trees have at least one available spot
            for tr, tc in unassigned_trees:
                avail = [(nr, nc) for nr, nc in get_neighbors(tr, tc) if grid[nr][nc] == '?']
                if len(avail) == 0:
                    return False

        return True

    def backtrack(unassigned_trees, grid, row_rem, col_rem):
        if not unassigned_trees:
            # All trees paired, verify exact clue matches
            if any(r != 0 for r in row_rem) or any(c != 0 for c in col_rem):
                return False
            return grid

        # Minimum Remaining Values (MRV) heuristic: pick the most constrained tree
        best_tree = None
        min_avail = 999
        best_avail_list = []

        for tr, tc in unassigned_trees:
            avail = [(nr, nc) for nr, nc in get_neighbors(tr, tc) if grid[nr][nc] == '?']
            if len(avail) < min_avail:
                min_avail = len(avail)
                best_tree = (tr, tc)
                best_avail_list = avail

        if min_avail == 0:
            return False

        next_unassigned = [t for t in unassigned_trees if t != best_tree]

        for nr, nc in best_avail_list:
            if row_rem[nr] > 0 and col_rem[nc] > 0:
                new_grid = [row[:] for row in grid]
                new_row_rem = row_rem[:]
                new_col_rem = col_rem[:]

                # Place tent
                new_grid[nr][nc] = 't'
                new_row_rem[nr] -= 1
                new_col_rem[nc] -= 1

                # Tents cannot touch even diagonally
                for nnr, nnc in get_8_neighbors(nr, nc):
                    if new_grid[nnr][nnc] == '?':
                        new_grid[nnr][nnc] = '.'

                if propagate(new_grid, new_row_rem, new_col_rem, next_unassigned):
                    res = backtrack(next_unassigned, new_grid, new_row_rem, new_col_rem)
                    if res: return res

        return False

    # Initialize grid
    grid = [['?' for _ in range(grid_size)] for _ in range(grid_size)]
    for r, c in trees:
        grid[r][c] = 'T'

    row_rem = list(row_clues)
    col_rem = list(col_clues)

    # Initial propagation
    if propagate(grid, row_rem, col_rem, trees):
        ans_grid = backtrack(trees, grid, row_rem, col_rem)
        if ans_grid:
            # Format output
            final_grid = []
            for r in range(grid_size):
                row = []
                for c in range(grid_size):
                    if ans_grid[r][c] == 't':
                        row.append('t')
                    else:
                        row.append(None)
                final_grid.append(row)
            return final_grid

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
