import sys

# Increase recursion depth for deep backtracking if needed
sys.setrecursionlimit(2000)

class MasyuSolver:
    def __init__(self, observation):
        self.data = observation['data']
        self.R = len(self.data)
        self.C = len(self.data[0])
        self.clues = {}
        for r in range(self.R):
            for c in range(self.C):
                if self.data[r][c] in ('W', 'B'):
                    self.clues[(r, c)] = self.data[r][c]

        self.edges = []
        self.edge_idx = {}
        # Horizontal edges
        for r in range(self.R):
            for c in range(self.C - 1):
                u, v = (r, c), (r, c+1)
                self.edge_idx[(u, v)] = len(self.edges)
                self.edge_idx[(v, u)] = len(self.edges)
                self.edges.append((u, v))
        # Vertical edges
        for r in range(self.R - 1):
            for c in range(self.C):
                u, v = (r, c), (r+1, c)
                self.edge_idx[(u, v)] = len(self.edges)
                self.edge_idx[(v, u)] = len(self.edges)
                self.edges.append((u, v))

        self.num_edges = len(self.edges)
        self.adj = { (r, c): [] for r in range(self.R) for c in range(self.C) }
        for i, (u, v) in enumerate(self.edges):
            self.adj[u].append((v, i))
            self.adj[v].append((u, i))

    def get_edge(self, u, v):
        return self.edge_idx.get((u, v), None)

    def solve(self):
        # State: 0 = undecided, 1 = line, -1 = no line
        state = [0] * self.num_edges
        return self.backtrack(state)

    def backtrack(self, state):
        state = self.propagate(state)
        if state is None:
            return None

        if 0 not in state:
            if self.is_valid_solution(state):
                return state
            return None

        # Branching heuristic: pick an undecided edge incident to a dot with degree 1
        best_e = -1
        for r in range(self.R):
            for c in range(self.C):
                u = (r, c)
                inc_edges = [e for v, e in self.adj[u]]
                c1 = sum(1 for e in inc_edges if state[e] == 1)
                c0 = sum(1 for e in inc_edges if state[e] == 0)
                if c1 == 1 and c0 > 0:
                    for e in inc_edges:
                        if state[e] == 0:
                            best_e = e
                            break
                if best_e != -1: break
            if best_e != -1: break

        # Fallback: pick any undecided edge
        if best_e == -1:
            for e in range(self.num_edges):
                if state[e] == 0:
                    best_e = e
                    break

        if best_e == -1:
            return None

        # Try placing a line first (often leads to faster solutions in loop puzzles)
        for val in [1, -1]:
            new_state = list(state)
            new_state[best_e] = val
            res = self.backtrack(new_state)
            if res is not None:
                return res

        return None

    def propagate(self, state):
        changed = True
        while changed:
            changed = False

            # 1. Dot Degree Constraints
            for r in range(self.R):
                for c in range(self.C):
                    u = (r, c)
                    inc_edges = [e for v, e in self.adj[u]]
                    c1 = sum(1 for e in inc_edges if state[e] == 1)
                    c0 = sum(1 for e in inc_edges if state[e] == 0)

                    is_clue = u in self.clues

                    if c1 > 2: return None
                    if is_clue and c1 + c0 < 2: return None
                    if not is_clue and c1 == 1 and c0 == 0: return None

                    if c1 == 2 and c0 > 0:
                        for e in inc_edges:
                            if state[e] == 0:
                                state[e] = -1
                                changed = True
                    elif c1 + c0 == 2 and c0 > 0 and (is_clue or c1 == 1):
                        for e in inc_edges:
                            if state[e] == 0:
                                state[e] = 1
                                changed = True
                    elif not is_clue and c1 == 0 and c0 == 1:
                        for e in inc_edges:
                            if state[e] == 0:
                                state[e] = -1
                                changed = True

            # 2. Clue Constraints
            for u, clue in self.clues.items():
                r, c = u
                h_left = self.get_edge(u, (r, c-1))
                h_right = self.get_edge(u, (r, c+1))
                v_up = self.get_edge(u, (r-1, c))
                v_down = self.get_edge(u, (r+1, c))

                def get_s(e): return state[e] if e is not None else -1

                if clue == 'W':
                    h_left2 = self.get_edge((r, c-1), (r, c-2))
                    h_right2 = self.get_edge((r, c+1), (r, c+2))
                    v_up2 = self.get_edge((r-1, c), (r-2, c))
                    v_down2 = self.get_edge((r+1, c), (r+2, c))

                    pos_H = (get_s(h_left) != -1 and get_s(h_right) != -1 and 
                             get_s(v_up) != 1 and get_s(v_down) != 1)
                    if pos_H:
                        if get_s(h_left2) == 1 and get_s(h_right2) == 1:
                            pos_H = False

                    pos_V = (get_s(v_up) != -1 and get_s(v_down) != -1 and 
                             get_s(h_left) != 1 and get_s(h_right) != 1)
                    if pos_V:
                        if get_s(v_up2) == 1 and get_s(v_down2) == 1:
                            pos_V = False

                    if not pos_H and not pos_V: return None

                    if pos_H and not pos_V:
                        forces = [(h_left, 1), (h_right, 1), (v_up, -1), (v_down, -1)]
                        if get_s(h_left2) == 1: forces.append((h_right2, -1))
                        if get_s(h_right2) == 1: forces.append((h_left2, -1))
                        for e, val in forces:
                            if e is not None and state[e] == 0:
                                state[e] = val
                                changed = True

                    if pos_V and not pos_H:
                        forces = [(v_up, 1), (v_down, 1), (h_left, -1), (h_right, -1)]
                        if get_s(v_up2) == 1: forces.append((v_down2, -1))
                        if get_s(v_down2) == 1: forces.append((v_up2, -1))
                        for e, val in forces:
                            if e is not None and state[e] == 0:
                                state[e] = val
                                changed = True

                elif clue == 'B':
                    h_left2 = self.get_edge((r, c-1), (r, c-2))
                    h_right2 = self.get_edge((r, c+1), (r, c+2))
                    v_up2 = self.get_edge((r-1, c), (r-2, c))
                    v_down2 = self.get_edge((r+1, c), (r+2, c))

                    configs = []
                    if (get_s(v_up) != -1 and get_s(h_right) != -1 and 
                        get_s(v_down) != 1 and get_s(h_left) != 1 and
                        get_s(v_up2) != -1 and get_s(h_right2) != -1):
                        configs.append('UR')
                    if (get_s(h_right) != -1 and get_s(v_down) != -1 and 
                        get_s(h_left) != 1 and get_s(v_up) != 1 and
                        get_s(h_right2) != -1 and get_s(v_down2) != -1):
                        configs.append('RD')
                    if (get_s(v_down) != -1 and get_s(h_left) != -1 and 
                        get_s(v_up) != 1 and get_s(h_right) != 1 and
                        get_s(v_down2) != -1 and get_s(h_left2) != -1):
                        configs.append('DL')
                    if (get_s(h_left) != -1 and get_s(v_up) != -1 and 
                        get_s(h_right) != 1 and get_s(v_down) != 1 and
                        get_s(h_left2) != -1 and get_s(v_up2) != -1):
                        configs.append('LU')

                    if not configs: return None

                    def get_forces(cfg):
                        if cfg == 'UR': return {(v_up, 1), (h_right, 1), (v_down, -1), (h_left, -1), (v_up2, 1), (h_right2, 1)}
                        if cfg == 'RD': return {(h_right, 1), (v_down, 1), (h_left, -1), (v_up, -1), (h_right2, 1), (v_down2, 1)}
                        if cfg == 'DL': return {(v_down, 1), (h_left, 1), (v_up, -1), (h_right, -1), (v_down2, 1), (h_left2, 1)}
                        if cfg == 'LU': return {(h_left, 1), (v_up, 1), (h_right, -1), (v_down, -1), (h_left2, 1), (v_up2, 1)}

                    common_forces = get_forces(configs[0])
                    for cfg in configs[1:]:
                        common_forces &= get_forces(cfg)

                    for e, val in common_forces:
                        if e is not None and state[e] == 0:
                            state[e] = val
                            changed = True

            # 3. Cycle Prevention
            parent = {u: u for u in self.adj}
            def find(i):
                if parent[i] == i: return i
                parent[i] = find(parent[i])
                return parent[i]
            def union(i, j):
                root_i = find(i)
                root_j = find(j)
                if root_i != root_j:
                    parent[root_i] = root_j

            for e_idx, (u, v) in enumerate(self.edges):
                if state[e_idx] == 1:
                    union(u, v)

            for e_idx, (u, v) in enumerate(self.edges):
                if state[e_idx] == 0:
                    if find(u) == find(v):
                        comp_root = find(u)
                        comp_dots = [dot for dot in self.adj if find(dot) == comp_root]
                        all_clues_in = all(clue in comp_dots for clue in self.clues)
                        other_edges_1 = any(state[i] == 1 and find(self.edges[i][0]) != comp_root for i in range(self.num_edges))

                        # If closing the cycle misses clues or leaves other segments disconnected, it's invalid
                        if not all_clues_in or other_edges_1:
                            state[e_idx] = -1
                            changed = True

        return state

    def is_valid_solution(self, state):
        for r in range(self.R):
            for c in range(self.C):
                u = (r, c)
                inc_edges = [e for v, e in self.adj[u]]
                c1 = sum(1 for e in inc_edges if state[e] == 1)
                if c1 not in (0, 2): return False
                if u in self.clues and c1 != 2: return False

        parent = {u: u for u in self.adj}
        def find(i):
            if parent[i] == i: return i
            parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        first_u = None
        for e_idx, (u, v) in enumerate(self.edges):
            if state[e_idx] == 1:
                union(u, v)
                if first_u is None: first_u = u

        if first_u is None: return False

        root = find(first_u)
        for e_idx, (u, v) in enumerate(self.edges):
            if state[e_idx] == 1:
                if find(u) != root: return False

        for u, clue in self.clues.items():
            r, c = u
            h_left = self.get_edge(u, (r, c-1))
            h_right = self.get_edge(u, (r, c+1))
            v_up = self.get_edge(u, (r-1, c))
            v_down = self.get_edge(u, (r+1, c))
            def get_s(e): return state[e] if e is not None else -1

            if clue == 'W':
                is_H = get_s(h_left) == 1 and get_s(h_right) == 1
                is_V = get_s(v_up) == 1 and get_s(v_down) == 1
                if not is_H and not is_V: return False
                if is_H:
                    h_left2 = self.get_edge((r, c-1), (r, c-2))
                    h_right2 = self.get_edge((r, c+1), (r, c+2))
                    if get_s(h_left2) == 1 and get_s(h_right2) == 1: return False
                if is_V:
                    v_up2 = self.get_edge((r-1, c), (r-2, c))
                    v_down2 = self.get_edge((r+1, c), (r+2, c))
                    if get_s(v_up2) == 1 and get_s(v_down2) == 1: return False
            elif clue == 'B':
                is_H = get_s(h_left) == 1 or get_s(h_right) == 1
                is_V = get_s(v_up) == 1 or get_s(v_down) == 1
                if not (is_H and is_V): return False

                if get_s(v_up) == 1:
                    v_up2 = self.get_edge((r-1, c), (r-2, c))
                    if get_s(v_up2) != 1: return False
                if get_s(v_down) == 1:
                    v_down2 = self.get_edge((r+1, c), (r+2, c))
                    if get_s(v_down2) != 1: return False
                if get_s(h_left) == 1:
                    h_left2 = self.get_edge((r, c-1), (r, c-2))
                    if get_s(h_left2) != 1: return False
                if get_s(h_right) == 1:
                    h_right2 = self.get_edge((r, c+1), (r, c+2))
                    if get_s(h_right2) != 1: return False

        return True

    def extract_path(self, state):
        start_e = None
        for i, s in enumerate(state):
            if s == 1:
                start_e = i
                break
        if start_e is None: return []

        u, v = self.edges[start_e]
        path = [u, v]
        curr = v
        prev = u

        while True:
            next_dot = None
            for nxt, e_idx in self.adj[curr]:
                if nxt != prev and state[e_idx] == 1:
                    next_dot = nxt
                    break
            if next_dot is None:
                break
            if next_dot == path[0]:
                path.append(next_dot)
                break
            path.append(next_dot)
            prev = curr
            curr = next_dot

        return path

def solve(observation):
    solver = MasyuSolver(observation)
    state = solver.solve()
    if state is None:
        return "No Solution"
    path = solver.extract_path(state)
    return path

if __name__ == "__main__":
    print(solve(OBSERVATION))
