        if all(s != -1 for s in state):
            components, _, _ = get_components(state)
            active_comps = [c for c in components if len(c) > 1]
            if len(active_comps) == 1:
                comp = active_comps[0]
                if all(c in comp for c in circle_positions):
                    return state
            return None

        best_edge = -1
        max_score = -1
        for i in range(num_edges):
            if state[i] == -1:
                u, v = edges[i]
                score = 0
                for node in (u, v):
                    assigned = sum(1 for e in node_edges[node] if state[e] != -1)
                    score += assigned * 10
                    if node in circle_positions:
                        score += 5
                if score > max_score:
                    max_score = score
                    best_edge = i

        if best_edge == -1:
            return None

        state_copy = list(state)
        state_copy[best_edge] = 1
        res = solve_recursive(state_copy)
        if res is not None:
            return res

        state_copy = list(state)
        state_copy[best_edge] = 0
        return solve_recursive(state_copy)

    initial_state = [-1] * num_edges
    final_state = solve_recursive(initial_state)

    if final_state is None:
        return "No Solution"

    # Extract path
    adj = {i: [] for i in range(N*N)}
    for i, (u, v) in enumerate(edges):
        if final_state[i] == 1:
            adj[u].append(v)
            adj[v].append(u)

    start_node = -1
    for i in range(N*N):
        if len(adj[i]) > 0:
            start_node = i
            break

    if start_node == -1: return "No Solution"

    path = [start_node]
    curr = adj[start_node][0]
    prev = start_node

    while curr != start_node:
        path.append(curr)
        next_nodes = adj[curr]
        nxt = next_nodes[0] if next_nodes[0] != prev else next_nodes[1]
        prev = curr
        curr = nxt

    path.append(start_node)

    return [(node // N, node % N) for node in path]

