OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, 2, None, None, None, 2, None], [2, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, 6], [None, 1, None, None, None, 3, None], [None, None, None, None, None, None, None]]}

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])

    numbers = []
    for r in range(R):
        for c in range(C):
            if grid_data[r][c] is not None:
                numbers.append((r, c, grid_data[r][c]))

    # color: 0=UNKNOWN, 1=BLACK, 2=WHITE
    color = [[0]*C for _ in range(R)]
    island_id = [[-1]*C for _ in range(R)]

    for i, (r, c, val) in enumerate(numbers):
        color[r][c] = 2
        island_id[r][c] = i

    def get_neighbors(r, c):
        res = []
        if r > 0: res.append((r-1, c))
        if r < R-1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < C-1: res.append((r, c+1))
        return res

    def propagate(color, island_id):
        changed = True
        while changed:
            changed = False

            # 1. 2x2 Black prevention
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                    black_count = sum(1 for rr, cc in cells if color[rr][cc] == 1)
                    unknown_count = sum(1 for rr, cc in cells if color[rr][cc] == 0)
                    if black_count == 4:
                        return False
                    if black_count == 3 and unknown_count == 1:
                        for rr, cc in cells:
                            if color[rr][cc] == 0:
                                color[rr][cc] = 2
                                changed = True

            # 2. Island separation
            for r in range(R):
                for c in range(C):
                    if color[r][c] == 0 or (color[r][c] == 2 and island_id[r][c] == -1):
                        adj_islands = set()
                        for nr, nc in get_neighbors(r, c):
                            if color[nr][nc] == 2 and island_id[nr][nc] != -1:
                                adj_islands.add(island_id[nr][nc])
                        if len(adj_islands) > 1:
                            if color[r][c] == 2:
                                return False
                            color[r][c] = 1
                            changed = True

            # 3. Island completion and expansion
            for i, (r, c, size) in enumerate(numbers):
                island_cells = []
                q = [(r, c)]
                visited = set([(r, c)])
                while q:
                    curr_r, curr_c = q.pop(0)
                    island_cells.append((curr_r, curr_c))
                    for nr, nc in get_neighbors(curr_r, curr_c):
                        if color[nr][nc] == 2 and island_id[nr][nc] == i and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))

                if len(island_cells) > size:
                    return False

                expandable_neighbors = set()
                for ir, ic in island_cells:
                    for nr, nc in get_neighbors(ir, ic):
                        if color[nr][nc] == 0 or (color[nr][nc] == 2 and island_id[nr][nc] == -1):
                            expandable_neighbors.add((nr, nc))

                if len(island_cells) == size:
                    for nr, nc in expandable_neighbors:
                        if color[nr][nc] == 0:
                            color[nr][nc] = 1
                            changed = True
                        elif color[nr][nc] == 2:
                            return False
                elif len(island_cells) < size:
                    if len(expandable_neighbors) == 0:
                        return False
                    if len(expandable_neighbors) == 1:
                        nr, nc = expandable_neighbors.pop()
                        if color[nr][nc] == 0:
                            color[nr][nc] = 2
                            island_id[nr][nc] = i
                            changed = True
                        elif color[nr][nc] == 2:
                            island_id[nr][nc] = i
                            changed = True

            # 4. Unreachable cells are BLACK
            can_reach = [[False]*C for _ in range(R)]
            for i, (r, c, size) in enumerate(numbers):
                island_cells = []
                q = [(r, c)]
                visited = set([(r, c)])
                while q:
