                    island_cells.append((curr_r, curr_c))
                    for nr, nc in get_neighbors(curr_r, curr_c):
                        if color[nr][nc] == 2 and island_id[nr][nc] == i and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))

                rem_size = size - len(island_cells)
                if rem_size > 0:
                    q = []
                    dist = {}
                    for ir, ic in island_cells:
                        q.append((ir, ic))
                        dist[(ir, ic)] = 0

                    while q:
                        curr_r, curr_c = q.pop(0)
                        d = dist[(curr_r, curr_c)]
                        if d == rem_size:
                            continue
                        for nr, nc in get_neighbors(curr_r, curr_c):
                            if (color[nr][nc] == 0 or (color[nr][nc] == 2 and island_id[nr][nc] == -1)) and (nr, nc) not in dist:
                                touches_other = False
                                for nnr, nnc in get_neighbors(nr, nc):
                                    if color[nnr][nnc] == 2 and island_id[nnr][nnc] != -1 and island_id[nnr][nnc] != i:
                                        touches_other = True
                                        break
                                if not touches_other:
                                    dist[(nr, nc)] = d + 1
                                    if color[nr][nc] == 0:
                                        can_reach[nr][nc] = True
                                    q.append((nr, nc))

            for r in range(R):
                for c in range(C):
                    if color[r][c] == 0 and not can_reach[r][c]:
                        color[r][c] = 1
                        changed = True

            # 5. White cells must be connected to an island
            for r in range(R):
                for c in range(C):
                    if color[r][c] == 2 and island_id[r][c] == -1:
                        q = [(r, c)]
                        visited = set([(r, c)])
                        reachable_islands = set()
                        while q:
                            curr_r, curr_c = q.pop(0)
                            for nr, nc in get_neighbors(curr_r, curr_c):
                                if color[nr][nc] != 1 and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    if color[nr][nc] == 2 and island_id[nr][nc] != -1:
                                        reachable_islands.add(island_id[nr][nc])
                                    else:
                                        q.append((nr, nc))
                        if len(reachable_islands) == 0:
                            return False
                        if len(reachable_islands) == 1:
                            adj_islands = set()
                            for nr, nc in get_neighbors(r, c):
                                if color[nr][nc] == 2 and island_id[nr][nc] != -1:
                                    adj_islands.add(island_id[nr][nc])
                            if len(adj_islands) == 1:
                                island_id[r][c] = adj_islands.pop()
                                changed = True

            # 6. Black connectivity
            black_cells = [(r, c) for r in range(R) for c in range(C) if color[r][c] == 1]
            if black_cells:
                visited_b = set()
                q = [black_cells[0]]
                visited_b.add(black_cells[0])
                while q:
                    curr_r, curr_c = q.pop(0)
                    for nr, nc in get_neighbors(curr_r, curr_c):
                        if color[nr][nc] != 2 and (nr, nc) not in visited_b:
                            visited_b.add((nr, nc))
                            q.append((nr, nc))
                for br, bc in black_cells:
                    if (br, bc) not in visited_b:
                        return False

        return True

    def is_solved(color):
        for r in range(R):
            for c in range(C):
                if color[r][c] == 0:
                    return False

        for r in range(R - 1):
            for c in range(C - 1):
                if color[r][c] == 1 and color[r+1][c] == 1 and color[r][c+1] == 1 and color[r+1][c+1] == 1:
                    return False

        black_cells = [(r, c) for r in range(R) for c in range(C) if color[r][c] == 1]
        if black_cells:
            visited = set([black_cells[0]])
            q = [black_cells[0]]
            while q:
                curr_r, curr_c = q.pop(0)
                for nr, nc in get_neighbors(curr_r, curr_c):
                    if color[nr][nc] == 1 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if len(visited) != len(black_cells):
                return False

        visited_white = set()
        for r, c, size in numbers:
            if color[r][c] != 2: return False
            if (r, c) in visited_white: return False

            comp = set([(r, c)])
            q = [(r, c)]
            while q:
                curr_r, curr_c = q.pop(0)
                for nr, nc in get_neighbors(curr_r, curr_c):
                    if color[nr][nc] == 2 and (nr, nc) not in comp:
                        comp.add((nr, nc))
                        q.append((nr, nc))
            if len(comp) != size:
                return False
            visited_white.update(comp)

        for r in range(R):
            for c in range(C):
                if color[r][c] == 2 and (r, c) not in visited_white:
                    return False

        return True

    def solve_recursive(color, island_id):
        color_copy = [row[:] for row in color]
        island_id_copy = [row[:] for row in island_id]

        if not propagate(color_copy, island_id_copy):
            return None

        if is_solved(color_copy):
            return color_copy

        best_cell = None
        best_score = -1

        for r in range(R):
            for c in range(C):
                if color_copy[r][c] == 0:
                    score = sum(1 for nr, nc in get_neighbors(r, c) if color_copy[nr][nc] != 0)
                    if score > best_score:
                        best_score = score
                        best_cell = (r, c)

        if best_cell is None:
            return None

        r, c = best_cell

        color_copy[r][c] = 1
        res = solve_recursive(color_copy, island_id_copy)
        if res: return res

        color_copy[r][c] = 2
        res = solve_recursive(color_copy, island_id_copy)
        if res: return res

        return None

    ans = solve_recursive(color, island_id)
    if ans is None:
        return "No Solution"

    result = []
    for r in range(R):
        row = []
        for c in range(C):
            if ans[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        result.append(row)

    return result

