            r, c, val = queue.pop(0)

            # Region propagation: water flows down, empty space goes up
            reg = region[r][c]
            for r2, c2 in region_cells[reg]:
                if val == 1 and r2 >= r:
                    if state[r2][c2] == 0: return False
                    if state[r2][c2] == -1:
                        state[r2][c2] = 1
                        queue.append((r2, c2, 1))
                elif val == 0 and r2 <= r:
                    if state[r2][c2] == 1: return False
                    if state[r2][c2] == -1:
                        state[r2][c2] = 0
                        queue.append((r2, c2, 0))

            # Row propagation
            row_unk = 0
            row_wat = 0
            for c2 in range(C):
                if state[r][c2] == 1: row_wat += 1
                elif state[r][c2] == -1: row_unk += 1

            if row_wat > row_water_counts[r]: return False
            if row_wat + row_unk < row_water_counts[r]: return False

            if row_wat == row_water_counts[r] and row_unk > 0:
                for c2 in range(C):
                    if state[r][c2] == -1:
                        state[r][c2] = 0
                        queue.append((r, c2, 0))
            elif row_wat + row_unk == row_water_counts[r] and row_unk > 0:
                for c2 in range(C):
                    if state[r][c2] == -1:
                        state[r][c2] = 1
                        queue.append((r, c2, 1))

            # Col propagation
            col_unk = 0
            col_wat = 0
            for r2 in range(R):
                if state[r2][c] == 1: col_wat += 1
                elif state[r2][c] == -1: col_unk += 1

            if col_wat > col_water_counts[c]: return False
            if col_wat + col_unk < col_water_counts[c]: return False

            if col_wat == col_water_counts[c] and col_unk > 0:
                for r2 in range(R):
                    if state[r2][c] == -1:
                        state[r2][c] = 0
                        queue.append((r2, c, 0))
            elif col_wat + col_unk == col_water_counts[c] and col_unk > 0:
                for r2 in range(R):
                    if state[r2][c] == -1:
                        state[r2][c] = 1
                        queue.append((r2, c, 1))
        return True

    def backtrack(state):
        best_r, best_c = -1, -1
        for r in range(R):
            for c in range(C):
                if state[r][c] == -1:
                    best_r, best_c = r, c
                    break
            if best_r != -1: break

        if best_r == -1:
            return state

        # Try setting to water
        state_copy1 = [row[:] for row in state]
        state_copy1[best_r][best_c] = 1
        if propagate(state_copy1, [(best_r, best_c, 1)]):
            res = backtrack(state_copy1)
            if res is not None: return res

        # Try setting to empty
        state_copy0 = [row[:] for row in state]
        state_copy0[best_r][best_c] = 0
        if propagate(state_copy0, [(best_r, best_c, 0)]):
            res = backtrack(state_copy0)
            if res is not None: return res

        return None

    grid_state = [[-1]*C for _ in range(R)]
    initial_queue = []

    # Initial constraints from 0 or max clues
    for r in range(R):
        if row_water_counts[r] == 0:
            for c in range(C):
                if grid_state[r][c] == -1:
                    grid_state[r][c] = 0
                    initial_queue.append((r, c, 0))
        elif row_water_counts[r] == C:
            for c in range(C):
                if grid_state[r][c] == -1:
                    grid_state[r][c] = 1
                    initial_queue.append((r, c, 1))

    for c in range(C):
        if col_water_counts[c] == 0:
            for r in range(R):
                if grid_state[r][c] == -1:
                    grid_state[r][c] = 0
                    initial_queue.append((r, c, 0))
        elif col_water_counts[c] == R:
            for r in range(R):
                if grid_state[r][c] == -1:
                    grid_state[r][c] = 1
                    initial_queue.append((r, c, 1))

    if not propagate(grid_state, initial_queue):
        return "No Solution"

    # Probing (Singleton Consistency) to mimic human deduction
    changed = True
    while changed:
        changed = False
        for r in range(R):
            for c in range(C):
                if grid_state[r][c] == -1:
                    state_copy1 = [row[:] for row in grid_state]
                    state_copy1[r][c] = 1
                    valid1 = propagate(state_copy1, [(r, c, 1)])

                    state_copy0 = [row[:] for row in grid_state]
                    state_copy0[r][c] = 0
                    valid0 = propagate(state_copy0, [(r, c, 0)])

                    if not valid1 and not valid0:
                        return "No Solution"
                    elif valid1 and not valid0:
                        grid_state[r][c] = 1
                        if not propagate(grid_state, [(r, c, 1)]): return "No Solution"
                        changed = True
                    elif not valid1 and valid0:
                        grid_state[r][c] = 0
                        if not propagate(grid_state, [(r, c, 0)]): return "No Solution"
                        changed = True

    final_state = backtrack(grid_state)
    if final_state is None:
        return "No Solution"

    res = []
    for r in range(R):
        row_res = []
        for c in range(C):
            if final_state[r][c] == 1:
                row_res.append('W')
            else:
                row_res.append(None)
        res.append(row_res)

    return res

