                trees.append((r, c))

    def ortho_neighbors(r, c):
        res = []
        if r > 0: res.append((r-1, c))
        if r < R - 1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < C - 1: res.append((r, c+1))
        return res

    def all_neighbors(r, c):
        res = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    res.append((nr, nc))
        return res

    def backtrack(unassigned_trees, current_grid, current_row_counts, current_col_counts):
        # Create a working copy of the state for this node
        g = [row[:] for row in current_grid]
        r_counts = list(current_row_counts)
        c_counts = list(current_col_counts)
        u_trees = set(unassigned_trees)

        # Constraint Propagation
        while True:
