                        for nr, nc in ortho_neighbors(r, c):
                            if (nr, nc) in u_trees:
                                has_unassigned = True
                                break
                        if not has_unassigned:
                            g[r][c] = 'x'
                            changed = True

            # 2. Mark rows and columns that have fulfilled their tent quota as 'x'
            for r in range(R):
                if r_counts[r] == 0:
