            if len(placements) == 0:
                return False

            if len(placements) < min_placements:
                min_placements = len(placements)
                best_tree = (tr, tc)
                best_placements = placements

        # Branching
        u_trees.remove(best_tree)
        for r, c in best_placements:
            # Apply placement
            g[r][c] = 't'
            r_counts[r] -= 1
            c_counts[c] -= 1

            # Mark 8-way neighbors as 'x' to prevent touching tents
            changed_cells = []
            for nr, nc in all_neighbors(r, c):
                if g[nr][nc] == '.':
                    g[nr][nc] = 'x'
                    changed_cells.append((nr, nc))

            # Recurse
            res = backtrack(u_trees, g, r_counts, c_counts)
            if res:
                return res

            # Backtrack local changes for the next iteration
            g[r][c] = '.'
            r_counts[r] += 1
            c_counts[c] += 1
            for nr, nc in changed_cells:
                g[nr][nc] = '.'

