def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    R = len(row_targets)
    C = len(col_targets)

    # Weights are 1-indexed based on row/col position
    col_weights = list(range(1, C + 1))
    row_weights = list(range(1, R + 1))

    # Generate all valid combinations for each row
    valid_rows = []
    for i in range(R):
        target = row_targets[i]
        valid = []
        for mask in range(1 << C):
            s = sum(col_weights[j] for j in range(C) if (mask & (1 << j)))
            if s == target:
                valid.append(tuple(1 if (mask & (1 << j)) else 0 for j in range(C)))
        valid_rows.append(valid)

    # Generate all valid combinations for each column
    valid_cols = []
    for j in range(C):
        target = col_targets[j]
        valid = []
        for mask in range(1 << R):
            s = sum(row_weights[i] for i in range(R) if (mask & (1 << i)))
            if s == target:
                valid.append(tuple(1 if (mask & (1 << i)) else 0 for i in range(R)))
        valid_cols.append(valid)

    # AC-3 Constraint Propagation to drastically reduce search space
    changed = True
    while changed:
        changed = False
        for i in range(R):
            for j in range(C):
                possible_r = set(r[j] for r in valid_rows[i])
                possible_c = set(c[i] for c in valid_cols[j])
                common = possible_r.intersection(possible_c)

                if not common:
                    return "No Solution"

                if len(common) < len(possible_r):
                    valid_rows[i] = [r for r in valid_rows[i] if r[j] in common]
                    changed = True
                if len(common) < len(possible_c):
                    valid_cols[j] = [c for c in valid_cols[j] if c[i] in common]
                    changed = True

    # Precompute tight bounds for remaining column sums based on reduced domains
    max_remaining = [[0] * C for _ in range(R)]
    min_remaining = [[0] * C for _ in range(R)]
    for j in range(C):
        for r_idx in range(R):
            max_rem = -1
            min_rem = float('inf')
            for c in valid_cols[j]:
                rem = sum(row_weights[i] * c[i] for i in range(r_idx + 1, R))
                if rem > max_rem: max_rem = rem
                if rem < min_rem: min_rem = rem
            max_remaining[r_idx][j] = max_rem
            min_remaining[r_idx][j] = min_rem

    # Backtracking search with aggressive pruning
    def backtrack(row_idx, current_grid, current_col_sums):
        if row_idx == R:
            if current_col_sums == col_targets:
                return current_grid
            return None

        for r in valid_rows[row_idx]:
            possible = True
            for j in range(C):
                new_sum = current_col_sums[j] + row_weights[row_idx] * r[j]
                # Prune if the target cannot be reached even with max/min possible remaining sums
                if new_sum + min_remaining[row_idx][j] > col_targets[j]:
                    possible = False
                    break
                if new_sum + max_remaining[row_idx][j] < col_targets[j]:
                    possible = False
                    break
            if possible:
                current_grid.append(r)
                new_col_sums = [current_col_sums[j] + row_weights[row_idx] * r[j] for j in range(C)]
                res = backtrack(row_idx + 1, current_grid, new_col_sums)
                if res:
                    return res
                current_grid.pop()
        return None

    grid = backtrack(0, [], [0] * C)

    if grid:
        res = []
        for row in grid:
            res.append(['B' if cell else None for cell in row])
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
