                circles.append((r, c))

    state = {}
    from collections import deque
    queue = deque()

    def set_edge(e, val):
        if e not in edge_endpoints:
            if val == True: 
                raise Conflict()
            return
        if e in state:
            if state[e] != val: 
                raise Conflict()
            return
        state[e] = val
        queue.append(e)

    def check_vertex(v):
        inc = adj[v]
        on_edges = [e for e in inc if state.get(e) == True]
        off_edges = [e for e in inc if state.get(e) == False]
        unk_edges = [e for e in inc if e not in state]

        if len(on_edges) > 2: 
            raise Conflict()
        if len(on_edges) == 2:
            for e in unk_edges: 
                set_edge(e, False)

        r, c = v
        ctype = grid[r][c]
        if ctype in ('B', 'W'):
            if len(on_edges) + len(unk_edges) < 2: 
                raise Conflict()
            if len(on_edges) + len(unk_edges) == 2:
                for e in unk_edges: 
                    set_edge(e, True)
        else:
            if len(on_edges) == 1 and len(unk_edges) == 0: 
                raise Conflict()
            if len(on_edges) == 1 and len(unk_edges) == 1:
                set_edge(unk_edges[0], True)
            if len(on_edges) == 0 and len(unk_edges) == 1:
                set_edge(unk_edges[0], False)

    def check_circle(v):
        r, c = v
        ctype = grid[r][c]
        if ctype == 'B':
            H1 = ('H', r, c-1)
            H2 = ('H', r, c)
            V1 = ('V', r-1, c)
            V2 = ('V', r, c)

            if state.get(H1) == True and state.get(H2) == True: raise Conflict()
            if state.get(V1) == True and state.get(V2) == True: raise Conflict()

            if state.get(H1) == True:
                set_edge(H2, False)
                set_edge(('H', r, c-2), True)
            if state.get(H2) == True:
                set_edge(H1, False)
                set_edge(('H', r, c+1), True)
            if state.get(V1) == True:
                set_edge(V2, False)
                set_edge(('V', r-2, c), True)
            if state.get(V2) == True:
                set_edge(V1, False)
                set_edge(('V', r+1, c), True)

