            H2 = ('H', r, c)
            V1 = ('V', r-1, c)
            V2 = ('V', r, c)

            if state.get(H1) == True: set_edge(H2, True)
            if state.get(H2) == True: set_edge(H1, True)
            if state.get(H1) == False: set_edge(H2, False)
            if state.get(H2) == False: set_edge(H1, False)

