                set_edge(V2, False)

    def check_loops():
        parent = {}
        for e, val in state.items():
            if val:
                u, v = edge_endpoints[e]
                if u not in parent: parent[u] = u
                if v not in parent: parent[v] = v

        def find(i):
            if parent[i] == i: return i
            parent[i] = find(parent[i])
            return parent[i]

        for e, val in state.items():
            if val:
                u, v = edge_endpoints[e]
                root_u = find(u)
                root_v = find(v)
                if root_u != root_v:
                    parent[root_u] = root_v
                else:
                    loop_root = root_u
                    for c in circles:
                        if c not in parent or find(c) != loop_root:
                            raise Conflict()
                    for e_unk in all_edges:
                        if e_unk not in state:
                            set_edge(e_unk, False)
                    return

    def propagate():
        while queue:
            e = queue.popleft()
            u, v = edge_endpoints[e]
            check_vertex(u)
            check_vertex(v)
            if grid[u[0]][u[1]] in ('B', 'W'): check_circle(u)
            if grid[v[0]][v[1]] in ('B', 'W'): check_circle(v)
            if state[e] == True:
