    def initial_setup():
        for r in range(n):
            for c in range(n):
                ctype = grid[r][c]
                if ctype == 'B':
                    if c < 2: set_edge(('H', r, c-1), False)
                    if c > n - 3: set_edge(('H', r, c), False)
                    if r < 2: set_edge(('V', r-1, c), False)
                    if r > n - 3: set_edge(('V', r, c), False)
                elif ctype == 'W':
                    if c == 0 or c == n - 1:
                        set_edge(('H', r, c-1), False)
                        set_edge(('H', r, c), False)
                    if r == 0 or r == n - 1:
                        set_edge(('V', r-1, c), False)
                        set_edge(('V', r, c), False)
        for v in all_vertices:
            check_vertex(v)
            if grid[v[0]][v[1]] in ('B', 'W'):
                check_circle(v)

    def get_next_edge():
        for v in all_vertices:
            inc = adj[v]
            on_count = sum(1 for e in inc if state.get(e) == True)
            if on_count == 1:
                for e in inc:
                    if e not in state:
                        return e
        for c in circles:
            for e in adj[c]:
                if e not in state:
                    return e
        for e in all_edges:
