        if not e:
            for c in circles:
                if sum(1 for inc_e in adj[c] if state.get(inc_e) == True) != 2:
                    return False
            return True

        state_backup = state.copy()

        try:
            set_edge(e, True)
            propagate()
            if solve_backtrack(): return True
