            pass

        state.clear()
        state.update(state_backup)
        queue.clear()

        try:
            set_edge(e, False)
            propagate()
            if solve_backtrack(): return True
        except Conflict:
            pass

        state.clear()
        state.update(state_backup)
        queue.clear()
        return False

    try:
        initial_setup()
        propagate()
        if not solve_backtrack():
            return "No Solution"
    except Conflict:
        return "No Solution"

    start_v = None
    for v in all_vertices:
        if any(state.get(e) == True for e in adj[v]):
            start_v = v
            break

    if not start_v: 
        return "No Solution"

    path = [start_v]
    curr = start_v
    prev_e = None

    while True:
        next_v = None
        next_e = None
        for e in adj[curr]:
            if state.get(e) == True and e != prev_e:
                next_e = e
                u, v = edge_endpoints[e]
                next_v = v if u == curr else u
                break

        if not next_v:
            break

        path.append(next_v)
        curr = next_v
        prev_e = next_e

        if curr == start_v:
            break

    return path

