def solve(observation):
    data = observation['data']
    N = len(data)

    # Parse regions
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = data[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append(r * N + c)

    # Precompute neighbors for fast access
    neighbors = {}
    for r in range(N):
        for c in range(N):
            idx = r * N + c
            neighbors[idx] = []
            if r > 0: neighbors[idx].append((r - 1) * N + c)
            if r < N - 1: neighbors[idx].append((r + 1) * N + c)
            if c > 0: neighbors[idx].append(r * N + c - 1)
            if c < N - 1: neighbors[idx].append(r * N + c + 1)

    def propagate(state):
        """
        Applies deductive rules to reduce the search space.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Region constraints: exactly 2 shaded cells per region
            for rid, cells in regions.items():
                shaded = []
                unknown = []
                for c in cells:
                    if state[c] == 1: shaded.append(c)
                    elif state[c] == -1: unknown.append(c)

                if len(shaded) > 2: return False
                if len(shaded) + len(unknown) < 2: return False

                if len(shaded) == 2 and unknown:
                    for c in unknown:
                        state[c] = 0
                        changed = True
                elif len(shaded) + len(unknown) == 2 and unknown:
                    for c in unknown:
                        state[c] = 1
                        changed = True

            # 2. Domino constraints
            for i in range(N * N):
                if state[i] == 1:
                    sh_n = []
                    un_n = []
                    for n in neighbors[i]:
                        if state[n] == 1: sh_n.append(n)
                        elif state[n] == -1: un_n.append(n)

                    # A shaded cell can have at most 1 shaded neighbor
                    if len(sh_n) > 1: return False

                    if len(sh_n) == 1:
                        # Domino is complete, all other neighbors must be unshaded
                        for n in un_n:
                            state[n] = 0
                            changed = True
                    elif len(sh_n) == 0:
                        # Needs a partner
                        if len(un_n) == 0: return False
                        if len(un_n) == 1:
                            state[un_n[0]] = 1
                            changed = True

                elif state[i] == -1:
                    sh_n = []
                    for n in neighbors[i]:
                        if state[n] == 1: sh_n.append(n)

                    # If shading this cell would connect it to 2+ shaded cells, it's invalid
                    if len(sh_n) >= 2:
                        state[i] = 0
                        changed = True
                    elif len(sh_n) == 1:
                        # If its only shaded neighbor already has a partner, it cannot be shaded
                        sn = sh_n[0]
                        sn_sh_n = [n for n in neighbors[sn] if state[n] == 1]
                        if len(sn_sh_n) == 1:
                            state[i] = 0
                            changed = True
                    else:
                        # If it has no possible partners (all neighbors are 0), it cannot be shaded
                        possible_partners = [n for n in neighbors[i] if state[n] != 0]
                        if len(possible_partners) == 0:
                            state[i] = 0
                            changed = True

        return True

    def solve_recursive(state):
        if not propagate(state):
            return None

        # Find the most constrained region that still needs shaded cells
        best_rid = None
        min_un = 999

        for rid, cells in regions.items():
            sh = sum(1 for c in cells if state[c] == 1)
            if sh == 2: continue
            un = [c for c in cells if state[c] == -1]
            if len(un) > 0 and len(un) < min_un:
                min_un = len(un)
                best_rid = rid

        # If all regions are satisfied, verify the final state
        if best_rid is None:
            for i in range(N * N):
                if state[i] == 1:
                    sh_n = sum(1 for n in neighbors[i] if state[n] == 1)
                    if sh_n != 1: return None
            return state

        # Branch on the first unknown cell in the chosen region
        un_cells = [c for c in regions[best_rid] if state[c] == -1]
        c = un_cells[0]

        # Try shading the cell first
        state_copy = list(state)
        state_copy[c] = 1
        res = solve_recursive(state_copy)
        if res: return res

        # Try leaving it unshaded
        state_copy = list(state)
        state_copy[c] = 0
        return solve_recursive(state_copy)

    # Initialize state: -1 = unknown, 0 = unshaded, 1 = shaded
    initial_state = [-1] * (N * N)
    solution = solve_recursive(initial_state)

    if solution:
        ans = []
        for r in range(N):
            row = []
            for c in range(N):
                if solution[r * N + c] == 1:
                    row.append('S')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    return "No Solution"

