                row_avail_counts = [0] * R
                col_avail_counts = [0] * C
                avail_cells = set()
                for dom in new_domains.values():
                    avail_cells.update(dom)

                for ar, ac in avail_cells:
                    row_avail_counts[ar] += 1
                    col_avail_counts[ac] += 1

                for rr in range(R):
                    if new_row_rem[rr] > 0 and row_avail_counts[rr] < new_row_rem[rr]:
                        possible = False
                        break
                if possible:
                    for cc in range(C):
                        if new_col_rem[cc] > 0 and col_avail_counts[cc] < new_col_rem[cc]:
                            possible = False
                            break

            if possible:
                new_unassigned = [i for i in unassigned if i != best_idx]
                res = backtrack(new_unassigned, new_domains, new_row_rem, new_col_rem, new_placed)
                if res:
                    return res

        return None

    unassigned_init = list(range(len(trees)))
    solution = backtrack(unassigned_init, domains, row_counts, col_counts, set())

    if solution:
        ans_grid = [[None for _ in range(C)] for _ in range(R)]
        for r, c in solution:
            ans_grid[r][c] = 't'
        return ans_grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
