OBSERVATION = {'data': [[None, 'W', None, None, 'W', 'W', None, None, None, 'B'], [None, None, None, None, None, None, None, None, None, None], ['B', None, None, 'W', None, None, None, 'W', None, None], [None, 'W', None, None, 'W', 'W', None, None, None, 'W'], [None, None, None, 'W', None, None, None, None, None, None], [None, None, None, None, 'W', None, 'W', None, None, None], [None, 'W', None, None, None, None, 'W', None, 'W', None], [None, 'W', None, None, 'B', None, None, None, None, None], ['W', None, None, None, None, 'B', None, None, None, None], [None, None, None, None, None, None, None, 'B', None, 'B']]}

class MasyuSolver:
    def __init__(self, observation):
        self.data = observation['data']
        self.N = len(self.data)
        self.circles = {}
        for r in range(self.N):
            for c in range(self.N):
                if self.data[r][c] in ('W', 'B'):
                    self.circles[(r, c)] = self.data[r][c]
        self.num_edges = 2 * self.N * (self.N - 1)
        # state: -1 = undecided, 0 = empty, 1 = line
        self.state = [-1] * self.num_edges
        self.changed = False

    def H_idx(self, r, c):
        if 0 <= r < self.N and 0 <= c < self.N - 1:
            return r * (self.N - 1) + c
        return None

    def V_idx(self, r, c):
        if 0 <= r < self.N - 1 and 0 <= c < self.N:
            return self.N * (self.N - 1) + r * self.N + c
        return None

    def get_edge(self, idx):
        if idx is None: return 0
        return self.state[idx]

    def set_edge(self, idx, val):
        if idx is None:
            return val == 0
        if self.state[idx] == 1 - val:
            return False
        if self.state[idx] == -1:
            self.state[idx] = val
            self.changed = True
        return True

    def check_cycles(self):
        adj = {v: [] for v in range(self.N * self.N)}
        for r in range(self.N):
            for c in range(self.N - 1):
                idx = self.H_idx(r, c)
                if self.state[idx] == 1:
                    u, v = r * self.N + c, r * self.N + c + 1
                    adj[u].append(v)
                    adj[v].append(u)
        for r in range(self.N - 1):
            for c in range(self.N):
                idx = self.V_idx(r, c)
                if self.state[idx] == 1:
                    u, v = r * self.N + c, (r + 1) * self.N + c
                    adj[u].append(v)
                    adj[v].append(u)

        visited = set()
        components = []
        for i in range(self.N * self.N):
            if i not in visited and len(adj[i]) > 0:
                comp = set()
                q = [i]
                visited.add(i)
                is_cycle = False
                edges_in_comp = 0
                while q:
                    curr = q.pop(0)
                    comp.add(curr)
                    edges_in_comp += len(adj[curr])
                    for nxt in adj[curr]:
                        if nxt not in visited:
                            visited.add(nxt)
                            q.append(nxt)
                edges_in_comp //= 2
                if edges_in_comp >= len(comp):
                    is_cycle = True
                components.append((comp, is_cycle))

        total_circles = len(self.circles)
        for comp, is_cycle in components:
            circles_in_comp = sum(1 for r, c in self.circles if r * self.N + c in comp)
            if is_cycle:
                if circles_in_comp < total_circles:
                    return False
                if circles_in_comp == total_circles:
                    for idx in range(self.num_edges):
                        if self.state[idx] == -1:
                            if not self.set_edge(idx, 0): return False
            else:
                if circles_in_comp < total_circles:
                    for r in range(self.N):
                        for c in range(self.N - 1):
                            idx = self.H_idx(r, c)
                            if self.state[idx] == -1:
                                u, v = r * self.N + c, r * self.N + c + 1
                                if u in comp and v in comp:
                                    if not self.set_edge(idx, 0): return False
                    for r in range(self.N - 1):
                        for c in range(self.N):
                            idx = self.V_idx(r, c)
                            if self.state[idx] == -1:
                                u, v = r * self.N + c, (r + 1) * self.N + c
                                if u in comp and v in comp:
                                    if not self.set_edge(idx, 0): return False
        return True

    def deduce(self):
        self.changed = True
        while self.changed:
            self.changed = False
            for r in range(self.N):
                for c in range(self.N):
                    u, d, l, r_ = self.V_idx(r-1, c), self.V_idx(r, c), self.H_idx(r, c-1), self.H_idx(r, c)
                    inc = [u, d, l, r_]
                    vals = [self.get_edge(i) for i in inc]
                    ones = vals.count(1)
                    zeros = vals.count(0)
                    undecided = [inc[i] for i in range(4) if vals[i] == -1]

                    is_circle = (r, c) in self.circles

                    if is_circle:
                        if ones > 2: return False
                        if ones == 2:
                            for i in undecided:
                                if not self.set_edge(i, 0): return False
                        if 4 - zeros == 2:
                            for i in undecided:
                                if not self.set_edge(i, 1): return False
                        if 4 - zeros < 2: return False
                    else:
                        if ones > 2: return False
                        if ones == 2:
                            for i in undecided:
                                if not self.set_edge(i, 0): return False
                        if ones == 1 and zeros == 3: return False
                        if ones == 1 and zeros == 2:
                            for i in undecided:
                                if not self.set_edge(i, 1): return False
                        if ones == 0 and zeros == 3:
                            for i in undecided:
                                if not self.set_edge(i, 0): return False

                    if is_circle:
                        ctype = self.circles[(r, c)]
                        if ctype == 'W':
                            vu, vd, vl, vr = vals
                            if vu == 1 or vd == 1:
                                if not self.set_edge(u, 1): return False
                                if not self.set_edge(d, 1): return False
                                if not self.set_edge(l, 0): return False
                                if not self.set_edge(r_, 0): return False
                            if vl == 1 or vr == 1:
                                if not self.set_edge(l, 1): return False
                                if not self.set_edge(r_, 1): return False
                                if not self.set_edge(u, 0): return False
                                if not self.set_edge(d, 0): return False
                            if vu == 0 or vd == 0:
                                if not self.set_edge(l, 1): return False
                                if not self.set_edge(r_, 1): return False
                                if not self.set_edge(u, 0): return False
                                if not self.set_edge(d, 0): return False
                            if vl == 0 or vr == 0:
                                if not self.set_edge(u, 1): return False
                                if not self.set_edge(d, 1): return False
                                if not self.set_edge(l, 0): return False
                                if not self.set_edge(r_, 0): return False

                            if self.get_edge(u) == 1 and self.get_edge(d) == 1:
                                uu = self.V_idx(r-2, c)
                                dd = self.V_idx(r+1, c)
                                if self.get_edge(uu) == 1:
                                    if not self.set_edge(dd, 0): return False
                                if self.get_edge(dd) == 1:
                                    if not self.set_edge(uu, 0): return False
                            if self.get_edge(l) == 1 and self.get_edge(r_) == 1:
                                ll = self.H_idx(r, c-2)
                                rr = self.H_idx(r, c+1)
                                if self.get_edge(ll) == 1:
                                    if not self.set_edge(rr, 0): return False
                                if self.get_edge(rr) == 1:
                                    if not self.set_edge(ll, 0): return False

                        elif ctype == 'B':
                            vu, vd, vl, vr = vals
                            uu, dd, ll, rr = self.V_idx(r-2, c), self.V_idx(r+1, c), self.H_idx(r, c-2), self.H_idx(r, c+1)
                            if vu == 1:
                                if not self.set_edge(uu, 1): return False
                                if not self.set_edge(d, 0): return False
                            if vd == 1:
                                if not self.set_edge(dd, 1): return False
                                if not self.set_edge(u, 0): return False
                            if vl == 1:
                                if not self.set_edge(ll, 1): return False
                                if not self.set_edge(r_, 0): return False
                            if vr == 1:
                                if not self.set_edge(rr, 1): return False
                                if not self.set_edge(l, 0): return False

                            if self.get_edge(uu) == 0:
                                if not self.set_edge(u, 0): return False
                            if self.get_edge(dd) == 0:
                                if not self.set_edge(d, 0): return False
                            if self.get_edge(ll) == 0:
                                if not self.set_edge(l, 0): return False
                            if self.get_edge(rr) == 0:
                                if not self.set_edge(r_, 0): return False

            if not self.check_cycles():
                return False
        return True

    def get_best_undecided(self):
        for r in range(self.N):
            for c in range(self.N):
                u, d, l, r_ = self.V_idx(r-1, c), self.V_idx(r, c), self.H_idx(r, c-1), self.H_idx(r, c)
                inc = [u, d, l, r_]
                vals = [self.get_edge(i) for i in inc]
                if vals.count(1) == 1:
                    for i in inc:
                        if self.get_edge(i) == -1:
                            return i

        for r, c in self.circles:
            u, d, l, r_ = self.V_idx(r-1, c), self.V_idx(r, c), self.H_idx(r, c-1), self.H_idx(r, c)
            for i in [u, d, l, r_]:
                if self.get_edge(i) == -1:
                    return i

        for i in range(self.num_edges):
            if self.state[i] == -1:
                return i
        return -1

    def solve_recursive(self):
        if not self.deduce():
            return False

        best_idx = self.get_best_undecided()
        if best_idx == -1:
            return self.get_path() is not None

        saved_state = list(self.state)

        self.state[best_idx] = 1
        if self.solve_recursive():
            return True

        self.state = list(saved_state)
        self.state[best_idx] = 0
        if self.solve_recursive():
            return True

        self.state = list(saved_state)
        return False

    def get_path(self):
        adj = {v: [] for v in range(self.N * self.N)}
        for r in range(self.N):
            for c in range(self.N - 1):
                if self.state[self.H_idx(r, c)] == 1:
                    u, v = r * self.N + c, r * self.N + c + 1
                    adj[u].append(v)
                    adj[v].append(u)
        for r in range(self.N - 1):
            for c in range(self.N):
                if self.state[self.V_idx(r, c)] == 1:
                    u, v = r * self.N + c, (r + 1) * self.N + c
                    adj[u].append(v)
                    adj[v].append(u)

        start = -1
        for i in range(self.N * self.N):
            if len(adj[i]) > 0:
                if len(adj[i]) != 2: return None
                start = i
                break
        if start == -1: return None

        path = []
        curr = start
        prev = -1
        while True:
            path.append((curr // self.N, curr % self.N))
            nxts = adj[curr]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            prev = curr
            curr = nxt
            if curr == start:
                break
        path.append((start // self.N, start % self.N))

        visited = set(r * self.N + c for r, c in path)
        for i in range(self.N * self.N):
            if len(adj[i]) > 0 and i not in visited:
                return None

        for r, c in self.circles:
            if r * self.N + c not in visited:
                return None

        return path

def solve(observation):
    solver = MasyuSolver(observation)
    if solver.solve_recursive():
        return solver.get_path()
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
