    def is_solved(g):
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    return False
        for r in range(R - 1):
            for c in range(C - 1):
                if g[r][c] == 1 and g[r+1][c] == 1 and g[r][c+1] == 1 and g[r+1][c+1] == 1:
                    return False
        black_cells = [(r, c) for r in range(R) for c in range(C) if g[r][c] == 1]
        if black_cells:
            visited = set()
            q = [black_cells[0]]
            visited.add(black_cells[0])
            while q:
                curr_r, curr_c = q.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 1 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if len(visited) != len(black_cells):
                return False
        white_visited = set()
        for r in range(R):
            for c in range(C):
                if g[r][c] == 2 and (r, c) not in white_visited:
                    comp = set()
                    q = [(r, c)]
                    comp.add((r, c))
                    white_visited.add((r, c))
                    comp_nums = []
                    while q:
                        curr_r, curr_c = q.pop(0)
                        if (curr_r, curr_c) in numbers:
                            comp_nums.append(numbers[(curr_r, curr_c)])
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 2 and (nr, nc) not in white_visited:
                                white_visited.add((nr, nc))
                                comp.add((nr, nc))
                                q.append((nr, nc))
                    if len(comp_nums) != 1:
                        return False
                    if len(comp) != comp_nums[0]:
                        return False
        return True

    def backtrack(g):
        current_grid = [row[:] for row in g]

        if not propagate(current_grid, numbers):
            return None

        solved = True
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] == 0:
                    solved = False
                    break
            if not solved:
                break

        if solved:
            if is_solved(current_grid):
                return current_grid
            else:
                return None

        best_cell = None
        max_neighbors = -1
        for r in range(R):
            for c in range(C):
                if current_grid[r][c] == 0:
                    neighbors = 0
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C and current_grid[nr][nc] != 0:
                            neighbors += 1
                    if neighbors > max_neighbors:
                        max_neighbors = neighbors
                        best_cell = (r, c)

        if best_cell:
            r, c = best_cell
            current_grid[r][c] = 1
            res = backtrack(current_grid)
            if res: return res

            current_grid[r][c] = 2
            res = backtrack(current_grid)
            if res: return res

        return None

    solution = backtrack(grid)

    if solution:
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if solution[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    return "No Solution"

