OBSERVATION = {'data': [[None, None, None, 1, None], [None, 1, 2, 3, 3], [None, 2, None, None, None], [None, None, None, None, None], [1, None, 2, None, 0]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # state: -1 for unknown, 0 for safe, 1 for mine
    state = [[-1 for _ in range(C)] for _ in range(R)]
    clues = {}

    # Initialize state with knowns (clues are safe cells)
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                state[r][c] = 0

    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    neighbors.append((nr, nc))
        return neighbors

    def propagate(current_state):
        """
        Aggressively applies basic Minesweeper deduction rules:
        1. If a clue needs N mines and has exactly N unknown neighbors, all are mines.
        2. If a clue needs N mines and already has N mines, all other unknown neighbors are safe.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False
            for (r, c), N in clues.items():
                neighbors = get_neighbors(r, c)
                unknowns = []
                mines = 0
                for nr, nc in neighbors:
                    if current_state[nr][nc] == 1:
                        mines += 1
                    elif current_state[nr][nc] == -1:
                        unknowns.append((nr, nc))

                # Contradiction checks
                if mines > N:
                    return False
                if mines + len(unknowns) < N:
                    return False

                # Deduction rules
                if len(unknowns) > 0:
                    if mines == N:
                        for nr, nc in unknowns:
                            current_state[nr][nc] = 0
                            changed = True
                    elif mines + len(unknowns) == N:
                        for nr, nc in unknowns:
                            current_state[nr][nc] = 1
                            changed = True
        return True

    def backtrack(current_state):
        """
        Backtracking search with forward checking (propagation).
        """
        if not propagate(current_state):
            return None

        best_cell = None
        max_adj_clues = -1

        # Heuristic: Pick the most constrained unassigned cell (most adjacent clues)
        for r in range(R):
            for c in range(C):
                if current_state[r][c] == -1:
                    adj_clues = sum(1 for nr, nc in get_neighbors(r, c) if (nr, nc) in clues)
                    if adj_clues > max_adj_clues:
                        max_adj_clues = adj_clues
                        best_cell = (r, c)

        if not best_cell:
            # All cells assigned successfully
            return current_state

        r, c = best_cell

        # Branch 1: Assume cell is safe (0)
        state_copy = [row[:] for row in current_state]
        state_copy[r][c] = 0
        res = backtrack(state_copy)
        if res: return res

        # Branch 2: Assume cell is a mine (1)
        state_copy = [row[:] for row in current_state]
        state_copy[r][c] = 1
        res = backtrack(state_copy)
        if res: return res

        return None

    final_state = backtrack(state)

    if final_state:
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if final_state[r][c] == 1:
                    row.append('F')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

