OBSERVATION = {'region': [[0, 1, 2, 3, 3, 4], [0, 1, 2, 3, 3, 4], [0, 2, 2, 5, 6, 7], [8, 8, 9, 10, 11, 7], [8, 8, 9, 10, 11, 12], [13, 14, 14, 15, 15, 12]], 'row_water_counts': [1, 1, 4, 2, 4, 2], 'col_water_counts': [3, 5, 2, 2, 1, 1]}

def solve(observation):
    region_grid = observation['region']
    row_clues = observation['row_water_counts']
    col_clues = observation['col_water_counts']

    R = len(region_grid)
    C = len(region_grid[0])

    # Group cells by region
    regions = {}
    for r in range(R):
        for c in range(C):
            reg_id = region_grid[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))

    # Determine possible water levels for each region.
    # A level 'L' means all cells in the region with row >= L are water.
    # 'inf' means the region is completely empty.
    domains = {}
    for reg_id, cells in regions.items():
        rows = sorted(list(set(r for r, c in cells)))
        domains[reg_id] = rows + [float('inf')]

    def get_bounds(assignment, current_domains):
        """Calculates the minimum and maximum possible water cells for each row and column."""
        min_row = [0] * R
        max_row = [0] * R
        min_col = [0] * C
        max_col = [0] * C

        for r in range(R):
            for c in range(C):
                reg_id = region_grid[r][c]
                if reg_id in assignment:
                    if r >= assignment[reg_id]:
                        min_row[r] += 1
                        max_row[r] += 1
                        min_col[c] += 1
                        max_col[c] += 1
                else:
                    possible_levels = current_domains[reg_id]
                    can_be_water = any(r >= lvl for lvl in possible_levels)
                    can_be_empty = any(r < lvl for lvl in possible_levels)

                    if can_be_water:
                        max_row[r] += 1
                        max_col[c] += 1
                    if not can_be_empty:
                        min_row[r] += 1
                        min_col[c] += 1

        return min_row, max_row, min_col, max_col

    def reduce_domains(assignment, current_domains):
        """Applies constraint propagation to reduce domains of unassigned regions."""
        changed = True
        while changed:
            changed = False
            for reg_id in list(current_domains.keys()):
                if reg_id in assignment:
                    continue
                valid_levels = []
                for lvl in current_domains[reg_id]:
                    # Temporarily assign the level to check bounds
                    assignment[reg_id] = lvl
                    min_row, max_row, min_col, max_col = get_bounds(assignment, current_domains)

                    is_possible = True
                    for r in range(R):
                        if min_row[r] > row_clues[r] or max_row[r] < row_clues[r]:
                            is_possible = False
                            break
                    if is_possible:
                        for c in range(C):
                            if min_col[c] > col_clues[c] or max_col[c] < col_clues[c]:
                                is_possible = False
                                break
                    if is_possible:
                        valid_levels.append(lvl)

                del assignment[reg_id]

                if len(valid_levels) < len(current_domains[reg_id]):
                    current_domains[reg_id] = valid_levels
                    changed = True

            # If any domain becomes empty, we've hit a contradiction
            if any(len(d) == 0 for d in current_domains.values()):
                return False
        return True

    def backtrack(assignment, current_domains):
        """Recursive backtracking search with forward checking."""
        if not reduce_domains(assignment, current_domains):
            return None

        unassigned = [r for r in current_domains if r not in assignment]
        if not unassigned:
            # Verify exact match when all regions are assigned
            min_row, max_row, min_col, max_col = get_bounds(assignment, current_domains)
            if min_row == row_clues and min_col == col_clues:
                return assignment
            return None

        # Heuristic: pick the region with the fewest remaining possible levels
        unassigned.sort(key=lambda x: len(current_domains[x]))
        reg_id = unassigned[0]

        for lvl in current_domains[reg_id]:
            assignment[reg_id] = lvl
            # Deep copy domains to isolate branches
            new_domains = {k: v[:] for k, v in current_domains.items()}
            new_domains[reg_id] = [lvl]

            result = backtrack(assignment, new_domains)
            if result:
                return result

            del assignment[reg_id]

        return None

    initial_domains = {k: v[:] for k, v in domains.items()}
    solution = backtrack({}, initial_domains)

    if solution:
        ans = []
        for r in range(R):
            row_ans = []
            for c in range(C):
                reg_id = region_grid[r][c]
                if r >= solution[reg_id]:
                    row_ans.append('W')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return str(ans)
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
