def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    state = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] is not None:
                state[(r, c)] = grid[r][c]

    # Precompute 2x2 blocks for fast checking
    blocks = []
    for r in range(R - 1):
        for c in range(C - 1):
            blocks.append([(r, c), (r+1, c), (r, c+1), (r+1, c+1)])

    # Precompute orthogonal neighbors
    neighbors = {}
    for r in range(R):
        for c in range(C):
            nbs = []
            if r > 0: nbs.append((r-1, c))
            if r < R - 1: nbs.append((r+1, c))
            if c > 0: nbs.append((r, c-1))
            if c < C - 1: nbs.append((r, c+1))
            neighbors[(r, c)] = nbs

    def get_reachable(color, current_state):
        """
        Returns the set of all cells that can be reached from the current cells of `color`.
        If the current cells of `color` are already disconnected, returns None.
        """
        color_cells = [pos for pos, val in current_state.items() if val == color]
        opp_color = 'W' if color == 'B' else 'B'

        # If no cells of this color exist yet, any cell not of the opposite color is potentially reachable
        if not color_cells:
            return set([(r, c) for r in range(R) for c in range(C) if current_state.get((r, c)) != opp_color])

        start = color_cells[0]
        visited = set([start])
        queue = [start]

        # BFS to find all reachable cells using empty cells and cells of the same color
        while queue:
            curr = queue.pop(0)
            for nb in neighbors[curr]:
                if nb not in visited and current_state.get(nb) != opp_color:
                    visited.add(nb)
                    queue.append(nb)

        # If any already assigned cell of this color is not reachable, the state is invalid
        for cell in color_cells:
            if cell not in visited:
                return None

        return visited

    def check_2x2(current_state):
        """Checks if there are any fully colored 2x2 blocks of the same color."""
        for block in blocks:
            colors = [current_state.get(pos) for pos in block]
            if colors.count('B') == 4 or colors.count('W') == 4:
                return False
        return True

    def propagate(current_state):
        """Applies deductive rules to force cell colors and prune invalid states."""
        state = current_state.copy()
        while True:
            changed = False

            # 1. 2x2 Rule Deductions
            for block in blocks:
                colors = [state.get(pos) for pos in block]
                b_count = colors.count('B')
                w_count = colors.count('W')

                if b_count == 4 or w_count == 4:
                    return None # Contradiction

                if b_count == 3 and colors.count(None) == 1:
                    pos = block[colors.index(None)]
                    if pos not in state:
                        state[pos] = 'W'
                        changed = True
                elif w_count == 3 and colors.count(None) == 1:
                    pos = block[colors.index(None)]
                    if pos not in state:
                        state[pos] = 'B'
                        changed = True

            # 2. Global Reachability Deductions
            reachable_B = get_reachable('B', state)
            if reachable_B is None: return None
            reachable_W = get_reachable('W', state)
            if reachable_W is None: return None

            unassigned = [(r, c) for r in range(R) for c in range(C) if (r, c) not in state]
            for pos in unassigned:
                if pos not in reachable_B and pos not in reachable_W:
                    return None # Cell cannot be B or W
                if pos not in reachable_B:
                    state[pos] = 'W'
                    changed = True
                elif pos not in reachable_W:
                    state[pos] = 'B'
                    changed = True

            # 3. 1-Step Lookahead (Articulation Points)
            # Only run if simpler deductions didn't change anything to save computation
            if not changed:
                for pos in unassigned:
                    # Try assigning Black
                    state[pos] = 'B'
                    b_ok = get_reachable('B', state) is not None and get_reachable('W', state) is not None and check_2x2(state)

                    # Try assigning White
                    state[pos] = 'W'
                    w_ok = get_reachable('B', state) is not None and get_reachable('W', state) is not None and check_2x2(state)

                    del state[pos] # Revert

                    if not b_ok and not w_ok:
                        return None # Both assignments lead to immediate contradiction
                    elif b_ok and not w_ok:
                        state[pos] = 'B'
                        changed = True
                        break # Restart propagation with new information
                    elif w_ok and not b_ok:
                        state[pos] = 'W'
                        changed = True
                        break

            if not changed:
                break

        return state

    def solve_recursive(current_state):
        """Backtracking search with aggressive constraint propagation."""
        current_state = propagate(current_state)
        if current_state is None: 
            return None

        unassigned = [(r, c) for r in range(R) for c in range(C) if (r, c) not in current_state]
        if not unassigned:
            return current_state # All cells assigned and valid

        # Heuristic: Pick the most constrained cell (most assigned neighbors)
        best_cell = None
        max_assigned_nbs = -1
        max_nbs = -1
        for pos in unassigned:
            assigned_nbs = sum(1 for nb in neighbors[pos] if nb in current_state)
            total_nbs = len(neighbors[pos])
            if assigned_nbs > max_assigned_nbs or (assigned_nbs == max_assigned_nbs and total_nbs > max_nbs):
                max_assigned_nbs = assigned_nbs
                max_nbs = total_nbs
                best_cell = pos

        # Branching
        for color in ['B', 'W']:
            next_state = current_state.copy()
            next_state[best_cell] = color
            result = solve_recursive(next_state)
            if result:
                return result

        return None

    solution = solve_recursive(state)
    if solution:
        res = []
        for r in range(R):
            row = []
            for c in range(C):
                row.append(solution[(r, c)])
            res.append(row)
        return res
    return "No Solution"

