OBSERVATION = {'data': [[None, 'W', None, None, None, None], [None, None, None, 'W', None, None], [None, None, 'B', 'B', 'B', 'B'], [None, 'B', None, None, 'B', None], [None, None, 'W', None, None, None], [None, None, None, None, None, None]]}

def solve(observation):
    grid = [row[:] for row in observation['data']]
    R = len(grid)
    C = len(grid[0])

    def is_valid_2x2(r, c, g):
        """
        Checks if the 2x2 block starting at top-left (r, c) is valid.
        Rules: No 2x2 can be all 'B' or all 'W'. No 2x2 checkerboard pattern.
        """
        cells = [g[r][c], g[r][c+1], g[r+1][c], g[r+1][c+1]]
        if None in cells:
            return True
        b_count = cells.count('B')
        w_count = cells.count('W')
        if b_count == 4 or w_count == 4:
            return False
        # Check for checkerboard pattern
        if b_count == 2 and w_count == 2:
            if g[r][c] == g[r+1][c+1] and g[r][c+1] == g[r+1][c]:
                return False
        return True

    def check_and_deduce_connectivity(g, color):
        """
        Checks if all cells of `color` can potentially be connected.
        If they can, it also deduces if any `None` cells are unreachable by this color,
        forcing them to be the opposite color.
        """
        start = None
        total_color = 0
        for r in range(R):
            for c in range(C):
                if g[r][c] == color:
                    total_color += 1
                    if start is None:
                        start = (r, c)

        if total_color == 0:
            return True, False

        visited = set()
        q = [start]
        visited.add(start)
        reached_color = 0

        # BFS to find all reachable cells for the given color
        while q:
            curr_r, curr_c = q.pop(0)
            if g[curr_r][curr_c] == color:
                reached_color += 1

            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    if (nr, nc) not in visited:
                        if g[nr][nc] == color or g[nr][nc] is None:
                            visited.add((nr, nc))
                            q.append((nr, nc))

        # If we couldn't reach all existing cells of this color, state is invalid
        if reached_color < total_color:
            return False, False

        changed = False
        opp_color = 'W' if color == 'B' else 'B'

        # Any unassigned cell that cannot be reached MUST be the opposite color
        for r in range(R):
            for c in range(C):
                if g[r][c] is None and (r, c) not in visited:
                    g[r][c] = opp_color
                    changed = True

        return True, changed

    def propagate(g):
        """
        Aggressively applies local 2x2 constraints and global connectivity constraints
        to deduce forced cell assignments.
        """
        changed = True
        while changed:
            changed = False

            # 1. Local 2x2 Propagation
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
                    vals = [g[nr][nc] for nr, nc in cells]
                    none_count = vals.count(None)

                    if none_count == 0:
                        if not is_valid_2x2(r, c, g):
                            return False
                    elif none_count == 1:
                        idx = vals.index(None)
                        nr, nc = cells[idx]

                        valid_colors = []
                        for color in ['B', 'W']:
                            g[nr][nc] = color
                            if is_valid_2x2(r, c, g):
                                valid_colors.append(color)
                        g[nr][nc] = None # Revert for now

                        if len(valid_colors) == 0:
                            return False # Contradiction found
                        elif len(valid_colors) == 1:
                            g[nr][nc] = valid_colors[0]
                            changed = True

            # 2. Global Connectivity Propagation
            valid, conn_changed = check_and_deduce_connectivity(g, 'B')
            if not valid: return False
            if conn_changed: changed = True

            valid, conn_changed = check_and_deduce_connectivity(g, 'W')
            if not valid: return False
            if conn_changed: changed = True

        return True

    def get_unassigned(g):
        """
        Heuristic: Pick the unassigned cell with the most assigned neighbors
        to maximize constraint triggering.
        """
        best_cell = None
        max_neighbors = -1
        for r in range(R):
            for c in range(C):
                if g[r][c] is None:
                    neighbors = 0
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C and g[nr][nc] is not None:
                            neighbors += 1
                    if neighbors > max_neighbors:
                        max_neighbors = neighbors
                        best_cell = (r, c)
        return best_cell

    def count_components(color, g):
        """Counts the number of orthogonally connected components of a given color."""
        visited = set()
        components = 0
        for r in range(R):
            for c in range(C):
                if g[r][c] == color and (r,c) not in visited:
                    components += 1
                    q = [(r,c)]
                    visited.add((r,c))
                    while q:
                        curr_r, curr_c = q.pop(0)
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == color and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                q.append((nr,nc))
        return components

    def backtrack(g_curr):
        """Main recursive backtracking search with constraint propagation."""
        if not propagate(g_curr):
            return False

        unassigned = get_unassigned(g_curr)
        if unassigned is None:
            # Fully assigned, verify final strict connectivity rule
            if count_components('B', g_curr) == 1 and count_components('W', g_curr) == 1:
                return True
            return False

        r, c = unassigned
        for color in ['B', 'W']:
            g_next = [row[:] for row in g_curr]
            g_next[r][c] = color
            if backtrack(g_next):
                # If successful, bubble up the solution
                for i in range(R):
                    for j in range(C):
                        g_curr[i][j] = g_next[i][j]
                return True

        return False

    if backtrack(grid):
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
