def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Identify all unique regions
    regions = set()
    for r in range(N):
        for c in range(N):
            regions.add(grid[r][c])

    def get_region_cells(reg_id):
        return [(r, c) for r in range(N) for c in range(N) if grid[r][c] == reg_id]

    # Initialize domains: domains[r][c] is True if a star can be placed at (r, c)
    domains = [[True] * N for _ in range(N)]

    def is_valid_state(current_domains):
        # Check if any row, col, or region has 0 possible cells left
        for i in range(N):
            if not any(current_domains[i][c] for c in range(N)): return False
            if not any(current_domains[r][i] for r in range(N)): return False
        for reg in regions:
            if not any(current_domains[r][c] for r, c in get_region_cells(reg)): return False
        return True

    def propagate(current_domains):
        changed = True
        while changed:
            changed = False
            forced_stars = []

            # 1. Hidden Singles: Check rows, cols, regions for single available cells
            for i in range(N):
                # Row check
                possible_cols = [c for c in range(N) if current_domains[i][c]]
                if len(possible_cols) == 1:
                    forced_stars.append((i, possible_cols[0]))
                # Col check
                possible_rows = [r for r in range(N) if current_domains[r][i]]
                if len(possible_rows) == 1:
                    forced_stars.append((possible_rows[0], i))

            for reg in regions:
                possible_cells = [(r, c) for r, c in get_region_cells(reg) if current_domains[r][c]]
                if len(possible_cells) == 1:
                    forced_stars.append(possible_cells[0])

            # Apply forced stars
            if forced_stars:
                for r, c in forced_stars:
                    if not current_domains[r][c]: continue # Might have been invalidated by another forced star

                    # Eliminate row and col
                    for i in range(N):
                        if i != c and current_domains[r][i]:
                            current_domains[r][i] = False
                            changed = True
                        if i != r and current_domains[i][c]:
                            current_domains[i][c] = False
                            changed = True

                    # Eliminate neighbors (including diagonal)
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0: continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N and current_domains[nr][nc]:
                                current_domains[nr][nc] = False
                                changed = True

                    # Eliminate region
                    reg = grid[r][c]
                    for rr, cc in get_region_cells(reg):
                        if (rr, cc) != (r, c) and current_domains[rr][cc]:
                            current_domains[rr][cc] = False
                            changed = True

            # 2. Line/Box Reduction
            for reg in regions:
                possible_cells = [(r, c) for r, c in get_region_cells(reg) if current_domains[r][c]]
                if not possible_cells: continue

                # If all possible cells for a region are in the same row, eliminate other cells in that row
                rows = set(r for r, c in possible_cells)
                if len(rows) == 1:
                    r = list(rows)[0]
                    for c in range(N):
                        if grid[r][c] != reg and current_domains[r][c]:
                            current_domains[r][c] = False
                            changed = True

                # If all possible cells for a region are in the same col, eliminate other cells in that col
                cols = set(c for r, c in possible_cells)
                if len(cols) == 1:
                    c = list(cols)[0]
                    for r in range(N):
                        if grid[r][c] != reg and current_domains[r][c]:
                            current_domains[r][c] = False
                            changed = True

        return is_valid_state(current_domains)

    def solve_recursive(current_domains, row):
        if row == N:
            # All rows processed, verify final state
            stars = []
            for r in range(N):
                cols = [c for c in range(N) if current_domains[r][c]]
                if len(cols) != 1: return None
                stars.append((r, cols[0]))

            # Verify region constraint
            reg_counts = {reg: 0 for reg in regions}
            for r, c in stars:
                reg_counts[grid[r][c]] += 1
            if any(count != 1 for count in reg_counts.values()): return None

            # Format output
            ans = [[None for _ in range(N)] for _ in range(N)]
            for r, c in stars:
                ans[r][c] = 'S'
            return ans

        # Try placing a star in each valid column of the current row
        for col in range(N):
            if current_domains[row][col]:
                # Clone domains for backtracking
                next_domains = [list(d) for d in current_domains]

                # Apply placement constraints
                for i in range(N):
                    if i != col: next_domains[row][i] = False
                    if i != row: next_domains[i][col] = False
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = row + dr, col + dc
                        if 0 <= nr < N and 0 <= nc < N:
                            next_domains[nr][nc] = False
                reg = grid[row][col]
                for rr, cc in get_region_cells(reg):
                    if (rr, cc) != (row, col):
                        next_domains[rr][cc] = False

                # Propagate constraints and recurse if valid
                if propagate(next_domains):
                    res = solve_recursive(next_domains, row + 1)
                    if res: return res

        return None

    # Initial constraint propagation
    if not propagate(domains):
        return "No Solution"

    ans = solve_recursive(domains, 0)
    return ans if ans else "No Solution"

