OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, 2, None], [None, None, 4, None, None, None, None], [None, 1, None, None, None, 4, None], [None, None, None, None, 4, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, None, None, None]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])
    BLACK = 1
    WHITE = 2
    UNKNOWN = 0

    numbers = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                numbers[(r, c)] = data[r][c]

    def neighbors(r, c):
        res = []
        if r > 0: res.append((r-1, c))
        if r < R - 1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < C - 1: res.append((r, c+1))
        return res

    def get_components(allowed_colors, grid):
        visited = set()
        components = []
        for r in range(R):
            for c in range(C):
                if (r, c) not in visited and grid[r][c] in allowed_colors:
                    comp = set()
                    q = [(r, c)]
                    visited.add((r, c))
                    while q:
                        curr_r, curr_c = q.pop(0)
                        comp.add((curr_r, curr_c))
                        for nr, nc in neighbors(curr_r, curr_c):
                            if (nr, nc) not in visited and grid[nr][nc] in allowed_colors:
                                visited.add((nr, nc))
                                q.append((nr, nc))
                    components.append(comp)
        return components

    def get_all_shapes(r, c, v, grid):
        if v == 1:
            is_valid = True
            for nr, nc in neighbors(r, c):
                if grid[nr][nc] == WHITE:
                    is_valid = False
                    break
            if is_valid:
                return [frozenset({(r, c)})]
            return []

        shapes = {frozenset({(r, c)})}
        for _ in range(v - 1):
            next_shapes = set()
            for shape in shapes:
                shape_neighbors = set()
                for sr, sc in shape:
                    for nr, nc in neighbors(sr, sc):
                        if (nr, nc) not in shape and grid[nr][nc] in (WHITE, UNKNOWN):
                            shape_neighbors.add((nr, nc))
                for nr, nc in shape_neighbors:
                    next_shapes.add(shape | {(nr, nc)})
            shapes = next_shapes

        valid_shapes = []
        for shape in shapes:
            is_valid = True
            for sr, sc in shape:
                if (sr, sc) in numbers and (sr, sc) != (r, c):
                    is_valid = False
                    break
            if not is_valid: continue

            for sr, sc in shape:
                for nr, nc in neighbors(sr, sc):
                    if (nr, nc) not in shape and grid[nr][nc] == WHITE:
                        is_valid = False
                        break
                if not is_valid: break

            if is_valid:
                valid_shapes.append(shape)

        return valid_shapes

    def deduce(grid):
        while True:
            changed = False

            shapes_for_num = {}
            possible_white_cells = set()

            for (r, c), v in numbers.items():
                shapes = get_all_shapes(r, c, v, grid)
                if not shapes:
                    return False
                shapes_for_num[(r, c)] = shapes
                for shape in shapes:
                    possible_white_cells.update(shape)

            for r in range(R):
                for c in range(C):
                    if grid[r][c] == WHITE and (r, c) not in possible_white_cells:
                        return False

            for r in range(R):
                for c in range(C):
                    if grid[r][c] == UNKNOWN and (r, c) not in possible_white_cells:
                        grid[r][c] = BLACK
                        changed = True

            white_cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == WHITE]
            for wr, wc in white_cells:
                capable_nums = []
                for num_pos, shapes in shapes_for_num.items():
                    if any((wr, wc) in shape for shape in shapes):
                        capable_nums.append(num_pos)

                if len(capable_nums) == 0:
                    return False
                elif len(capable_nums) == 1:
                    num_pos = capable_nums[0]
                    filtered_shapes = [s for s in shapes_for_num[num_pos] if (wr, wc) in s]
                    if len(filtered_shapes) < len(shapes_for_num[num_pos]):
                        shapes_for_num[num_pos] = filtered_shapes
                        changed = True

            for num_pos, shapes in shapes_for_num.items():
                if not shapes: return False
                intersection = set.intersection(*[set(s) for s in shapes])
                for r, c in intersection:
                    if grid[r][c] == UNKNOWN:
                        grid[r][c] = WHITE
                        changed = True

            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                    blacks = sum(1 for cr, cc in cells if grid[cr][cc] == BLACK)
                    unknowns = [ (cr, cc) for cr, cc in cells if grid[cr][cc] == UNKNOWN ]
                    if blacks == 4:
                        return False
                    if blacks == 3 and len(unknowns) == 1:
                        ur, uc = unknowns[0]
                        grid[ur][uc] = WHITE
                        changed = True

            bu_components = get_components({BLACK, UNKNOWN}, grid)
            black_comps = [comp for comp in bu_components if any(grid[r][c] == BLACK for r, c in comp)]

            if len(black_comps) > 1:
                return False

            if len(black_comps) == 1:
                main_comp = black_comps[0]
                for r in range(R):
                    for c in range(C):
                        if grid[r][c] == UNKNOWN and (r, c) not in main_comp:
                            grid[r][c] = WHITE
                            changed = True

                b_cells = [(r, c) for r, c in main_comp if grid[r][c] == BLACK]
                if len(b_cells) > 1:
                    for r, c in list(main_comp):
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = WHITE
                            visited = set()
                            q = [b_cells[0]]
                            visited.add(b_cells[0])
                            connected_b_count = 1
                            while q:
                                curr_r, curr_c = q.pop(0)
                                for nr, nc in neighbors(curr_r, curr_c):
                                    if (nr, nc) not in visited and grid[nr][nc] in {BLACK, UNKNOWN}:
                                        visited.add((nr, nc))
                                        q.append((nr, nc))
                                        if grid[nr][nc] == BLACK:
                                            connected_b_count += 1
                            if connected_b_count < len(b_cells):
                                grid[r][c] = BLACK
                                changed = True
                            else:
                                grid[r][c] = UNKNOWN

            if not changed:
                break

        return True

    def is_solved(grid):
        for r in range(R):
            for c in range(C):
                if grid[r][c] == UNKNOWN:
                    return False
        for r in range(R - 1):
            for c in range(C - 1):
                if all(grid[r+dr][c+dc] == BLACK for dr in (0,1) for dc in (0,1)):
                    return False
        b_cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == BLACK]
        if b_cells:
            visited = set()
            q = [b_cells[0]]
            visited.add(b_cells[0])
            count = 0
            while q:
                curr_r, curr_c = q.pop(0)
                count += 1
                for nr, nc in neighbors(curr_r, curr_c):
                    if (nr, nc) not in visited and grid[nr][nc] == BLACK:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            if count != len(b_cells):
                return False
        w_cells = set((r, c) for r in range(R) for c in range(C) if grid[r][c] == WHITE)
        for (nr, nc), v in numbers.items():
            if grid[nr][nc] != WHITE: return False
            visited = set()
            q = [(nr, nc)]
            visited.add((nr, nc))
            while q:
                curr_r, curr_c = q.pop(0)
                for n_r, n_c in neighbors(curr_r, curr_c):
                    if (n_r, n_c) in w_cells and (n_r, n_c) not in visited:
                        visited.add((n_r, n_c))
                        q.append((n_r, n_c))
            if len(visited) != v: return False
            w_cells -= visited
        if w_cells: return False
        return True

    def backtrack(grid):
        if not deduce(grid):
            return None

        if is_solved(grid):
            return grid

        best_cell = None
        for r in range(R):
            for c in range(C):
                if grid[r][c] == UNKNOWN:
                    for nr, nc in neighbors(r, c):
                        if grid[nr][nc] != UNKNOWN:
                            best_cell = (r, c)
                            break
                if best_cell: break
            if best_cell: break

        if not best_cell:
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == UNKNOWN:
                        best_cell = (r, c)
                        break
                if best_cell: break

        if not best_cell:
            return None

        r, c = best_cell

        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = BLACK
        res = backtrack(grid_copy)
        if res: return res

        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = WHITE
        res = backtrack(grid_copy)
        if res: return res

        return None

    initial_grid = [[UNKNOWN for _ in range(C)] for _ in range(R)]
    for (r, c), v in numbers.items():
        initial_grid[r][c] = WHITE

    result_grid = backtrack(initial_grid)

    if result_grid:
        res = []
        for r in range(R):
            row = []
            for c in range(C):
                if result_grid[r][c] == BLACK:
                    row.append('B')
                else:
                    row.append(None)
            res.append(row)
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
