class NurikabeSolver:
    def __init__(self, grid):
        self.R = len(grid)
        self.C = len(grid[0])
        self.targets = {}
        for r in range(self.R):
            for c in range(self.C):
                if grid[r][c] is not None:
                    self.targets[(r, c)] = grid[r][c]

        self.color = [[0 for _ in range(self.C)] for _ in range(self.R)] # 0: UNK, 1: BLACK, 2: WHITE
        self.island = [[None for _ in range(self.C)] for _ in range(self.R)]

        self.island_list = list(self.targets.keys())
        for i, (r, c) in enumerate(self.island_list):
            self.color[r][c] = 2
            self.island[r][c] = i

    def neighbors(self, r, c):
        res = []
        if r > 0: res.append((r-1, c))
        if r < self.R - 1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < self.C - 1: res.append((r, c+1))
        return res

    def save_state(self):
        return (
            [row[:] for row in self.color],
            [row[:] for row in self.island]
        )

    def restore_state(self, state):
        self.color = [row[:] for row in state[0]]
        self.island = [row[:] for row in state[1]]

    def propagate(self):
        while True:
            changed_simple = True
            while changed_simple:
                changed_simple = False

                # 1. 2x2 Black
                for r in range(self.R - 1):
                    for c in range(self.C - 1):
                        cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                        blacks = [p for p in cells if self.color[p[0]][p[1]] == 1]
                        unks = [p for p in cells if self.color[p[0]][p[1]] == 0]
                        if len(blacks) == 4:
                            return False
                        if len(blacks) == 3 and len(unks) == 1:
                            ur, uc = unks[0]
                            self.color[ur][uc] = 2
                            changed_simple = True

                # 2. Island separation & White connectivity
                for r in range(self.R):
                    for c in range(self.C):
                        if self.color[r][c] == 0:
                            adj_islands = set()
                            for nr, nc in self.neighbors(r, c):
                                if self.island[nr][nc] is not None:
                                    adj_islands.add(self.island[nr][nc])
                            if len(adj_islands) > 1:
                                self.color[r][c] = 1
                                changed_simple = True
                        elif self.color[r][c] == 2:
                            adj_islands = set()
                            for nr, nc in self.neighbors(r, c):
                                if self.island[nr][nc] is not None:
                                    adj_islands.add(self.island[nr][nc])
                            if self.island[r][c] is None:
                                if len(adj_islands) == 1:
                                    self.island[r][c] = list(adj_islands)[0]
                                    changed_simple = True
                                elif len(adj_islands) > 1:
                                    return False
                            else:
                                if any(isl != self.island[r][c] for isl in adj_islands):
                                    return False

                # 3. Island completion
                island_sizes = {i: 0 for i in range(len(self.island_list))}
                for r in range(self.R):
                    for c in range(self.C):
                        if self.island[r][c] is not None:
                            island_sizes[self.island[r][c]] += 1

                for i, root in enumerate(self.island_list):
                    target = self.targets[root]
                    if island_sizes[i] > target:
                        return False
                    if island_sizes[i] == target:
                        for r in range(self.R):
                            for c in range(self.C):
                                if self.island[r][c] == i:
                                    for nr, nc in self.neighbors(r, c):
                                        if self.color[nr][nc] == 0:
                                            self.color[nr][nc] = 1
                                            changed_simple = True
                                        elif self.color[nr][nc] == 2 and self.island[nr][nc] is None:
                                            return False

                # 4. Unreachable cells
                reachable_by = { (r, c): set() for r in range(self.R) for c in range(self.C) if self.color[r][c] == 0 }
                for i, root in enumerate(self.island_list):
                    target = self.targets[root]
                    current_size = island_sizes[i]
                    if current_size == target:
                        continue

                    q = []
                    dist = {}
                    for r in range(self.R):
                        for c in range(self.C):
                            if self.island[r][c] == i:
                                q.append((r, c))
                                dist[(r, c)] = 0

                    head = 0
                    while head < len(q):
                        r, c = q[head]
                        head += 1
                        d = dist[(r, c)]
                        if self.color[r][c] == 0:
                            reachable_by[(r, c)].add(i)

                        if current_size + d < target:
                            for nr, nc in self.neighbors(r, c):
                                if self.color[nr][nc] != 1 and self.island[nr][nc] in (None, i):
                                    if (nr, nc) not in dist:
                                        dist[(nr, nc)] = d + 1
                                        q.append((nr, nc))

                for r in range(self.R):
                    for c in range(self.C):
                        if self.color[r][c] == 0:
                            if len(reachable_by[(r, c)]) == 0:
                                self.color[r][c] = 1
                                changed_simple = True

                # 5. Black connectivity (simple check)
                black_cells = [(r, c) for r in range(self.R) for c in range(self.C) if self.color[r][c] == 1]
                if black_cells:
                    start = black_cells[0]
                    visited_all = set([start])
                    q = [start]
                    head = 0
                    while head < len(q):
                        curr_r, curr_c = q[head]
                        head += 1
                        for nr, nc in self.neighbors(curr_r, curr_c):
                            if self.color[nr][nc] in (0, 1) and (nr, nc) not in visited_all:
                                visited_all.add((nr, nc))
                                q.append((nr, nc))
                    for br, bc in black_cells:
                        if (br, bc) not in visited_all:
                            return False

                # 6. Check isolated WHITE cells
                for r in range(self.R):
                    for c in range(self.C):
                        if self.color[r][c] == 2 and self.island[r][c] is None:
                            visited = set([(r, c)])
                            q = [(r, c)]
                            head = 0
                            reachable_islands = set()
                            while head < len(q):
                                curr_r, curr_c = q[head]
                                head += 1
                                for nr, nc in self.neighbors(curr_r, curr_c):
                                    if self.color[nr][nc] != 1 and (nr, nc) not in visited:
                                        visited.add((nr, nc))
                                        q.append((nr, nc))
                                        if self.island[nr][nc] is not None:
                                            reachable_islands.add(self.island[nr][nc])
                            if not reachable_islands:
                                return False

            # Expensive checks
            changed_expensive = False

            # Articulation points for Black
            black_cells = [(r, c) for r in range(self.R) for c in range(self.C) if self.color[r][c] == 1]
            if len(black_cells) > 1:
                for r in range(self.R):
                    for c in range(self.C):
                        if self.color[r][c] == 0:
                            start = None
                            for br, bc in black_cells:
                                if (br, bc) != (r, c):
                                    start = (br, bc)
                                    break
                            if start:
                                visited = set([start])
                                q = [start]
                                head = 0
                                while head < len(q):
                                    curr_r, curr_c = q[head]
                                    head += 1
                                    for nr, nc in self.neighbors(curr_r, curr_c):
                                        if (nr, nc) != (r, c) and self.color[nr][nc] in (0, 1) and (nr, nc) not in visited:
                                            visited.add((nr, nc))
                                            q.append((nr, nc))
                                disconnected = False
                                for br, bc in black_cells:
                                    if (br, bc) != (r, c) and (br, bc) not in visited:
                                        disconnected = True
                                        break
                                if disconnected:
                                    self.color[r][c] = 1
                                    changed_expensive = True

            if changed_expensive:
                continue

            # Island expansion articulation points
            island_sizes = {i: 0 for i in range(len(self.island_list))}
            for r in range(self.R):
                for c in range(self.C):
                    if self.island[r][c] is not None:
                        island_sizes[self.island[r][c]] += 1

            for i, root in enumerate(self.island_list):
                target = self.targets[root]
                current_size = island_sizes[i]
                if current_size < target:
                    for r in range(self.R):
                        for c in range(self.C):
                            if self.color[r][c] == 0:
                                visited = set()
                                q = []
                                for ir in range(self.R):
                                    for ic in range(self.C):
                                        if self.island[ir][ic] == i:
                                            visited.add((ir, ic))
                                            q.append((ir, ic))
                                head = 0
                                reachable_size = 0
                                while head < len(q):
                                    curr_r, curr_c = q[head]
                                    head += 1
                                    reachable_size += 1
                                    if reachable_size >= target:
                                        break
                                    for nr, nc in self.neighbors(curr_r, curr_c):
                                        if (nr, nc) != (r, c) and self.color[nr][nc] != 1 and self.island[nr][nc] in (None, i) and (nr, nc) not in visited:
                                            visited.add((nr, nc))
                                            q.append((nr, nc))
                                if reachable_size < target:
                                    self.color[r][c] = 2
                                    changed_expensive = True

            if changed_expensive:
                continue

            break

        return True

    def strong_propagate(self):
        if not self.propagate():
            return False
        while True:
            changed = False
            for r in range(self.R):
                for c in range(self.C):
                    if self.color[r][c] == 0:
                        # Try BLACK
                        saved_state = self.save_state()
                        self.color[r][c] = 1
                        res_black = self.propagate()
                        self.restore_state(saved_state)

                        # Try WHITE
                        saved_state = self.save_state()
                        self.color[r][c] = 2
                        res_white = self.propagate()
                        self.restore_state(saved_state)

                        if not res_black and not res_white:
                            return False
                        elif not res_black:
                            self.color[r][c] = 2
                            if not self.propagate(): return False
                            changed = True
                            break
                        elif not res_white:
                            self.color[r][c] = 1
                            if not self.propagate(): return False
                            changed = True
                            break
                if changed:
                    break
            if not changed:
                break
        return True

    def search(self):
        if not self.strong_propagate():
            return None

        best_cell = None
        min_options = 999

        for r in range(self.R):
            for c in range(self.C):
                if self.color[r][c] == 0:
                    score = 0
                    for nr, nc in self.neighbors(r, c):
                        if self.island[nr][nc] is not None:
                            score -= 10
                        elif self.color[nr][nc] == 1:
                            score -= 1

                    if score < min_options:
                        min_options = score
                        best_cell = (r, c)

        if best_cell is None:
            for r in range(self.R):
                for c in range(self.C):
                    if self.color[r][c] == 0:
                        return None
                    if self.color[r][c] == 2 and self.island[r][c] is None:
                        return None

            island_sizes = {i: 0 for i in range(len(self.island_list))}
            for r in range(self.R):
                for c in range(self.C):
                    if self.island[r][c] is not None:
                        island_sizes[self.island[r][c]] += 1
            for i, root in enumerate(self.island_list):
                if island_sizes[i] != self.targets[root]:
                    return None

            black_cells = [(r, c) for r in range(self.R) for c in range(self.C) if self.color[r][c] == 1]
            if black_cells:
                start = black_cells[0]
                visited = set([start])
                q = [start]
                head = 0
                while head < len(q):
                    curr_r, curr_c = q[head]
                    head += 1
                    for nr, nc in self.neighbors(curr_r, curr_c):
                        if self.color[nr][nc] == 1 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                if len(visited) != len(black_cells):
                    return None

            for r in range(self.R - 1):
                for c in range(self.C - 1):
                    if self.color[r][c] == 1 and self.color[r+1][c] == 1 and self.color[r][c+1] == 1 and self.color[r+1][c+1] == 1:
                        return None

            return self.format_result()

        r, c = best_cell

        saved_state = self.save_state()
        self.color[r][c] = 1
        res = self.search()
        if res:
            return res

        self.restore_state(saved_state)

        self.color[r][c] = 2
        res = self.search()
        if res:
            return res

        self.restore_state(saved_state)
        return None

    def format_result(self):
        res = []
        for r in range(self.R):
            row = []
            for c in range(self.C):
                if self.color[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            res.append(row)
        return res

def solve(observation):
    grid = observation['data']
    solver = NurikabeSolver(grid)
    res = solver.search()
    if res:
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
