OBSERVATION = {'data': [[None, None, None, None, None, 'W'], [None, None, 'B', 'W', None, None], [None, None, None, 'W', 'B', None], [None, None, 'W', None, 'W', None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None]]}

def solve(observation):
    grid = observation['data']
    N = len(grid)

    def is_2x2_valid(g):
        """Check if there are any 2x2 blocks of the same color."""
        for r in range(N-1):
            for c in range(N-1):
                b_count = 0
                w_count = 0
                for dr in (0, 1):
                    for dc in (0, 1):
                        val = g[r+dr][c+dc]
                        if val == 'B': b_count += 1
                        elif val == 'W': w_count += 1
                if b_count == 4 or w_count == 4:
                    return False
        return True

    def is_connectable(color, g):
        """
        Check if all cells of the given color can potentially be connected.
        This does a BFS through cells of `color` and `None`.
        """
        cells = []
        for r in range(N):
            for c in range(N):
                if g[r][c] == color:
                    cells.append((r, c))
        if not cells:
            return True

        start = cells[0]
        q = [start]
        visited = [[False]*N for _ in range(N)]
        visited[start[0]][start[1]] = True
        count = 1

        head = 0
        while head < len(q):
            curr_r, curr_c = q[head]
            head += 1
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < N and 0 <= nc < N and not visited[nr][nc]:
                    if g[nr][nc] in (color, None):
                        visited[nr][nc] = True
                        q.append((nr, nc))
                        if g[nr][nc] == color:
                            count += 1

        return count == len(cells)

    def is_valid_final(g):
        """Strict check for the final filled grid."""
        if not is_2x2_valid(g): return False

        for color in ('B', 'W'):
            cells = [(r, c) for r in range(N) for c in range(N) if g[r][c] == color]
            if cells:
                visited = set()
                q = [cells[0]]
                visited.add(cells[0])
                head = 0
                while head < len(q):
                    curr = q[head]
                    head += 1
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr[0] + dr, curr[1] + dc
                        if 0 <= nr < N and 0 <= nc < N and g[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                if len(visited) != len(cells): return False
        return True

    def deduce(g):
        """
        Apply human-like logical deductions to aggressively prune the search space.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. 2x2 Rule Deductions
            for r in range(N-1):
                for c in range(N-1):
                    b_count = 0
                    w_count = 0
                    none_cell = None
                    for dr in (0, 1):
                        for dc in (0, 1):
                            val = g[r+dr][c+dc]
                            if val == 'B': b_count += 1
                            elif val == 'W': w_count += 1
                            else: none_cell = (r+dr, c+dc)

                    if b_count == 3 and w_count == 0 and none_cell:
                        g[none_cell[0]][none_cell[1]] = 'W'
                        changed = True
                    elif w_count == 3 and b_count == 0 and none_cell:
                        g[none_cell[0]][none_cell[1]] = 'B'
                        changed = True
                    elif b_count == 4 or w_count == 4:
                        return False

            # 2. Global Connectivity Check
            if not is_connectable('B', g) or not is_connectable('W', g):
                return False

            # 3. Essential Cell Deductions (Articulation Points / Choke Points)
            for r in range(N):
                for c in range(N):
                    if g[r][c] is None:
                        # Test setting to 'W'
                        g[r][c] = 'W'
                        valid_w = is_connectable('B', g) and is_connectable('W', g) and is_2x2_valid(g)

                        # Test setting to 'B'
                        g[r][c] = 'B'
                        valid_b = is_connectable('B', g) and is_connectable('W', g) and is_2x2_valid(g)

                        # Revert
                        g[r][c] = None

                        if not valid_w and not valid_b:
                            return False # Contradiction: neither color works
                        elif valid_w and not valid_b:
                            g[r][c] = 'W'
                            changed = True
                        elif valid_b and not valid_w:
                            g[r][c] = 'B'
                            changed = True

        return True

    def backtrack(g):
        """Backtracking search with constraint propagation."""
        g_copy = [row[:] for row in g]

        # Apply deductions first
        if not deduce(g_copy):
            return None

        empty_cells = [(r, c) for r in range(N) for c in range(N) if g_copy[r][c] is None]

        # Base case: grid is full
        if not empty_cells:
            if is_valid_final(g_copy):
                return g_copy
            return None

        # Heuristic: Pick the empty cell with the most filled neighbors to maximize constraints
        def count_filled_neighbors(r, c):
            cnt = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N and g_copy[nr][nc] is not None:
                        cnt += 1
            return cnt

        empty_cells.sort(key=lambda x: count_filled_neighbors(x[0], x[1]), reverse=True)
        r, c = empty_cells[0]

        # Branch 1: Try 'B'
        g_copy[r][c] = 'B'
        res = backtrack(g_copy)
        if res: return res

        # Branch 2: Try 'W'
        g_copy[r][c] = 'W'
        res = backtrack(g_copy)
        if res: return res

        return None

    solution = backtrack(grid)
    return solution if solution else "No Solution"

