OBSERVATION = {'data': [[0, 1, 1, 1, 2, 2, 3, 3], [0, 0, 4, 4, 5, 5, 3, 3], [0, 0, 4, 4, 5, 5, 3, 3], [0, 0, 4, 6, 6, 5, 7, 7], [0, 0, 4, 4, 4, 5, 7, 7], [8, 9, 9, 10, 10, 5, 11, 11], [8, 9, 9, 10, 10, 5, 11, 11], [9, 9, 9, 9, 9, 5, 12, 12]]}

def solve(observation):
    grid_data = observation['data']
    N = len(grid_data)

    regions = {}
    for r in range(N):
        for c in range(N):
            rid = grid_data[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    # grid: 0=unknown, 1=shaded, -1=unshaded
    grid = [[0]*N for _ in range(N)]

    def propagate(g):
        changed = True
        while changed:
            changed = False

            # Rule 1: Region counts (exactly 2 shaded cells per region)
            for rid, cells in regions.items():
                shaded = [c for c in cells if g[c[0]][c[1]] == 1]
                unshaded = [c for c in cells if g[c[0]][c[1]] == -1]
                unknown = [c for c in cells if g[c[0]][c[1]] == 0]

                if len(shaded) > 2: 
                    return False
                if len(shaded) == 2 and unknown:
                    for r, c in unknown:
                        g[r][c] = -1
                        changed = True
                if len(cells) - len(unshaded) < 2: 
                    return False
                if len(cells) - len(unshaded) == 2 and unknown:
                    for r, c in unknown:
                        g[r][c] = 1
                        changed = True

            # Rule 2 & 3: Domino rules (every shaded cell has exactly 1 shaded neighbor)
            for r in range(N):
                for c in range(N):
                    if g[r][c] == 1:
                        s_neighbors = []
                        u_neighbors = []
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if g[nr][nc] == 1: 
                                    s_neighbors.append((nr, nc))
                                elif g[nr][nc] == 0: 
                                    u_neighbors.append((nr, nc))

                        if len(s_neighbors) > 1: 
                            return False
                        if len(s_neighbors) == 1:
                            # Domino is complete, all other orthogonal neighbors must be unshaded
                            if u_neighbors:
                                for nr, nc in u_neighbors:
                                    g[nr][nc] = -1
                                    changed = True
                        elif len(s_neighbors) == 0:
                            if len(u_neighbors) == 0: 
                                return False
                            if len(u_neighbors) == 1:
                                nr, nc = u_neighbors[0]
                                g[nr][nc] = 1
                                changed = True

            # Rule 4: Prevent isolated cells that cannot form a domino
            for r in range(N):
                for c in range(N):
                    if g[r][c] == 0:
                        possible = 0
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N and g[nr][nc] != -1:
                                possible += 1
                        if possible == 0:
                            g[r][c] = -1
                            changed = True

        return True

    def is_valid_final(g):
        for rid, cells in regions.items():
            if sum(1 for r, c in cells if g[r][c] == 1) != 2: 
                return False
        for r in range(N):
            for c in range(N):
                if g[r][c] == 1:
                    s_neighbors = sum(1 for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] 
                                      if 0 <= r+dr < N and 0 <= c+dc < N and g[r+dr][c+dc] == 1)
                    if s_neighbors != 1: 
                        return False
        return True

    def search(g):
        if not propagate(g): 
            return None

        best_cell = None
        min_u = 999
        # Heuristic: pick an unknown cell in the region with the fewest unknown cells
        for rid, cells in regions.items():
            unknown = [c for c in cells if g[c[0]][c[1]] == 0]
            if 0 < len(unknown) < min_u:
                min_u = len(unknown)
                best_cell = unknown[0]

        if not best_cell:
            if is_valid_final(g): 
                return g
            return None

        r, c = best_cell

        # Try shading the cell
        g_copy = [row[:] for row in g]
        g_copy[r][c] = 1
        res = search(g_copy)
        if res: 
            return res

        # Try unshading the cell
        g_copy = [row[:] for row in g]
        g_copy[r][c] = -1
        return search(g_copy)

    res = search(grid)
    if res:
        ans = []
        for r in range(N):
            row = []
            for c in range(N):
                row.append('S' if res[r][c] == 1 else None)
            ans.append(row)
        return ans
    return "No Solution"

