    def get_shapes(r, c, T, k, N):
        shapes = []
        if T == 'W':
            # Horizontal straight segment
            for l in range(1, k):
                right = k - l
                shape = {}
                if c - l < 0 or c + right > N:
                    continue
                for i in range(c - l, c + right):
                    shape[tuple(sorted(((r, i), (r, i+1))))] = 1
                # Force turns at the ends
                if c - l - 1 >= 0:
                    shape[tuple(sorted(((r, c - l - 1), (r, c - l))))] = 0
                if c + right + 1 <= N:
                    shape[tuple(sorted(((r, c + right), (r, c + right + 1))))] = 0
                shapes.append(shape)

            # Vertical straight segment
            for u in range(1, k):
                d = k - u
                shape = {}
                if r - u < 0 or r + d > N:
                    continue
                for i in range(r - u, r + d):
                    shape[tuple(sorted(((i, c), (i+1, c))))] = 1
                # Force turns at the ends
                if r - u - 1 >= 0:
                    shape[tuple(sorted(((r - u - 1, c), (r - u, c))))] = 0
                if r + d + 1 <= N:
                    shape[tuple(sorted(((r + d, c), (r + d + 1, c))))] = 0
                shapes.append(shape)

        elif T == 'B':
            dirs = [
                ((-1, 0), (0, -1)), # Up, Left
                ((-1, 0), (0, 1)),  # Up, Right
                ((1, 0), (0, -1)),  # Down, Left
                ((1, 0), (0, 1))    # Down, Right
            ]
            for d1, d2 in dirs:
                for l1 in range(1, k):
                    l2 = k - l1
                    shape = {}

                    # Check bounds for the segments
                    end1_r, end1_c = r + d1[0]*l1, c + d1[1]*l1
                    if not (0 <= end1_r <= N and 0 <= end1_c <= N):
                        continue
                    end2_r, end2_c = r + d2[0]*l2, c + d2[1]*l2
                    if not (0 <= end2_r <= N and 0 <= end2_c <= N):
                        continue

                    # Add edges for first direction
                    curr_r, curr_c = r, c
                    for _ in range(l1):
                        next_r, next_c = curr_r + d1[0], curr_c + d1[1]
                        edge = tuple(sorted(((curr_r, curr_c), (next_r, next_c))))
                        shape[edge] = 1
                        curr_r, curr_c = next_r, next_c
                    # Force turn at the end of first segment
                    next_r, next_c = curr_r + d1[0], curr_c + d1[1]
                    if 0 <= next_r <= N and 0 <= next_c <= N:
                        edge = tuple(sorted(((curr_r, curr_c), (next_r, next_c))))
                        shape[edge] = 0

                    # Add edges for second direction
                    curr_r, curr_c = r, c
                    for _ in range(l2):
                        next_r, next_c = curr_r + d2[0], curr_c + d2[1]
                        edge = tuple(sorted(((curr_r, curr_c), (next_r, next_c))))
                        shape[edge] = 1
                        curr_r, curr_c = next_r, next_c
                    # Force turn at the end of second segment
                    next_r, next_c = curr_r + d2[0], curr_c + d2[1]
                    if 0 <= next_r <= N and 0 <= next_c <= N:
                        edge = tuple(sorted(((curr_r, curr_c), (next_r, next_c))))
                        shape[edge] = 0

                    # Ensure the loop turns AT the black circle
                    for d in [(-1,0), (1,0), (0,-1), (0,1)]:
                        if d != d1 and d != d2:
                            next_r, next_c = r + d[0], c + d[1]
                            if 0 <= next_r <= N and 0 <= next_c <= N:
                                edge = tuple(sorted(((r, c), (next_r, next_c))))
                                shape[edge] = 0

                    shapes.append(shape)
        return shapes

    all_shapes = []
    for r, c, T, k in clues:
        shapes = get_shapes(r, c, T, k, N)
        if not shapes:
            return "No Solution"
        all_shapes.append(shapes)

    # Sort clues by the number of valid shapes to prune the search tree early
    clue_order = list(range(len(clues)))
    clue_order.sort(key=lambda i: len(all_shapes[i]))

    def propagate(edge_state):
        changed = True
        while changed:
            changed = False
            degrees = { (r,c): 0 for r in range(N+1) for c in range(N+1) }
            possible_edges = { (r,c): [] for r in range(N+1) for c in range(N+1) }

            for r in range(N+1):
                for c in range(N+1):
                    for dr, dc in [(1,0), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr <= N and 0 <= nc <= N:
                            edge = tuple(sorted(((r, c), (nr, nc))))
                            val = edge_state.get(edge)
                            if val == 1:
                                degrees[(r, c)] += 1
                                degrees[(nr, nc)] += 1
                            elif val is None:
                                possible_edges[(r, c)].append(edge)
                                possible_edges[(nr, nc)].append(edge)

            for node, deg in degrees.items():
                poss = possible_edges[node]
                if deg > 2:
                    return False
                if deg == 2:
                    for e in poss:
                        edge_state[e] = 0
                        changed = True
                if deg == 1:
                    if len(poss) == 0:
                        return False
                    if len(poss) == 1:
                        edge_state[poss[0]] = 1
                        changed = True
                if deg == 0:
                    if len(poss) == 1:
                        edge_state[poss[0]] = 0
                        changed = True

                is_clue = any(r == node[0] and c == node[1] for r, c, _, _ in clues)
                if is_clue and deg + len(poss) < 2:
                    return False

            # Cycle detection
            adj = {node: [] for node in degrees}
            for edge, val in edge_state.items():
                if val == 1:
                    adj[edge[0]].append(edge[1])
                    adj[edge[1]].append(edge[0])

            visited = set()
            for start_node in adj:
                if start_node not in visited and len(adj[start_node]) > 0:
                    q = [(start_node, None)]
                    comp_visited = set()
                    cycle_found = False
                    while q:
                        curr, parent = q.pop(0)
                        if curr in comp_visited:
                            cycle_found = True
                            break
                        comp_visited.add(curr)
                        for neighbor in adj[curr]:
                            if neighbor != parent:
                                q.append((neighbor, curr))

                    if cycle_found:
                        clues_in_cycle = sum(1 for r, c, _, _ in clues if (r, c) in comp_visited)
                        if clues_in_cycle < len(clues):
                            return False
                        # If cycle contains all clues, force all other edges to 0
                        for r in range(N+1):
                            for c in range(N+1):
                                for dr, dc in [(1,0), (0,1)]:
                                    nr, nc = r + dr, c + dc
                                    if 0 <= nr <= N and 0 <= nc <= N:
                                        edge = tuple(sorted(((r, c), (nr, nc))))
                                        if edge not in edge_state:
                                            edge_state[edge] = 0
                                            changed = True
                    visited.update(comp_visited)
        return True

    def is_valid_solution(state):
        degrees = { (r,c): 0 for r in range(N+1) for c in range(N+1) }
        for edge, val in state.items():
            if val == 1:
                degrees[edge[0]] += 1
                degrees[edge[1]] += 1

        for d in degrees.values():
            if d != 0 and d != 2:
                return False

        start_node = None
        for node, d in degrees.items():
            if d == 2:
                start_node = node
                break
        if not start_node: return False

        adj = {node: [] for node in degrees}
        for edge, val in state.items():
            if val == 1:
                adj[edge[0]].append(edge[1])
                adj[edge[1]].append(edge[0])

        visited = set()
        curr = start_node
        prev = None
        while True:
            visited.add(curr)
            next_nodes = [n for n in adj[curr] if n != prev]
            if not next_nodes:
                break
            prev = curr
            curr = next_nodes[0]
            if curr == start_node:
                break

        for edge, val in state.items():
            if val == 1:
                if edge[0] not in visited or edge[1] not in visited:
                    return False

        for r, c, _, _ in clues:
            if (r, c) not in visited:
                return False

        return True

    def solve_remaining(state):
        if not propagate(state):
            return None

        unassigned = None
        degrees = { (r,c): 0 for r in range(N+1) for c in range(N+1) }
        possible_edges = { (r,c): [] for r in range(N+1) for c in range(N+1) }
        for r in range(N+1):
            for c in range(N+1):
                for dr, dc in [(1,0), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr <= N and 0 <= nc <= N:
                        edge = tuple(sorted(((r, c), (nr, nc))))
                        val = state.get(edge)
                        if val == 1:
                            degrees[(r, c)] += 1
                            degrees[(nr, nc)] += 1
                        elif val is None:
                            possible_edges[(r, c)].append(edge)
                            possible_edges[(nr, nc)].append(edge)

        # Prioritize edges connected to degree 1 nodes
        for node, deg in degrees.items():
            if deg == 1:
                if possible_edges[node]:
                    unassigned = possible_edges[node][0]
                    break

        if not unassigned:
            for r in range(N+1):
                for c in range(N+1):
                    for dr, dc in [(1,0), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr <= N and 0 <= nc <= N:
                            edge = tuple(sorted(((r, c), (nr, nc))))
                            if edge not in state:
                                unassigned = edge
                                break
                    if unassigned: break
                if unassigned: break

        if not unassigned:
            if is_valid_solution(state):
                return state
            return None

        state1 = state.copy()
        state1[unassigned] = 1
        res = solve_remaining(state1)
        if res: return res

        state0 = state.copy()
        state0[unassigned] = 0
        return solve_remaining(state0)

    def backtrack(clue_idx, current_state):
        if not propagate(current_state):
            return None

        if clue_idx == len(clues):
            return solve_remaining(current_state)

        c_idx = clue_order[clue_idx]
        for shape in all_shapes[c_idx]:
            compatible = True
            for edge, val in shape.items():
                if edge in current_state and current_state[edge] != val:
                    compatible = False
                    break
            if compatible:
                new_state = current_state.copy()
                new_state.update(shape)
                res = backtrack(clue_idx + 1, new_state)
                if res:
                    return res
        return None

    final_state = backtrack(0, {})
    if not final_state:
        return "No Solution"

    # Extract ordered path
    adj = { (r,c): [] for r in range(N+1) for c in range(N+1) }
    for edge, val in final_state.items():
        if val == 1:
            adj[edge[0]].append(edge[1])
            adj[edge[1]].append(edge[0])

    start_node = None
    for node, neighbors in adj.items():
        if len(neighbors) > 0:
            start_node = node
            break

    path = [start_node]
    curr = start_node
    prev = None
    while True:
        next_nodes = [n for n in adj[curr] if n != prev]
        if not next_nodes:
            break
        prev = curr
        curr = next_nodes[0]
        path.append(curr)
        if curr == start_node:
            break

    return path

if __name__ == "__main__":
    print(solve(OBSERVATION))
