def solve(observation):
    data = observation['data']
    N = len(data)

    # Group cells by region
    regions = {}
    for r in range(N):
        for c in range(N):
            reg = data[r][c]
            if reg not in regions:
                regions[reg] = []
            regions[reg].append((r, c))

    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbors.append((nr, nc))
        return neighbors

    def solve_recursive(row, current_domain):
        # Base case: all rows processed
        if row == N:
            # Final verification: exactly 1 star per region
            for reg, cells in regions.items():
                stars = sum(1 for r, c in cells if current_domain[r][c] == 2)
                if stars != 1: return None
            return current_domain

        for col in range(N):
            if current_domain[row][col] == 1:
                # Try placing a star at (row, col)
                new_domain = [r[:] for r in current_domain]
                new_domain[row][col] = 2 # 2 represents a placed star

                valid = True

                # Forward Checking: Eliminate invalid cells
                # 1. Same row
                for c in range(N):
                    if c != col:
                        new_domain[row][c] = 0

                # 2. Same column
                for r in range(N):
                    if r != row:
                        new_domain[r][col] = 0

                # 3. Neighbors (including diagonal)
                for nr, nc in get_neighbors(row, col):
                    new_domain[nr][nc] = 0

                # 4. Same region
                reg = data[row][col]
                for rr, cc in regions[reg]:
                    if (rr, cc) != (row, col):
                        new_domain[rr][cc] = 0

                # Pruning: Check if any future row has 0 possible cells
                for r in range(row + 1, N):
                    if sum(1 for c in range(N) if new_domain[r][c] == 1) == 0:
                        valid = False
                        break

                # Pruning: Check if any region has 0 possible cells left
                if valid:
                    for reg_id, cells in regions.items():
                        possible_stars = sum(1 for r, c in cells if new_domain[r][c] in [1, 2])
                        if possible_stars == 0:
                            valid = False
                            break

                if valid:
                    res = solve_recursive(row + 1, new_domain)
                    if res: return res

        return None

    # Initialize domain: 1 means possible, 0 means impossible
    initial_domain = [[1 for _ in range(N)] for _ in range(N)]

    # Human-like Deduction: Initial Constraint Propagation
    # If all cells of a region are confined to a single row or column,
    # then the star for that region MUST be in that row/col.
    # Consequently, no other region can have a star in that row/col.
    for reg, cells in regions.items():
        rows = set(r for r, c in cells)
        if len(rows) == 1:
            r = list(rows)[0]
            for c in range(N):
                if data[r][c] != reg:
                    initial_domain[r][c] = 0

        cols = set(c for r, c in cells)
        if len(cols) == 1:
            c = list(cols)[0]
            for r in range(N):
                if data[r][c] != reg:
                    initial_domain[r][c] = 0

    solution_domain = solve_recursive(0, initial_domain)

    if solution_domain:
        ans = []
        for r in range(N):
            row_ans = []
            for c in range(N):
                if solution_domain[r][c] == 2:
                    row_ans.append('S')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    return "No Solution"

