def solve(observation):
    grid = observation['data']
    n = len(grid)

    # State for backtracking
    # stars[r] = c means a star is placed at (r, c)
    stars = [-1] * n
    used_cols = set()
    used_regions = set()

    def can_place(r, c):
        # Check column constraint
        if c in used_cols:
            return False

        # Check region constraint
        reg = grid[r][c]
        if reg in used_regions:
            return False

        # Check touching constraint (including diagonally)
        # Since we place row by row, we only need to check the immediately preceding row
        if r > 0:
            prev_c = stars[r-1]
            if abs(prev_c - c) <= 1:
                return False

        return True

    def backtrack(row):
        # If we have successfully placed a star in every row, we found a solution
        if row == n:
            return True

        for col in range(n):
            if can_place(row, col):
                # Place star
                stars[row] = col
                used_cols.add(col)
                used_regions.add(grid[row][col])

                # Recurse to next row
                if backtrack(row + 1):
                    return True

                # Backtrack
                stars[row] = -1
                used_cols.remove(col)
                used_regions.remove(grid[row][col])

        return False

    if backtrack(0):
        # Format the output grid
        ans = []
        for r in range(n):
            row_ans = []
            for c in range(n):
                if stars[r] == c:
                    row_ans.append('S')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    else:
        return "No Solution"

