                if len(ones) > 2: 
                    return False # Contradiction: too many shaded cells
                if len(ones) + len(unassigned) < 2: 
                    return False # Contradiction: not enough cells to reach 2

                if len(ones) == 2 and len(unassigned) > 0:
                    for r, c in unassigned:
                        grid[r][c] = 0
                        changed = True
                elif len(ones) + len(unassigned) == 2 and len(unassigned) > 0:
                    for r, c in unassigned:
                        grid[r][c] = 1
                        changed = True

            # Rule 2: Every shaded cell must have EXACTLY ONE shaded orthogonal neighbor.
            # This perfectly enforces both the "must be a domino" and "dominoes cannot touch" rules.
            for r in range(rows):
                for c in range(cols):
                    if grid[r][c] == 1:
                        neighbors = get_neighbors(r, c)
                        ones = [n for n in neighbors if grid[n[0]][n[1]] == 1]
                        unassigned = [n for n in neighbors if grid[n[0]][n[1]] == -1]

                        if len(ones) > 1: 
                            return False # Contradiction: touching dominoes or tromino
                        if len(ones) + len(unassigned) < 1: 
                            return False # Contradiction: isolated shaded cell

                        if len(ones) == 1 and len(unassigned) > 0:
                            # Domino is complete, block all other neighbors
                            for nr, nc in unassigned:
                                grid[nr][nc] = 0
                                changed = True
                        elif len(ones) == 0 and len(unassigned) == 1:
                            # Forced to form a domino with the only available neighbor
                            nr, nc = unassigned[0]
                            grid[nr][nc] = 1
                            changed = True

        return True

    def search(grid):
        """
        Backtracking search with constraint propagation (DPLL-style).
        """
        if not propagate(grid):
            return None

        # Find the best unassigned cell to branch on
        # Heuristic: pick an unassigned cell from the region with the fewest unassigned cells
        best_cell = None
        min_unassigned = float('inf')
        for reg, cells in regions.items():
            unassigned = [c for c in cells if grid[c[0]][c[1]] == -1]
            if 0 < len(unassigned) < min_unassigned:
                min_unassigned = len(unassigned)
                best_cell = unassigned[0]

        if best_cell is None:
            return grid # All cells assigned and valid

        r, c = best_cell

        # Try shading the cell first (often leads to faster propagation)
        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = 1
        res = search(grid_copy)
        if res: return res

        # Try leaving the cell unshaded
        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = 0
        return search(grid_copy)

    initial_grid = [[-1]*cols for _ in range(rows)]
    solution = search(initial_grid)

    if solution:
        ans = []
        for row in solution:
            ans.append([ 'S' if val == 1 else None for val in row ])
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
