import itertools

def count_visible(line):
    """Counts the number of visible skyscrapers in a line."""
    count = 0
    max_h = 0
    for h in line:
        if h > max_h:
            count += 1
            max_h = h
    return count

def is_valid_line(line, clue1, clue2):
    """Checks if a line of skyscrapers satisfies the given clues from both ends."""
    if clue1 > 0 and count_visible(line) != clue1:
        return False
    if clue2 > 0 and count_visible(line[::-1]) != clue2:
        return False
    return True

def solve(observation):
    """
    Solves the Skyscrapers puzzle using constraint propagation and backtracking.
    It precomputes all valid permutations for each row and column based on the clues,
    and then uses backtracking with aggressive prefix pruning to find the solution.
    """
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    # Precompute valid permutations for each row
    valid_rows = []
    for r in range(N):
        valid = []
        for p in itertools.permutations(range(1, N + 1)):
            if is_valid_line(p, L[r], R[r]):
                valid.append(p)
        valid_rows.append(valid)

    # Precompute valid prefixes for each column to allow aggressive pruning during backtracking
    valid_cols_prefixes = [[set() for _ in range(N + 1)] for _ in range(N)]
    for c in range(N):
        for p in itertools.permutations(range(1, N + 1)):
            if is_valid_line(p, U[c], D[c]):
                for length in range(N + 1):
                    valid_cols_prefixes[c][length].add(p[:length])

    grid = []

    def backtrack(row_idx):
        # If all rows are filled successfully, the puzzle is solved
        if row_idx == N:
            return True

        # Try each valid permutation for the current row
        for p in valid_rows[row_idx]:
            valid = True
            # Check if adding this row maintains valid column prefixes
            for c in range(N):
                prefix = tuple(grid[r][c] for r in range(row_idx)) + (p[c],)
                if prefix not in valid_cols_prefixes[c][row_idx + 1]:
                    valid = False
                    break

            # If all column prefixes are valid, proceed to the next row
            if valid:
                grid.append(p)
                if backtrack(row_idx + 1):
                    return True
                grid.pop() # Backtrack

        return False

    if backtrack(0):
        return [list(row) for row in grid]
    else:
        return "No Solution"

