                new_perms = [p for p in valid_row_perms[r] if all(p[c] in domains[r][c] for c in range(N))]
                if not new_perms: 
                    return False
                valid_row_perms[r] = new_perms

                # Update cell domains based on remaining valid row permutations
                for c in range(N):
                    possible_vals = set(p[c] for p in valid_row_perms[r])
                    if not possible_vals.issuperset(domains[r][c]):
                        domains[r][c] &= possible_vals
                        if not domains[r][c]: 
                            return False
                        changed_cols.add(c)
            else:
                c = changed_cols.pop()
                # Filter valid column permutations based on current cell domains
                new_perms = [p for p in valid_col_perms[c] if all(p[r] in domains[r][c] for r in range(N))]
                if not new_perms: 
                    return False
                valid_col_perms[c] = new_perms

                # Update cell domains based on remaining valid column permutations
                for r in range(N):
