        if min_cell is None:
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        r, c = min_cell

        # Try each possible value in the chosen cell's domain
        for val in list(domains[r][c]):
            # Deep copy state for backtracking
            new_domains = [[set(domains[i][j]) for j in range(N)] for i in range(N)]
            new_row_perms = [list(valid_row_perms[i]) for i in range(N)]
            new_col_perms = [list(valid_col_perms[i]) for i in range(N)]

            # Assign value and propagate constraints
            new_domains[r][c] = {val}
            if propagate(new_domains, new_row_perms, new_col_perms, {r}, {c}):
                res = backtrack(new_domains, new_row_perms, new_col_perms)
                if res:
                    return res

        return False

    res = backtrack(domains, valid_row_perms, valid_col_perms)
    if res:
        return res
    return "No Solution"

