def solve(observation):
    data = observation['data']
    horizontal = observation['horizontal']
    vertical = observation['vertical']

    N = len(data)

    # Initialize domains for each cell: 1 to N
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Parse inequalities into a standard format: ((r1, c1), (r2, c2), operator)
    inequalities = []
    for key, val in horizontal.items():
        r, c_plus_half = ast.literal_eval(key)
        r = int(r)
        c = int(c_plus_half - 0.5)
        if val == '<':
            inequalities.append(((r, c), (r, c + 1), '<'))
        elif val == '>':
            inequalities.append(((r, c), (r, c + 1), '>'))

    for key, val in vertical.items():
        r_plus_half, c = ast.literal_eval(key)
        r = int(r_plus_half - 0.5)
        c = int(c)
        if val == '^':
            inequalities.append(((r, c), (r + 1, c), '<'))
        elif val == 'v':
            inequalities.append(((r, c), (r + 1, c), '>'))

    def propagate(domains):
        """
        Applies constraint propagation to reduce domains.
        Returns False if a contradiction is found (empty domain), True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Row and Column uniqueness (Naked Singles)
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = list(domains[r][c])[0]
                        # Remove from the rest of the row
                        for c2 in range(N):
                            if c != c2 and val in domains[r][c2]:
                                domains[r][c2].remove(val)
                                changed = True
                        # Remove from the rest of the column
                        for r2 in range(N):
                            if r != r2 and val in domains[r2][c]:
                                domains[r2][c].remove(val)
                                changed = True

            # 2. Hidden Singles in rows
            for r in range(N):
                for val in range(1, N + 1):
                    possible_cols = [c for c in range(N) if val in domains[r][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # 3. Hidden Singles in columns
            for c in range(N):
                for val in range(1, N + 1):
                    possible_rows = [r for r in range(N) if val in domains[r][c]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True

            # 4. Inequality constraints
            for (r1, c1), (r2, c2), op in inequalities:
                if not domains[r1][c1] or not domains[r2][c2]:
                    return False

                if op == '<':
                    # A < B
                    max_b = max(domains[r2][c2])
                    min_a = min(domains[r1][c1])

                    to_remove_a = {x for x in domains[r1][c1] if x >= max_b}
                    if to_remove_a:
                        domains[r1][c1] -= to_remove_a
                        changed = True

                    to_remove_b = {x for x in domains[r2][c2] if x <= min_a}
                    if to_remove_b:
                        domains[r2][c2] -= to_remove_b
                        changed = True

                elif op == '>':
                    # A > B
                    max_a = max(domains[r1][c1])
                    min_b = min(domains[r2][c2])

                    to_remove_a = {x for x in domains[r1][c1] if x <= min_b}
                    if to_remove_a:
                        domains[r1][c1] -= to_remove_a
                        changed = True

                    to_remove_b = {x for x in domains[r2][c2] if x >= max_a}
                    if to_remove_b:
                        domains[r2][c2] -= to_remove_b
                        changed = True

            # Check for any empty domains (invalid state)
            for r in range(N):
                for c in range(N):
                    if not domains[r][c]:
                        return False
        return True

    def backtrack(domains):
        """
        Backtracking search with Minimum Remaining Values (MRV) heuristic.
        """
        if not propagate(domains):
            return None

        # Find the cell with the smallest domain size > 1
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if 1 < len(domains[r][c]) < min_len:
                    min_len = len(domains[r][c])
                    best_cell = (r, c)

        if best_cell is None:
            # All domains have size 1, puzzle is solved
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        r, c = best_cell
        # Try assigning each possible value to the chosen cell
        for val in list(domains[r][c]):
            # Deep copy domains for the recursive call
            new_domains = [[set(d) for d in row] for row in domains]
            new_domains[r][c] = {val}
            result = backtrack(new_domains)
            if result:
                return result

        return None

    solution = backtrack(domains)
    if solution:
        return solution
    else:
        return "No Solution"

