def generate_perms(N, clue1, clue2):
    valid = []
    def solve_perm(idx, current_perm, available, max_so_far, vis_count):
        if idx == N:
            if (clue1 == 0 or vis_count == clue1) and \
               (clue2 == 0 or count_visible(current_perm[::-1]) == clue2):
                valid.append(tuple(current_perm))
            return

        # Look-ahead pruning based on clue1 (left/top clue)
        if clue1 != 0:
            min_future_vis = 0
            if available:
                max_avail = max(available)
                if max_avail > max_so_far:
                    min_future_vis = 1
            # If even with the minimum possible future visible buildings we exceed the clue, prune
            if vis_count + min_future_vis > clue1:
                return

            # If even by making all remaining buildings visible we can't reach the clue, prune
            if vis_count + len(available) < clue1:
                return

        for val in range(1, N + 1):
            if val in available:
                available.remove(val)
                current_perm.append(val)

                new_max = max(max_so_far, val)
                new_vis = vis_count + (1 if val > max_so_far else 0)

                solve_perm(idx + 1, current_perm, available, new_max, new_vis)

                current_perm.pop()
                available.add(val)

