    for i in range(N):
        valid_row_perms.append(generate_perms(N, L[i], R[i]))

    valid_col_perms = []
    for j in range(N):
        valid_col_perms.append(generate_perms(N, U[j], D[j]))

    def reduce_domains(row_perms, col_perms):
        """
        Aggressively filters permutations by ensuring that the possible values for each cell (i, j)
        are consistent between the remaining valid row permutations and column permutations.
        """
        changed = True
        while changed:
            changed = False
            for i in range(N):
                for j in range(N):
                    if not row_perms[i] or not col_perms[j]:
                        return False

                    row_vals = set(p[j] for p in row_perms[i])
                    col_vals = set(p[i] for p in col_perms[j])

                    intersect = row_vals.intersection(col_vals)

                    if not intersect:
                        return False

                    if len(intersect) < len(row_vals):
                        row_perms[i] = [p for p in row_perms[i] if p[j] in intersect]
                        changed = True

                    if len(intersect) < len(col_vals):
                        col_perms[j] = [p for p in col_perms[j] if p[i] in intersect]
                        changed = True
        return True

    def solve_recursive(row_perms, col_perms):
        # Apply constraint propagation
        if not reduce_domains(row_perms, col_perms):
            return None

        # Find the most constrained row or column to branch on (Minimum Remaining Values heuristic)
        min_len = float('inf')
        best_idx = -1
        is_row = True

        for i in range(N):
            if 1 < len(row_perms[i]) < min_len:
                min_len = len(row_perms[i])
                best_idx = i
                is_row = True

        for j in range(N):
            if 1 < len(col_perms[j]) < min_len:
                min_len = len(col_perms[j])
                best_idx = j
                is_row = False

        # If all rows and columns have exactly 1 valid permutation, we found the solution
        if best_idx == -1:
            return [list(p[0]) for p in row_perms]

        # Branching
        if is_row:
            for p in row_perms[best_idx]:
                new_row_perms = [list(perms) for perms in row_perms]
                new_col_perms = [list(perms) for perms in col_perms]
                new_row_perms[best_idx] = [p]
                result = solve_recursive(new_row_perms, new_col_perms)
                if result: return result
        else:
            for p in col_perms[best_idx]:
                new_row_perms = [list(perms) for perms in row_perms]
                new_col_perms = [list(perms) for perms in col_perms]
                new_col_perms[best_idx] = [p]
                result = solve_recursive(new_row_perms, new_col_perms)
                if result: return result

        return None

    ans = solve_recursive(valid_row_perms, valid_col_perms)
    return ans if ans else "No Solution"

