import collections

def solve(observation):
    data = observation['data']
    N = len(data)

    horizontal = observation.get('horizontal', {})
    vertical = observation.get('vertical', {})

    # Parse inequalities into a unified format: ((r1, c1), (r2, c2), op)
    inequalities = []
    for k, v in horizontal.items():
        k_clean = k.strip('()')
        r_str, c_str = k_clean.split(',')
        r = int(r_str)
        c_half = float(c_str)
        c1 = int(c_half - 0.5)
        c2 = int(c_half + 0.5)
        inequalities.append(((r, c1), (r, c2), v))

    for k, v in vertical.items():
        k_clean = k.strip('()')
        r_str, c_str = k_clean.split(',')
        r_half = float(r_str)
        c = int(c_str)
        r1 = int(r_half - 0.5)
        r2 = int(r_half + 0.5)
        if v == '^':
            inequalities.append(((r1, c), (r2, c), '<'))
        elif v == 'v':
            inequalities.append(((r1, c), (r2, c), '>'))

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Precompute neighbors for AllDiff constraints (same row and column)
    alldiff_neighbors = { (r, c): set() for r in range(N) for c in range(N) }
    for r in range(N):
        for c in range(N):
            for i in range(N):
                if i != c:
                    alldiff_neighbors[(r, c)].add((r, i))
                if i != r:
                    alldiff_neighbors[(r, c)].add((i, c))

    # Precompute inequality constraints for fast lookup
    ineq_op = {}
    ineq_neighbors = { (r, c): [] for r in range(N) for c in range(N) }
    for (r1, c1), (r2, c2), op in inequalities:
        ineq_neighbors[(r1, c1)].append((r2, c2))
        ineq_neighbors[(r2, c2)].append((r1, c1))
        if op == '<':
            ineq_op[((r1, c1), (r2, c2))] = '<'
            ineq_op[((r2, c2), (r1, c1))] = '>'
        else:
            ineq_op[((r1, c1), (r2, c2))] = '>'
            ineq_op[((r2, c2), (r1, c1))] = '<'

    def revise(u, v):
        """
        Revise domain of u based on domain of v.
        Returns True if domain of u was modified.
        """
        revised = False

        # Apply AllDiff constraint
        if v in alldiff_neighbors[u]:
            if len(domains[v]) == 1:
                val = next(iter(domains[v]))
                if val in domains[u]:
                    domains[u].remove(val)
                    revised = True

        # Apply Inequality constraint
        if (u, v) in ineq_op:
            op = ineq_op[(u, v)]
            if op == '<':
                max_v = max(domains[v])
                to_remove = [x for x in domains[u] if x >= max_v]
                for x in to_remove:
                    domains[u].remove(x)
                    revised = True
            elif op == '>':
                min_v = min(domains[v])
                to_remove = [x for x in domains[u] if x <= min_v]
                for x in to_remove:
                    domains[u].remove(x)
                    revised = True

        return revised

    def ac3(queue=None):
        """
        AC-3 Constraint Propagation Algorithm.
        """
        if queue is None:
            queue = collections.deque()
            for r in range(N):
                for c in range(N):
                    u = (r, c)
                    for v in alldiff_neighbors[u]:
                        queue.append((u, v))
                    for v in ineq_neighbors[u]:
                        queue.append((u, v))

        while queue:
            u, v = queue.popleft()
            if revise(u, v):
                if len(domains[u]) == 0:
                    return False
                for w in alldiff_neighbors[u]:
                    if w != v:
                        queue.append((w, u))
                for w in ineq_neighbors[u]:
                    if w != v:
                        queue.append((w, u))
        return True

    # Initial constraint propagation
    if not ac3():
        return "No Solution"

    def is_solved():
        return all(len(domains[(r, c)]) == 1 for r in range(N) for c in range(N))

    def get_mrv_var():
        """
        Minimum Remaining Values (MRV) heuristic for variable selection.
        """
        min_len = N + 1
        best_var = None
        for r in range(N):
            for c in range(N):
                if len(domains[(r, c)]) > 1:
                    if len(domains[(r, c)]) < min_len:
                        min_len = len(domains[(r, c)])
                        best_var = (r, c)
        return best_var

    def backtrack():
        """
        Backtracking search with forward checking (AC-3).
        """
        if is_solved():
            return True

        var = get_mrv_var()
        if not var:
            return False

        # Snapshot domains for backtracking
        original_domains = {k: set(v) for k, v in domains.items()}

        for val in sorted(list(domains[var])):
            domains[var] = {val}

            # Only propagate constraints from the newly assigned variable
            queue = collections.deque()
            for w in alldiff_neighbors[var]:
                queue.append((w, var))
            for w in ineq_neighbors[var]:
                queue.append((w, var))

            if ac3(queue):
                if backtrack():
                    return True

            # Restore domains if assignment failed
            for k in domains:
                domains[k] = set(original_domains[k])

        return False

    if backtrack():
        return [[next(iter(domains[(r, c)])) for c in range(N)] for r in range(N)]
    else:
        return "No Solution"

