OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 3, 2, 2, 1, None], [None, None, 3, None, 3, None], [1, 2, None, 2, None, 1], [1, None, 3, 2, None, 1], [None, None, 1, None, 1, None]]}

def solve(observation):
    clues = observation['data']
    N = len(clues) - 1

    # grid[r][c] will be 0 for '\' and 1 for '/'
    grid = [[-1] * N for _ in range(N)]

    def get_dot_idx(r, c):
        return r * (N + 1) + c

    def get_incident_dots(r, c, val):
        if val == 0: # '\' connects top-left to bottom-right
            return get_dot_idx(r, c), get_dot_idx(r+1, c+1)
        else: # '/' connects bottom-left to top-right
            return get_dot_idx(r+1, c), get_dot_idx(r, c+1)

    def get_dot_vars(r, c):
        # Returns list of (cell_r, cell_c, required_val_to_connect)
        vars = []
        if r > 0 and c > 0: vars.append((r-1, c-1, 0)) # Top-left cell needs '\'
        if r > 0 and c < N: vars.append((r-1, c, 1))   # Top-right cell needs '/'
        if r < N and c > 0: vars.append((r, c-1, 1))   # Bottom-left cell needs '/'
        if r < N and c < N: vars.append((r, c, 0))     # Bottom-right cell needs '\'
        return vars

    # Precompute variables for each clue to speed up propagation
    dot_vars = {}
    for r in range(N+1):
        for c in range(N+1):
            if clues[r][c] is not None:
                dot_vars[(r, c)] = get_dot_vars(r, c)

    def find(i, p):
        if p[i] == i: return i
        p[i] = find(p[i], p)
        return p[i]

    def union(i, j, p):
        root_i = find(i, p)
        root_j = find(j, p)
        if root_i != root_j:
            p[root_i] = root_j
            return True
        return False

    def propagate(grid, p):
        changed = True
        while changed:
            changed = False

            # 1. Enforce degree constraints from clues
            for (r, c), vars in dot_vars.items():
                clue = clues[r][c]
                connected = 0
                unassigned = []
                for cr, cc, req_val in vars:
                    if grid[cr][cc] == req_val:
                        connected += 1
                    elif grid[cr][cc] == -1:
                        unassigned.append((cr, cc, req_val))

                if connected > clue:
                    return False # Too many connections
                if connected + len(unassigned) < clue:
                    return False # Not enough potential connections

                # If exactly enough connections, all unassigned must NOT connect
                if connected == clue and len(unassigned) > 0:
                    for cr, cc, req_val in unassigned:
                        grid[cr][cc] = 1 - req_val
                        changed = True
                # If all unassigned are needed to reach the clue, they MUST connect
                elif connected + len(unassigned) == clue and len(unassigned) > 0:
                    for cr, cc, req_val in unassigned:
                        grid[cr][cc] = req_val
                        changed = True

            if changed:
                # Rebuild DSU to ensure consistency before loop checking
                p[:] = list(range((N+1)*(N+1)))
                for r in range(N):
                    for c in range(N):
                        if grid[r][c] != -1:
                            d1, d2 = get_incident_dots(r, c, grid[r][c])
                            if not union(d1, d2, p):
                                return False
                continue # Re-evaluate clues with new assignments

            # 2. Enforce loop prevention
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == -1:
                        d1, d2 = get_incident_dots(r, c, 0)
                        loop0 = find(d1, p) == find(d2, p)

                        d3, d4 = get_incident_dots(r, c, 1)
                        loop1 = find(d3, p) == find(d4, p)

                        if loop0 and loop1:
                            return False # Both options create a loop
                        elif loop0:
                            grid[r][c] = 1 # '\' creates loop, must be '/'
                            changed = True
                        elif loop1:
                            grid[r][c] = 0 # '/' creates loop, must be '\'
                            changed = True

            if changed:
                # Rebuild DSU after loop prevention deductions
                p[:] = list(range((N+1)*(N+1)))
                for r in range(N):
                    for c in range(N):
                        if grid[r][c] != -1:
                            d1, d2 = get_incident_dots(r, c, grid[r][c])
                            if not union(d1, d2, p):
                                return False
        return True

    def solve_backtrack(grid, p):
        # Heuristic: pick the unassigned cell surrounded by the most clues
        best_cell = None
        max_clues = -1
        for r in range(N):
            for c in range(N):
                if grid[r][c] == -1:
                    clue_count = 0
                    for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                        if clues[r+dr][c+dc] is not None:
                            clue_count += 1
                    if clue_count > max_clues:
                        max_clues = clue_count
                        best_cell = (r, c)

        if not best_cell:
            return grid # All cells assigned successfully

        r, c = best_cell

        for val in [0, 1]:
            new_grid = [row[:] for row in grid]
            new_p = p[:]

            new_grid[r][c] = val
            d1, d2 = get_incident_dots(r, c, val)

            # If adding this edge creates a loop, prune this branch
            if not union(d1, d2, new_p):
                continue

            if propagate(new_grid, new_p):
                res = solve_backtrack(new_grid, new_p)
                if res: return res

        return None

    # Initial DSU and propagation
    p = list(range((N+1)*(N+1)))
    if not propagate(grid, p):
        return "No Solution"

    res = solve_backtrack(grid, p)

    if res:
        ans = []
        for r in range(N):
            row_str = []
            for c in range(N):
                row_str.append('/' if res[r][c] == 1 else '\\')
            ans.append(row_str)
        return ans
    return "No Solution"

