from collections import deque

def solve(observation):
    N = len(observation['data'])
    domains = {}

    # Initialize domains
    for r in range(N):
        for c in range(N):
            val = observation['data'][r][c]
            if val is not None:
                domains[(r, c)] = {val}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Build constraint graph
    constraints = { (r, c): [] for r in range(N) for c in range(N) }

    # AllDiff constraints for rows and columns
    for r in range(N):
        for c1 in range(N):
            for c2 in range(N):
                if c1 != c2:
                    constraints[(r, c1)].append(((r, c2), '!='))

    for c in range(N):
        for r1 in range(N):
            for r2 in range(N):
                if r1 != r2:
                    constraints[(r1, c)].append(((r2, c), '!='))

    # Inequality constraints
    for k, v in observation['horizontal'].items():
        k_clean = k.strip('()')
        r_str, c_str = [x.strip() for x in k_clean.split(',')]
        r = int(r_str)
        c = int(float(c_str) - 0.5)
        if v == '<':
            constraints[(r, c)].append(((r, c + 1), '<'))
            constraints[(r, c + 1)].append(((r, c), '>'))
        elif v == '>':
            constraints[(r, c)].append(((r, c + 1), '>'))
            constraints[(r, c + 1)].append(((r, c), '<'))

    for k, v in observation['vertical'].items():
        k_clean = k.strip('()')
        r_str, c_str = [x.strip() for x in k_clean.split(',')]
        r = int(float(r_str) - 0.5)
        c = int(c_str)
        if v == '^':
            constraints[(r, c)].append(((r + 1, c), '<'))
            constraints[(r + 1, c)].append(((r, c), '>'))
        elif v == 'v':
            constraints[(r, c)].append(((r + 1, c), '>'))
            constraints[(r + 1, c)].append(((r, c), '<'))

    def revise(xi, xj, constraint_type, domains):
        revised = False
        if constraint_type == '!=':
            if len(domains[xj]) == 1:
                val = list(domains[xj])[0]
                if val in domains[xi]:
                    domains[xi].remove(val)
                    revised = True
        elif constraint_type == '<':
            if not domains[xj]: return False
            max_j = max(domains[xj])
            to_remove = [x for x in domains[xi] if x >= max_j]
            for x in to_remove:
                domains[xi].remove(x)
                revised = True
        elif constraint_type == '>':
            if not domains[xj]: return False
            min_j = min(domains[xj])
            to_remove = [x for x in domains[xi] if x <= min_j]
            for x in to_remove:
                domains[xi].remove(x)
                revised = True
        return revised

    def ac3(domains, constraints, queue=None):
        if queue is None:
            q = deque()
            for xi in constraints:
                for xj, c_type in constraints[xi]:
                    q.append((xi, xj, c_type))
        else:
            q = deque(queue)

        while q:
            xi, xj, c_type = q.popleft()
            if revise(xi, xj, c_type, domains):
                if len(domains[xi]) == 0:
                    return False
                for xk, c_type_i_to_k in constraints[xi]:
                    if xk != xj:
                        # Find the reverse constraint type to add to queue
                        for neighbor, c_type_k_to_i in constraints[xk]:
                            if neighbor == xi:
                                q.append((xk, xi, c_type_k_to_i))
                                break
        return True

    def solve_csp(domains, queue=None):
        # Propagate constraints
        if not ac3(domains, constraints, queue):
            return None

        # Check if solved
        if all(len(d) == 1 for d in domains.values()):
            return {k: list(v)[0] for k, v in domains.items()}

        # Select unassigned variable using Minimum Remaining Values (MRV) heuristic
        unassigned = [k for k, v in domains.items() if len(v) > 1]
        unassigned.sort(key=lambda k: (len(domains[k]), k[0], k[1]))
        var = unassigned[0]

        # Try assigning values
        for val in sorted(list(domains[var])):
            new_domains = {k: set(v) for k, v in domains.items()}
            new_domains[var] = {val}

            # Only queue constraints affected by this assignment
            new_queue = []
            for xk, c_type_var_to_k in constraints[var]:
                for neighbor, c_type_k_to_var in constraints[xk]:
                    if neighbor == var:
                        new_queue.append((xk, var, c_type_k_to_var))
                        break

            result = solve_csp(new_domains, new_queue)
            if result:
                return result

        return None

    solution = solve_csp(domains)
    if solution:
        res = [[0] * N for _ in range(N)]
        for (r, c), val in solution.items():
            res[r][c] = val
        return res
    return "No Solution"

