import sys

# Increase recursion depth for Tarjan's algorithm on larger grids
sys.setrecursionlimit(2000)

def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    # state: 0 = UNKNOWN, 1 = BLACK, 2 = WHITE
    state = [[0] * C for _ in range(R)]

    # Initial deductions based on human logic
    for r in range(R):
        for c in range(C):
            # Pattern: x y x -> y must be WHITE
            if c + 2 < C and grid[r][c] == grid[r][c+2]:
                state[r][c+1] = 2
            if r + 2 < R and grid[r][c] == grid[r+2][c]:
                state[r+1][c] = 2

    for r in range(R):
        for c in range(C):
            # Pattern: x x adjacent -> any other x in the same row/col must be BLACK
            if c + 1 < C and grid[r][c] == grid[r][c+1]:
                for c2 in range(C):
                    if c2 != c and c2 != c+1 and grid[r][c2] == grid[r][c]:
                        state[r][c2] = 1
            if r + 1 < R and grid[r][c] == grid[r+1][c]:
                for r2 in range(R):
                    if r2 != r and r2 != r+1 and grid[r2][c] == grid[r][c]:
                        state[r2][c] = 1

    def is_valid(current_state):
        # 1. Check adjacent black cells
        for r in range(R):
            for c in range(C):
                if current_state[r][c] == 1:
                    if r + 1 < R and current_state[r+1][c] == 1: return False
                    if c + 1 < C and current_state[r][c+1] == 1: return False

        # 2. Check duplicate white cells in rows and columns
        for r in range(R):
            seen = set()
            for c in range(C):
                if current_state[r][c] == 2:
                    val = grid[r][c]
                    if val in seen: return False
                    seen.add(val)
        for c in range(C):
            seen = set()
            for r in range(R):
                if current_state[r][c] == 2:
                    val = grid[r][c]
                    if val in seen: return False
                    seen.add(val)

        # 3. Check connectivity of non-black cells
        start = None
        non_black_count = 0
        for r in range(R):
            for c in range(C):
                if current_state[r][c] != 1:
                    non_black_count += 1
                    if start is None:
                        start = (r, c)

        if non_black_count == 0:
            return True

        visited = set()
        q = [start]
        visited.add(start)
        head = 0
        while head < len(q):
            curr_r, curr_c = q[head]
            head += 1
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < R and 0 <= nc < C and current_state[nr][nc] != 1:
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))

        if len(visited) != non_black_count:
            return False

        return True

    def get_articulation_points(current_state):
        # Tarjan's algorithm to find articulation points in the non-black cell graph
        points = []
        nodes = []
        node_set = set()
        for r in range(R):
            for c in range(C):
                if current_state[r][c] != 1:
                    nodes.append((r, c))
                    node_set.add((r, c))

        if not nodes:
            return points

        adj = {u: [] for u in nodes}
        for r, c in nodes:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in node_set:
                    adj[(r, c)].append((nr, nc))

        visited = set()
        discovery_time = {}
        low = {}
        parent = {}
        time = [0]
        ap_set = set()

        def dfs(u):
            visited.add(u)
            discovery_time[u] = time[0]
            low[u] = time[0]
            time[0] += 1
            children = 0

            for v in adj[u]:
                if v not in visited:
                    parent[v] = u
                    children += 1
                    dfs(v)
                    low[u] = min(low[u], low[v])

                    if parent.get(u) is None and children > 1:
                        ap_set.add(u)
                    if parent.get(u) is not None and low[v] >= discovery_time[u]:
                        ap_set.add(u)
                elif v != parent.get(u):
                    low[u] = min(low[u], discovery_time[v])

        dfs(nodes[0])

        for u in ap_set:
            if current_state[u[0]][u[1]] == 0:
                points.append(u)

        return points

    def propagate_simple(current_state):
        changed = True
        while changed:
            changed = False
            if not is_valid(current_state):
                return False

            # Rule 1: Black cells force orthogonal neighbors to be White
            for r in range(R):
                for c in range(C):
                    if current_state[r][c] == 1:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if current_state[nr][nc] == 1:
                                    return False
                                if current_state[nr][nc] == 0:
                                    current_state[nr][nc] = 2
                                    changed = True

            # Rule 2: White cells force cells with the same number in row/col to be Black
            for r in range(R):
                for c in range(C):
                    if current_state[r][c] == 2:
                        val = grid[r][c]
                        for c2 in range(C):
                            if c2 != c and grid[r][c2] == val:
                                if current_state[r][c2] == 2:
                                    return False
                                if current_state[r][c2] == 0:
                                    current_state[r][c2] = 1
                                    changed = True
                        for r2 in range(R):
                            if r2 != r and grid[r2][c] == val:
                                if current_state[r2][c] == 2:
                                    return False
                                if current_state[r2][c] == 0:
                                    current_state[r2][c] = 1
                                    changed = True

            # Rule 3: Articulation points of the non-black graph must be White
            if not is_valid(current_state):
                return False
            art_points = get_articulation_points(current_state)
            for r, c in art_points:
                if current_state[r][c] == 0:
                    current_state[r][c] = 2
                    changed = True

        return True

    def propagate(current_state):
        # Full propagation with 1-step lookahead
        if not propagate_simple(current_state):
            return False

        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    if current_state[r][c] == 0:
                        # Lookahead: Try setting to BLACK
                        temp_state = [row[:] for row in current_state]
                        temp_state[r][c] = 1
                        if not propagate_simple(temp_state):
                            current_state[r][c] = 2
                            changed = True
                            if not propagate_simple(current_state):
                                return False
                            continue

                        # Lookahead: Try setting to WHITE
                        temp_state = [row[:] for row in current_state]
                        temp_state[r][c] = 2
                        if not propagate_simple(temp_state):
                            current_state[r][c] = 1
                            changed = True
                            if not propagate_simple(current_state):
                                return False
        return True

    def solve_backtrack(current_state):
        if not propagate(current_state):
            return None

        # Check if fully solved
        solved = True
        for r in range(R):
            for c in range(C):
                if current_state[r][c] == 0:
                    solved = False
                    break
            if not solved:
                break

        if solved:
            return current_state

        # Find the first UNKNOWN cell to branch on
        best_cell = None
        for r in range(R):
            for c in range(C):
                if current_state[r][c] == 0:
                    best_cell = (r, c)
                    break
            if best_cell:
                break

        r, c = best_cell

        # Branch: Try WHITE first
        state_copy = [row[:] for row in current_state]
        state_copy[r][c] = 2
        res = solve_backtrack(state_copy)
        if res: return res

        # Branch: Try BLACK
        state_copy = [row[:] for row in current_state]
        state_copy[r][c] = 1
        res = solve_backtrack(state_copy)
        if res: return res

        return None

    if not propagate(state):
        return "No Solution"

    final_state = solve_backtrack(state)

    if final_state:
        ans = [[None]*C for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if final_state[r][c] == 1:
                    ans[r][c] = 'B'
        return ans
    else:
        return "No Solution"

