def generate_perms(N, clue1, clue2):
    # Generates all valid permutations for a line (row or column) given its two clues.
    # clue1 is the visibility from the start (left/top), clue2 from the end (right/bottom).
    def backtrack(perm, available, max_so_far, vis_so_far):
        # Prune if visibility exceeds clue
        if clue1 != 0 and vis_so_far > clue1:
            return
        # Prune if we can't possibly reach the required visibility
        if clue1 != 0 and vis_so_far + len(available) < clue1:
            return

        if not available:
            # Final check for clue1
            if clue1 != 0 and vis_so_far != clue1:
                return
            # Final check for clue2 (reverse visibility)
            if clue2 != 0:
                vis2 = 0
                m2 = 0
                for x in reversed(perm):
                    if x > m2:
                        vis2 += 1
                        m2 = x
                if vis2 != clue2:
                    return
            yield perm
            return

        for val in available:
            new_vis = vis_so_far + 1 if val > max_so_far else vis_so_far
            new_max = max(max_so_far, val)
            yield from backtrack(perm + (val,), available - {val}, new_max, new_vis)

    # Optimization: if clue1 is 0 but clue2 is not, generate in reverse to prune early
    if clue1 == 0 and clue2 != 0:
        def backtrack_rev(perm, available, max_so_far, vis_so_far):
            if clue2 != 0 and vis_so_far > clue2:
                return
            if clue2 != 0 and vis_so_far + len(available) < clue2:
                return
            if not available:
                if clue2 != 0 and vis_so_far != clue2:
                    return
                yield perm
                return
            for val in available:
                new_vis = vis_so_far + 1 if val > max_so_far else vis_so_far
                new_max = max(max_so_far, val)
                yield from backtrack_rev(perm + (val,), available - {val}, new_max, new_vis)

        return [p[::-1] for p in backtrack_rev((), set(range(1, N + 1)), 0, 0)]

    return list(backtrack((), set(range(1, N + 1)), 0, 0))

def reduce_domains(domains, valid_rows, valid_cols, N):
    # Applies Generalized Arc Consistency (GAC) between the cell domains and the valid permutations
    # for each row and column.
    changed = True
    while changed:
        changed = False

        # Enforce row constraints
        for r in range(N):
            new_valid_rows = []
            possible_vals = [set() for _ in range(N)]
            for perm in valid_rows[r]:
                # Check if permutation is compatible with current cell domains
                if all(perm[c] in domains[r][c] for c in range(N)):
                    new_valid_rows.append(perm)
                    for c in range(N):
                        possible_vals[c].add(perm[c])

            valid_rows[r] = new_valid_rows
            # Update domains based on compatible permutations
            for c in range(N):
                if len(possible_vals[c]) < len(domains[r][c]):
                    domains[r][c] &= possible_vals[c]
                    changed = True
                if not domains[r][c]:
                    return False # Domain wiped out, invalid state

        # Enforce column constraints
        for c in range(N):
            new_valid_cols = []
            possible_vals = [set() for _ in range(N)]
            for perm in valid_cols[c]:
                # Check if permutation is compatible with current cell domains
                if all(perm[r] in domains[r][c] for r in range(N)):
                    new_valid_cols.append(perm)
                    for r in range(N):
                        possible_vals[r].add(perm[r])

            valid_cols[c] = new_valid_cols
            # Update domains based on compatible permutations
            for r in range(N):
                if len(possible_vals[r]) < len(domains[r][c]):
                    domains[r][c] &= possible_vals[r]
                    changed = True
                if not domains[r][c]:
                    return False # Domain wiped out, invalid state

    return True

def solve_backtrack(domains, valid_rows, valid_cols, N):
    # Propagate constraints
    if not reduce_domains(domains, valid_rows, valid_cols, N):
        return None

    # Check if puzzle is completely solved
    min_len = N + 1
    min_r, min_c = -1, -1
    for r in range(N):
        for c in range(N):
            if 1 < len(domains[r][c]) < min_len:
                min_len = len(domains[r][c])
                min_r, min_c = r, c

    if min_r == -1:
        # All domains have exactly 1 value, solution found
        return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

    # Backtracking: branch on the cell with the smallest domain > 1 (MRV heuristic)
    for val in domains[min_r][min_c]:
        # Create deep copies of state for the branch
        new_domains = [[set(domains[r][c]) for c in range(N)] for r in range(N)]
        new_domains[min_r][min_c] = {val}

        new_valid_rows = [list(vr) for vr in valid_rows]
        new_valid_cols = [list(vc) for vc in valid_cols]

        result = solve_backtrack(new_domains, new_valid_rows, new_valid_cols, N)
        if result:
            return result

    return None

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    N = len(U)

    # Precompute all valid permutations for each row and column based on side clues
    valid_rows = []
    for i in range(N):
        valid_rows.append(generate_perms(N, L[i], R[i]))

    valid_cols = []
    for j in range(N):
        valid_cols.append(generate_perms(N, U[j], D[j]))

    # Initialize domains: every cell can potentially be any building height 1..N
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Start backtracking search with constraint propagation
    result = solve_backtrack(domains, valid_rows, valid_cols, N)

    if result:
        return result
    else:
        return "No Solution"

