import copy

class FutoshikiSolver:
    def __init__(self, observation):
        self.n = len(observation['data'])
        self.domains = [[set(range(1, self.n + 1)) for _ in range(self.n)] for _ in range(self.n)]
        self.inequalities = []
        self.degree = [[0] * self.n for _ in range(self.n)]

        for r in range(self.n):
            for c in range(self.n):
                val = observation['data'][r][c]
                if val is not None:
                    self.domains[r][c] = {val}

        for k, v in observation['horizontal'].items():
            k = k.strip('()')
            parts = k.split(',')
            r = int(float(parts[0]))
            c_mid = float(parts[1])
            c1 = int(c_mid - 0.5)
            c2 = int(c_mid + 0.5)
            if v == '<':
                self.inequalities.append((r, c1, r, c2, '<'))
            else:
                self.inequalities.append((r, c1, r, c2, '>'))
            self.degree[r][c1] += 1
            self.degree[r][c2] += 1

        for k, v in observation['vertical'].items():
            k = k.strip('()')
            parts = k.split(',')
            r_mid = float(parts[0])
            c = int(float(parts[1]))
            r1 = int(r_mid - 0.5)
            r2 = int(r_mid + 0.5)
            if v == '^':
                self.inequalities.append((r1, c, r2, c, '<'))
            else:
                self.inequalities.append((r1, c, r2, c, '>'))
            self.degree[r1][c] += 1
            self.degree[r2][c] += 1

    def propagate(self):
        changed = True
        while changed:
            changed = False

            # 1. Row and Col AllDiff
            for i in range(self.n):
                for j in range(self.n):
                    if len(self.domains[i][j]) == 1:
                        val = list(self.domains[i][j])[0]
                        # Remove from row
                        for c in range(self.n):
                            if c != j and val in self.domains[i][c]:
                                self.domains[i][c].remove(val)
                                changed = True
                                if not self.domains[i][c]: return False
                        # Remove from col
                        for r in range(self.n):
                            if r != i and val in self.domains[r][j]:
                                self.domains[r][j].remove(val)
                                changed = True
                                if not self.domains[r][j]: return False

            # 2. Inequalities
            for r1, c1, r2, c2, op in self.inequalities:
                dom1 = self.domains[r1][c1]
                dom2 = self.domains[r2][c2]
                if op == '<':
                    max2 = max(dom2)
                    to_remove1 = [v for v in dom1 if v >= max2]
                    if to_remove1:
                        for v in to_remove1: dom1.remove(v)
                        changed = True
                        if not dom1: return False

                    min1 = min(dom1)
                    to_remove2 = [v for v in dom2 if v <= min1]
                    if to_remove2:
                        for v in to_remove2: dom2.remove(v)
                        changed = True
                        if not dom2: return False
                else:
                    max1 = max(dom1)
                    to_remove2 = [v for v in dom2 if v >= max1]
                    if to_remove2:
                        for v in to_remove2: dom2.remove(v)
                        changed = True
                        if not dom2: return False

                    min2 = min(dom2)
                    to_remove1 = [v for v in dom1 if v <= min2]
                    if to_remove1:
                        for v in to_remove1: dom1.remove(v)
                        changed = True
                        if not dom1: return False

            # 3. Hidden singles
            for i in range(self.n):
                for val in range(1, self.n + 1):
                    # Row
                    possible_cols = [c for c in range(self.n) if val in self.domains[i][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(self.domains[i][c]) > 1:
                            self.domains[i][c] = {val}
                            changed = True
                    elif len(possible_cols) == 0:
                        return False

                    # Col
                    possible_rows = [r for r in range(self.n) if val in self.domains[r][i]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(self.domains[r][i]) > 1:
                            self.domains[r][i] = {val}
                            changed = True
                    elif len(possible_rows) == 0:
                        return False
        return True

    def solve(self):
        if not self.propagate():
            return None

        # Find MRV (Minimum Remaining Values) with Degree heuristic tie-breaker
        min_len = self.n + 1
        max_deg = -1
        best_cell = None
        for r in range(self.n):
            for c in range(self.n):
                if len(self.domains[r][c]) > 1:
                    if len(self.domains[r][c]) < min_len:
                        min_len = len(self.domains[r][c])
                        max_deg = self.degree[r][c]
                        best_cell = (r, c)
                    elif len(self.domains[r][c]) == min_len:
                        if self.degree[r][c] > max_deg:
                            max_deg = self.degree[r][c]
                            best_cell = (r, c)

        if best_cell is None:
            return [[list(self.domains[r][c])[0] for c in range(self.n)] for r in range(self.n)]

        r, c = best_cell
        saved_domains = copy.deepcopy(self.domains)

        for val in sorted(list(self.domains[r][c])):
            self.domains[r][c] = {val}
            result = self.solve()
            if result:
                return result
            self.domains = copy.deepcopy(saved_domains)

        return None

def solve(observation):
    solver = FutoshikiSolver(observation)
    result = solver.solve()
    if result:
        return result
    return "No Solution"

