    neighbors = {}
    for r in range(N):
        for c in range(N):
            n = set()
            for i in range(N):
                if i != c: n.add((r, i))
                if i != r: n.add((i, c))
            neighbors[(r, c)] = n

    # Parse inequalities into a directed dictionary
    ineq_dict = {}

    def parse_key(k):
        parts = k.strip('()').split(',')
        return float(parts[0]), float(parts[1])

    for k, v in observation['horizontal'].items():
        r_float, c_float = parse_key(k)
        r = int(r_float)
        c = int(c_float - 0.5)
        if v == '<':
            ineq_dict[((r, c), (r, c+1))] = '<'
            ineq_dict[((r, c+1), (r, c))] = '>'
        else:
            ineq_dict[((r, c), (r, c+1))] = '>'
            ineq_dict[((r, c+1), (r, c))] = '<'

    for k, v in observation['vertical'].items():
        r_float, c_float = parse_key(k)
        r = int(r_float - 0.5)
        c = int(c_float)
        if v == '^':
            ineq_dict[((r, c), (r+1, c))] = '<'
            ineq_dict[((r+1, c), (r, c))] = '>'
        else:
            ineq_dict[((r, c), (r+1, c))] = '>'
            ineq_dict[((r+1, c), (r, c))] = '<'

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            val = observation['data'][r][c]
            if val is not None:
                domains[(r, c)] = {val}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Constraint propagation function
    def revise(domains, pos1, pos2):
        revised = False
        d1 = domains[pos1]
        d2 = domains[pos2]

        # Apply inequality constraints
        ineq = ineq_dict.get((pos1, pos2))
        if ineq == '<':
            max_d2 = max(d2)
            to_remove = [x for x in d1 if x >= max_d2]
            if to_remove:
                for x in to_remove: d1.remove(x)
                revised = True
        elif ineq == '>':
            min_d2 = min(d2)
            to_remove = [x for x in d1 if x <= min_d2]
            if to_remove:
                for x in to_remove: d1.remove(x)
                revised = True

        # Apply AllDiff (not equal) constraints
        if len(d2) == 1:
            val = list(d2)[0]
            if val in d1:
                d1.remove(val)
                revised = True

        return revised

    # AC-3 Algorithm
    def ac3(domains, queue=None):
        if queue is None:
            queue = deque()
            for r in range(N):
                for c in range(N):
                    for nr, nc in neighbors[(r, c)]:
                        queue.append(((r, c), (nr, nc)))
        else:
            queue = deque(queue)

        while queue:
            (r1, c1), (r2, c2) = queue.popleft()
            if revise(domains, (r1, c1), (r2, c2)):
                if not domains[(r1, c1)]:
                    return False
                for nr, nc in neighbors[(r1, c1)]:
                    if (nr, nc) != (r2, c2):
                        queue.append(((nr, nc), (r1, c1)))
        return True

    # Initial constraint propagation
    if not ac3(domains):
        return "No Solution"

    # Backtracking search with Minimum Remaining Values (MRV) heuristic
    def backtrack(domains):
        unassigned = [pos for pos in domains if len(domains[pos]) > 1]
        if not unassigned:
            return domains

        # MRV heuristic
        pos = min(unassigned, key=lambda p: len(domains[p]))

        for val in list(domains[pos]):
            new_domains = {k: set(v) for k, v in domains.items()}
            new_domains[pos] = {val}

            # Only add arcs originating from the newly assigned variable
            queue = deque([((nr, nc), pos) for nr, nc in neighbors[pos]])

            if ac3(new_domains, queue):
                result = backtrack(new_domains)
                if result:
                    return result

        return False

    result = backtrack(domains)
    if result:
        ans = [[list(result[(r, c)])[0] for c in range(N)] for r in range(N)]
        return ans
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
