            return True
        return False

    # Helper to convert 2D dot coordinates to 1D index for DSU
    def dot_idx(r, c):
        return r * (N + 1) + c

    # Helper to get all valid incident cells and their connecting values for a given dot
    def get_incident(r, c):
        inc = []
        if r < N and c < N: inc.append((r, c, '\\')) # Bottom-right cell
        if r > 0 and c > 0: inc.append((r-1, c-1, '\\')) # Top-left cell
        if r > 0 and c < N: inc.append((r-1, c, '/')) # Top-right cell
        if r < N and c > 0: inc.append((r, c-1, '/')) # Bottom-left cell
        return inc

    # Precalculate incident cells for all dots to speed up propagation
    dot_incidents = [[get_incident(r, c) for c in range(N+1)] for r in range(N+1)]

    def propagate():
        """
        Applies constraint propagation to deduce forced moves.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Enforce degree constraints on numbered dots
            for r in range(N+1):
                for c in range(N+1):
                    if clues[r][c] is not None:
                        k = clues[r][c]
                        conn = 0
                        unass = []
                        for cr, cc, val in dot_incidents[r][c]:
                            if cells[cr][cc] == val:
                                conn += 1
                            elif cells[cr][cc] is None:
                                unass.append((cr, cc, val))

                        # Contradiction: too many connections or not enough potential connections
                        if conn > k: return False
                        if conn + len(unass) < k: return False

                        # Forced moves: if exactly enough connections, all unassigned must NOT connect
                        if conn == k and len(unass) > 0:
                            for cr, cc, val in unass:
                                cells[cr][cc] = '/' if val == '\\' else '\\'
                                changed = True
                        # Forced moves: if all remaining unassigned are needed, they MUST connect
                        elif conn + len(unass) == k and len(unass) > 0:
                            for cr, cc, val in unass:
                                cells[cr][cc] = val
                                changed = True

            # 2. Enforce loop prevention
            parent.clear()
            parent.extend(range((N+1)*(N+1)))

            # Build DSU from currently assigned cells
            for r in range(N):
                for c in range(N):
                    if cells[r][c] == '\\':
                        if not union(dot_idx(r, c), dot_idx(r+1, c+1)):
                            return False # Loop detected in assigned cells
                    elif cells[r][c] == '/':
                        if not union(dot_idx(r+1, c), dot_idx(r, c+1)):
                            return False # Loop detected in assigned cells

            # Check unassigned cells to see if either assignment forces a loop
            for r in range(N):
                for c in range(N):
                    if cells[r][c] is None:
                        loop_backslash = find(dot_idx(r, c)) == find(dot_idx(r+1, c+1))
                        loop_slash = find(dot_idx(r+1, c)) == find(dot_idx(r, c+1))

