        best_cell = None
        max_score = -1

        # Find the most constrained unassigned cell
        for r in range(N):
            for c in range(N):
                if cells[r][c] is None:
                    score = 0
                    # Evaluate constraints from incident dots
                    for dr, dc in [(r, c), (r+1, c+1), (r+1, c), (r, c+1)]:
                        if clues[dr][dc] is not None:
                            unass = sum(1 for cr, cc, _ in dot_incidents[dr][dc] if cells[cr][cc] is None)
                            if unass > 0:
                                score += 10 - unass # Higher score for fewer unassigned neighbors
                    if score > max_score:
                        max_score = score
                        best_cell = (r, c)

        if best_cell is None:
            return True # All cells assigned successfully

        r, c = best_cell

        # Save state before branching
        state = [row[:] for row in cells]

        for val in ['\\', '/']:
            cells[r][c] = val
            if propagate():
                if solve_backtrack():
                    return True
            # Restore state if branch fails
            for i in range(N):
                for j in range(N):
                    cells[i][j] = state[i][j]

        return False

    # Initial propagation and start backtracking
    if propagate() and solve_backtrack():
        return cells
    else:
        return "No Solution"

