    # connecting_value is the diagonal ('/' or '\') that connects the cell to the dot.
    def get_dot_cells(dr, dc, N):
        cells = []
        if dr > 0 and dc > 0: cells.append((dr - 1, dc - 1, '\\'))
        if dr > 0 and dc < N: cells.append((dr - 1, dc, '/'))
        if dr < N and dc > 0: cells.append((dr, dc - 1, '/'))
        if dr < N and dc < N: cells.append((dr, dc, '\\'))
        return cells

    # Builds a Disjoint Set Union (DSU) to detect and prevent closed loops.
    # Dots are nodes, diagonals are edges.
    def get_dsu(current_grid):
        parent = list(range((N + 1) * (N + 1)))
        def find(i):
            if parent[i] == i: return i
            parent[i] = find(parent[i])
            return parent[i]
        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        has_loop = False
        for r in range(N):
            for c in range(N):
                val = current_grid[r][c]
                if val == '\\':
                    u = r * (N + 1) + c
                    v = (r + 1) * (N + 1) + (c + 1)
                    if not union(u, v): has_loop = True
                elif val == '/':
                    u = (r + 1) * (N + 1) + c
                    v = r * (N + 1) + (c + 1)
                    if not union(u, v): has_loop = True
        return parent, find, union, has_loop

    # Constraint propagation engine
    # Applies human-like deduction rules to force assignments and prune the search space.
    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # Rule 1: Dot Clues
            for dr in range(N + 1):
                for dc in range(N + 1):
                    clue = data[dr][dc]
                    if clue is None: continue

                    cells = get_dot_cells(dr, dc, N)
                    connected = 0
                    unassigned_cells = []
                    for cr, cc, cval in cells:
                        if grid[cr][cc] == cval:
                            connected += 1
                        elif grid[cr][cc] is None:
                            unassigned_cells.append((cr, cc, cval))

                    # Contradiction checks
                    if connected > clue: return False
                    if connected + len(unassigned_cells) < clue: return False

                    # Deduction: If connected equals clue, all remaining must NOT connect.
                    if connected == clue and len(unassigned_cells) > 0:
                        for cr, cc, cval in unassigned_cells:
                            grid[cr][cc] = '/' if cval == '\\' else '\\'
                            changed = True
                    # Deduction: If connected + unassigned equals clue, all remaining MUST connect.
                    elif connected + len(unassigned_cells) == clue and len(unassigned_cells) > 0:
                        for cr, cc, cval in unassigned_cells:
                            grid[cr][cc] = cval
                            changed = True

            # Rule 2: Loop Prevention
            parent, find, union, has_loop = get_dsu(grid)
            if has_loop: return False

            for r in range(N):
                for c in range(N):
                    if grid[r][c] is None:
                        # Check if '\' forms a loop
                        u_bs = r * (N + 1) + c
                        v_bs = (r + 1) * (N + 1) + (c + 1)
                        loop_bs = find(u_bs) == find(v_bs)

                        # Check if '/' forms a loop
                        u_fs = (r + 1) * (N + 1) + c
                        v_fs = r * (N + 1) + (c + 1)
                        loop_fs = find(u_fs) == find(v_fs)

                        if loop_bs and loop_fs: 
                            return False # Both choices form a loop -> Contradiction
                        elif loop_bs:
                            grid[r][c] = '/'
                            changed = True
                            union(u_fs, v_fs)
                        elif loop_fs:
                            grid[r][c] = '\\'
                            changed = True
                            union(u_bs, v_bs)

        return True

    # Final validation of a fully assigned grid
    def is_valid(grid):
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None: return False
        for dr in range(N + 1):
            for dc in range(N + 1):
                clue = data[dr][dc]
                if clue is None: continue
                cells = get_dot_cells(dr, dc, N)
                connected = sum(1 for cr, cc, cval in cells if grid[cr][cc] == cval)
                if connected != clue: return False
        _, _, _, has_loop = get_dsu(grid)
        if has_loop: return False
        return True

    # Backtracking search with aggressive constraint propagation
    def solve_bt(grid):
        current_grid = [row[:] for row in grid]

        if not propagate(current_grid):
            return None

        # Check if the grid is fully solved
        solved = True
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] is None:
                    solved = False
                    break
            if not solved: break

        if solved:
            if is_valid(current_grid):
                return current_grid
            else:
                return None

        # Heuristic: Branch on a cell that is part of the most constrained dot
        best_cell = None
        min_unassigned = 999

        for dr in range(N + 1):
            for dc in range(N + 1):
                clue = data[dr][dc]
                if clue is None: continue
                cells = get_dot_cells(dr, dc, N)
                unassigned = [ (cr, cc) for cr, cc, _ in cells if current_grid[cr][cc] is None ]
                if 0 < len(unassigned) < min_unassigned:
                    min_unassigned = len(unassigned)
                    best_cell = unassigned[0]

        if best_cell is not None:
            min_r, min_c = best_cell
        else:
            # Fallback to the first available unassigned cell
            for r in range(N):
                for c in range(N):
                    if current_grid[r][c] is None:
                        min_r, min_c = r, c
                        break
                if min_r != -1: break

        # Try both possible diagonal assignments
        for val in ['/', '\\']:
            current_grid[min_r][min_c] = val
            result = solve_bt(current_grid)
            if result is not None:
                return result
            current_grid[min_r][min_c] = None # Backtrack

        return None

    initial_grid = [[None for _ in range(N)] for _ in range(N)]
    solution = solve_bt(initial_grid)
    return solution if solution else "No Solution"

