                    possible_rows = [r for r in range(N) if val in current_domains[r][c]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(current_domains[r][c]) > 1:
                            current_domains[r][c] = {val}
                            changed = True
                    elif len(possible_rows) == 0:
