                    min_r, min_c = r, c

        if min_len == N + 1:
            # All domains have size 1, puzzle is solved
            return [[list(current_domains[r][c])[0] for c in range(N)] for r in range(N)]

        # Try assigning each possible value to the chosen cell
        for val in current_domains[min_r][min_c]:
            new_domains = [[set(current_domains[r][c]) for c in range(N)] for r in range(N)]
            new_domains[min_r][min_c] = {val}
            result = backtrack(new_domains)
            if result:
                return result

        return None

    ans = backtrack(domains)
    return ans if ans else "No Solution"

