def check_connectivity_possible(state):
    """
    Checks if it's still possible for all white cells to be connected.
    It does this by running a BFS on all non-black cells starting from the first white cell.
    If any white cell is unreachable, it returns False.
    """
    N = len(state)
    white_cells = []
    for r in range(N):
        for c in range(N):
            if state[r][c] == 2:
                white_cells.append((r, c))

    if not white_cells:
        return True

    start = white_cells[0]
    visited = set([start])
    q = [start]

    while q:
        curr_r, curr_c = q.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = curr_r + dr, curr_c + dc
            if 0 <= nr < N and 0 <= nc < N:
                if state[nr][nc] != 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

    for r, c in white_cells:
        if (r, c) not in visited:
            return False
    return True

