def propagate_fast(state, grid):
    """
    Applies fast, direct logical deductions:
    1. Black cells force orthogonal neighbors to be white.
    2. White cells force other cells in the same row/col with the same value to be black.
    """
    N = len(grid)
    changed = True
    while changed:
        changed = False
        for r in range(N):
            for c in range(N):
                if state[r][c] == 1:
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N:
                            if state[nr][nc] == 1:
