                                changed = True
                    for r2 in range(N):
                        if r != r2 and grid[r2][c] == val:
                            if state[r2][c] == 2:
                                return False # Contradiction: duplicate whites
                            if state[r2][c] == 0:
                                state[r2][c] = 1
                                changed = True

        if not check_connectivity_possible(state):
            return False

        if deduce_unreachable_must_be_black(state):
            changed = True

    return True

def deduce_forced_cells(state, grid):
    """
    1-step lookahead: tries setting each unknown cell to Black and White.
    If one choice leads to an immediate contradiction, the other choice is forced.
    """
    N = len(state)
    changed = False
    for r in range(N):
        for c in range(N):
            if state[r][c] == 0:
                # Try BLACK
                state[r][c] = 1
                state_copy_b = [row[:] for row in state]
                res_b = propagate_fast(state_copy_b, grid)

                # Try WHITE
                state[r][c] = 2
                state_copy_w = [row[:] for row in state]
                res_w = propagate_fast(state_copy_w, grid)

                state[r][c] = 0 # Reset

                if not res_b and not res_w:
                    return "CONTRADICTION"
                elif not res_b:
                    state[r][c] = 2
                    changed = True
                    return True # Return early to restart full propagation
                elif not res_w:
                    state[r][c] = 1
                    changed = True
                    return True
    return False

def propagate(state, grid):
    """
    Full constraint propagation loop combining fast deductions and lookahead.
    """
    changed = True
    while changed:
        if not propagate_fast(state, grid):
            return False

        changed = deduce_forced_cells(state, grid)
        if changed == "CONTRADICTION":
            return False

    return True

def is_solved(state, grid):
    """
    Verifies if the current state is a complete and valid solution.
    """
    N = len(grid)
    for r in range(N):
        for c in range(N):
            if state[r][c] == 0:
                return False

    for r in range(N):
        for c in range(N):
            if state[r][c] == 1:
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        if state[nr][nc] == 1:
                            return False

    for r in range(N):
        seen = set()
        for c in range(N):
            if state[r][c] == 2:
                val = grid[r][c]
                if val in seen:
                    return False
                seen.add(val)

    for c in range(N):
        seen = set()
        for r in range(N):
            if state[r][c] == 2:
                val = grid[r][c]
                if val in seen:
                    return False
                seen.add(val)

    if not check_connectivity_possible(state):
        return False

    return True

def apply_initial_deductions(state, grid):
    """
    Applies standard Hitori starting patterns:
    - A B A pattern: B must be white.
    - A A pattern: Any other A in the same row/col must be black.
    """
    N = len(grid)
    for r in range(N):
        for c in range(N - 2):
            if grid[r][c] == grid[r][c+2]:
                state[r][c+1] = 2
    for c in range(N):
        for r in range(N - 2):
            if grid[r][c] == grid[r+2][c]:
                state[r+1][c] = 2

    for r in range(N):
        for c in range(N - 1):
            if grid[r][c] == grid[r][c+1]:
                for c2 in range(N):
                    if c2 != c and c2 != c+1 and grid[r][c2] == grid[r][c]:
                        state[r][c2] = 1
    for c in range(N):
        for r in range(N - 1):
            if grid[r][c] == grid[r+1][c]:
                for r2 in range(N):
                    if r2 != r and r2 != r+1 and grid[r2][c] == grid[r][c]:
                        state[r2][c] = 1

def solve_recursive(state, grid):
    """
    Backtracking search with aggressive constraint propagation.
    """
    state_copy = [row[:] for row in state]

    if not propagate(state_copy, grid):
        return None

    if is_solved(state_copy, grid):
        return state_copy

    # Find the best cell to guess (most constrained)
    best_r, best_c = -1, -1
    max_duplicates = -1

    N = len(grid)
    for r in range(N):
        for c in range(N):
            if state_copy[r][c] == 0:
                val = grid[r][c]
                dups = 0
                for c2 in range(N):
                    if c != c2 and grid[r][c2] == val and state_copy[r][c2] != 1:
                        dups += 1
                for r2 in range(N):
                    if r != r2 and grid[r2][c] == val and state_copy[r2][c] != 1:
                        dups += 1

                if dups > max_duplicates:
                    max_duplicates = dups
                    best_r, best_c = r, c

    if best_r == -1:
        return None

    # Try BLACK first
    state_copy[best_r][best_c] = 1
    res = solve_recursive(state_copy, grid)
    if res: return res

    # Try WHITE
    state_copy[best_r][best_c] = 2
    res = solve_recursive(state_copy, grid)
    if res: return res

    return None

def solve(observation):
    grid = observation['data']
    N = len(grid)
    # 0: Unknown, 1: Black, 2: White
    state = [[0] * N for _ in range(N)]

    apply_initial_deductions(state, grid)

    ans = solve_recursive(state, grid)

    if ans:
        result = []
        for r in range(N):
            row = []
            for c in range(N):
                if ans[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            result.append(row)
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
