def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    UNKNOWN = 0
    WHITE = 1
    BLACK = 2

    def get_neighbors(r, c):
        res = []
        if r > 0: res.append((r-1, c))
        if r < R - 1: res.append((r+1, c))
        if c > 0: res.append((r, c-1))
        if c < C - 1: res.append((r, c+1))
        return res

    def is_connected(state, ignore_r=-1, ignore_c=-1):
        # Checks if all non-black cells form a single connected component.
        # Optionally ignores one cell (treats it as black) to test connectivity.
        start = None
        non_black_count = 0
        for r in range(R):
            for c in range(C):
                if r == ignore_r and c == ignore_c:
                    continue
                if state[r][c] != BLACK:
                    non_black_count += 1
                    if start is None:
                        start = (r, c)

        if non_black_count == 0:
            return True

        visited = set()
        if start is None: 
            return True

        q = [start]
        visited.add(start)

        while q:
            curr_r, curr_c = q.pop(0)
            for nr, nc in get_neighbors(curr_r, curr_c):
                if nr == ignore_r and nc == ignore_c:
                    continue
                if state[nr][nc] != BLACK and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        return len(visited) == non_black_count

    def deduce(state):
        # Applies human-like deduction rules to propagate constraints.
        changed = True
        while changed:
            changed = False

            # If the current state is already disconnected, it's invalid.
            if not is_connected(state):
                return False

            # Rule 1: Adjacency to Black
            # Black cells cannot touch orthogonally.
            for r in range(R):
                for c in range(C):
                    if state[r][c] == BLACK:
                        for nr, nc in get_neighbors(r, c):
                            if state[nr][nc] == UNKNOWN:
                                state[nr][nc] = WHITE
                                changed = True
                            elif state[nr][nc] == BLACK:
                                return False # Contradiction: adjacent black cells

            # Rule 2: Uniqueness in row/col for White
            # No unshaded number appears more than once in any row or column.
            for r in range(R):
                for c in range(C):
                    if state[r][c] == WHITE:
                        val = data[r][c]
                        for i in range(C):
                            if i != c and data[r][i] == val:
                                if state[r][i] == UNKNOWN:
                                    state[r][i] = BLACK
                                    changed = True
                                elif state[r][i] == WHITE:
                                    return False # Contradiction: duplicate white numbers
                        for i in range(R):
                            if i != r and data[i][c] == val:
                                if state[i][c] == UNKNOWN:
                                    state[i][c] = BLACK
                                    changed = True
                                elif state[i][c] == WHITE:
                                    return False # Contradiction: duplicate white numbers

            # Rule 3: Connectivity
            # If shading a cell black disconnects the white cells, it must be white.
            for r in range(R):
                for c in range(C):
                    if state[r][c] == UNKNOWN:
                        if not is_connected(state, r, c):
                            state[r][c] = WHITE
                            changed = True

            # Rule 4: x, y, x pattern
            # In a sequence of A, B, A, the middle cell B must be white.
            for r in range(R):
                for c in range(C - 2):
                    if data[r][c] == data[r][c+2]:
                        if state[r][c+1] == UNKNOWN:
                            state[r][c+1] = WHITE
                            changed = True
            for c in range(C):
                for r in range(R - 2):
                    if data[r][c] == data[r+2][c]:
                        if state[r+1][c] == UNKNOWN:
                            state[r+1][c] = WHITE
                            changed = True

            # Rule 5: x, x pattern implies other x's are Black
            # If two adjacent cells have the same value, one must be black.
            # Thus, any other cell in the same row/col with that value must be black.
            for r in range(R):
                for c in range(C - 1):
                    if data[r][c] == data[r][c+1]:
                        val = data[r][c]
                        for i in range(C):
                            if i != c and i != c+1 and data[r][i] == val:
                                if state[r][i] == UNKNOWN:
                                    state[r][i] = BLACK
                                    changed = True
            for c in range(C):
                for r in range(R - 1):
                    if data[r][c] == data[r+1][c]:
                        val = data[r][c]
                        for i in range(R):
                            if i != r and i != r+1 and data[i][c] == val:
                                if state[i][c] == UNKNOWN:
                                    state[i][c] = BLACK
                                    changed = True

        return True

    def is_solved(state):
        for r in range(R):
            for c in range(C):
                if state[r][c] == UNKNOWN:
                    return False
        return True

    def is_valid_final(state):
        # Final strict validation of all rules
        for r in range(R):
            for c in range(C):
                if state[r][c] == UNKNOWN: 
                    return False
                if state[r][c] == BLACK:
                    for nr, nc in get_neighbors(r, c):
                        if state[nr][nc] == BLACK: 
                            return False
                if state[r][c] == WHITE:
                    val = data[r][c]
                    for i in range(C):
                        if i != c and state[r][i] == WHITE and data[r][i] == val: 
                            return False
                    for i in range(R):
                        if i != r and state[i][c] == WHITE and data[i][c] == val: 
                            return False
        if not is_connected(state): 
            return False
        return True

    def solve_dfs(state):
        # Apply deductions first to prune search space
        if not deduce(state):
            return None

        if is_solved(state):
            if is_valid_final(state):
                return state
            return None

        # Heuristic: pick an unknown cell with the most duplicates in its row/col
        best_cell = None
        max_dups = -1

        for r in range(R):
            for c in range(C):
                if state[r][c] == UNKNOWN:
                    val = data[r][c]
                    dups = sum(1 for i in range(C) if data[r][i] == val) + sum(1 for i in range(R) if data[i][c] == val)
                    if dups > max_dups:
                        max_dups = dups
                        best_cell = (r, c)

        if not best_cell:
            return None

        r, c = best_cell

        # Branch 1: Try setting to BLACK
        state_copy = [row[:] for row in state]
        state_copy[r][c] = BLACK
        res = solve_dfs(state_copy)
        if res: return res

        # Branch 2: Try setting to WHITE
        state_copy = [row[:] for row in state]
        state_copy[r][c] = WHITE
        res = solve_dfs(state_copy)
        if res: return res

        return None

    initial_state = [[UNKNOWN for _ in range(C)] for _ in range(R)]
    final_state = solve_dfs(initial_state)

    if final_state:
        ans = []
        for r in range(R):
            row_ans = []
            for c in range(C):
                if final_state[r][c] == BLACK:
                    row_ans.append('B')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    return "No Solution"

