OBSERVATION = {'region': [[0, 0, 0, 1, 1], [0, 0, 1, 1, 3], [2, 2, 2, 1, 3], [2, 2, 3, 3, 3], [4, 4, 4, 4, 4]], 'data': [[None, 5, None, None, 1], [None, None, None, 4, None], [None, None, None, None, None], [None, 2, None, None, None], [1, None, None, 2, None]]}

def solve(observation):
    regions = observation['region']
    data = observation['data']
    N = len(data)

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Precompute peers for each cell (cells in same row, col, or region)
    def get_peers(r, c):
        peers = set()
        for i in range(N):
            if i != c: peers.add((r, i))
            if i != r: peers.add((i, c))
        reg_id = regions[r][c]
        for i in range(N):
            for j in range(N):
                if regions[i][j] == reg_id and (i, j) != (r, c):
                    peers.add((i, j))
        return peers

    peers_map = {(r, c): get_peers(r, c) for r in range(N) for c in range(N)}

    # Precompute groups (rows, cols, regions) for hidden singles deduction
    groups = []
    for r in range(N):
        groups.append([(r, c) for c in range(N)])
    for c in range(N):
        groups.append([(r, c) for r in range(N)])

    reg_cells = {i: [] for i in range(N)}
    for r in range(N):
        for c in range(N):
            reg_cells[regions[r][c]].append((r, c))
    for cells in reg_cells.values():
        groups.append(cells)

    # Constraint propagation: Naked Singles and Hidden Singles
    def propagate(current_domains):
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles: If a cell has only one possible value, remove it from peers
            for cell, dom in current_domains.items():
                if len(dom) == 1:
                    val = list(dom)[0]
                    for peer in peers_map[cell]:
                        if val in current_domains[peer]:
                            current_domains[peer].remove(val)
                            changed = True
                            if len(current_domains[peer]) == 0:
                                return False # Contradiction found

            # 2. Hidden Singles: If a value can only go in one cell within a group, assign it
            for group in groups:
                for val in range(1, N + 1):
                    possible_cells = [cell for cell in group if val in current_domains[cell]]
                    if len(possible_cells) == 0:
                        return False # Contradiction: value cannot be placed in this group
                    if len(possible_cells) == 1:
                        cell = possible_cells[0]
                        if len(current_domains[cell]) > 1:
                            current_domains[cell] = {val}
                            changed = True

        return True

    # Backtracking search with Minimum Remaining Values (MRV) heuristic
    def search(current_domains):
        if not propagate(current_domains):
            return False

        # Check if puzzle is completely solved
        if all(len(d) == 1 for d in current_domains.values()):
            return current_domains

        # Find the cell with the fewest possible remaining values (MRV)
        min_len = N + 1
        best_cell = None
        for cell, dom in current_domains.items():
            if len(dom) > 1 and len(dom) < min_len:
                min_len = len(dom)
                best_cell = cell

        if best_cell is None:
            return False

        # Try assigning each possible value to the chosen cell
        for val in list(current_domains[best_cell]):
            new_domains = {k: set(v) for k, v in current_domains.items()}
            new_domains[best_cell] = {val}
            result = search(new_domains)
            if result:
                return result

        return False

    solution_domains = search(domains)

    if solution_domains:
        solution = [[0] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                solution[r][c] = list(solution_domains[(r, c)])[0]
        return solution
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
