    # Parse vertical constraints
    for k, v in observation.get('vertical', {}).items():
        k = k.strip('()')
        r_str, c_str = k.split(',')
        r = int(float(r_str) - 0.5)
        c = int(float(c_str))
        if v == '=':
            same_color.append(((r, c), (r+1, c)))
        elif v == 'x':
            diff_color.append(((r, c), (r+1, c)))

