    for (r1, c1), (r2, c2) in same_color + diff_color:
        constrained_cells.add((r1, c1))
        constrained_cells.add((r2, c2))

    def is_valid(g):
        for i in range(N):
            row_b = sum(1 for x in g[i] if x == 'B')
            row_w = sum(1 for x in g[i] if x == 'W')
            if row_b > N // 2 or row_w > N // 2: return False

            col_b = sum(1 for r in range(N) if g[r][i] == 'B')
            col_w = sum(1 for r in range(N) if g[r][i] == 'W')
            if col_b > N // 2 or col_w > N // 2: return False

            for j in range(N - 2):
                if g[i][j] is not None and g[i][j] == g[i][j+1] == g[i][j+2]: return False
                if g[j][i] is not None and g[j][i] == g[j+1][i] == g[j+2][i]: return False

        for (r1, c1), (r2, c2) in same_color:
            if g[r1][c1] is not None and g[r2][c2] is not None:
                if g[r1][c1] != g[r2][c2]: return False
        for (r1, c1), (r2, c2) in diff_color:
            if g[r1][c1] is not None and g[r2][c2] is not None:
                if g[r1][c1] == g[r2][c2]: return False

        return True

    def propagate(g):
        changed = True
        while changed:
