            for i in range(N):
                row_b = sum(1 for x in g[i] if x == 'B')
                row_w = sum(1 for x in g[i] if x == 'W')
                if row_b == N // 2 and row_w < N // 2:
                    for j in range(N):
                        if g[i][j] is None:
                            g[i][j] = 'W'
