                if r1 == r2: # Horizontal constraint
                    c_min, c_max = min(c1, c2), max(c1, c2)
                    if c_min - 1 >= 0 and g[r1][c_min - 1] is not None:
                        opp = 'W' if g[r1][c_min - 1] == 'B' else 'B'
                        if g[r1][c_min] is None:
                            g[r1][c_min] = opp
