                            changed = True
                elif c1 == c2: # Vertical constraint
                    r_min, r_max = min(r1, r2), max(r1, r2)
                    if r_min - 1 >= 0 and g[r_min - 1][c1] is not None:
                        opp = 'W' if g[r_min - 1][c1] == 'B' else 'B'
                        if g[r_min][c1] is None:
                            g[r_min][c1] = opp
                            changed = True
                        if g[r_max][c2] is None:
                            g[r_max][c2] = opp
                            changed = True
                    if r_max + 1 < N and g[r_max + 1][c1] is not None:
                        opp = 'W' if g[r_max + 1][c1] == 'B' else 'B'
                        if g[r_min][c1] is None:
                            g[r_min][c1] = opp
                            changed = True
                        if g[r_max][c2] is None:
                            g[r_max][c2] = opp
                            changed = True

            for (r1, c1), (r2, c2) in diff_color:
                if g[r1][c1] is not None and g[r2][c2] is None:
                    g[r2][c2] = 'W' if g[r1][c1] == 'B' else 'B'
                    changed = True
                elif g[r2][c2] is not None and g[r1][c1] is None:
                    g[r1][c1] = 'W' if g[r2][c2] == 'B' else 'B'
                    changed = True

            if not is_valid(g):
                return False

        return True

    def solve_backtrack(g):
        if not is_valid(g):
            return None

        best_cell = None
        max_score = -1

        # Heuristic: pick the most constrained empty cell
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    filled_r = sum(1 for x in g[r] if x is not None)
                    filled_c = sum(1 for x in range(N) if g[x][c] is not None)
                    score = filled_r + filled_c
                    if (r, c) in constrained_cells:
                        score += 2
                    if score > max_score:
                        max_score = score
                        best_cell = (r, c)

        if best_cell is None:
            return g # Puzzle solved

        r, c = best_cell
        for val in ['B', 'W']:
            new_g = [row[:] for row in g]
            new_g[r][c] = val
            if propagate(new_g):
                result = solve_backtrack(new_g)
                if result:
                    return result
        return None

    if not propagate(grid):
        return "No Solution"

    solution = solve_backtrack(grid)
    if solution:
        return solution
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
