OBSERVATION = {'data': [[None, None, None, 9, None, None, None], [None, 5, None, None, None, None, 8], [None, None, None, 8, None, None, 10], [None, None, None, 9, None, None, None], [7, None, None, 9, None, None, None], [3, None, None, None, None, 3, None], [None, None, None, 4, None, None, None]]}

def solve(observation):
    clues = observation['data']
    N = len(clues)

    UNKNOWN = -1
    BLACK = 0
    WHITE = 1

    grid = [[UNKNOWN for _ in range(N)] for _ in range(N)]

    # Clue cells are always WHITE
    for r in range(N):
        for c in range(N):
            if clues[r][c] is not None:
                grid[r][c] = WHITE

    def check_connectivity(g):
        """
        Checks if the graph of all non-BLACK cells is connected.
        In a valid Kuromasu, the final WHITE cells are connected.
        Since the final WHITE cells are a subset of the current non-BLACK cells,
        and any isolated component of non-BLACK cells would be forced to become all BLACK
        (which would violate the no-adjacent-black rule), the non-BLACK cells MUST be connected.
        """
        start = None
        count = 0
        for r in range(N):
            for c in range(N):
                if g[r][c] != BLACK:
                    count += 1
                    if start is None:
                        start = (r, c)
        if count == 0: return True

        visited = set([start])
        queue = [start]
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and g[nr][nc] != BLACK and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == count

    def is_articulation_point(g, r, c):
        """
        If setting an UNKNOWN cell to BLACK disconnects the non-BLACK graph,
        then it MUST be WHITE.
        """
        g[r][c] = BLACK
        conn = check_connectivity(g)
        g[r][c] = UNKNOWN
        return not conn

    def process_clue(g, r, c, V):
        """
        Applies visibility constraints for a single clue.
        Calculates min and max possible visible cells.
        Forces cells to be WHITE if required to reach the clue value.
        Forces cells to be BLACK if the clue value is already reached in a direction.
        """
        changed = False
        D = {}
        W = {}
        dirs = [(-1,0), (1,0), (0,-1), (0,1)]
        for dr, dc in dirs:
            d_dist = 1
            w_dist = 1

            # Distance to first BLACK cell or edge
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N and g[nr][nc] != BLACK:
                d_dist += 1
                nr += dr
                nc += dc
            D[(dr, dc)] = d_dist

            # Distance to first UNKNOWN or BLACK cell (i.e., consecutive WHITEs)
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N and g[nr][nc] == WHITE:
                w_dist += 1
                nr += dr
                nc += dc
            W[(dr, dc)] = w_dist

        max_v = 1 + sum(D[d] - 1 for d in dirs)
        min_v = 1 + sum(W[d] - 1 for d in dirs)

        if max_v < V or min_v > V:
            return False # Conflict detected

        for d in dirs:
            dr, dc = d
            # Minimum required WHITE cells in this direction
            req = V - (max_v - (D[d] - 1))
            for k in range(W[d], req + 1):
                nr, nc = r + k*dr, c + k*dc
                if 0 <= nr < N and 0 <= nc < N:
                    if g[nr][nc] == UNKNOWN:
                        g[nr][nc] = WHITE
                        changed = True
                    elif g[nr][nc] == BLACK:
                        return False

            # Maximum allowed WHITE cells in this direction
            allow = V - (min_v - (W[d] - 1))
            if W[d] - 1 == allow:
                # If we have exactly reached the allowed limit, the next cell MUST be BLACK
                nr, nc = r + W[d]*dr, c + W[d]*dc
                if 0 <= nr < N and 0 <= nc < N:
                    if g[nr][nc] == UNKNOWN:
                        g[nr][nc] = BLACK
                        changed = True
                    elif g[nr][nc] == WHITE:
                        return False
        return changed

    def propagate(g):
        """
        Repeatedly applies all deductive rules until no more changes can be made.
        """
        changed = True
        while changed:
            changed = False

            # 1. No adjacent BLACK cells
            for r in range(N):
                for c in range(N):
                    if g[r][c] == BLACK:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if g[nr][nc] == BLACK:
                                    return False
                                elif g[nr][nc] == UNKNOWN:
                                    g[nr][nc] = WHITE
                                    changed = True

            # 2. Global connectivity check
            if not check_connectivity(g):
                return False

            # 3. Clue visibility constraints
            for r in range(N):
                for c in range(N):
                    if clues[r][c] is not None:
                        res = process_clue(g, r, c, clues[r][c])
                        if res is False:
                            return False
                        if res is True:
                            changed = True

            # 4. Articulation points (expensive, run only if fast rules stall)
            if not changed:
                for r in range(N):
                    for c in range(N):
                        if g[r][c] == UNKNOWN:
                            if is_articulation_point(g, r, c):
                                g[r][c] = WHITE
                                changed = True
        return True

    def solve_recursive(g):
        """
        Backtracking search with aggressive 1-step lookahead constraint propagation.
        """
        if not propagate(g):
            return False

        # Check if fully solved
        solved = True
        for r in range(N):
            for c in range(N):
                if g[r][c] == UNKNOWN:
                    solved = False
                    break
            if not solved: break

        if solved:
            # Final verification of all clues
            for r in range(N):
                for c in range(N):
                    if clues[r][c] is not None:
                        vis = 1
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            while 0 <= nr < N and 0 <= nc < N and g[nr][nc] == WHITE:
                                vis += 1
                                nr += dr
                                nc += dc
                        if vis != clues[r][c]:
                            return False
            return True

        # 1-step lookahead: try setting each UNKNOWN cell to BLACK and WHITE
        for r in range(N):
            for c in range(N):
                if g[r][c] == UNKNOWN:
                    g_black = [row[:] for row in g]
                    g_black[r][c] = BLACK
                    res_black = propagate(g_black)

                    g_white = [row[:] for row in g]
                    g_white[r][c] = WHITE
                    res_white = propagate(g_white)

                    if not res_black and not res_white:
                        return False # Contradiction in both branches
                    elif not res_black:
                        g[r][c] = WHITE # Must be WHITE
                        return solve_recursive(g)
                    elif not res_white:
                        g[r][c] = BLACK # Must be BLACK
                        return solve_recursive(g)

        # If lookahead fails to prune, fallback to guessing (rare for Kuromasu)
        best_r, best_c = -1, -1
        for r in range(N):
            for c in range(N):
                if g[r][c] == UNKNOWN:
                    best_r, best_c = r, c
                    break
            if best_r != -1: break

        if best_r != -1:
            g_guess = [row[:] for row in g]
            g_guess[best_r][best_c] = WHITE
            if solve_recursive(g_guess):
                for i in range(N): g[i] = g_guess[i]
                return True

            g_guess = [row[:] for row in g]
            g_guess[best_r][best_c] = BLACK
            if solve_recursive(g_guess):
                for i in range(N): g[i] = g_guess[i]
                return True

        return False

    if solve_recursive(grid):
        # Format the output grid
        ans = []
        for r in range(N):
            row = []
            for c in range(N):
                if grid[r][c] == BLACK:
                    row.append('B')
                elif clues[r][c] is not None:
                    row.append(clues[r][c])
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
