def solve(observation):
    region = observation['region']
    data = observation['data']

    N = len(region)

    data_dict = {}
    region_cells = {}
    for r in range(N):
        for c in range(N):
            reg = region[r][c]
            if reg not in region_cells:
                region_cells[reg] = []
            region_cells[reg].append((r, c))
            if data[r][c] is not None:
                data_dict[reg] = data[r][c]

    # Precompute minimal segments that span exactly 3 regions.
    # According to Heyawake rules, a straight line of white cells cannot pass through 3 or more regions.
    # Thus, any segment consisting of the last cell of region A, all cells of region B, 
    # and the first cell of region C in a row/col MUST contain at least one black cell.
    segments = []

    # Row segments
    for r in range(N):
        curr_reg = region[r][0]
        blocks = []
        start_c = 0
        for c in range(1, N):
            if region[r][c] != curr_reg:
                blocks.append((curr_reg, start_c, c-1))
                curr_reg = region[r][c]
                start_c = c
        blocks.append((curr_reg, start_c, N-1))
        for i in range(len(blocks)-2):
            seg = []
            seg.append((r, blocks[i][2])) # Last cell of region A
            for c in range(blocks[i+1][1], blocks[i+1][2]+1):
                seg.append((r, c))        # All cells of region B
            seg.append((r, blocks[i+2][1])) # First cell of region C
            segments.append(seg)

    # Column segments
    for c in range(N):
        curr_reg = region[0][c]
        blocks = []
        start_r = 0
        for r in range(1, N):
            if region[r][c] != curr_reg:
                blocks.append((curr_reg, start_r, r-1))
                curr_reg = region[r][c]
                start_r = r
        blocks.append((curr_reg, start_r, N-1))
        for i in range(len(blocks)-2):
            seg = []
            seg.append((blocks[i][2], c))
            for r in range(blocks[i+1][1], blocks[i+1][2]+1):
                seg.append((r, c))
            seg.append((blocks[i+2][1], c))
            segments.append(seg)

    segments_containing = {}
    for r in range(N):
        for c in range(N):
            segments_containing[(r, c)] = []
    for seg in segments:
        for r, c in seg:
            segments_containing[(r, c)].append(seg)

    def check_connectivity(grid):
        zeros = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    zeros.append((r, c))
        if not zeros: return True

        start = zeros[0]
        visited = set([start])
        q = [start]
        while q:
            curr_r, curr_c = q.pop(0)
            for nr, nc in [(curr_r-1,curr_c), (curr_r+1,curr_c), (curr_r,curr_c-1), (curr_r,curr_c+1)]:
                if 0 <= nr < N and 0 <= nc < N:
                    # Traverse both white (0) and unassigned (-1) cells
                    if grid[nr][nc] != 1 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))

        for z in zeros:
            if z not in visited: return False
        return True

    def propagate(grid, queue):
        while queue:
            r, c, val = queue.pop(0)
            if grid[r][c] != -1:
                if grid[r][c] != val: return False
                continue
            grid[r][c] = val

            if val == 1:
                # Black cells cannot touch orthogonally
                for nr, nc in [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]:
                    if 0 <= nr < N and 0 <= nc < N:
                        if grid[nr][nc] == 1: return False
                        if grid[nr][nc] == -1: queue.append((nr, nc, 0))

            # Region clue constraints
            reg = region[r][c]
            clue = data_dict.get(reg)
            if clue is not None:
                cells = region_cells[reg]
                ones = sum(1 for cr, cc in cells if grid[cr][cc] == 1)
                zeros = sum(1 for cr, cc in cells if grid[cr][cc] == 0)
                unassigned = len(cells) - ones - zeros
                if ones > clue: return False
                if ones + unassigned < clue: return False
                if ones == clue and unassigned > 0:
                    for cr, cc in cells:
                        if grid[cr][cc] == -1: queue.append((cr, cc, 0))
                if ones + unassigned == clue and unassigned > 0:
                    for cr, cc in cells:
                        if grid[cr][cc] == -1: queue.append((cr, cc, 1))

            # Line of sight (segment) constraints
            for seg in segments_containing[(r, c)]:
                ones = sum(1 for cr, cc in seg if grid[cr][cc] == 1)
                zeros = sum(1 for cr, cc in seg if grid[cr][cc] == 0)
                unassigned = len(seg) - ones - zeros
                if ones == 0 and unassigned == 0: return False
                if ones == 0 and unassigned == 1:
                    for cr, cc in seg:
                        if grid[cr][cc] == -1: queue.append((cr, cc, 1))

        if not check_connectivity(grid): return False
        return True

    def solve_recursive(grid):
        unassigned = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] == -1:
                    unassigned.append((r, c))

        if not unassigned:
            if check_connectivity(grid):
                return grid
            return None

        # Heuristic: pick cell involved in the most segment constraints and with a region clue
        def score(cell):
            r, c = cell
            reg = region[r][c]
            s = 0
            if reg in data_dict:
                s += 10
            s += len(segments_containing[(r, c)])
            return s

        unassigned.sort(key=score, reverse=True)
        r, c = unassigned[0]

        for val in [1, 0]:
            new_grid = [row[:] for row in grid]
            queue = [(r, c, val)]
            if propagate(new_grid, queue):
                result = solve_recursive(new_grid)
                if result:
                    return result

        return None

    grid = [[-1 for _ in range(N)] for _ in range(N)]
    queue = []

    # Initial constraint population from 0 and full clues
    for reg, clue in data_dict.items():
        cells = region_cells[reg]
        if clue == 0:
            for r, c in cells:
                queue.append((r, c, 0))
        elif clue == len(cells):
            for r, c in cells:
                queue.append((r, c, 1))

    if not propagate(grid, queue):
        return "No Solution"

    solution = solve_recursive(grid)

    if solution:
        ans = []
        for r in range(N):
            row = []
            for c in range(N):
                if solution[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    return "No Solution"

