class FutoshikiSolver:
    def __init__(self, observation):
        self.n = len(observation['data'])
        # Initialize domains for each cell: 1 to N
        self.domains = [[set(range(1, self.n + 1)) for _ in range(self.n)] for _ in range(self.n)]
        self.inequalities = [] # Stores tuples of (r1, c1, r2, c2) meaning grid[r1][c1] < grid[r2][c2]

        # Apply givens to domains
        for r in range(self.n):
            for c in range(self.n):
                val = observation['data'][r][c]
                if val is not None:
                    self.domains[r][c] = {val}

        # Parse horizontal inequalities
        for key, symbol in observation['horizontal'].items():
            r_str, c_str = key.strip('()').split(',')
            r = int(r_str)
            c = float(c_str)
            c1 = int(c - 0.5)
            c2 = int(c + 0.5)
            if symbol == '<':
                self.inequalities.append((r, c1, r, c2))
            elif symbol == '>':
                self.inequalities.append((r, c2, r, c1))

        # Parse vertical inequalities
        for key, symbol in observation['vertical'].items():
            r_str, c_str = key.strip('()').split(',')
            r = float(r_str)
            c = int(c_str)
            r1 = int(r - 0.5)
            r2 = int(r + 0.5)
            if symbol == '^':
                self.inequalities.append((r1, c, r2, c))
            elif symbol == 'v':
                self.inequalities.append((r2, c, r1, c))

    def propagate(self):
        """
        Applies constraint propagation to reduce domains.
        Returns False if a contradiction is found (empty domain), True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Row and Column AllDiff constraints
            for r in range(self.n):
                for c in range(self.n):
                    if len(self.domains[r][c]) == 1:
                        val = list(self.domains[r][c])[0]
                        # Remove from same row
                        for c2 in range(self.n):
                            if c != c2 and val in self.domains[r][c2]:
                                self.domains[r][c2].remove(val)
                                changed = True
                                if not self.domains[r][c2]: return False
                        # Remove from same column
                        for r2 in range(self.n):
                            if r != r2 and val in self.domains[r2][c]:
                                self.domains[r2][c].remove(val)
                                changed = True
                                if not self.domains[r2][c]: return False

            # 2. Inequality constraints (grid[r1][c1] < grid[r2][c2])
            for r1, c1, r2, c2 in self.inequalities:
                max_b = max(self.domains[r2][c2])
                to_remove_a = [x for x in self.domains[r1][c1] if x >= max_b]
                for x in to_remove_a:
                    self.domains[r1][c1].remove(x)
                    changed = True
                if not self.domains[r1][c1]: return False

                min_a = min(self.domains[r1][c1])
                to_remove_b = [x for x in self.domains[r2][c2] if x <= min_a]
                for x in to_remove_b:
                    self.domains[r2][c2].remove(x)
                    changed = True
                if not self.domains[r2][c2]: return False

            # 3. Hidden Singles (if a value can only go in one cell in a row/col, assign it)
            for r in range(self.n):
                for val in range(1, self.n + 1):
                    possible_cols = [c for c in range(self.n) if val in self.domains[r][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(self.domains[r][c]) > 1:
                            self.domains[r][c] = {val}
                            changed = True
                    elif len(possible_cols) == 0:
                        return False

            for c in range(self.n):
                for val in range(1, self.n + 1):
                    possible_rows = [r for r in range(self.n) if val in self.domains[r][c]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(self.domains[r][c]) > 1:
                            self.domains[r][c] = {val}
                            changed = True
                    elif len(possible_rows) == 0:
                        return False

        return True

    def solve(self):
        """
        Recursive backtracking search with MRV (Minimum Remaining Values) heuristic.
        """
        # Propagate constraints first
        if not self.propagate():
            return None

        # Find the unassigned cell with the smallest domain (MRV)
        min_len = self.n + 1
        best_cell = None
        for r in range(self.n):
            for c in range(self.n):
                if len(self.domains[r][c]) > 1:
                    if len(self.domains[r][c]) < min_len:
                        min_len = len(self.domains[r][c])
                        best_cell = (r, c)

        # If all cells are assigned, we found a solution
        if best_cell is None:
            return [[list(self.domains[r][c])[0] for c in range(self.n)] for r in range(self.n)]

        r, c = best_cell

        # Try assigning each possible value to the chosen cell
        for val in sorted(list(self.domains[r][c])):
            # Save the current state of domains
            saved_domains = [[set(self.domains[i][j]) for j in range(self.n)] for i in range(self.n)]

            # Make the assignment
            self.domains[r][c] = {val}

            # Recurse
            result = self.solve()
            if result is not None:
                return result

            # Backtrack: restore the domains
            self.domains = saved_domains

        return None

def solve(observation):
    solver = FutoshikiSolver(observation)
    result = solver.solve()
    if result:
        return result
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
