import sys

sys.setrecursionlimit(2000)

def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']

    R = len(region_grid)
    C = len(region_grid[0])

    region_cells = {}
    region_data = {}

    for r in range(R):
        for c in range(C):
            reg = region_grid[r][c]
            if reg not in region_cells:
