                region_data[reg] = data_grid[r][c]
            else:
                if data_grid[r][c] is not None:
                    region_data[reg] = data_grid[r][c]
            region_cells[reg].append((r, c))

    segments = []
    # Precompute all minimal straight segments that span exactly 3 regions.
    # According to Heyawake rules, such segments cannot be entirely white.
    for r in range(R):
        c = 0
        while c < C:
            start_c = c
            reg = region_grid[r][c]
            while c < C and region_grid[r][c] == reg:
                c += 1
            end_c = c - 1
            if start_c > 0 and end_c < C - 1:
                seg = [(r, i) for i in range(start_c - 1, end_c + 2)]
                segments.append(seg)

    for c in range(C):
        r = 0
        while r < R:
            start_r = r
            reg = region_grid[r][c]
            while r < R and region_grid[r][c] == reg:
                r += 1
            end_r = r - 1
            if start_r > 0 and end_r < R - 1:
                seg = [(i, c) for i in range(start_r - 1, end_r + 2)]
                segments.append(seg)

    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # 1. No adjacent black cells
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if grid[nr][nc] == 1:
                                    return False
                                if grid[nr][nc] == -1:
                                    grid[nr][nc] = 0
                                    changed = True

            # 2. Region counts
            for reg, cells in region_cells.items():
                target = region_data[reg]
                if target is None: continue
                kb = sum(1 for r, c in cells if grid[r][c] == 1)
                ku = sum(1 for r, c in cells if grid[r][c] == -1)
                if kb > target: return False
                if kb + ku < target: return False
                if kb == target and ku > 0:
                    for r, c in cells:
                        if grid[r][c] == -1:
                            grid[r][c] = 0
                            changed = True
                if kb + ku == target and ku > 0:
                    for r, c in cells:
                        if grid[r][c] == -1:
                            grid[r][c] = 1
                            changed = True

            # 3. Segments constraint (Line of sight)
            for seg in segments:
                kb = sum(1 for r, c in seg if grid[r][c] == 1)
                ku = sum(1 for r, c in seg if grid[r][c] == -1)
                if kb == 0 and ku == 0: return False
                if kb == 0 and ku == 1:
                    for r, c in seg:
                        if grid[r][c] == -1:
                            grid[r][c] = 1
                            changed = True

            # 4. Connectivity and Articulation Points of non-black cells
            adj = {}
            for r in range(R):
                for c in range(C):
                    if grid[r][c] != 1:
                        adj[(r, c)] = []
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != 1:
                                adj[(r, c)].append((nr, nc))

            if not adj: continue

            start_node = next(iter(adj))
            visited = set()
            tin = {}
            low = {}
            timer = 0
            articulation_points = set()

            def dfs(v, p=-1):
                nonlocal timer
                visited.add(v)
                tin[v] = low[v] = timer
                timer += 1
                children = 0
                for to in adj[v]:
                    if to == p: continue
                    if to in visited:
                        low[v] = min(low[v], tin[to])
                    else:
                        children += 1
                        dfs(to, v)
                        low[v] = min(low[v], low[to])
                        if low[to] >= tin[v] and p != -1:
                            articulation_points.add(v)
                if p == -1 and children > 1:
                    articulation_points.add(v)

            dfs(start_node)

            # If the graph of non-black cells is disconnected, it's invalid
            if len(visited) < len(adj):
                return False

            # Any articulation point in the non-black cell graph MUST be white
            for r, c in articulation_points:
                if grid[r][c] == -1:
                    grid[r][c] = 0
                    changed = True

        return True

    def solve_recursive(grid):
        if not propagate(grid):
            return None

        unassigned = []
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    unassigned.append((r, c))

        if not unassigned:
            return grid

        best_cell = None
        best_score = float('inf')

        # Branching heuristic: pick an unknown cell in a constrained region
        for reg, cells in region_cells.items():
            if region_data[reg] is not None:
                ku = sum(1 for r, c in cells if grid[r][c] == -1)
                if 0 < ku < best_score:
                    best_score = ku
                    for r, c in cells:
                        if grid[r][c] == -1:
                            best_cell = (r, c)
                            break

        if best_cell is None:
            best_cell = unassigned[0]

        r, c = best_cell

        # Try setting to 1 (black) first as it triggers more constraints
        for val in [1, 0]:
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val
            result = solve_recursive(new_grid)
            if result:
                return result

        return None

    initial_grid = [[-1 for _ in range(C)] for _ in range(R)]
    solution = solve_recursive(initial_grid)

    if solution:
        ans = []
        for r in range(R):
            row_ans = []
            for c in range(C):
                if solution[r][c] == 1:
                    row_ans.append('B')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    else:
        return "No Solution"

