            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def get_valid_combos(r, c, V, current_grid):
        valid_L = []
        for dr, dc in DIRS:
            reach_W = 0
            reach_U = 0
            nr, nc = r + dr, c + dc
            while 0 <= nr < N and 0 <= nc < N and current_grid[nr][nc] != BLACK:
                if current_grid[nr][nc] == WHITE:
                    if reach_U == 0:
                        reach_W += 1
                reach_U += 1
                nr += dr
                nc += dc

            possible_l = []
            for l in range(reach_W, reach_U + 1):
                if l < reach_U:
                    br, bc = r + dr * (l + 1), c + dc * (l + 1)
                    if current_grid[br][bc] == WHITE:
                        continue
                    adj_black = False
                    for nbr, nbc in neighbors(br, bc):
                        if current_grid[nbr][nbc] == BLACK:
                            adj_black = True
                            break
                    if adj_black:
                        continue
                possible_l.append(l)
            valid_L.append(possible_l)

        combos = []
        set_L3 = set(valid_L[3])
        for l0 in valid_L[0]:
            for l1 in valid_L[1]:
                for l2 in valid_L[2]:
                    req_l3 = V - 1 - l0 - l1 - l2
                    if req_l3 in set_L3:
                        combos.append((l0, l1, l2, req_l3))
        return combos

    def propagate(current_grid):
        changed = True
        while changed:
            changed = False

            # 1. No adjacent black cells
            for r in range(N):
                for c in range(N):
                    if current_grid[r][c] == BLACK:
                        for nr, nc in neighbors(r, c):
                            if current_grid[nr][nc] == BLACK:
                                return False
                            if current_grid[nr][nc] == UNKNOWN:
                                current_grid[nr][nc] = WHITE
                                changed = True

            # 2. Clue visibility combinations
            for r, c, V in clues:
                combos = get_valid_combos(r, c, V, current_grid)
                if not combos:
                    return False

                for i, (dr, dc) in enumerate(DIRS):
                    min_l = min(combo[i] for combo in combos)
                    max_l = max(combo[i] for combo in combos)

                    nr, nc = r + dr, c + dc
                    for _ in range(min_l):
                        if current_grid[nr][nc] == UNKNOWN:
                            current_grid[nr][nc] = WHITE
                            changed = True
                        nr += dr
                        nc += dc

                    curr_reach_W = 0
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < N and 0 <= nc < N and current_grid[nr][nc] == WHITE:
                        curr_reach_W += 1
                        nr += dr
                        nc += dc

                    if curr_reach_W == max_l:
                        br, bc = r + dr * (max_l + 1), c + dc * (max_l + 1)
                        if 0 <= br < N and 0 <= bc < N:
                            if current_grid[br][bc] == UNKNOWN:
                                current_grid[br][bc] = BLACK
                                changed = True
                            elif current_grid[br][bc] == WHITE:
                                return False

            # 3. Connectivity of WHITE cells
            reachable = set()
            start_r, start_c, _ = clues[0]
            q = [(start_r, start_c)]
            reachable.add((start_r, start_c))
            while q:
                curr_r, curr_c = q.pop(0)
                for nr, nc in neighbors(curr_r, curr_c):
                    if current_grid[nr][nc] in (WHITE, UNKNOWN) and (nr, nc) not in reachable:
                        reachable.add((nr, nc))
                        q.append((nr, nc))

            for r in range(N):
                for c in range(N):
                    if (r, c) not in reachable:
                        if current_grid[r][c] == WHITE:
