                        if current_grid[r][c] == UNKNOWN:
                            current_grid[r][c] = BLACK
                            changed = True

            # 4. Articulation points
            if not changed:
                for r in range(N):
                    for c in range(N):
                        if current_grid[r][c] == UNKNOWN:
                            current_grid[r][c] = BLACK

                            reachable_test = set()
                            q_test = [(start_r, start_c)]
                            reachable_test.add((start_r, start_c))
                            while q_test:
                                curr_r, curr_c = q_test.pop(0)
                                for nr, nc in neighbors(curr_r, curr_c):
                                    if current_grid[nr][nc] in (WHITE, UNKNOWN) and (nr, nc) not in reachable_test:
                                        reachable_test.add((nr, nc))
                                        q_test.append((nr, nc))

                            disconnects = False
                            for wr in range(N):
                                for wc in range(N):
                                    if current_grid[wr][wc] == WHITE and (wr, wc) not in reachable_test:
                                        disconnects = True
                                        break
                                if disconnects: break

                            current_grid[r][c] = UNKNOWN

                            if disconnects:
                                current_grid[r][c] = WHITE
                                changed = True
                                break
                    if changed:
