# Helper function to count visible skyscrapers in a line
def get_visible_count(line):
    count = 0
    max_h = 0
    for h in line:
        if h > max_h:
            count += 1
            max_h = h
    return count

# Generates all valid permutations for a line given its start and end clues
def get_valid_perms_helper(N, clue_start, clue_end):
    valid = []
    def backtrack(path, available, max_so_far, visible_count):
        # Prune if we already see more than allowed
        if clue_start > 0 and visible_count > clue_start:
            return
        # Prune if we can't possibly reach the required visible count
        if clue_start > 0 and visible_count + len(available) < clue_start:
            return

        if not available:
            if clue_start > 0 and visible_count != clue_start:
                return
            if clue_end > 0 and get_visible_count(path[::-1]) != clue_end:
                return
            valid.append(tuple(path))
            return

        for v in available:
            new_max = max(max_so_far, v)
            new_visible = visible_count + (1 if v > max_so_far else 0)
            new_available = available - {v}
            path.append(v)
            backtrack(path, new_available, new_max, new_visible)
            path.pop()

    backtrack([], set(range(1, N + 1)), 0, 0)
    return valid

# Wrapper to handle cases where only the end clue is provided efficiently
def get_valid_perms(N, clue_start, clue_end):
    if clue_start == 0 and clue_end > 0:
        valid_reversed = get_valid_perms_helper(N, clue_end, 0)
        return [p[::-1] for p in valid_reversed]
    else:
        return get_valid_perms_helper(N, clue_start, clue_end)

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    # Precompute all valid permutations for each row and column based on clues
    row_perms = [get_valid_perms(N, L[i], R[i]) for i in range(N)]
    col_perms = [get_valid_perms(N, U[i], D[i]) for i in range(N)]

    # Initialize domains for each cell to {1..N}
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Constraint propagation (AC-3 style)
    def propagate(domains, row_perms, col_perms):
        changed = True
        while changed:
            changed = False

            # Update cell domains based on valid permutations
            for r in range(N):
                for c in range(N):
                    possible_from_row = {p[c] for p in row_perms[r]}
                    possible_from_col = {p[r] for p in col_perms[c]}
                    new_domain = domains[r][c] & possible_from_row & possible_from_col

                    if not new_domain:
                        return False # Contradiction found

                    if len(new_domain) < len(domains[r][c]):
                        domains[r][c] = new_domain
                        changed = True

            # Filter row permutations based on updated cell domains
            for r in range(N):
                new_row_perms = [p for p in row_perms[r] if all(p[c] in domains[r][c] for c in range(N))]
                if not new_row_perms:
                    return False
                if len(new_row_perms) < len(row_perms[r]):
                    row_perms[r] = new_row_perms
                    changed = True

            # Filter column permutations based on updated cell domains
            for c in range(N):
                new_col_perms = [p for p in col_perms[c] if all(p[r] in domains[r][c] for r in range(N))]
                if not new_col_perms:
                    return False
                if len(new_col_perms) < len(col_perms[c]):
                    col_perms[c] = new_col_perms
                    changed = True

        return True

    # Backtracking search with constraint propagation
    def search(domains, row_perms, col_perms):
        if not propagate(domains, row_perms, col_perms):
            return None

        solved = True
        min_len = N + 1
        best_cell = None

        # Find the cell with the smallest domain > 1 for the next guess (MRV heuristic)
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    solved = False
                    if len(domains[r][c]) < min_len:
                        min_len = len(domains[r][c])
                        best_cell = (r, c)
                elif len(domains[r][c]) == 0:
                    return None

        if solved:
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        r, c = best_cell
        for v in domains[r][c]:
            # Create deep copies for the backtracking branch
            new_domains = [[set(domains[i][j]) for j in range(N)] for i in range(N)]
            new_row_perms = [list(row_perms[i]) for i in range(N)]
            new_col_perms = [list(col_perms[i]) for i in range(N)]

            new_domains[r][c] = {v}
            result = search(new_domains, new_row_perms, new_col_perms)
            if result:
                return result

        return None

    ans = search(domains, row_perms, col_perms)
    return ans if ans else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
