            c_start = regs[i][2]
            c_end = regs[i+2][1]
            cells = [(r, c) for c in range(c_start, c_end + 1)]
            line_constraints.append(cells)

    # Column constraints
    for c in range(C):
        regs = []
        for r in range(R):
            reg_id = region[r][c]
            if not regs or regs[-1][0] != reg_id:
                regs.append([reg_id, r, r])
            else:
                regs[-1][2] = r
        for i in range(len(regs) - 2):
            r_start = regs[i][2]
            r_end = regs[i+2][1]
            cells = [(r, c) for r in range(r_start, r_end + 1)]
            line_constraints.append(cells)

    grid = [[-1]*C for _ in range(R)]

    def is_valid(r, c):
        return 0 <= r < R and 0 <= c < C

    def get_neighbors(r, c):
        return [(r+dr, c+dc) for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)] if is_valid(r+dr, c+dc)]

    def check_connectivity():
        start = None
        target_count = 0
        for r in range(R):
            for c in range(C):
                if grid[r][c] != 1:
                    target_count += 1
                    if start is None:
                        start = (r, c)
        if target_count == 0:
            return True

        visited = set([start])
        q = [start]
        while q:
            curr_r, curr_c = q.pop(0)
            for nr, nc in get_neighbors(curr_r, curr_c):
                if grid[nr][nc] != 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == target_count

    def is_state_valid():
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 1:
                    for nr, nc in get_neighbors(r, c):
                        if grid[nr][nc] == 1:
                            return False

        for reg_id, cells in regions.items():
            if reg_id in clues:
                blacks = sum(1 for r, c in cells if grid[r][c] == 1)
                unassigned = sum(1 for r, c in cells if grid[r][c] == -1)
                if blacks > clues[reg_id]:
                    return False
                if blacks + unassigned < clues[reg_id]:
                    return False

        for cells in line_constraints:
            blacks = sum(1 for r, c in cells if grid[r][c] == 1)
            unassigned = sum(1 for r, c in cells if grid[r][c] == -1)
            if blacks == 0 and unassigned == 0:
                return False

        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            # 1. Adjacent to black must be white
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        for nr, nc in get_neighbors(r, c):
                            if grid[nr][nc] == -1:
                                grid[nr][nc] = 0
                                changed = True
                            elif grid[nr][nc] == 1:
                                return False

            # 2. Region clues
            for reg_id, cells in regions.items():
                if reg_id in clues:
                    blacks = 0
                    unassigned = []
                    for r, c in cells:
                        if grid[r][c] == 1:
                            blacks += 1
                        elif grid[r][c] == -1:
                            unassigned.append((r, c))

                    if blacks > clues[reg_id] or blacks + len(unassigned) < clues[reg_id]:
                        return False

                    if blacks == clues[reg_id] and unassigned:
                        for r, c in unassigned:
                            grid[r][c] = 0
                            changed = True
                    elif blacks + len(unassigned) == clues[reg_id] and unassigned:
                        for r, c in unassigned:
                            grid[r][c] = 1
                            changed = True

            # 3. Line constraints
            for cells in line_constraints:
                blacks = 0
                unassigned = []
                for r, c in cells:
                    if grid[r][c] == 1:
                        blacks += 1
                    elif grid[r][c] == -1:
                        unassigned.append((r, c))
                if blacks == 0:
                    if len(unassigned) == 0:
                        return False
                    elif len(unassigned) == 1:
                        r, c = unassigned[0]
                        grid[r][c] = 1
                        changed = True

            # 4. Connectivity check
            if not check_connectivity():
                return False

        return True

    def solve_backtrack():
        saved_grid = [row[:] for row in grid]

        if not propagate():
            for r in range(R):
                for c in range(C):
                    grid[r][c] = saved_grid[r][c]
            return False

        best_cell = None
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    best_cell = (r, c)
                    break
            if best_cell:
                break

        if not best_cell:
            if is_state_valid() and check_connectivity():
                return True
            else:
                for r in range(R):
                    for c in range(C):
                        grid[r][c] = saved_grid[r][c]
                return False

        r, c = best_cell

        # Try White (0)
        grid[r][c] = 0
        if solve_backtrack():
            return True

        # Try Black (1)
        grid[r][c] = 1
        if solve_backtrack():
            return True

        # Backtrack
        for r in range(R):
            for c in range(C):
                grid[r][c] = saved_grid[r][c]
        return False

    if not solve_backtrack():
        return "No Solution"

    res = []
    for r in range(R):
        row_res = []
        for c in range(C):
            if grid[r][c] == 1:
                row_res.append('B')
            else:
                row_res.append(None)
        res.append(row_res)
    return res

if __name__ == "__main__":
    print(solve(OBSERVATION))
