        if D[i] > 0:
            for r in range(N):
                max_val = N - D[i] + 1 + (N - 1 - r)
                domains[r][i] = {v for v in domains[r][i] if v <= max_val}
            if D[i] == 1: 
                domains[N-1][i] = {N}
            if D[i] == N:
                for r in range(N): 
                    domains[r][i] = {N - r}

        if L[i] > 0:
            for c in range(N):
                max_val = N - L[i] + 1 + c
                domains[i][c] = {v for v in domains[i][c] if v <= max_val}
            if L[i] == 1: 
                domains[i][0] = {N}
            if L[i] == N:
                for c in range(N): 
                    domains[i][c] = {c + 1}

        if R[i] > 0:
            for c in range(N):
                max_val = N - R[i] + 1 + (N - 1 - c)
                domains[i][c] = {v for v in domains[i][c] if v <= max_val}
            if R[i] == 1: 
                domains[i][N-1] = {N}
            if R[i] == N:
                for c in range(N): 
                    domains[i][c] = {N - c}

    grid = [[0] * N for _ in range(N)]

    def is_valid(r, c, val):
        # Check row and column uniqueness
        for i in range(c):
            if grid[r][i] == val: return False
        for i in range(r):
            if grid[i][c] == val: return False

        grid[r][c] = val
        valid = True

        # Aggressive partial line visibility checks
        if L[r] > 0:
            vis = 0
            m = 0
            for i in range(c + 1):
                if grid[r][i] > m:
                    vis += 1
                    m = grid[r][i]
            # If current visible + max possible remaining is less than clue, prune
            if vis + (N - 1 - c) < L[r]: valid = False
            # If current visible already exceeds clue, prune
            if vis > L[r]: valid = False

        if valid and U[c] > 0:
            vis = 0
            m = 0
            for i in range(r + 1):
                if grid[i][c] > m:
                    vis += 1
                    m = grid[i][c]
