            if vis > U[c]: valid = False

        # Full line visibility checks for right and down
        if valid and R[r] > 0 and c == N - 1:
            vis = 0
            m = 0
            for i in range(N - 1, -1, -1):
                if grid[r][i] > m:
                    vis += 1
                    m = grid[r][i]
            if vis != R[r]: valid = False

        if valid and D[c] > 0 and r == N - 1:
            vis = 0
            m = 0
            for i in range(N - 1, -1, -1):
                if grid[i][c] > m:
                    vis += 1
                    m = grid[i][c]
            if vis != D[c]: valid = False

        grid[r][c] = 0
        return valid

    def solve_bt(r, c):
        if r == N:
            return True

        next_r, next_c = (r, c + 1) if c + 1 < N else (r + 1, 0)

        for val in range(1, N + 1):
            if val in domains[r][c]:
                if is_valid(r, c, val):
                    grid[r][c] = val
                    if solve_bt(next_r, next_c):
                        return True
                    grid[r][c] = 0
        return False

    if solve_bt(0, 0):
        return grid
    return "No Solution"

