def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    R = len(region_grid)
    C = len(region_grid[0])

    regions = {}
    region_clues = {}
    for r in range(R):
        for c in range(C):
            reg_id = region_grid[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
                region_clues[reg_id] = data_grid[r][c]
            else:
                if data_grid[r][c] is not None:
                    region_clues[reg_id] = data_grid[r][c]
            regions[reg_id].append((r, c))

    segments = []
    # Precompute all minimal straight segments that span exactly 3 regions.
    # According to the rules, a straight white line cannot pass through more than 2 regions.
    # Thus, any segment spanning 3 regions must contain at least one black cell.

    # Rows
    for r in range(R):
        intervals = []
        curr_reg = region_grid[r][0]
        start_c = 0
        for c in range(1, C):
            if region_grid[r][c] != curr_reg:
                intervals.append((start_c, c - 1, curr_reg))
                curr_reg = region_grid[r][c]
                start_c = c
        intervals.append((start_c, C - 1, curr_reg))

        for i in range(len(intervals) - 2):
            seg = [(r, intervals[i][1])]
            for c in range(intervals[i+1][0], intervals[i+1][1] + 1):
                seg.append((r, c))
            seg.append((r, intervals[i+2][0]))
            segments.append(seg)

    # Cols
    for c in range(C):
        intervals = []
        curr_reg = region_grid[0][c]
        start_r = 0
        for r in range(1, R):
            if region_grid[r][c] != curr_reg:
                intervals.append((start_r, r - 1, curr_reg))
                curr_reg = region_grid[r][c]
                start_r = r
        intervals.append((start_r, R - 1, curr_reg))

        for i in range(len(intervals) - 2):
            seg = [(intervals[i][1], c)]
            for r in range(intervals[i+1][0], intervals[i+1][1] + 1):
                seg.append((r, c))
            seg.append((intervals[i+2][0], c))
            segments.append(seg)

    def check_connectivity_and_reachability(grid):
        whites = []
        unknowns = []
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0: whites.append((r, c))
                elif grid[r][c] == -1: unknowns.append((r, c))

        if not whites: 
            return True, []

        start = whites[0]
        q = [start]
        visited = {start}

        head = 0
        while head < len(q):
            curr = q[head]
            head += 1
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = curr[0]+dr, curr[1]+dc
                if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited:
                    if grid[nr][nc] in (0, -1):
                        visited.add((nr, nc))
                        q.append((nr, nc))

        # If any known white cell is unreachable, the white cells are disconnected
        for w in whites:
            if w not in visited:
                return False, []

        # Any unknown cell that cannot reach the main white component MUST be black
        forced_blacks = []
        for u in unknowns:
            if u not in visited:
                forced_blacks.append(u)

        return True, forced_blacks

    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # 1. No orthogonal black cells
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if grid[nr][nc] == 1:
                                    return False
                                if grid[nr][nc] == -1:
                                    grid[nr][nc] = 0
                                    changed = True

            # 2. Region clues
            for reg_id, cells in regions.items():
                clue = region_clues[reg_id]
                if clue is None: continue

                num_black = sum(1 for r, c in cells if grid[r][c] == 1)
                num_unknown = sum(1 for r, c in cells if grid[r][c] == -1)

                if num_black > clue:
                    return False
                if num_black + num_unknown < clue:
                    return False

                if num_black == clue and num_unknown > 0:
                    for r, c in cells:
                        if grid[r][c] == -1:
                            grid[r][c] = 0
                            changed = True
                elif num_black + num_unknown == clue and num_unknown > 0:
                    for r, c in cells:
                        if grid[r][c] == -1:
                            grid[r][c] = 1
                            changed = True

            # 3. 3-region segments (Rule: no straight white line spans >2 regions)
            for seg in segments:
                num_black = sum(1 for r, c in seg if grid[r][c] == 1)
                if num_black > 0:
                    continue

                num_unknown = sum(1 for r, c in seg if grid[r][c] == -1)

                if num_unknown == 0:
                    return False
                if num_unknown == 1:
                    for r, c in seg:
                        if grid[r][c] == -1:
                            grid[r][c] = 1
                            changed = True

            # 4. Connectivity and Reachability
            is_valid, forced_blacks = check_connectivity_and_reachability(grid)
            if not is_valid:
                return False
            if forced_blacks:
                for r, c in forced_blacks:
                    if grid[r][c] == -1:
                        grid[r][c] = 1
                        changed = True

        return True

    def solve_recursive(grid):
        if not propagate(grid):
            return None

        best_cell = None
        best_score = float('inf')

        # Heuristic: pick the most constrained unknown cell
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    score = 0
                    reg_id = region_grid[r][c]
                    clue = region_clues[reg_id]
                    if clue is not None:
                        cells = regions[reg_id]
                        num_black = sum(1 for r1, c1 in cells if grid[r1][c1] == 1)
                        num_unknown = sum(1 for r1, c1 in cells if grid[r1][c1] == -1)
                        needed = clue - num_black
                        slack = num_unknown - needed
                        score += slack * 10
                    else:
                        score += 1000

                    active_segs = 0
                    for seg in segments:
                        if (r, c) in seg:
                            num_black = sum(1 for r1, c1 in seg if grid[r1][c1] == 1)
                            if num_black == 0:
                                active_segs += 1
                    score -= active_segs

                    if score < best_score:
                        best_score = score
                        best_cell = (r, c)

        if best_cell is None:
            return grid

        r, c = best_cell

        # Try 0 (white) first
        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = 0
        res = solve_recursive(grid_copy)
        if res: return res

        # Try 1 (black)
        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = 1
        res = solve_recursive(grid_copy)
        if res: return res

        return None

    # Initialize grid: -1 = unknown, 0 = white, 1 = black
    initial_grid = [[-1 for _ in range(C)] for _ in range(R)]

    # Pre-fill regions with clue 0
    for reg_id, cells in regions.items():
        if region_clues[reg_id] == 0:
            for r, c in cells:
                initial_grid[r][c] = 0

    solution = solve_recursive(initial_grid)

    if solution:
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if solution[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

