def solve(observation):
    data = observation['data']
    N = len(data) - 1

    def get_adjacent_cells(r, c):
        cells = []
        if r > 0 and c > 0: cells.append((r-1, c-1))
        if r > 0 and c < N: cells.append((r-1, c))
        if r < N and c > 0: cells.append((r, c-1))
        if r < N and c < N: cells.append((r, c))
        return cells

    def get_connecting_val(cell_r, cell_c, dot_r, dot_c):
        # 1 is '\', 2 is '/'
        if dot_r == cell_r and dot_c == cell_c: return 1
        if dot_r == cell_r and dot_c == cell_c + 1: return 2
        if dot_r == cell_r + 1 and dot_c == cell_c: return 2
        if dot_r == cell_r + 1 and dot_c == cell_c + 1: return 1

    def get_non_connecting_val(cell_r, cell_c, dot_r, dot_c):
        return 3 - get_connecting_val(cell_r, cell_c, dot_r, dot_c)

    def get_endpoints(r, c, val):
        if val == 1:
            return (r, c), (r+1, c+1)
        else:
            return (r+1, c), (r, c+1)

    def find_state(parent, i):
        root = i
        while parent[root] != root:
            root = parent[root]
        curr = i
        while curr != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    def apply_val(r, c, val, state):
        grid, deg, free, parent = state
        grid[r][c] = val

        free[r][c] -= 1
        free[r+1][c] -= 1
        free[r][c+1] -= 1
        free[r+1][c+1] -= 1

        u, v = get_endpoints(r, c, val)
        deg[u[0]][u[1]] += 1
        deg[v[0]][v[1]] += 1

        root_u = find_state(parent, u)
        root_v = find_state(parent, v)
        if root_u == root_v:
            return False # Cycle detected
        parent[root_u] = root_v

        for dr, dc in [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]:
            if data[dr][dc] is not None:
                if deg[dr][dc] > data[dr][dc]:
                    return False
                if deg[dr][dc] + free[dr][dc] < data[dr][dc]:
                    return False
        return True

    def propagate(state):
        grid, deg, free, parent = state
        changed = True
        while changed:
            changed = False

            # 1. Dot degree constraints
            for r in range(N + 1):
                for c in range(N + 1):
                    if data[r][c] is not None and free[r][c] > 0:
                        if deg[r][c] == data[r][c]:
                            for cr, cc in get_adjacent_cells(r, c):
                                if grid[cr][cc] == 0:
                                    val = get_non_connecting_val(cr, cc, r, c)
                                    if not apply_val(cr, cc, val, state):
                                        return False
                                    changed = True
                        elif deg[r][c] + free[r][c] == data[r][c]:
                            for cr, cc in get_adjacent_cells(r, c):
                                if grid[cr][cc] == 0:
                                    val = get_connecting_val(cr, cc, r, c)
                                    if not apply_val(cr, cc, val, state):
                                        return False
                                    changed = True

            # 2. Cycle prevention
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0:
                        u1, v1 = get_endpoints(r, c, 1)
                        cycle1 = find_state(parent, u1) == find_state(parent, v1)

                        u2, v2 = get_endpoints(r, c, 2)
                        cycle2 = find_state(parent, u2) == find_state(parent, v2)

                        if cycle1 and cycle2:
                            return False
                        elif cycle1:
                            if not apply_val(r, c, 2, state):
                                return False
                            changed = True
                        elif cycle2:
                            if not apply_val(r, c, 1, state):
                                return False
                            changed = True

        return True

    def copy_state(state):
        grid, deg, free, parent = state
        return (
            [row[:] for row in grid],
            [row[:] for row in deg],
            [row[:] for row in free],
            parent.copy()
        )

    def solve_dfs(state):
        if not propagate(state):
            return None

        grid, deg, free, parent = state

        best_cell = None
        min_slack = 999

        # Heuristic: pick the most constrained cell
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    cell_min_slack = 999
                    for dr, dc in [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]:
                        if data[dr][dc] is not None:
                            slack = free[dr][dc] - (data[dr][dc] - deg[dr][dc])
                            if slack < cell_min_slack:
                                cell_min_slack = slack

                    if cell_min_slack == 999:
                        cell_min_slack = 100

                    if cell_min_slack < min_slack:
                        min_slack = cell_min_slack
                        best_cell = (r, c)

        if best_cell is None:
            return grid

        r, c = best_cell

        for val in [1, 2]:
            new_state = copy_state(state)
            if apply_val(r, c, val, new_state):
                result = solve_dfs(new_state)
                if result is not None:
                    return result

        return None

    # Initialize state
    grid = [[0] * N for _ in range(N)]
    deg = [[0] * (N + 1) for _ in range(N + 1)]
    free = [[0] * (N + 1) for _ in range(N + 1)]

    for r in range(N):
        for c in range(N):
            free[r][c] += 1
            free[r+1][c] += 1
            free[r][c+1] += 1
            free[r+1][c+1] += 1

    parent = {(r, c): (r, c) for r in range(N + 1) for c in range(N + 1)}

    initial_state = (grid, deg, free, parent)

    result_grid = solve_dfs(initial_state)

    if result_grid is None:
        return "No Solution"

    char_grid = []
    for r in range(N):
        row = []
        for c in range(N):
            if result_grid[r][c] == 1:
                row.append('\\')
            else:
                row.append('/')
        char_grid.append(row)

    return char_grid

