def solve(observation):
    data = observation['data']
    N = len(data)

    horizontal = observation.get('horizontal', {})
    vertical = observation.get('vertical', {})

    # Parse inequalities into a list of (r1, c1, r2, c2) where V[r1][c1] < V[r2][c2]
    less_than = []
    for k, v in horizontal.items():
        r_str, c_str = k.strip('()').split(',')
        r = int(float(r_str))
        c = float(c_str)
        c1 = int(c - 0.5)
        c2 = int(c + 0.5)
        if v == '<':
            less_than.append((r, c1, r, c2))
        elif v == '>':
            less_than.append((r, c2, r, c1))

    for k, v in vertical.items():
        r_str, c_str = k.strip('()').split(',')
        r = float(r_str)
        c = int(float(c_str))
        r1 = int(r - 0.5)
        r2 = int(r + 0.5)
        if v == '^':
            less_than.append((r1, c, r2, c))
        elif v == 'v':
            less_than.append((r2, c, r1, c))

    # Initialize domains
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def propagate(doms):
        changed = True
        while changed:
            changed = False

            # 1. Row and Col AllDiff (Naked Singles)
            for i in range(N):
                for j in range(N):
                    if len(doms[i][j]) == 1:
                        val = list(doms[i][j])[0]
                        # Remove from same row
                        for c in range(N):
                            if c != j and val in doms[i][c]:
                                doms[i][c].remove(val)
                                changed = True
                                if not doms[i][c]: return False
                        # Remove from same col
                        for r in range(N):
                            if r != i and val in doms[r][j]:
                                doms[r][j].remove(val)
                                changed = True
                                if not doms[r][j]: return False

            # 2. Hidden Singles
            for i in range(N):
                # Check rows for hidden singles
                for val in range(1, N + 1):
                    possible_cols = [c for c in range(N) if val in doms[i][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(doms[i][c]) > 1:
                            doms[i][c] = {val}
                            changed = True
                    elif len(possible_cols) == 0:
                        return False
                # Check cols for hidden singles
                for val in range(1, N + 1):
                    possible_rows = [r for r in range(N) if val in doms[r][i]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(doms[r][i]) > 1:
                            doms[r][i] = {val}
                            changed = True
                    elif len(possible_rows) == 0:
                        return False

            # 3. Inequalities (Arc Consistency)
            for r1, c1, r2, c2 in less_than:
                min_a = min(doms[r1][c1])
                max_b = max(doms[r2][c2])

                # A must be less than the maximum possible value of B
                new_dom_a = {x for x in doms[r1][c1] if x < max_b}
                if len(new_dom_a) < len(doms[r1][c1]):
                    doms[r1][c1] = new_dom_a
                    changed = True
                    if not doms[r1][c1]: return False

                # B must be greater than the minimum possible value of A
                new_dom_b = {x for x in doms[r2][c2] if x > min_a}
                if len(new_dom_b) < len(doms[r2][c2]):
                    doms[r2][c2] = new_dom_b
                    changed = True
                    if not doms[r2][c2]: return False

        return True

    def solve_backtrack(doms):
        # Propagate constraints
        if not propagate(doms):
            return None

        # Find the cell with the Minimum Remaining Values (MRV heuristic)
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(doms[r][c]) > 1:
                    if len(doms[r][c]) < min_len:
                        min_len = len(doms[r][c])
                        best_cell = (r, c)

        # If all cells have exactly 1 value, the puzzle is solved
        if best_cell is None:
            return doms

        r, c = best_cell

        # Try all possible values for the chosen cell
        for val in doms[r][c]:
            # Deep copy domains for backtracking state
            new_doms = [[set(d) for d in row] for row in doms]
            new_doms[r][c] = {val}

            result = solve_backtrack(new_doms)
            if result is not None:
                return result

        return None

    final_domains = solve_backtrack(domains)

    if final_domains:
        return [[list(final_domains[r][c])[0] for c in range(N)] for r in range(N)]
    else:
        return "No Solution"

