    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Pre-calculate neighbors for each cell to speed up constraint propagation
    neighbors = {}
    for r in range(N):
        for c in range(N):
            nbs = set()
            # Row and Column neighbors
            for i in range(N):
                if i != c: nbs.add((r, i))
                if i != r: nbs.add((i, c))
            # Region neighbors
            region_id = regions[r][c]
            for rr in range(N):
                for cc in range(N):
                    if regions[rr][cc] == region_id and (rr, cc) != (r, c):
                        nbs.add((rr, cc))
            neighbors[(r, c)] = nbs

    # Initial constraint propagation based on givens
    for r in range(N):
        for c in range(N):
            if grid[r][c] != 0:
                val = grid[r][c]
                for nr, nc in neighbors[(r, c)]:
                    if (nr, nc) in domains and val in domains[(nr, nc)]:
                        domains[(nr, nc)].remove(val)

    def backtrack(domains):
        # If no domains left, all cells are filled successfully
        if not domains:
            return True

        # Minimum Remaining Values (MRV) heuristic
        min_len = N + 1
        best_cell = None
        for cell, dom in domains.items():
            if len(dom) < min_len:
                min_len = len(dom)
                best_cell = cell

        # If any cell has no possible values, this path is a dead end
        if min_len == 0:
            return False

        r, c = best_cell
        dom = domains[r, c]
        del domains[r, c]

        for val in dom:
            grid[r][c] = val

            # Forward checking: create a copy of domains and propagate the new assignment
            new_domains = {k: v.copy() for k, v in domains.items()}
            possible = True
            for nr, nc in neighbors[(r, c)]:
                if (nr, nc) in new_domains and val in new_domains[(nr, nc)]:
                    new_domains[(nr, nc)].remove(val)
                    if not new_domains[(nr, nc)]:
                        possible = False
                        break

            # If forward checking succeeds, continue searching
            if possible:
                if backtrack(new_domains):
                    return True

        # Backtrack: undo assignment and restore domain
        grid[r][c] = 0
        domains[r, c] = dom
        return False

    if backtrack(domains):
        return grid
    else:
        return "No Solution"

