import copy

def solve_recursive(grid, horizontal, vertical):
    if not is_valid(grid):
        return None

    current_grid = copy.deepcopy(grid)

    if not propagate(current_grid, horizontal, vertical):
        return None

    if not is_valid(current_grid):
        return None

    is_full = True
    for r in range(len(current_grid)):
        for c in range(len(current_grid[0])):
            if current_grid[r][c] is None:
                is_full = False

                # Try 'B'
                current_grid[r][c] = 'B'
                res = solve_recursive(current_grid, horizontal, vertical)
                if res is not None:
                    return res

                # Try 'W'
                current_grid[r][c] = 'W'
                res = solve_recursive(current_grid, horizontal, vertical)
                if res is not None:
                    return res

                return None # Backtrack

    if is_full:
        return current_grid
    return None

