def solve(observation):
    class JigsawSolver:
        def __init__(self, obs):
            self.N = len(obs['data'])
            self.regions = obs['region']
            self.grid = [[obs['data'][r][c] for c in range(self.N)] for r in range(self.N)]
            self.domains = [[set(range(1, self.N + 1)) if self.grid[r][c] is None else {self.grid[r][c]} 
                             for c in range(self.N)] for r in range(self.N)]

            self.region_cells = [[] for _ in range(self.N)]
            for r in range(self.N):
                for c in range(self.N):
                    self.region_cells[self.regions[r][c]].append((r, c))

        def get_peers(self, r, c):
            peers = set()
            for i in range(self.N):
                peers.add((r, i))
                peers.add((i, c))
            for pr, pc in self.region_cells[self.regions[r][c]]:
                peers.add((pr, pc))
            peers.remove((r, c))
            return peers

        def initial_propagate(self):
            for r in range(self.N):
                for c in range(self.N):
                    if self.grid[r][c] is not None:
                        val = self.grid[r][c]
                        for pr, pc in self.get_peers(r, c):
                            if val in self.domains[pr][pc]:
                                self.domains[pr][pc].remove(val)
                                if not self.domains[pr][pc]:
                                    return False
            return True

        def is_solved(self):
            for r in range(self.N):
                for c in range(self.N):
                    if self.grid[r][c] is None:
                        return False
            return True

        def find_empty_mrv(self):
            min_len = self.N + 1
            best_cell = None
            for r in range(self.N):
                for c in range(self.N):
                    if self.grid[r][c] is None:
                        if len(self.domains[r][c]) < min_len:
                            min_len = len(self.domains[r][c])
                            best_cell = (r, c)
            return best_cell

        def apply_deductions(self):
            changed = True
            while changed:
                changed = False
                # Naked Singles
                for r in range(self.N):
                    for c in range(self.N):
                        if self.grid[r][c] is None and len(self.domains[r][c]) == 1:
                            val = list(self.domains[r][c])[0]
                            self.grid[r][c] = val
                            for pr, pc in self.get_peers(r, c):
                                if val in self.domains[pr][pc]:
                                    self.domains[pr][pc].remove(val)
                                    if not self.domains[pr][pc]:
                                        return False
                            changed = True

                # Hidden Singles
                for r in range(self.N):
                    for val in range(1, self.N + 1):
                        if any(self.grid[r][c] == val for c in range(self.N)): continue
                        possible_cols = [c for c in range(self.N) if self.grid[r][c] is None and val in self.domains[r][c]]
                        if len(possible_cols) == 1:
                            c = possible_cols[0]
                            if len(self.domains[r][c]) > 1:
                                self.domains[r][c] = {val}
                                changed = True

                for c in range(self.N):
                    for val in range(1, self.N + 1):
                        if any(self.grid[r][c] == val for r in range(self.N)): continue
                        possible_rows = [r for r in range(self.N) if self.grid[r][c] is None and val in self.domains[r][c]]
                        if len(possible_rows) == 1:
                            r = possible_rows[0]
                            if len(self.domains[r][c]) > 1:
                                self.domains[r][c] = {val}
                                changed = True

                for region_id in range(self.N):
                    for val in range(1, self.N + 1):
                        if any(self.grid[r][c] == val for r, c in self.region_cells[region_id]): continue
                        possible_cells = [(r, c) for r, c in self.region_cells[region_id] if self.grid[r][c] is None and val in self.domains[r][c]]
                        if len(possible_cells) == 1:
                            r, c = possible_cells[0]
                            if len(self.domains[r][c]) > 1:
                                self.domains[r][c] = {val}
                                changed = True
            return True

        def backtrack(self):
            if not self.apply_deductions():
                return False

            if self.is_solved():
                return True

            cell = self.find_empty_mrv()
            if not cell:
                return False
            r, c = cell

            if len(self.domains[r][c]) == 0:
                return False

            for val in list(self.domains[r][c]):
                saved_grid = [row[:] for row in self.grid]
                saved_domains = [[self.domains[i][j].copy() for j in range(self.N)] for i in range(self.N)]

                self.grid[r][c] = val
                self.domains[r][c] = {val}

                valid = True
                for pr, pc in self.get_peers(r, c):
                    if val in self.domains[pr][pc]:
                        self.domains[pr][pc].remove(val)
                        if not self.domains[pr][pc]:
                            valid = False
                            break

                if valid:
                    if self.backtrack():
                        return True

                self.grid = saved_grid
                self.domains = saved_domains

            return False

        def run(self):
            if not self.initial_propagate():
                return "No Solution"
            if self.backtrack():
                return self.grid
            return "No Solution"

    solver = JigsawSolver(observation)
    return solver.run()

