                if 0 <= nr < R and 0 <= nc < C and current_state[nr][nc] in ('W', None):
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        stack.append((nr, nc))
        return len(visited) == count

    def set_black(r, c, current_state):
        """Set a cell to Black and propagate constraints."""
        if current_state[r][c] == 'W': 
            return False
        if current_state[r][c] == 'B': 
            return True

        current_state[r][c] = 'B'

        # Orthogonal neighbors of a Black cell must be White
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if not set_white(nr, nc, current_state):
                    return False
        return True

    def set_white(r, c, current_state):
        """Set a cell to White and propagate constraints."""
        if current_state[r][c] == 'B': 
            return False
        if current_state[r][c] == 'W': 
            return True

        current_state[r][c] = 'W'
        val = data[r][c]

        # No other White cell in the same row or column can have the same value
        for i in range(R):
            if i != r and data[i][c] == val:
                if not set_black(i, c, current_state):
                    return False
        for j in range(C):
            if j != c and data[r][j] == val:
                if not set_black(r, j, current_state):
                    return False
        return True

    def apply_deductions(current_state):
        """Apply 1-step lookahead deduction to all undecided cells."""
        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    if current_state[r][c] is None:
                        # Test setting to Black
                        state_b = [row[:] for row in current_state]
                        valid_b = set_black(r, c, state_b) and is_connected(state_b)

                        # Test setting to White
                        state_w = [row[:] for row in current_state]
                        valid_w = set_white(r, c, state_w) and is_connected(state_w)

                        if not valid_b and not valid_w:
                            return False # Contradiction, invalid path
                        elif not valid_b:
                            # Must be White
                            if not set_white(r, c, current_state): 
                                return False
                            changed = True
                        elif not valid_w:
                            # Must be Black
                            if not set_black(r, c, current_state): 
                                return False
                            changed = True
        return True

    def backtrack(current_state):
        """Backtracking search with aggressive constraint propagation."""
        if not is_connected(current_state):
            return None

        if not apply_deductions(current_state):
            return None

        # Find the first undecided cell
        best_cell = None
        for r in range(R):
            for c in range(C):
                if current_state[r][c] is None:
                    best_cell = (r, c)
                    break
            if best_cell: 
                break

        # If all cells are decided, we found a solution
        if not best_cell:
            return current_state

        r, c = best_cell

        # Try Black
        state_copy = [row[:] for row in current_state]
        if set_black(r, c, state_copy):
            res = backtrack(state_copy)
            if res: 
                return res

        # Try White
        state_copy = [row[:] for row in current_state]
        if set_white(r, c, state_copy):
            res = backtrack(state_copy)
            if res: 
                return res

        return None

    res_state = backtrack(state)

    if res_state:
        # Convert internal 'W'/'B' representation to expected None/'B' output
        return [[None if cell == 'W' else 'B' for cell in row] for row in res_state]

    return "No Solution"

