            for i in range(N):
                for j in range(N):
                    if regions[i][j] == region_id and (i, j) != (r, c):
                        peers[r][c].add((i, j))

    def assign(domains, r, c, val):
        """Assign a value to a cell and propagate constraints."""
        if val not in domains[r][c]:
            return False
        other_vals = set(domains[r][c])
        other_vals.remove(val)
        for other_val in other_vals:
            if not eliminate(domains, r, c, other_val):
                return False
        return True

    def eliminate(domains, r, c, val):
        """Eliminate a value from a cell's domain and propagate if it becomes a singleton."""
        if val not in domains[r][c]:
            return True
        domains[r][c].remove(val)

        # Contradiction: no possible values left
        if len(domains[r][c]) == 0:
            return False

        # Forward checking: if only one value left, eliminate it from all peers
        if len(domains[r][c]) == 1:
            last_val = list(domains[r][c])[0]
            for pr, pc in peers[r][c]:
                if not eliminate(domains, pr, pc, last_val):
                    return False
        return True

    # Initialize domains with all possible values
    initial_domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply initial givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                if not assign(initial_domains, r, c, data[r][c]):
                    return "No Solution"

    def search(domains):
        """Backtracking search with Minimum Remaining Values (MRV) heuristic."""
        min_len = N + 1
        best_cell = None

        # Find the unassigned cell with the fewest possible values
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_len:
                        min_len = len(domains[r][c])
                        best_cell = (r, c)

        # If all cells are assigned, we have a solution
        if best_cell is None:
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        r, c = best_cell

        # Try each possible value for the chosen cell
        for val in list(domains[r][c]):
            # Create a deep copy of domains for backtracking
            domains_copy = [[set(domains[i][j]) for j in range(N)] for i in range(N)]
            if assign(domains_copy, r, c, val):
                result = search(domains_copy)
                if result:
                    return result
        return False

    result = search(initial_domains)
    if result:
        return result
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
