def solve(observation):
    regions = observation['region']
    data = observation['data']
    N = len(regions)

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Group cells by their region ID
    region_cells = {}
    for r in range(N):
        for c in range(N):
            reg_id = regions[r][c]
            if reg_id not in region_cells:
                region_cells[reg_id] = []
            region_cells[reg_id].append((r, c))

    # Precompute neighbors for each cell (row, col, region)
    neighbors_map = {}
    for r in range(N):
        for c in range(N):
            neighbors = set()
            # Same row
            for cc in range(N):
                if cc != c:
                    neighbors.add((r, cc))
            # Same column
            for rr in range(N):
                if rr != r:
                    neighbors.add((rr, c))
            # Same region
            reg_id = regions[r][c]
            for rr, cc in region_cells[reg_id]:
                if rr != r or cc != c:
                    neighbors.add((rr, cc))
            neighbors_map[(r, c)] = neighbors

    # AC-3 algorithm for initial constraint propagation
    def ac3():
        queue = [(xi, xj) for xi in domains for xj in neighbors_map[xi]]
        while queue:
            xi, xj = queue.pop(0)
            if revise(xi, xj):
                if not domains[xi]:
                    return False
                for xk in neighbors_map[xi]:
                    if xk != xj:
                        queue.append((xk, xi))
        return True

    def revise(xi, xj):
        revised = False
        # For inequality constraints, we only revise if xj is assigned a single value
        if len(domains[xj]) == 1:
            val = next(iter(domains[xj]))
            if val in domains[xi]:
                domains[xi].remove(val)
                revised = True
        return revised

    if not ac3():
        return "No Solution"

    # Backtracking search with Minimum Remaining Values (MRV) heuristic
    def backtrack():
        # Find unassigned variables
        unassigned = [v for v in domains if len(domains[v]) > 1]
        if not unassigned:
            return True # All variables assigned

        # MRV heuristic: pick the variable with the smallest domain
        unassigned.sort(key=lambda v: len(domains[v]))
        var = unassigned[0]

        original_domain = set(domains[var])
        for val in original_domain:
            domains[var] = {val}

            # Forward checking
            valid = True
            removed_values = []
            for neighbor in neighbors_map[var]:
                if val in domains[neighbor]:
                    domains[neighbor].remove(val)
                    removed_values.append((neighbor, val))
                    if not domains[neighbor]:
                        valid = False
                        break

            if valid:
                if backtrack():
                    return True

            # Restore domains if assignment failed
            for neighbor, v in removed_values:
                domains[neighbor].add(v)

        # Restore variable domain
        domains[var] = original_domain
        return False

    if backtrack():
        solution = [[0] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                solution[r][c] = next(iter(domains[(r, c)]))
        return solution
    else:
        return "No Solution"

