import sys

# Increase recursion depth for safety, though iterative DSU is used
sys.setrecursionlimit(2000)

def solve(observation):
    target = observation['data']
    N = len(target) - 1

    # Iterative DSU find with path compression
    def find(p, r, c):
        curr_r, curr_c = r, c
        while p[curr_r][curr_c] != (curr_r, curr_c):
            curr_r, curr_c = p[curr_r][curr_c]

        root_r, root_c = curr_r, curr_c
        curr_r, curr_c = r, c
        while p[curr_r][curr_c] != (curr_r, curr_c):
            next_r, next_c = p[curr_r][curr_c]
            p[curr_r][curr_c] = (root_r, root_c)
            curr_r, curr_c = next_r, next_c

        return (root_r, root_c)

    # DSU union
    def union(p, r1, c1, r2, c2):
        root1 = find(p, r1, c1)
        root2 = find(p, r2, c2)
        if root1 != root2:
            p[root1[0]][root1[1]] = root2
            return True
        return False

    # Assign a diagonal to a cell and update DSU
    def assign(grid, parent, r, c, diag):
        grid[r][c] = diag
        if diag == '\\':
            if not union(parent, r, c, r+1, c+1):
                return False # Forms a loop
        else:
            if not union(parent, r, c+1, r+1, c):
                return False # Forms a loop
        return True

    # Constraint propagation
    def propagate(grid, parent):
        changed = True
        while changed:
            changed = False

            # 1. Check dot degree constraints
            for r in range(N + 1):
                for c in range(N + 1):
                    if target[r][c] is None: continue

                    deg = 0
                    unassigned = []

                    # Top-Left cell
                    if r > 0 and c > 0:
                        if grid[r-1][c-1] == '\\': deg += 1
                        elif grid[r-1][c-1] == 0: unassigned.append((r-1, c-1, '\\'))
                    # Top-Right cell
                    if r > 0 and c < N:
                        if grid[r-1][c] == '/': deg += 1
                        elif grid[r-1][c] == 0: unassigned.append((r-1, c, '/'))
                    # Bottom-Left cell
                    if r < N and c > 0:
                        if grid[r][c-1] == '/': deg += 1
                        elif grid[r][c-1] == 0: unassigned.append((r, c-1, '/'))
                    # Bottom-Right cell
                    if r < N and c < N:
                        if grid[r][c] == '\\': deg += 1
                        elif grid[r][c] == 0: unassigned.append((r, c, '\\'))

                    k = target[r][c] - deg
                    U = len(unassigned)

                    if k < 0 or k > U:
                        return False # Contradiction

                    if k == 0 and U > 0:
                        for cell_r, cell_c, req_diag in unassigned:
                            assign_diag = '/' if req_diag == '\\' else '\\'
                            if grid[cell_r][cell_c] == 0:
                                if not assign(grid, parent, cell_r, cell_c, assign_diag): return False
                                changed = True
                            elif grid[cell_r][cell_c] != assign_diag:
                                return False # Contradiction
                    elif k == U and U > 0:
                        for cell_r, cell_c, req_diag in unassigned:
                            if grid[cell_r][cell_c] == 0:
                                if not assign(grid, parent, cell_r, cell_c, req_diag): return False
                                changed = True
                            elif grid[cell_r][cell_c] != req_diag:
                                return False # Contradiction

            # 2. Check loop constraints for unassigned cells
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 0:
                        loop_backslash = (find(parent, r, c) == find(parent, r+1, c+1))
                        loop_forwardslash = (find(parent, r, c+1) == find(parent, r+1, c))

                        if loop_backslash and loop_forwardslash:
                            return False # Both options form a loop
                        elif loop_backslash:
                            if not assign(grid, parent, r, c, '/'): return False
                            changed = True
                        elif loop_forwardslash:
                            if not assign(grid, parent, r, c, '\\'): return False
                            changed = True

        return True

    # Heuristic to pick the most constrained unassigned cell
    def get_best_cell(grid):
        best_cell = None
        best_score = -1

        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    score = 0
                    for dr, dc in [(0,0), (0,1), (1,0), (1,1)]:
                        tr, tc = r + dr, c + dc
                        if target[tr][tc] is not None:
                            U = 0
                            if tr > 0 and tc > 0 and grid[tr-1][tc-1] == 0: U += 1
                            if tr > 0 and tc < N and grid[tr-1][tc] == 0: U += 1
                            if tr < N and tc > 0 and grid[tr][tc-1] == 0: U += 1
                            if tr < N and tc < N and grid[tr][tc] == 0: U += 1

                            if U > 0:
                                score += 10.0 / U

                    if score > best_score:
                        best_score = score
                        best_cell = (r, c)
        return best_cell

    # DFS with backtracking
    def solve_dfs(grid, parent):
        if not propagate(grid, parent):
            return None

        cell = get_best_cell(grid)
        if cell is None:
            return grid # All cells assigned successfully

        r, c = cell

        # Try '\'
        grid_copy = [row[:] for row in grid]
        parent_copy = [[parent[i][j] for j in range(N+1)] for i in range(N+1)]
        if assign(grid_copy, parent_copy, r, c, '\\'):
            res = solve_dfs(grid_copy, parent_copy)
            if res: return res

        # Try '/'
        grid_copy = [row[:] for row in grid]
        parent_copy = [[parent[i][j] for j in range(N+1)] for i in range(N+1)]
        if assign(grid_copy, parent_copy, r, c, '/'):
            res = solve_dfs(grid_copy, parent_copy)
            if res: return res

        return None

    initial_grid = [[0 for _ in range(N)] for _ in range(N)]
    initial_parent = [[(r, c) for c in range(N+1)] for r in range(N+1)]

    solution = solve_dfs(initial_grid, initial_parent)

    if solution:
        return solution
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
