                curr_block = [(r, c)]
            else:
                curr_block.append((r, c))
        if curr_block:
            blocks.append(curr_block)

        for i in range(len(blocks) - 2):
            seg = [blocks[i][-1]] + blocks[i+1] + [blocks[i+2][0]]
            min_invalid_segs.append(seg)

    for c in range(C):
        blocks = []
        curr_region = None
        curr_block = []
        for r in range(R):
