            min_invalid_segs.append(seg)

    grid = [[None for _ in range(C)] for _ in range(R)]

    def is_connected(cells):
        if not cells:
            return True
        start = cells[0]
        visited = set([start])
        queue = [start]
        cells_set = set(cells)
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells_set and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        return len(visited) == len(cells)

