        clue = observation['U'][i]
        if clue > 0:
            for r in range(N):
                # A building at distance 'r' cannot be so tall that it hides too many buildings
                max_val = N - clue + 1 + r
                domains[r][i] = {v for v in domains[r][i] if v <= max_val}
            if clue == 1:
                domains[0][i] = {N}
            elif clue == N:
                for r in range(N):
                    domains[r][i] = {r + 1}

        # Bottom clues (D)
        clue = observation['D'][i]
        if clue > 0:
            for r in range(N):
                max_val = N - clue + 1 + (N - 1 - r)
                domains[r][i] = {v for v in domains[r][i] if v <= max_val}
            if clue == 1:
                domains[N - 1][i] = {N}
            elif clue == N:
                for r in range(N):
                    domains[r][i] = {N - r}

