                    if observation['R'][r] > 0 and get_visible(grid[r][::-1]) != observation['R'][r]: 
                        possible = False
                # Check Col c
                if all(grid[i][c] != 0 for i in range(N)):
                    if observation['U'][c] > 0 and get_visible([grid[i][c] for i in range(N)]) != observation['U'][c]: 
                        possible = False
                    if observation['D'][c] > 0 and get_visible([grid[i][c] for i in range(N)][::-1]) != observation['D'][c]: 
                        possible = False

            if possible:
                if solve_bt(next_domains, filled_count + 1):
                    return True

            # Backtrack
            grid[r][c] = 0

        return False

    if solve_bt(domains, 0):
        return grid
    return "No Solution"

