                domains[r][c] = {data[r][c]}

    # Parse inequalities into a unified format: ((r1, c1), (r2, c2), operator)
    inequalities = []
    for k, v in observation['horizontal'].items():
        k_clean = k.replace('(', '').replace(')', '')
        r_str, c_str = k_clean.split(',')
        r = int(float(r_str))
        c_plus_half = float(c_str)
        c = int(c_plus_half - 0.5)
        inequalities.append(((r, c), (r, c + 1), v))

    for k, v in observation['vertical'].items():
        k_clean = k.replace('(', '').replace(')', '')
        r_str, c_str = k_clean.split(',')
        r_plus_half = float(r_str)
        c = int(float(c_str))
        r = int(r_plus_half - 0.5)
        op = '<' if v == '^' else '>'
        inequalities.append(((r, c), (r + 1, c), op))

    def propagate(domains):
        """
        Applies constraint propagation to reduce domains.
        Returns False if a contradiction is found (empty domain), True otherwise.
        """
        changed = True
        while changed:
            changed = False

            # 1. Naked Singles (Row and Column AllDiff)
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        val = list(domains[r][c])[0]
                        # Remove from same row
                        for c2 in range(N):
