                                domains[r][c2].remove(val)
                                changed = True
                                if not domains[r][c2]: return False
                        # Remove from same column
                        for r2 in range(N):
                            if r != r2 and val in domains[r2][c]:
                                domains[r2][c].remove(val)
                                changed = True
                                if not domains[r2][c]: return False

            # 2. Hidden Singles (Row and Column)
            for r in range(N):
                for val in range(1, N + 1):
                    possible_cols = [c for c in range(N) if val in domains[r][c]]
                    if len(possible_cols) == 1:
                        c = possible_cols[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True
                    elif len(possible_cols) == 0:
                        return False

            for c in range(N):
                for val in range(1, N + 1):
                    possible_rows = [r for r in range(N) if val in domains[r][c]]
                    if len(possible_rows) == 1:
                        r = possible_rows[0]
                        if len(domains[r][c]) > 1:
                            domains[r][c] = {val}
                            changed = True
                    elif len(possible_rows) == 0:
                        return False

            # 3. Inequalities Propagation
            for (r1, c1), (r2, c2), op in inequalities:
                if op == '>':
                    # V[r1][c1] > V[r2][c2]
                    min_y = min(domains[r2][c2])
                    to_remove_x = [x for x in domains[r1][c1] if x <= min_y]
                    if to_remove_x:
                        for x in to_remove_x: domains[r1][c1].remove(x)
                        changed = True
                        if not domains[r1][c1]: return False

                    max_x = max(domains[r1][c1])
                    to_remove_y = [y for y in domains[r2][c2] if y >= max_x]
                    if to_remove_y:
                        for y in to_remove_y: domains[r2][c2].remove(y)
                        changed = True
                        if not domains[r2][c2]: return False

                elif op == '<':
                    # V[r1][c1] < V[r2][c2]
                    max_y = max(domains[r2][c2])
                    to_remove_x = [x for x in domains[r1][c1] if x >= max_y]
                    if to_remove_x:
                        for x in to_remove_x: domains[r1][c1].remove(x)
                        changed = True
                        if not domains[r1][c1]: return False

                    min_x = min(domains[r1][c1])
                    to_remove_y = [y for y in domains[r2][c2] if y <= min_x]
                    if to_remove_y:
                        for y in to_remove_y: domains[r2][c2].remove(y)
                        changed = True
                        if not domains[r2][c2]: return False
        return True

    # Initial propagation based on givens and inequalities
    if not propagate(domains):
        return "No Solution"

    def backtrack(domains):
        # Find the unassigned variable with the smallest domain (MRV heuristic)
        min_len = N + 1
        best_r, best_c = -1, -1
        for r in range(N):
            for c in range(N):
                l = len(domains[r][c])
                if 1 < l < min_len:
                    min_len = l
                    best_r, best_c = r, c

        # If all variables are assigned, we found a solution
        if best_r == -1:
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        # Try assigning each possible value to the chosen variable
        for val in sorted(list(domains[best_r][best_c])):
            # Create a deep copy of domains for the new branch
            new_domains = [[set(d) for d in row] for row in domains]
            new_domains[best_r][best_c] = {val}

            if propagate(new_domains):
                res = backtrack(new_domains)
                if res:
                    return res
        return None

    ans = backtrack(domains)
    if ans:
        return ans
    return "No Solution"

