def solve(observation):
    regions = observation['region']
    data = observation['data']
    N = len(data)

    # Initialize domains for each cell
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Precompute neighbors for each cell to optimize constraint checking
    neighbors = {}
    for r in range(N):
        for c in range(N):
            nbrs = set()
            # Row constraints
            for i in range(N):
                if i != c: nbrs.add((r, i))
            # Column constraints
            for i in range(N):
                if i != r: nbrs.add((i, c))
            # Irregular region constraints
            reg_id = regions[r][c]
            for i in range(N):
                for j in range(N):
                    if (i, j) != (r, c) and regions[i][j] == reg_id:
                        nbrs.add((i, j))
            neighbors[(r, c)] = nbrs

    def ac3(domains):
        """
        Arc Consistency Algorithm #3 (AC-3)
        Propagates constraints to reduce the search space before and during backtracking.
        """
        queue = [(xi, xj) for xi in domains for xj in neighbors[xi]]
        while queue:
            xi, xj = queue.pop(0)
            if revise(domains, xi, xj):
                if len(domains[xi]) == 0:
                    return False # Domain wiped out, invalid state
                for xk in neighbors[xi]:
                    if xk != xj:
                        queue.append((xk, xi))
        return True

    def revise(domains, xi, xj):
        """
        Revises the domain of xi given the domain of xj.
        Returns True if the domain of xi was modified.
        """
        revised = False
        for x in list(domains[xi]):
            # If assigning x to xi leaves no valid options for xj, remove x from xi's domain
            if all(x == y for y in domains[xj]):
                domains[xi].remove(x)
                revised = True
        return revised

    def backtrack(domains):
        """
        Backtracking search with Minimum Remaining Values (MRV) heuristic.
        """
        # Check if assignment is complete
        if all(len(d) == 1 for d in domains.values()):
            return domains

        # Select unassigned variable using MRV heuristic
        unassigned = [v for v in domains if len(domains[v]) > 1]
        var = min(unassigned, key=lambda v: len(domains[v]))

        for value in list(domains[var]):
            # Create a deep copy of domains for the recursive call
            new_domains = {k: set(v) for k, v in domains.items()}
            new_domains[var] = {value}

            # Forward checking / constraint propagation
            if ac3(new_domains):
                result = backtrack(new_domains)
                if result:
                    return result
        return False

    # Initial constraint propagation
    if not ac3(domains):
        return "No Solution"

    # Start backtracking search
    solution_domains = backtrack(domains)

    if solution_domains:
        # Format the solution into a 2D list
        res = [[0] * N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                res[r][c] = list(solution_domains[(r, c)])[0]
        return res

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
