OBSERVATION = {'data': [[3, 4, 3, 2, 3], [4, 3, 2, 3, 5], [1, 2, 3, 1, 4], [5, 3, 1, 4, 2], [2, 4, 4, 3, 3]]}

def solve(observation):
    data = observation['data']
    N = len(data)
    # State: 0 = unknown, 1 = white, 2 = black
    initial_state = [[0] * N for _ in range(N)]

    # Apply initial human-like deduction patterns
    # Pattern 1: X Y X -> Y must be white
    for r in range(N):
        for c in range(N - 2):
            if data[r][c] == data[r][c+2]:
                initial_state[r][c+1] = 1
    for c in range(N):
        for r in range(N - 2):
            if data[r][c] == data[r+2][c]:
                initial_state[r+1][c] = 1

    # Pattern 2: X X -> any other X in the same row/col must be black
    for r in range(N):
        for c in range(N - 1):
            if data[r][c] == data[r][c+1]:
                val = data[r][c]
                for c2 in range(N):
                    if c2 != c and c2 != c+1 and data[r][c2] == val:
                        initial_state[r][c2] = 2
    for c in range(N):
        for r in range(N - 1):
            if data[r][c] == data[r+1][c]:
                val = data[r][c]
                for r2 in range(N):
                    if r2 != r and r2 != r+1 and data[r2][c] == val:
                        initial_state[r2][c] = 2

    def check_connectivity(state):
        """Check if all non-black cells form a single connected component."""
        start = None
        non_black_count = 0
        for r in range(N):
            for c in range(N):
                if state[r][c] != 2:
                    non_black_count += 1
                    if start is None:
                        start = (r, c)

        if non_black_count == 0:
            return True

        q = [start]
        visited = set([start])
        while q:
            r, c = q.pop(0)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and state[nr][nc] != 2 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        return len(visited) == non_black_count

    def apply_deductions(state):
        """Apply constraint propagation to deduce cell states."""
        changed = True
        while changed:
            changed = False

            # 1. Black cells force orthogonal neighbors to be white
            # 2. White cells force other cells with the same number in row/col to be black
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 2:
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if state[nr][nc] == 2:
                                    return False # Invalid: adjacent black cells
                                if state[nr][nc] == 0:
                                    state[nr][nc] = 1
                                    changed = True
                    elif state[r][c] == 1:
                        val = data[r][c]
                        for c2 in range(N):
                            if c != c2 and data[r][c2] == val:
                                if state[r][c2] == 1:
                                    return False # Invalid: duplicate white numbers in row
                                if state[r][c2] == 0:
                                    state[r][c2] = 2
                                    changed = True
                        for r2 in range(N):
                            if r != r2 and data[r2][c] == val:
                                if state[r2][c] == 1:
                                    return False # Invalid: duplicate white numbers in col
                                if state[r2][c] == 0:
                                    state[r2][c] = 2
                                    changed = True

            if not check_connectivity(state):
                return False

            # 3. 1-step lookahead: if setting an unknown to black breaks connectivity, it must be white
            for r in range(N):
                for c in range(N):
                    if state[r][c] == 0:
                        state[r][c] = 2
                        if not check_connectivity(state):
                            state[r][c] = 1
                            changed = True
                        else:
                            state[r][c] = 0

        return True

    def search(current_state):
        """Backtracking search with constraint propagation."""
        state_copy = [row[:] for row in current_state]

        if not apply_deductions(state_copy):
            return None

        best_cell = None
        for r in range(N):
            for c in range(N):
                if state_copy[r][c] == 0:
                    if best_cell is None:
                        best_cell = (r, c)

        if best_cell is None:
            # Final validation check
            for r in range(N):
                seen = set()
                for c in range(N):
                    if state_copy[r][c] == 1:
                        if data[r][c] in seen: return None
                        seen.add(data[r][c])
            for c in range(N):
                seen = set()
                for r in range(N):
                    if state_copy[r][c] == 1:
                        if data[r][c] in seen: return None
                        seen.add(data[r][c])
            return state_copy

        r, c = best_cell

        # Try setting to Black (2) first as it is more constrained
        next_state = [row[:] for row in state_copy]
        next_state[r][c] = 2
        res = search(next_state)
        if res: return res

        # Try setting to White (1)
        next_state = [row[:] for row in state_copy]
        next_state[r][c] = 1
        res = search(next_state)
        if res: return res

        return None

    solution = search(initial_state)
    if solution:
        ans = []
        for r in range(N):
            row_ans = []
            for c in range(N):
                if solution[r][c] == 2:
                    row_ans.append('B')
                else:
                    row_ans.append(None)
            ans.append(row_ans)
        return ans
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
