def solve(observation):
    region = observation['region']
    data = observation['data']
    R = len(region)
    C = len(region[0])

    regions = {}
    region_clues = {}
    for r in range(R):
        for c in range(C):
            reg_id = region[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))
            if data[r][c] is not None:
                region_clues[reg_id] = data[r][c]

    for reg_id in regions:
        if reg_id not in region_clues:
            region_clues[reg_id] = None

    # Precompute minimal line segments that span 3 regions
    line_segments = []
    for r in range(R):
        for c1 in range(C - 2):
            if region[r][c1] != region[r][c1+1]:
                regB = region[r][c1+1]
                for c2 in range(c1 + 2, C):
                    if region[r][c2] != regB:
                        line_segments.append([(r, c) for c in range(c1, c2 + 1)])
                        break

    for c in range(C):
        for r1 in range(R - 2):
            if region[r1][c] != region[r1+1][c]:
                regB = region[r1+1][c]
                for r2 in range(r1 + 2, R):
                    if region[r2][c] != regB:
                        line_segments.append([(r, c) for r in range(r1, r2 + 1)])
                        break

    def check_connectivity(grid):
        wu_cells = set()
        w_cells = set()
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0:
                    wu_cells.add((r, c))
                    w_cells.add((r, c))
                elif grid[r][c] == -1:
                    wu_cells.add((r, c))

        components = []
        visited = set()
        for start_node in wu_cells:
            if start_node not in visited:
                comp = set()
                q = [start_node]
                visited.add(start_node)
                while q:
                    curr = q.pop(0)
                    comp.add(curr)
                    r_, c_ = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r_+dr, c_+dc
                        if (nr, nc) in wu_cells and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                components.append(comp)

        w_comps = [comp for comp in components if comp.intersection(w_cells)]
        if len(w_comps) > 1:
            return False

        large_no_w_comps = [comp for comp in components if len(comp) > 1 and not comp.intersection(w_cells)]

        if w_cells and large_no_w_comps:
            return False

        if not w_cells and len(large_no_w_comps) > 1:
            return False

        for comp in components:
            if not comp.intersection(w_cells) and len(comp) == 1:
                r_, c_ = list(comp)[0]
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r_+dr, c_+dc
                    if 0<=nr<R and 0<=nc<C and grid[nr][nc] == 1:
                        return False
        return True

    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # 1. No adjacent blacks
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r+dr, c+dc
                            if 0<=nr<R and 0<=nc<C:
                                if grid[nr][nc] == 1:
                                    return False
                                elif grid[nr][nc] == -1:
                                    grid[nr][nc] = 0
                                    changed = True

            # 2. Region clues
            for reg_id, cells in regions.items():
                clue = region_clues[reg_id]
                if clue is None: continue
                blacks = sum(1 for r,c in cells if grid[r][c] == 1)
                unknowns = [(r,c) for r,c in cells if grid[r][c] == -1]
                if blacks > clue: return False
                if blacks + len(unknowns) < clue: return False
                if blacks == clue and unknowns:
                    for r,c in unknowns: grid[r][c] = 0
                    changed = True
                if blacks + len(unknowns) == clue and unknowns:
                    for r,c in unknowns: grid[r][c] = 1
                    changed = True

            # 3. Line segments (no white line spans 3 regions)
            for segment in line_segments:
                blacks = sum(1 for r,c in segment if grid[r][c] == 1)
                unknowns = [(r,c) for r,c in segment if grid[r][c] == -1]
                if blacks == 0:
                    if len(unknowns) == 0: return False
                    if len(unknowns) == 1:
                        r, c = unknowns[0]
                        grid[r][c] = 1
                        changed = True

            # 4. Connectivity
            if not check_connectivity(grid):
                return False

        return True

    def solve_recursive(grid):
        if not propagate(grid):
            return False

        unknowns = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == -1]
        if not unknowns:
            return True

        # Lookahead deduction
        while True:
            changed_by_lookahead = False
            unknowns = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == -1]
            if not unknowns: return True

            for r, c in unknowns:
                grid_b = [row[:] for row in grid]
                grid_b[r][c] = 1
                valid_b = propagate(grid_b)

                grid_w = [row[:] for row in grid]
                grid_w[r][c] = 0
                valid_w = propagate(grid_w)

                if not valid_b and not valid_w:
                    return False
                elif valid_b and not valid_w:
                    grid[r][c] = 1
                    changed_by_lookahead = True
                    break
                elif not valid_b and valid_w:
                    grid[r][c] = 0
                    changed_by_lookahead = True
                    break

            if not changed_by_lookahead:
                break
            if not propagate(grid):
                return False

        unknowns = [(r,c) for r in range(R) for c in range(C) if grid[r][c] == -1]
        if not unknowns:
            return True

        # Branching
        r, c = unknowns[0]

        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = 0
        if solve_recursive(grid_copy):
            for i in range(R):
                for j in range(C):
                    grid[i][j] = grid_copy[i][j]
            return True

        grid_copy = [row[:] for row in grid]
        grid_copy[r][c] = 1
        if solve_recursive(grid_copy):
            for i in range(R):
                for j in range(C):
                    grid[i][j] = grid_copy[i][j]
            return True

        return False

    grid = [[-1]*C for _ in range(R)]
    if solve_recursive(grid):
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if grid[r][c] == 1:
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
