def solve(observation):
    regions = observation['region']
    data = observation['data']
    N = len(data)

    # Precompute peers for each cell to optimize constraint propagation
    peers = [[set() for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            region_id = regions[r][c]
            for i in range(N):
                peers[r][c].add((r, i))
                peers[r][c].add((i, c))
            for i in range(N):
                for j in range(N):
                    if regions[i][j] == region_id:
                        peers[r][c].add((i, j))
            peers[r][c].remove((r, c))

    # Initialize domains: each cell can potentially be any number from 1 to N
    domains = [[list(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    def assign(r, c, val):
        """Assign val to cell (r, c) by eliminating all other values from its domain."""
        other_vals = [v for v in domains[r][c] if v != val]
        for other_val in other_vals:
            if not eliminate(r, c, other_val):
                return False
        return True

    def eliminate(r, c, val):
        """Eliminate val from the domain of cell (r, c)."""
        if val not in domains[r][c]:
            return True # Already eliminated

        domains[r][c].remove(val)

        # Constraint 1: If a cell has no possible values, the current path is invalid
        if len(domains[r][c]) == 0:
            return False

        # Constraint 2: Naked Single - If a cell has only one possible value, eliminate it from peers
        elif len(domains[r][c]) == 1:
            rem_val = domains[r][c][0]
            for pr, pc in peers[r][c]:
                if not eliminate(pr, pc, rem_val):
                    return False

        # Constraint 3: Hidden Single - Check if val has only one possible cell left in its row, col, or region

        # Check row
        places = [c_idx for c_idx in range(N) if val in domains[r][c_idx]]
        if len(places) == 0:
            return False
        elif len(places) == 1:
            if len(domains[r][places[0]]) > 1:
                if not assign(r, places[0], val):
                    return False

        # Check col
        places = [r_idx for r_idx in range(N) if val in domains[r_idx][c]]
        if len(places) == 0:
            return False
        elif len(places) == 1:
            if len(domains[places[0]][c]) > 1:
                if not assign(places[0], c, val):
                    return False

        # Check region
        region_id = regions[r][c]
        places = []
        for i in range(N):
            for j in range(N):
                if regions[i][j] == region_id and val in domains[i][j]:
                    places.append((i, j))
        if len(places) == 0:
            return False
        elif len(places) == 1:
            pr, pc = places[0]
            if len(domains[pr][pc]) > 1:
                if not assign(pr, pc, val):
                    return False

        return True

    # Apply initial givens from the observation
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                if not assign(r, c, data[r][c]):
                    return "No Solution"

    def search():
        """Backtracking search with Minimum Remaining Values (MRV) heuristic."""
        min_len = N + 1
        best_cell = None

        # Find the unassigned cell with the fewest possible values
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_len:
                        min_len = len(domains[r][c])
                        best_cell = (r, c)

        if best_cell is None:
            return True # All cells assigned, puzzle solved

        r, c = best_cell

        # Create a fast copy of domains for backtracking
        original_domains = [[list(d) for d in row] for row in domains]

        for val in list(domains[r][c]):
            if assign(r, c, val):
                if search():
                    return True
            # Backtrack: restore domains
            for i in range(N):
                for j in range(N):
                    domains[i][j] = list(original_domains[i][j])

        return False

    if search():
        return [[domains[r][c][0] for c in range(N)] for r in range(N)]
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
