OBSERVATION = {'region': [[0, 0, 0, 1, 2, 2], [3, 3, 4, 1, 6, 7], [3, 3, 4, 5, 6, 7], [3, 3, 8, 8, 6, 7], [3, 3, 8, 8, 9, 9], [3, 3, 10, 10, 10, 10]], 'data': [[None, None, None, None, 1, None], [3, None, 0, None, 1, None], [None, None, None, 1, None, None], [None, None, 1, None, None, None], [None, None, None, None, 1, None], [None, None, 1, None, None, None]]}

def solve(observation):
    region_grid = observation['region']
    data_grid = observation['data']
    R = len(region_grid)
    C = len(region_grid[0])

    # Parse regions and clues
    regions = {}
    clues = {}
    for r in range(R):
        for c in range(C):
            reg_id = region_grid[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))
            if data_grid[r][c] is not None:
                clues[reg_id] = data_grid[r][c]

    # Precalculate line-of-sight constraints (triplets)
    # A straight line of white cells cannot span 3 or more regions.
    # Thus, for any 3 consecutive region blocks in a row/col, 
    # the segment from the end of the 1st to the start of the 3rd must contain at least one black cell.
    triplets = []
    for r in range(R):
        blocks = []
        curr_reg = region_grid[r][0]
        start_c = 0
        for c in range(1, C):
            if region_grid[r][c] != curr_reg:
                blocks.append((curr_reg, start_c, c - 1))
                curr_reg = region_grid[r][c]
                start_c = c
        blocks.append((curr_reg, start_c, C - 1))
        for i in range(len(blocks) - 2):
            b1, b2, b3 = blocks[i], blocks[i+1], blocks[i+2]
            cells = [(r, c) for c in range(b1[2], b3[1] + 1)]
            triplets.append(cells)

    for c in range(C):
        blocks = []
        curr_reg = region_grid[0][c]
        start_r = 0
        for r in range(1, R):
            if region_grid[r][c] != curr_reg:
                blocks.append((curr_reg, start_r, r - 1))
                curr_reg = region_grid[r][c]
                start_r = r
        blocks.append((curr_reg, start_r, R - 1))
        for i in range(len(blocks) - 2):
            b1, b2, b3 = blocks[i], blocks[i+1], blocks[i+2]
            cells = [(r, c) for r in range(b1[2], b3[1] + 1)]
            triplets.append(cells)

    def is_valid_partial(grid):
        # 1. Black cells cannot touch orthogonally
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 1:
                    for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 1:
                            return False

        # 2. Region counts
        for reg_id, cells in regions.items():
            if reg_id in clues:
                clue = clues[reg_id]
                ones = sum(1 for r, c in cells if grid[r][c] == 1)
                unassigned = sum(1 for r, c in cells if grid[r][c] == -1)
                if ones > clue: return False
                if ones + unassigned < clue: return False

        # 3. Line-of-sight constraints
        for triplet in triplets:
            ones = sum(1 for r, c in triplet if grid[r][c] == 1)
            unassigned = sum(1 for r, c in triplet if grid[r][c] == -1)
            if ones == 0 and unassigned == 0:
                return False

        # 4. White cell connectivity (optimistic check)
        zeros = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 0]
        if zeros:
            start = zeros[0]
            visited = set([start])
            q = [start]
            while q:
                curr_r, curr_c = q.pop(0)
                for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                    nr, nc = curr_r+dr, curr_c+dc
                    if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited:
                        if grid[nr][nc] in (0, -1):
                            visited.add((nr, nc))
                            q.append((nr, nc))
            for z in zeros:
                if z not in visited:
                    return False

        return True

    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # Propagate adjacent 1s
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                            nr, nc = r+dr, c+dc
                            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == -1:
                                grid[nr][nc] = 0
                                changed = True

            # Propagate region counts
            for reg_id, cells in regions.items():
                if reg_id in clues:
                    clue = clues[reg_id]
                    ones = sum(1 for r, c in cells if grid[r][c] == 1)
                    unassigned = [ (r,c) for r, c in cells if grid[r][c] == -1 ]
                    if ones == clue and unassigned:
                        for r, c in unassigned:
                            grid[r][c] = 0
                            changed = True
                    elif ones + len(unassigned) == clue and unassigned:
                        for r, c in unassigned:
                            grid[r][c] = 1
                            changed = True

            # Propagate line-of-sight constraints
            for triplet in triplets:
                ones = sum(1 for r, c in triplet if grid[r][c] == 1)
                unassigned = [ (r,c) for r, c in triplet if grid[r][c] == -1 ]
                if ones == 0 and len(unassigned) == 1:
                    r, c = unassigned[0]
                    grid[r][c] = 1
                    changed = True

            if not is_valid_partial(grid):
                return False
        return True

    def solve_backtrack(current_grid):
        grid = [row[:] for row in current_grid]

        if not propagate(grid):
            return None

        best_cell = None
        for r in range(R):
            for c in range(C):
                if grid[r][c] == -1:
                    best_cell = (r, c)
                    break
            if best_cell: break

        if not best_cell:
            return grid

        r, c = best_cell

        for val in [0, 1]:
            grid[r][c] = val
            result = solve_backtrack(grid)
            if result:
                return result
            grid[r][c] = -1

        return None

    initial_grid = [[-1]*C for _ in range(R)]
    final_grid = solve_backtrack(initial_grid)

    if final_grid:
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                row.append('B' if final_grid[r][c] == 1 else None)
            ans.append(row)
        return ans
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
