OBSERVATION = {'data': [[None, 1, None, None, None, None, None, None, None, None, None], [None, None, 3, 1, None, 1, 2, 3, None, 1, None], [1, 2, 3, None, None, None, 1, None, None, None, 1], [None, 1, 1, None, None, 1, 1, None, 1, 2, 1], [None, None, 1, None, 2, 2, None, None, 2, 1, None], [None, 1, None, None, None, None, 3, None, 2, None, None], [None, 3, 1, None, 3, None, None, 1, 2, None, 1], [1, 1, 2, 3, 1, 2, None, 1, None, 2, None], [1, None, 2, None, 3, None, None, None, 1, None, 1], [1, 2, None, 2, 1, 2, None, 2, 2, 2, 1], [None, 1, 1, None, None, None, None, None, 1, None, None]]}

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.history = []

    def find(self, i):
        # No path compression to allow simple rollback
        while i != self.parent[i]:
            i = self.parent[i]
        return i

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i == root_j:
            return False
        if self.rank[root_i] < self.rank[root_j]:
            root_i, root_j = root_j, root_i
        self.history.append((root_j, self.parent[root_j], root_i, self.rank[root_i]))
        self.parent[root_j] = root_i
        if self.rank[root_i] == self.rank[root_j]:
            self.rank[root_i] += 1
        return True

    def get_checkpoint(self):
        return len(self.history)

    def rollback(self, checkpoint):
        while len(self.history) > checkpoint:
            root_j, old_parent_j, root_i, old_rank_i = self.history.pop()
            self.parent[root_j] = old_parent_j
            self.rank[root_i] = old_rank_i

class GokigenSolver:
    def __init__(self, observation):
        self.data = observation['data']
        self.N = len(self.data) - 1
        self.cells = [[-1] * self.N for _ in range(self.N)]
        self.degree = [[0] * (self.N + 1) for _ in range(self.N + 1)]
        self.free = [[0] * (self.N + 1) for _ in range(self.N + 1)]

        for r in range(self.N + 1):
            for c in range(self.N + 1):
                count = 0
                if r > 0 and c > 0: count += 1
                if r > 0 and c < self.N: count += 1
                if r < self.N and c > 0: count += 1
                if r < self.N and c < self.N: count += 1
                self.free[r][c] = count

        self.dsu = DSU((self.N + 1) * (self.N + 1))

    def can_assign(self, r, c, v):
        u1, v1 = (r, c), (r + 1, c + 1)
        u2, v2 = (r + 1, c), (r, c + 1)

        if v == 0:  # '\'
            if self.dsu.find(u1[0] * (self.N + 1) + u1[1]) == self.dsu.find(v1[0] * (self.N + 1) + v1[1]):
                return False
            if self.data[u1[0]][u1[1]] is not None and self.degree[u1[0]][u1[1]] + 1 > self.data[u1[0]][u1[1]]: return False
            if self.data[v1[0]][v1[1]] is not None and self.degree[v1[0]][v1[1]] + 1 > self.data[v1[0]][v1[1]]: return False
        else:       # '/'
            if self.dsu.find(u2[0] * (self.N + 1) + u2[1]) == self.dsu.find(v2[0] * (self.N + 1) + v2[1]):
                return False
            if self.data[u2[0]][u2[1]] is not None and self.degree[u2[0]][u2[1]] + 1 > self.data[u2[0]][u2[1]]: return False
            if self.data[v2[0]][v2[1]] is not None and self.degree[v2[0]][v2[1]] + 1 > self.data[v2[0]][v2[1]]: return False

        dots_not_getting_edge = [u2, v2] if v == 0 else [u1, v1]
        for dr, dc in dots_not_getting_edge:
            if self.data[dr][dc] is not None:
                if self.degree[dr][dc] + self.free[dr][dc] - 1 < self.data[dr][dc]:
                    return False

        return True

    def apply_assignment(self, r, c, v):
        chk = self.dsu.get_checkpoint()
        self.cells[r][c] = v

        u1, v1 = (r, c), (r + 1, c + 1)
        u2, v2 = (r + 1, c), (r, c + 1)

        if v == 0:
            self.dsu.union(u1[0] * (self.N + 1) + u1[1], v1[0] * (self.N + 1) + v1[1])
            self.degree[u1[0]][u1[1]] += 1
            self.degree[v1[0]][v1[1]] += 1
        else:
            self.dsu.union(u2[0] * (self.N + 1) + u2[1], v2[0] * (self.N + 1) + v2[1])
            self.degree[u2[0]][u2[1]] += 1
            self.degree[v2[0]][v2[1]] += 1

        self.free[u1[0]][u1[1]] -= 1
        self.free[v1[0]][v1[1]] -= 1
        self.free[u2[0]][u2[1]] -= 1
        self.free[v2[0]][v2[1]] -= 1

        return chk

    def undo_assignment(self, r, c, v, chk):
        self.cells[r][c] = -1
        u1, v1 = (r, c), (r + 1, c + 1)
        u2, v2 = (r + 1, c), (r, c + 1)

        if v == 0:
            self.degree[u1[0]][u1[1]] -= 1
            self.degree[v1[0]][v1[1]] -= 1
        else:
            self.degree[u2[0]][u2[1]] -= 1
            self.degree[v2[0]][v2[1]] -= 1

        self.free[u1[0]][u1[1]] += 1
        self.free[v1[0]][v1[1]] += 1
        self.free[u2[0]][u2[1]] += 1
        self.free[v2[0]][v2[1]] += 1

        self.dsu.rollback(chk)

    def propagate(self, assigned_list):
        changed = True
        while changed:
            changed = False
            for r in range(self.N):
                for c in range(self.N):
                    if self.cells[r][c] == -1:
                        can0 = self.can_assign(r, c, 0)
                        can1 = self.can_assign(r, c, 1)
                        if not can0 and not can1:
                            return False
                        if can0 and not can1:
                            chk = self.apply_assignment(r, c, 0)
                            assigned_list.append((r, c, 0, chk))
                            changed = True
                        elif can1 and not can0:
                            chk = self.apply_assignment(r, c, 1)
                            assigned_list.append((r, c, 1, chk))
                            changed = True
        return True

    def get_best_cell(self):
        best_dot = None
        min_score = 999
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                if self.data[r][c] is not None and self.free[r][c] > 0:
                    k = self.data[r][c] - self.degree[r][c]
                    n = self.free[r][c]
                    score = min(k, n - k)
                    if score < min_score:
                        min_score = score
                        best_dot = (r, c)

        if best_dot:
            dr, dc = best_dot
            for r, c in [(dr - 1, dc - 1), (dr - 1, dc), (dr, dc - 1), (dr, dc)]:
                if 0 <= r < self.N and 0 <= c < self.N and self.cells[r][c] == -1:
                    return (r, c)

        for r in range(self.N):
            for c in range(self.N):
                if self.cells[r][c] == -1:
                    return (r, c)
        return None

    def solve_recursive(self):
        best_cell = self.get_best_cell()
        if not best_cell:
            for r in range(self.N + 1):
                for c in range(self.N + 1):
                    if self.data[r][c] is not None and self.degree[r][c] != self.data[r][c]:
                        return False
            return True

        r, c = best_cell

        for v in [0, 1]:
            if self.can_assign(r, c, v):
                assigned_list = []
                chk = self.apply_assignment(r, c, v)
                assigned_list.append((r, c, v, chk))

                if self.propagate(assigned_list):
                    if self.solve_recursive():
                        return True

                for ar, ac, av, achk in reversed(assigned_list):
                    self.undo_assignment(ar, ac, av, achk)

        return False

    def solve(self):
        for r in range(self.N + 1):
            for c in range(self.N + 1):
                if self.data[r][c] is not None:
                    if self.data[r][c] > self.free[r][c] or self.data[r][c] < 0:
                        return "No Solution"

        assigned_list = []
        if not self.propagate(assigned_list):
            return "No Solution"

        if self.solve_recursive():
            res = []
            for r in range(self.N):
                row = []
                for c in range(self.N):
                    row.append('\\' if self.cells[r][c] == 0 else '/')
                res.append(row)
            return res
        else:
            return "No Solution"

def solve(observation):
    solver = GokigenSolver(observation)
    return solver.solve()

if __name__ == "__main__":
    print(solve(OBSERVATION))
