def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    UNKNOWN, BLACK, WHITE = 0, 1, 2
    state = [[UNKNOWN for _ in range(C)] for _ in range(R)]

    # Initial deductions based on Hitori rules
    # 1. Adjacent identical numbers mean any other identical number in that row/col must be BLACK
    for r in range(R):
        for c in range(C - 1):
            if grid[r][c] == grid[r][c+1]:
                val = grid[r][c]
                for j in range(C):
                    if j != c and j != c + 1 and grid[r][j] == val:
                        state[r][j] = BLACK
    for c in range(C):
        for r in range(R - 1):
            if grid[r][c] == grid[r+1][c]:
                val = grid[r][c]
                for i in range(R):
                    if i != r and i != r + 1 and grid[i][c] == val:
                        state[i][c] = BLACK

    # 2. Pattern A, B, A -> B must be WHITE to prevent adjacent BLACKs
    for r in range(R):
        for c in range(C - 2):
            if grid[r][c] == grid[r][c+2]:
                state[r][c+1] = WHITE
    for c in range(C):
        for r in range(R - 2):
            if grid[r][c] == grid[r+2][c]:
                state[r+1][c] = WHITE

    # Precompute heuristic scores for variable ordering (most constrained first)
    heuristic_scores = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            val = grid[r][c]
            count = 0
            for i in range(R):
                if grid[i][c] == val: count += 1
            for j in range(C):
                if grid[r][j] == val: count += 1
            heuristic_scores[r][c] = count

    def get_neighbors(r, c):
        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < R - 1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < C - 1: neighbors.append((r, c+1))
        return neighbors

    def is_non_black_connected(st):
        start_r, start_c = -1, -1
        non_black_count = 0
        for r in range(R):
            for c in range(C):
                if st[r][c] != BLACK:
                    if start_r == -1:
                        start_r, start_c = r, c
                    non_black_count += 1

        if non_black_count == 0:
            return True

        visited = set([(start_r, start_c)])
        q = [(start_r, start_c)]
        head = 0
        while head < len(q):
            curr_r, curr_c = q[head]
            head += 1
            for nr, nc in get_neighbors(curr_r, curr_c):
                if st[nr][nc] != BLACK and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        return len(visited) == non_black_count

    def propagate(st):
        changed = True
        while changed:
            changed = False

            # Rule 1: Black cells cannot touch orthogonally
            for r in range(R):
                for c in range(C):
                    if st[r][c] == BLACK:
                        for nr, nc in get_neighbors(r, c):
                            if st[nr][nc] == BLACK:
                                return False # Conflict: adjacent blacks
                            if st[nr][nc] == UNKNOWN:
                                st[nr][nc] = WHITE
                                changed = True

            # Rule 2: Unshaded numbers appear at most once in every row/col
            for r in range(R):
                for c in range(C):
                    if st[r][c] == WHITE:
                        val = grid[r][c]
                        for i in range(R):
                            if i != r and grid[i][c] == val:
                                if st[i][c] == WHITE:
                                    return False # Conflict: duplicate white in col
                                if st[i][c] == UNKNOWN:
                                    st[i][c] = BLACK
                                    changed = True
                        for j in range(C):
                            if j != c and grid[r][j] == val:
                                if st[r][j] == WHITE:
                                    return False # Conflict: duplicate white in row
                                if st[r][j] == UNKNOWN:
                                    st[r][j] = BLACK
                                    changed = True

            # Rule 3: All unshaded cells must form one connected group
            if not is_non_black_connected(st):
                return False # Conflict: disconnected white cells

            # Rule 4: Articulation points deduction
            # If setting an UNKNOWN cell to BLACK disconnects the graph, it MUST be WHITE
            if not changed:
                for r in range(R):
                    for c in range(C):
                        if st[r][c] == UNKNOWN:
                            st[r][c] = BLACK
                            connected = is_non_black_connected(st)
                            st[r][c] = UNKNOWN

                            if not connected:
                                st[r][c] = WHITE
                                changed = True
                                break
                    if changed:
                        break

        return True

    def search(st):
        if not propagate(st):
            return None

        # Find the most constrained UNKNOWN cell
        best_r, best_c = -1, -1
        max_score = -1
        for r in range(R):
            for c in range(C):
                if st[r][c] == UNKNOWN:
                    if heuristic_scores[r][c] > max_score:
                        max_score = heuristic_scores[r][c]
                        best_r, best_c = r, c

        if best_r == -1:
            return st # Solved

        # Try setting to BLACK first (more constrained, forces neighbors to WHITE)
        st_copy = [row[:] for row in st]
        st_copy[best_r][best_c] = BLACK
        res = search(st_copy)
        if res: return res

        # Try setting to WHITE
        st_copy = [row[:] for row in st]
        st_copy[best_r][best_c] = WHITE
        res = search(st_copy)
        if res: return res

        return None

    final_state = search(state)
    if final_state:
        ans = [[None for _ in range(C)] for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if final_state[r][c] == BLACK:
                    ans[r][c] = 'B'
        return ans
    return "No Solution"

