OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, 6, None], [None, None, None, None, 5], [None, 7, None, None, None]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Initialize grid: 'W' for white/clue, 'B' for black, 'U' for unknown
    grid = [['U' for _ in range(C)] for _ in range(R)]
    clues = []
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                grid[r][c] = 'W'
                clues.append((r, c, data[r][c]))

    def get_visible(r, c, dr, dc, g):
        """Returns min_len, max_len, and the list of cells in a given direction."""
        cells = []
        nr, nc = r + dr, c + dc
        while 0 <= nr < R and 0 <= nc < C:
            cells.append((nr, nc))
            nr += dr
            nc += dc

        min_len = 0
        max_len = 0
        for i, (nr, nc) in enumerate(cells):
            if g[nr][nc] == 'B':
                break
            max_len += 1
            if g[nr][nc] == 'U' and min_len == i:
                pass # min_len stops growing at the first 'U'
            elif g[nr][nc] == 'W' and min_len == i:
                min_len += 1
        return min_len, max_len, cells

    def propagate(g):
        """Applies deductive rules to reduce the search space. Returns False if conflict found."""
        changed = True
        while changed:
            changed = False

            # Rule 1: Black cells cannot touch orthogonally
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 'B':
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if g[nr][nc] == 'B':
                                    return False # Conflict: adjacent black cells
                                if g[nr][nc] == 'U':
                                    g[nr][nc] = 'W'
                                    changed = True

            # Rule 2: Clue visibility constraints
            for cr, cc, val in clues:
                dirs = [(-1,0), (1,0), (0,-1), (0,1)]
                dir_stats = []
                max_vis = 1
                min_vis = 1
                for dr, dc in dirs:
                    min_l, max_l, cells = get_visible(cr, cc, dr, dc, g)
                    dir_stats.append((min_l, max_l, cells))
                    max_vis += max_l
                    min_vis += min_l

                if max_vis < val: return False # Cannot reach required visibility
                if min_vis > val: return False # Exceeded required visibility

                for i, (dr, dc) in enumerate(dirs):
                    min_l, max_l, cells = dir_stats[i]

                    # Deduce 'W' cells: if we need cells from this direction even if all others are maxed
                    req_len = val - (max_vis - max_l)
                    if req_len > 0:
                        for j in range(req_len):
                            nr, nc = cells[j]
                            if g[nr][nc] == 'U':
                                g[nr][nc] = 'W'
                                changed = True

                    # Deduce 'B' cells: if making the first 'U' into 'W' would exceed the clue
                    if min_l < len(cells):
                        nr, nc = cells[min_l]
                        if g[nr][nc] == 'U':
                            next_min_l = min_l + 1
                            while next_min_l < len(cells) and g[cells[next_min_l][0]][cells[next_min_l][1]] == 'W':
                                next_min_l += 1
                            new_min_vis = min_vis - min_l + next_min_l
                            if new_min_vis > val:
                                g[nr][nc] = 'B'
                                changed = True

            # Rule 3: Connectivity constraints
            w_cells = [(r, c) for r in range(R) for c in range(C) if g[r][c] == 'W']
            if not w_cells: continue

            def get_reachable(start_r, start_c, avoid_r=-1, avoid_c=-1):
                q = [(start_r, start_c)]
                visited = set([(start_r, start_c)])
                idx = 0
                while idx < len(q):
                    curr_r, curr_c = q[idx]
                    idx += 1
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if (nr, nc) == (avoid_r, avoid_c): continue
                            if g[nr][nc] != 'B' and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                q.append((nr, nc))
                return visited

            # Check if all known 'W' cells are connected
            reachable = get_reachable(w_cells[0][0], w_cells[0][1])
            for r, c in w_cells:
                if (r, c) not in reachable:
                    return False # Conflict: disconnected white components

            # Any 'U' cell that cannot reach the main 'W' component must be 'B'
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 'U' and (r, c) not in reachable:
                        g[r][c] = 'B'
                        changed = True

            # Articulation points: if a 'U' cell is the only way to connect 'W' cells, it must be 'W'
            for r in range(R):
                for c in range(C):
                    if g[r][c] == 'U':
                        start_w = w_cells[0]
                        reach_without_u = get_reachable(start_w[0], start_w[1], r, c)
                        disconnects = False
                        for wr, wc in w_cells:
                            if (wr, wc) not in reach_without_u:
                                disconnects = True
                                break
                        if disconnects:
                            g[r][c] = 'W'
                            changed = True

        return True

    def solve_backtrack(g):
        if not propagate(g):
            return False

        # Check if puzzle is completely solved
        solved = True
        for r in range(R):
            for c in range(C):
                if g[r][c] == 'U':
                    solved = False
                    break
            if not solved: break

        if solved:
            # Final verification of all clues
            for cr, cc, val in clues:
                vis = 1
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    while 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 'W':
                        vis += 1
                        nr += dr
                        nc += dc
                if vis != val:
                    return False
            return True

        # Heuristic: pick the 'U' cell that is in the line of sight of the most clues
        best_u = None
        max_clues = -1

        for r in range(R):
            for c in range(C):
                if g[r][c] == 'U':
                    count = 0
                    for cr, cc, val in clues:
                        if cr == r or cc == c:
                            blocked = False
                            if cr == r:
                                step = 1 if c > cc else -1
                                for tc in range(cc + step, c, step):
                                    if g[r][tc] == 'B':
                                        blocked = True
                                        break
                            else:
                                step = 1 if r > cr else -1
                                for tr in range(cr + step, r, step):
                                    if g[tr][c] == 'B':
                                        blocked = True
                                        break
                            if not blocked:
                                count += 1
                    if count > max_clues:
                        max_clues = count
                        best_u = (r, c)

        if not best_u:
            return False

        r, c = best_u
        # Try 'B' first as it restricts visibility and forces adjacent 'W's
        for val in ['B', 'W']:
            new_g = [row[:] for row in g]
            new_g[r][c] = val
            if solve_backtrack(new_g):
                for i in range(R):
                    for j in range(C):
                        g[i][j] = new_g[i][j]
                return True

        return False

    if solve_backtrack(grid):
        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                if data[r][c] is not None:
                    row.append(data[r][c])
                elif grid[r][c] == 'B':
                    row.append('B')
                else:
                    row.append(None)
            ans.append(row)
        return ans
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
