def solve(observation):
    region_grid = observation['region']
    data = observation['data']
    R = len(region_grid)
    C = len(region_grid[0])

    regions = {}
    clues = {}
    for r in range(R):
        for c in range(C):
            reg_id = region_grid[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))
            if data[r][c] is not None:
                clues[reg_id] = data[r][c]

    for reg_id in regions:
        if reg_id not in clues:
            clues[reg_id] = None

    # Precompute line constraints: a straight white line cannot span 3 or more regions.
    # This means any segment spanning 3 regions must contain at least one black cell.
    # We only need to store minimal segments to maximize pruning efficiency.
    line_constraints = []

    # Horizontal constraints
    for r in range(R):
        for c1 in range(C):
            for c2 in range(c1 + 2, C):
                regs = set(region_grid[r][c] for c in range(c1, c2 + 1))
                if len(regs) >= 3:
                    left_regs = set(region_grid[r][c] for c in range(c1 + 1, c2 + 1))
                    right_regs = set(region_grid[r][c] for c in range(c1, c2))
                    if len(left_regs) < 3 and len(right_regs) < 3:
                        line_constraints.append([(r, c) for c in range(c1, c2 + 1)])

    # Vertical constraints
    for c in range(C):
        for r1 in range(R):
            for r2 in range(r1 + 2, R):
                regs = set(region_grid[r][c] for r in range(r1, r2 + 1))
                if len(regs) >= 3:
                    top_regs = set(region_grid[r][c] for r in range(r1 + 1, r2 + 1))
                    bottom_regs = set(region_grid[r][c] for r in range(r1, r2))
                    if len(top_regs) < 3 and len(bottom_regs) < 3:
                        line_constraints.append([(r, c) for r in range(r1, r2 + 1)])

    def propagate(grid):
        changed = True
        while changed:
            changed = False

            # 1. Region sums
            for reg_id, cells in regions.items():
                clue = clues[reg_id]
                if clue is None: continue
                blacks = sum(1 for r, c in cells if grid[r][c] == 1)
                unassigned = [(r, c) for r, c in cells if grid[r][c] == -1]

                if blacks > clue: return False
                if blacks + len(unassigned) < clue: return False

                if blacks == clue and unassigned:
                    for r, c in unassigned: grid[r][c] = 0
                    changed = True
                if blacks + len(unassigned) == clue and unassigned:
                    for r, c in unassigned: grid[r][c] = 1
                    changed = True

            # 2. No adjacent blacks
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 1:
                        for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if grid[nr][nc] == 1: return False
                                if grid[nr][nc] == -1:
                                    grid[nr][nc] = 0
                                    changed = True

            # 3. Line constraints
            for cells in line_constraints:
                blacks = sum(1 for r, c in cells if grid[r][c] == 1)
                unassigned = [(r, c) for r, c in cells if grid[r][c] == -1]
                if blacks == 0:
                    if len(unassigned) == 0: return False
                    if len(unassigned) == 1:
                        r, c = unassigned[0]
                        grid[r][c] = 1
                        changed = True

            # 4. Connectivity pruning
            allowed_cells = set((r, c) for r in range(R) for c in range(C) if grid[r][c] != 1)
            components = []
            while allowed_cells:
                start = allowed_cells.pop()
                comp = {start}
                q = [start]
                while q:
                    curr_r, curr_c = q.pop(0)
                    for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if (nr, nc) in allowed_cells:
                            allowed_cells.remove((nr, nc))
                            comp.add((nr, nc))
                            q.append((nr, nc))
                components.append(comp)

            white_comps = [comp for comp in components if any(grid[r][c] == 0 for r, c in comp)]

            if len(white_comps) > 1:
                return False

            if len(white_comps) == 1:
                for comp in components:
                    if comp != white_comps[0]:
                        if len(comp) > 1:
                            return False
                        else:
                            r, c = list(comp)[0]
                            if grid[r][c] == -1:
                                grid[r][c] = 1
                                changed = True

        return True

    def check_connectivity(grid):
        whites = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 0]
        if not whites: return True
        start = whites[0]
        q = [start]
        visited = {start}
        while q:
            curr_r, curr_c = q.pop(0)
            for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(whites)

    def solve_recursive(grid):
        if not propagate(grid):
            return None

        unassigned = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == -1]
        if not unassigned:
            if check_connectivity(grid):
                return grid
            return None

        # Heuristic: pick cell in a clued region with the fewest unassigned cells
        best_cell = unassigned[0]
        best_score = (float('inf'), float('inf'))
        for r, c in unassigned:
            reg_id = region_grid[r][c]
            clue = clues[reg_id]
            if clue is not None:
                cells_in_reg = regions[reg_id]
                unassigned_in_reg = sum(1 for rr, cc in cells_in_reg if grid[rr][cc] == -1)
                score = (0, unassigned_in_reg)
            else:
                score = (1, 0)
            if score < best_score:
                best_score = score
                best_cell = (r, c)

        r, c = best_cell

        for val in [0, 1]:
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val
            res = solve_recursive(new_grid)
            if res: return res

        return None

    initial_grid = [[-1] * C for _ in range(R)]
    solution = solve_recursive(initial_grid)

    if solution:
        ans = []
        for r in range(R):
            row_ans = []
            for c in range(C):
                row_ans.append('B' if solution[r][c] == 1 else None)
            ans.append(row_ans)
        return ans
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
