}

def solve(observation):
    grid = observation['data']
    N = len(grid)

    # Parse constraints into integer coordinate pairs for fast lookup
    horiz_cons = {}
    for k, v in observation.get('horizontal', {}).items():
        r_str, c_str = k.strip('()').split(',')
        horiz_cons[(int(float(r_str)), int(float(c_str) - 0.5))] = v

    vert_cons = {}
    for k, v in observation.get('vertical', {}).items():
        r_str, c_str = k.strip('()').split(',')
        vert_cons[(int(float(r_str) - 0.5), int(float(c_str)))] = v

    def is_valid(r, c, color, current_grid):
        # Check if placing 'color' exceeds the maximum allowed per row/col
        if sum(1 for i in range(N) if current_grid[r][i] == color) >= N // 2:
            return False
        if sum(1 for i in range(N) if current_grid[i][c] == color) >= N // 2:
            return False

        # Temporarily place the color to check for 3-consecutive violations
        current_grid[r][c] = color
        valid = True

        # Check horizontal 3-consecutive
        for i in range(max(0, c - 2), min(N - 2, c) + 1):
            if current_grid[r][i] == current_grid[r][i+1] == current_grid[r][i+2] != None:
                valid = False
                break

        # Check vertical 3-consecutive
        if valid:
            for i in range(max(0, r - 2), min(N - 2, r) + 1):
                if current_grid[i][c] == current_grid[i+1][c] == current_grid[i+2][c] != None:
                    valid = False
                    break

        # Check explicit adjacent constraints
        if valid:
            # Left neighbor
            if c > 0 and (r, c - 1) in horiz_cons:
                left = current_grid[r][c-1]
                if left is not None:
                    if horiz_cons[(r, c - 1)] == '=' and color != left: valid = False
                    if horiz_cons[(r, c - 1)] == 'x' and color == left: valid = False
            # Right neighbor
            if valid and c < N - 1 and (r, c) in horiz_cons:
                right = current_grid[r][c+1]
                if right is not None:
                    if horiz_cons[(r, c)] == '=' and color != right: valid = False
                    if horiz_cons[(r, c)] == 'x' and color == right: valid = False
            # Top neighbor
            if valid and r > 0 and (r - 1, c) in vert_cons:
                top = current_grid[r-1][c]
                if top is not None:
                    if vert_cons[(r - 1, c)] == '=' and color != top: valid = False
                    if vert_cons[(r - 1, c)] == 'x' and color == top: valid = False
            # Bottom neighbor
            if valid and r < N - 1 and (r, c) in vert_cons:
                bottom = current_grid[r+1][c]
                if bottom is not None:
                    if vert_cons[(r, c)] == '=' and color != bottom: valid = False
                    if vert_cons[(r, c)] == 'x' and color == bottom: valid = False

        # Remove temporary placement
        current_grid[r][c] = None
        return valid

    def propagate(current_grid):
        """
        Aggressively fills cells that have only one valid option.
        Returns False if a contradiction is found, True otherwise.
        """
        changed = True
        while changed:
            changed = False
            for r in range(N):
                for c in range(N):
                    if current_grid[r][c] is None:
                        can_be_B = is_valid(r, c, 'B', current_grid)
                        can_be_W = is_valid(r, c, 'W', current_grid)

                        if not can_be_B and not can_be_W:
                            return False # Contradiction: no valid color for this cell
                        elif can_be_B and not can_be_W:
                            current_grid[r][c] = 'B'
                            changed = True
                        elif not can_be_B and can_be_W:
                            current_grid[r][c] = 'W'
                            changed = True
        return True

    def solve_recursive(current_grid):
        """
        Backtracking search with MRV (Minimum Remaining Values) heuristic.
        """
        best_cell = None
        min_options = 3

        # Find the most constrained empty cell
        for r in range(N):
            for c in range(N):
                if current_grid[r][c] is None:
                    options = []
                    if is_valid(r, c, 'B', current_grid): options.append('B')
                    if is_valid(r, c, 'W', current_grid): options.append('W')

                    if len(options) == 0:
                        return None # Dead end
                    if len(options) < min_options:
                        min_options = len(options)
                        best_cell = (r, c, options)
                        if min_options == 1:
                            break # Optimal cell found
            if min_options == 1:
                break

        if best_cell is None:
            return current_grid # Puzzle solved

        r, c, options = best_cell

        # Try each valid option
        for color in options:
            next_grid = [row[:] for row in current_grid]
            next_grid[r][c] = color
            if propagate(next_grid):
                result = solve_recursive(next_grid)
                if result is not None:
                    return result

        return None

    # Create a working copy and perform initial constraint propagation
    grid_copy = [row[:] for row in grid]
    if not propagate(grid_copy):
        return "No Solution"

    # Start recursive search
    solution = solve_recursive(grid_copy)
    return solution if solution else "No Solution"

