def solve(observation):
    regions = observation['region']
    data = observation['data']
    N = len(regions)

    grid = [[0]*N for _ in range(N)]

    # Precompute cells for each region for fast lookup
    region_cells = [[] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            region_cells[regions[r][c]].append((r, c))

    # Initialize grid with givens
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                grid[r][c] = data[r][c]

    def is_valid(r, c, val):
        # Check row
        for i in range(N):
            if grid[r][i] == val: return False
        # Check col
        for i in range(N):
            if grid[i][c] == val: return False
        # Check region
        for rr, cc in region_cells[regions[r][c]]:
            if grid[rr][cc] == val: return False
        return True

    def get_empty_cell():
        # Minimum Remaining Values (MRV) heuristic
        min_options = N + 1
        best_cell = None
        best_options = []
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    options = []
                    for val in range(1, N+1):
                        if is_valid(r, c, val):
                            options.append(val)
                    if len(options) < min_options:
                        min_options = len(options)
                        best_cell = (r, c)
                        best_options = options
                        # Early failure detection
                        if min_options == 0:
                            return best_cell, best_options
        return best_cell, best_options

    def backtrack():
        cell, options = get_empty_cell()
        if cell is None:
            return True # All cells filled successfully
        if not options:
            return False # Dead end reached

        r, c = cell
        for val in options:
            grid[r][c] = val
            if backtrack():
                return True
            grid[r][c] = 0 # Undo assignment
        return False

    if backtrack():
        return grid
    else:
        return "No Solution"

