def solve(observation):
    region_map = observation['region']
    data = observation['data']
    N = len(data)

    # Initialize domains for each cell
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]

    # Apply givens to restrict domains
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Precompute neighbors for each cell to speed up constraint propagation
    neighbors_map = {}
    for r in range(N):
        for c in range(N):
            neighbors = set()
            # Same row
            for i in range(N):
                if i != c: neighbors.add((r, i))
            # Same column
            for i in range(N):
                if i != r: neighbors.add((i, c))
            # Same irregular region
            reg = region_map[r][c]
            for i in range(N):
                for j in range(N):
                    if region_map[i][j] == reg and (i, j) != (r, c):
                        neighbors.add((i, j))
            neighbors_map[(r, c)] = neighbors

    # Initial constraint propagation using a queue
    queue = []
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) == 1:
                queue.append((r, c))

    while queue:
        r, c = queue.pop(0)
        val = list(domains[r][c])[0]
        for nr, nc in neighbors_map[(r, c)]:
            if val in domains[nr][nc]:
                domains[nr][nc].remove(val)
                if len(domains[nr][nc]) == 0:
                    return "No Solution" # Contradiction found
                if len(domains[nr][nc]) == 1:
                    queue.append((nr, nc))

    # Backtracking search with Minimum Remaining Values (MRV) heuristic
    def backtrack(current_domains):
        # Find the unassigned cell with the fewest possible values
        min_len = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(current_domains[r][c]) > 1:
                    if len(current_domains[r][c]) < min_len:
                        min_len = len(current_domains[r][c])
                        best_cell = (r, c)

        # If no unassigned cells are left, the puzzle is solved
        if best_cell is None:
            res = []
            for r in range(N):
                row_res = []
                for c in range(N):
                    row_res.append(list(current_domains[r][c])[0])
                res.append(row_res)
            return res

        r, c = best_cell
        # Try each possible value for the selected cell
        for val in list(current_domains[r][c]):
            # Create a deep copy of the domains for this branch
            new_domains = [[set(d) for d in row] for row in current_domains]
            new_domains[r][c] = {val}

            # Propagate the new assignment
            q = [(r, c)]
            possible = True
            while q:
                curr_r, curr_c = q.pop(0)
                curr_val = list(new_domains[curr_r][curr_c])[0]
                for nr, nc in neighbors_map[(curr_r, curr_c)]:
                    if curr_val in new_domains[nr][nc]:
                        new_domains[nr][nc].remove(curr_val)
                        if len(new_domains[nr][nc]) == 0:
                            possible = False
                            break
                        if len(new_domains[nr][nc]) == 1:
                            q.append((nr, nc))
                if not possible:
                    break

            # If propagation didn't lead to a contradiction, continue searching
            if possible:
                result = backtrack(new_domains)
                if result != "No Solution":
                    return result

        return "No Solution"

    return backtrack(domains)

